THEME_COLORS = {"dark": DARK_COLORS, "light": LIGHT_COLORS}
THEME_NAMES = ("system", "light", "dark")
DEFAULT_THEME = "system"

# The live palette. Updated in place by apply_theme() so that every
# COLORS[...] read in the file keeps working without being rewritten.
COLORS = dict(DARK_COLORS)

def system_prefers_dark() -> bool:
    """What Windows itself is set to. Qt 6.5 and later answer directly; older
    builds have no such hint, and dark is pdfNote's own default."""
    try:
        hints = QGuiApplication.styleHints()
        scheme = hints.colorScheme()
    except Exception:
        return True
    try:
        if scheme == Qt.ColorScheme.Light:
            return False
        if scheme == Qt.ColorScheme.Dark:
            return True
    except AttributeError:
        pass
    return True


def resolve_theme(choice: str) -> str:
    """The theme actually shown: "system" follows Windows."""
    if choice == "dark":
        return "dark"
    if choice == "light":
        return "light"
    return "dark" if system_prefers_dark() else "light"


def apply_theme(choice: str) -> str:
    """Put `choice`'s colours into COLORS, in place, and answer what was
    resolved. In place because every read in this file is COLORS[...]; a new
    dict would leave each of them pointing at the old one."""
    resolved = resolve_theme(choice)
    COLORS.clear()
    COLORS.update(THEME_COLORS[resolved])
    application = QApplication.instance()
    if application is not None:
        # Whatever the stylesheet does not reach is drawn from this.
        application.setPalette(theme_palette())
    return resolved


