def resource_path(name: str) -> str:
    root = Path(getattr(sys, "_MEIPASS", Path(__file__).resolve().parent))
    return str(root / name)


# pdfNote's own tasks for the end of the process: run by atexit when Python
# ends the process, and by end_process when pdfNote does (6.21).
EXIT_TASKS: list[tuple[Callable[..., Any], tuple[Any, ...]]] = []


def run_at_exit(task: Callable[..., Any], *args: Any) -> None:
    entry = (task, args)

    def once() -> None:
        if entry in EXIT_TASKS:
            EXIT_TASKS.remove(entry)
            task(*args)

    EXIT_TASKS.append(entry)
    atexit.register(once)


def app_data_dir() -> Path:
    base = os.environ.get("LOCALAPPDATA") or tempfile.gettempdir()
    return Path(base) / "pdfNote"


def app_copyright() -> str:
    """The copyright line, with the holder's name as the UI language writes
    it: in Japanese script for Japanese, in Latin letters otherwise."""
    holder = APP_COPYRIGHT_HOLDER_JA if I18N.current == "ja" else APP_COPYRIGHT_HOLDER
    return f"© 2026 {holder}"


def _process_start_time(pid: int) -> int:
    """Start time (FILETIME ticks) of a running process, or 0 when it is not
    running or cannot be asked. Windows only; elsewhere always 0."""
    if sys.platform != "win32" or pid <= 0:
        return 0
    try:
        import ctypes
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.OpenProcess.restype = wintypes.HANDLE
        kernel32.OpenProcess.argtypes = (wintypes.DWORD, wintypes.BOOL, wintypes.DWORD)
        kernel32.GetExitCodeProcess.argtypes = (wintypes.HANDLE, ctypes.POINTER(wintypes.DWORD))
        kernel32.GetProcessTimes.argtypes = (wintypes.HANDLE,) + (
            ctypes.POINTER(wintypes.FILETIME),
        ) * 4
        kernel32.CloseHandle.argtypes = (wintypes.HANDLE,)
        handle = kernel32.OpenProcess(0x1000, False, pid)  # PROCESS_QUERY_LIMITED_INFORMATION
        if not handle:
            return 0
        try:
            code = wintypes.DWORD()
            if not kernel32.GetExitCodeProcess(handle, ctypes.byref(code)) or code.value != 259:
                return 0  # 259 = STILL_ACTIVE
            times = [wintypes.FILETIME() for _ in range(4)]
            if not kernel32.GetProcessTimes(handle, *(ctypes.byref(item) for item in times)):
                return 0
            return (times[0].dwHighDateTime << 32) | times[0].dwLowDateTime
        finally:
            kernel32.CloseHandle(handle)
    except Exception:
        return 0


def process_identity(pid: int | None = None) -> str:
    """Names a process by id and start time, so a recycled process id is
    never mistaken for the process that originally had it."""
    pid = os.getpid() if pid is None else pid
    start = _process_start_time(pid)
    return f"{pid}:{start}" if start else str(pid)


def owner_is_running(identity: str) -> bool:
    """Is the process that wrote a recovery snapshot still running?

    A second pdfNote started while the first had unsaved work used to offer
    to "restore" the first one's live snapshots -- and answering No deleted
    them, leaving the running instance without crash protection.
    """
    pid_text, _, start_text = str(identity or "").partition(":")
    try:
        pid = int(pid_text)
    except ValueError:
        return False
    if pid <= 0 or pid == os.getpid():
        return False
    if sys.platform == "win32":
        start = _process_start_time(pid)
        return bool(start) and (not start_text or str(start) == start_text)
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    return True


# Windows refuses a path of more than 259 characters to the ordinary file
# APIs, and MuPDF uses those. Python can still see such a file through the
# extended-length form, which is how this tells "too long" from "not there".
MAX_WINDOWS_PATH = 259


def path_too_long(path: str) -> bool:
    """The file is there, but its name is longer than Windows will take."""
    if sys.platform != "win32" or len(path) <= MAX_WINDOWS_PATH:
        return False
    if path.startswith("\\\\?\\"):
        return False
    try:
        return Path("\\\\?\\" + path).is_file()
    except OSError:
        return False


def is_remote_path(path: str) -> bool:
    """A UNC path, or a path on a mapped network drive."""
    if path.startswith(("\\\\", "//")):
        return True
    if sys.platform == "win32" and len(path) >= 2 and path[1] == ":":
        try:
            import ctypes

            return ctypes.windll.kernel32.GetDriveTypeW(path[:2] + "\\") == 4  # DRIVE_REMOTE
        except Exception:
            return False
    return False


class RecentFiles:
    _shared: dict[bool, "RecentFiles"] = {}

    def __init__(self, disabled: bool = False) -> None:
        self.disabled = disabled
        self.path = app_data_dir() / "settings.json"
        self.data: dict[str, Any] = {"recent": [], "last_folder": ""}
        if not disabled:
            self.load()

    @classmethod
    def shared(cls, disabled: bool = False) -> "RecentFiles":
        """The settings of this process, one object for every window (one
        more for test windows).

        Each window read settings.json when it opened and wrote its whole
        copy back on every change: a theme or language chosen in one window
        was put back by the next file another window opened, and recent
        files added in one were dropped by the other (6.2)."""
        settings = cls._shared.get(disabled)
        if settings is None:
            settings = cls._shared[disabled] = cls(disabled=disabled)
        return settings

    def load(self) -> None:
        try:
            value = json.loads(self.path.read_text(encoding="utf-8"))
            if isinstance(value, dict):
                self.data.update(value)
        except (OSError, ValueError, TypeError):
            # Preserve the recent-file list when upgrading from Sumi PDF Reader.
            legacy = self.path.parent.parent / "SumiPDFReader" / "settings.json"
            try:
                value = json.loads(legacy.read_text(encoding="utf-8"))
                if isinstance(value, dict):
                    self.data.update(value)
                    self.save()
            except (OSError, ValueError, TypeError):
                pass

    def save(self) -> None:
        if self.disabled:
            return
        # Through a temp file and a swap: writing in place left settings.json
        # truncated if pdfNote was killed mid-write (or a second instance
        # saved at the same moment), and the recent-file list was gone.
        partial = self.path.with_name(f"{self.path.name}.{os.getpid()}.tmp")
        try:
            self.path.parent.mkdir(parents=True, exist_ok=True)
            partial.write_text(
                json.dumps(self.data, ensure_ascii=False, indent=2), encoding="utf-8"
            )
            os.replace(partial, self.path)
        except OSError:
            try:
                partial.unlink(missing_ok=True)
            except OSError:
                pass

    def add(self, path: str) -> None:
        normalized = str(Path(path).resolve())
        recent = [p for p in self.data.get("recent", []) if p != normalized]
        self.data["recent"] = [normalized, *recent][:10]
        self.data["last_folder"] = str(Path(normalized).parent)
        self.save()

    def existing(self) -> list[str]:
        # Files on a network share are listed without asking the server:
        # checking a path on an unreachable share can block for tens of
        # seconds, which froze the start screen. Opening one that has gone
        # away still says "file not found".
        return [
            str(p)
            for p in self.data.get("recent", [])
            if isinstance(p, str) and (is_remote_path(p) or Path(p).is_file())
        ]


