class KeyNameTranslator(QTranslator):
    """Qt's key names (its "QShortcut" context) in the UI language.

    Qt asks for these every time it writes a shortcut out -- in a menu's
    shortcut column as well as through QKeySequence.toString(NativeText).
    Every other context gets None, a null string, which sends Qt on to its
    own catalogue for the dialog buttons. An empty string would not do:
    Qt takes "" as the translation, and "Ctrl+Shift+S" came out "CTRLSHIFTS".
    """

    def __init__(
        self, names: dict[str, str], parent: Any = None,
        strings: dict[tuple[str, str], str] | None = None,
    ) -> None:
        super().__init__(parent)
        self._names = names
        # Qt's own words for a language Qt has no catalogue for (QT_STRINGS).
        self._strings = strings or {}

    def translate(  # noqa: N802 - Qt's name
        self, context: str, source: str, disambiguation: Any = None, n: int = -1
    ) -> str | None:
        if context == "QShortcut" and source:
            return self._names.get(source, source)
        return self._strings.get((context, source))

    def isEmpty(self) -> bool:  # noqa: N802 - Qt's name
        return False


def key_sequence(keys: str) -> QKeySequence:
    """A shortcut from Qt's portable key names.

    Always portable: QKeySequence(str) reads the *translated* names, and
    once "Return" is shown as "Enter" that turns "Alt+Enter" into Alt+Return
    -- a second, identical shortcut on the same action, which Qt treats as
    ambiguous and then runs nothing.
    """
    return QKeySequence(keys, QKeySequence.PortableText)


def key_text(keys: str) -> str:
    """A key or chord written the way the UI language writes it:
    "Ctrl+Shift+S", "Ctrl+Mayús+S" in Spanish, "CTRL+SHIFT+S" in Russian.

    Takes Qt's portable names ("Ctrl+PgDown", "Del"). A chord that ends in
    a phrase rather than a key ("Shift+矢印キー") has its modifiers named
    the same way and the phrase translated; "Ctrl+1 – 9" keeps its range.
    A key pressed after another ("Alt+R, C") is written with the UI
    language's separator: "Alt+R、C" in Japanese (6.26).
    """
    if ", " in keys:
        first, then = keys.split(", ", 1)
        return tr("{first}、{then}").format(first=key_text(first), then=key_text(then))
    if " – " in keys:
        first, last = keys.split(" – ", 1)
        return f"{key_text(first)} – {last}"
    if keys.isascii():
        text = key_sequence(keys).toString(QKeySequence.NativeText)
        if text:
            return text
    *modifiers, last = keys.split("+")
    names = [QApplication.translate("QShortcut", name) for name in modifiers]
    return "+".join(names + [tr(last)])


