def install_qt_translations(code: str) -> bool:
    """Translate Qt's own strings into the UI language.

    The standard Yes/No/OK/Cancel buttons, the colour dialog and Qt's
    built-in context menus come from Qt, not from TRANSLATIONS, and stayed
    English in every language until this loaded Qt's catalogue for it.
    Key names come from KEY_NAMES, installed last so Qt asks it first.
    """
    app = QApplication.instance()
    if app is None:
        return False
    for translator in _QT_TRANSLATORS:
        app.removeTranslator(translator)
        translator.deleteLater()
    _QT_TRANSLATORS.clear()
    loaded = code == "en"
    # A frozen build may not report its bundled translations directory
    # through QLibraryInfo, so the copy PyInstaller unpacks is the fallback.
    for directory in (
        () if loaded else (
            QLibraryInfo.path(QLibraryInfo.TranslationsPath),
            resource_path("PySide6/translations"),
        )
    ):
        # European Portuguese has no catalogue of its own: Brazil's, with
        # the words that differ given in QT_STRINGS.
        names = (code, "pt_BR") if code == "pt_PT" else (code,)
        translator = QTranslator(app)
        if any(translator.load(f"qtbase_{name}", str(directory)) for name in names):
            app.installTranslator(translator)
            _QT_TRANSLATORS.append(translator)
            loaded = True
            break
        translator.deleteLater()
    strings = QT_STRINGS.get(code, {})
    key_names = KeyNameTranslator(KEY_NAMES.get(code, _LATIN_KEY_NAMES), app, strings)
    app.installTranslator(key_names)
    _QT_TRANSLATORS.append(key_names)
    return loaded or bool(strings)


# Every edit state a document passes through gets a number of its own, so an
# undo that comes back to the state last saved can tell (see DocumentSession).
DOCUMENT_STATE_IDS = itertools.count(1)


# ---- Undo: MuPDF's journal --------------------------------------------------
#
# Undo used to keep a copy of the whole document before every edit, which on
# a long document took most of a second an edit (1.6 s for 2,000 pages of
# text). MuPDF's journal records only the objects an edit changes. Every
# document gets a journal with an operation always open: whatever changes
# the document lands in it, and an undo or redo entry is a place in the
# journal (a JournalMark) instead of a copy.
#
# PyMuPDF 1.28 needs three repairs for that. Its check for an open journal
# operation asks MuPDF to look back through the history, which MuPDF refuses
# during an operation -- so every guarded call (fonts for text boxes,
# inserting PDF pages, updating objects) failed exactly when it was allowed.
# Its compiled new_page() and insert_pdf() make the same check; the
# equivalent pure-Python paths do not. journal_compatibility() measures the
# result, and a document keeps the old snapshots unless all of it passes.

# Files up to this size are read into memory when opened. The document then
# does not hold the file, so saving over it neither closes nor reopens the
# document -- and its journal, which is its undo history, survives the save.
OPEN_IN_MEMORY_BYTES = 256 * 1024 * 1024
_JOURNAL_OPERATION_NAMES = itertools.count(1)
_JOURNAL_AVAILABLE: bool | None = None


def _journal_have_operation(_pdf: Any) -> int:
    # MuPDF refuses any change outside an operation by itself; the check
    # PyMuPDF adds could only ever get in the way.
    return 1


def _new_page_journal_safe(self: fitz.Document, pno: int = -1, width: float = 595, height: float = 842) -> Any:
    """Document._newPage without the compiled helper, which makes the
    broken check."""
    if self.is_closed or self.is_encrypted:
        raise ValueError("document closed or encrypted")
    from pymupdf import mupdf

    pdf = fitz._as_pdf_document(self)
    mediabox = mupdf.FzRect(mupdf.FzRect.Fixed_UNIT)
    mediabox.x1 = width
    mediabox.y1 = height
    resources = mupdf.pdf_add_new_dict(pdf, 1)
    page_object = mupdf.pdf_add_page(pdf, mediabox, 0, resources, mupdf.FzBuffer())
    mupdf.pdf_insert_page(pdf, pno, page_object)
    self._reset_page_refs()
    return self[pno]


def _journalled(document: fitz.Document) -> bool:
    try:
        return bool(fitz._as_pdf_document(document).m_internal.journal)
    except Exception:
        return False


def _derotation(page: fitz.Page) -> tuple[fitz.Matrix, fitz.Rect]:
    """For a page turned 90, 180 or 270 degrees: the matrix that takes its
    coordinates back to the unturned page, and the bounds MuPDF gives that
    page. Worked out from the page's own bounds, which include UserUnit --
    PyMuPDF's derotation_matrix leaves it out and misplaces the text."""
    bounds = page.rect
    width, height = bounds.width, bounds.height
    rotation = page.rotation
    if rotation == 90:
        return fitz.Matrix(0, -1, 1, 0, 0, width), fitz.Rect(0, 0, height, width)
    if rotation == 180:
        return fitz.Matrix(-1, 0, 0, -1, width, height), fitz.Rect(0, 0, width, height)
    return fitz.Matrix(0, 1, -1, 0, height, 0), fitz.Rect(0, 0, height, width)


def _patch_pymupdf_journal() -> None:
    if getattr(fitz, "_pdfnote_journal_patched", False):
        return
    if hasattr(fitz, "JM_have_operation"):
        fitz.JM_have_operation = _journal_have_operation
    if hasattr(fitz.Document, "_newPage"):
        fitz.Document._newPage = _new_page_journal_safe

    # PyMuPDF reads the text of a turned page by setting its /Rotate to 0
    # and back: two writes, which the journal takes for a change. After an
    # undo that change cut off redo, so on a scanned document -- often
    # turned -- redo failed as soon as the page was drawn. Turning the
    # reading device instead gives the same coordinates and writes nothing.
    original_get_textpage = fitz.Page.get_textpage
    original_get_texttrace = fitz.Page.get_texttrace

    def get_textpage(self: fitz.Page, clip: Any = None, flags: int = 0, matrix: Any = None) -> Any:
        if self.rotation not in (90, 180, 270) or not _journalled(self.parent):
            return original_get_textpage(self, clip, flags, matrix)
        fitz.CheckParent(self)
        derotate, bounds = _derotation(self)
        transform = derotate * (fitz.Matrix(matrix) if matrix is not None else fitz.Matrix(1, 1))
        textpage = fitz.TextPage(
            self._get_textpage(bounds if clip is None else clip, flags=flags, matrix=transform)
        )
        textpage.parent = weakref.proxy(self)
        return textpage

    def get_texttrace(self: fitz.Page) -> list[dict]:
        if self.rotation not in (90, 180, 270) or not _journalled(self.parent):
            return original_get_texttrace(self)
        fitz.CheckParent(self)
        from pymupdf import extra, mupdf

        derotate, bounds = _derotation(self)
        trace: list[dict] = []
        device = extra.JM_new_texttrace_device(trace)
        device.ptm = mupdf.FzMatrix(1, 0, 0, -1, 0, bounds.y1)
        mupdf.fz_run_page(self.this, device, fitz.JM_matrix_from_py(derotate), mupdf.FzCookie())
        mupdf.fz_close_device(device)
        return trace

    fitz.Page.get_textpage = get_textpage
    fitz.Page.get_texttrace = get_texttrace

    # PyMuPDF deletes a link's object with pdf_delete_object(), which the
    # journal does not record: undoing the redaction that removed a link
    # put it back into the page's /Annots but not the link itself, and the
    # page referred to nothing. In a journalled document the link only
    # leaves /Annots; the object stays until a save rebuilds the file, as
    # every save after a redaction does, and garbage collection drops it.
    original_delete_link = fitz.Page.delete_link

    def delete_link(self: fitz.Page, linkdict: Any) -> Any:
        if not _journalled(self.parent):
            return original_delete_link(self, linkdict)
        from pymupdf import mupdf

        target = int(fitz._as_pdf_document(self.parent).m_internal.this)
        delete_object = mupdf.pdf_delete_object

        def keep_this_documents_objects(document: Any, number: int) -> Any:
            if int(document.m_internal.this) == target:
                return None
            return delete_object(document, number)

        mupdf.pdf_delete_object = keep_this_documents_objects
        try:
            return original_delete_link(self, linkdict)
        finally:
            mupdf.pdf_delete_object = delete_object

    fitz.Page.delete_link = delete_link
    original_insert_pdf = fitz.Document.insert_pdf

    def insert_pdf(self: fitz.Document, *args: Any, **kwargs: Any) -> Any:
        if not _journalled(self) or not hasattr(fitz, "g_use_extra"):
            return original_insert_pdf(self, *args, **kwargs)
        # The pure-Python path, for this call only. Another thread using
        # PyMuPDF meanwhile gets the same results by the same path.
        previous = fitz.g_use_extra
        fitz.g_use_extra = False
        try:
            return original_insert_pdf(self, *args, **kwargs)
        finally:
            fitz.g_use_extra = previous

    fitz.Document.insert_pdf = insert_pdf
    fitz._pdfnote_journal_patched = True


_patch_pymupdf_journal()


def journal_available() -> bool:
    """Can undo use the journal with this PyMuPDF? Measured once."""
    global _JOURNAL_AVAILABLE
    if _JOURNAL_AVAILABLE is None:
        try:
            _JOURNAL_AVAILABLE = journalling_supported()
        except Exception:
            _JOURNAL_AVAILABLE = False
    return _JOURNAL_AVAILABLE


def _next_journal_operation() -> str:
    return f"pdfnote-{next(_JOURNAL_OPERATION_NAMES)}"


# MuPDF keeps, per document, the fonts, colour spaces and images it has
# added (pdf_document.resources), so that the next text box or picture can
# use them again. The journal knows nothing of that table: undoing the edit
# that added a font takes the font out of the document, and the next edit
# used the missing object -- a text box's appearance, a form field or the
# OCR text layer then pointed at nothing, and inserting the same picture a
# second time raised. PyMuPDF keeps lists of its own of the same kind.
#
# MuPDF has no call that empties the table and leaves the document usable:
# pdf_drop_resource_tables() frees it for pdf_drop_document() and leaves
# the pointers behind. So after an undo or redo pdfNote frees it that way
# and clears the three pointers itself; MuPDF makes a new table on the next
# use. Python cannot name the table (the struct is anonymous), so where it
# lies is found once, on a throwaway document, from fields Python can set
# and read, and checked again on every document before anything is
# written. If either fails, undo keeps to snapshots (journal_compatibility).
_RESOURCE_TABLE_CHECKS = (0x5EED0001, 0x5EED0002, 0x5EED0003, 0x5EED0004)
_JOURNAL_FIELD_OFFSET: int | None = None
_JOURNAL_FIELD_SEARCHED = False
# The builds this layout has been confirmed on: (PyMuPDF, MuPDF), on a
# 64-bit little-endian process. The checks above run inside this process
# and cannot catch a read that crashes it, so on any other build the
# memory is not touched at all and undo keeps to snapshots (6.2). A new
# PyMuPDF goes here only once the functional QA passes on it.
JOURNAL_LAYOUT_TESTED = {("1.28.2", "1.28.2")}


def journal_layout_tested() -> bool:
    """Is this the PyMuPDF/MuPDF build, word size and byte order the
    resource-table layout was confirmed on?"""
    return (
        (str(getattr(fitz, "VersionBind", "")), str(getattr(fitz, "VersionFitz", "")))
        in JOURNAL_LAYOUT_TESTED
        and struct.calcsize("P") == 8
        and sys.byteorder == "little"
    )


def _struct_ints(address: int) -> tuple[int, int, int, int]:
    """num_type3_fonts, max_type3_fonts, orphans_max and orphans_count, as
    they lie before the journal pointer in pdf_document."""
    import ctypes

    read = lambda at: ctypes.c_int32.from_address(at).value
    return read(address - 64), read(address - 60), read(address - 24), read(address - 20)


def _journal_field_offset() -> int | None:
    """Where pdf_document keeps its journal pointer, counted from the start
    of the struct -- the resource table's three pointers lie 48 bytes
    before it. None when it cannot be found and confirmed."""
    global _JOURNAL_FIELD_OFFSET, _JOURNAL_FIELD_SEARCHED
    if _JOURNAL_FIELD_SEARCHED:
        return _JOURNAL_FIELD_OFFSET
    _JOURNAL_FIELD_SEARCHED = True
    if not journal_layout_tested():
        _JOURNAL_FIELD_OFFSET = None
        return None
    import ctypes

    document = fitz.open()
    try:
        document.new_page()
        document.journal_enable()
        pdf = fitz._as_pdf_document(document).m_internal
        base = int(pdf.this)
        journal = int(pdf.journal)
        start = int(pdf.lexbuf.this)
        saved = (pdf.num_type3_fonts, pdf.max_type3_fonts, pdf.orphans_max, pdf.orphans_count)
        (
            pdf.num_type3_fonts, pdf.max_type3_fonts, pdf.orphans_max, pdf.orphans_count
        ) = _RESOURCE_TABLE_CHECKS
        try:
            # The fields sit just past the 64 KB lexer buffer, and the scan
            # stops at the first match, inside the struct.
            address = start
            while address < start + 65536 + 1024:
                if ctypes.c_uint64.from_address(address).value == journal:
                    if _struct_ints(address) == _RESOURCE_TABLE_CHECKS:
                        _JOURNAL_FIELD_OFFSET = address - base
                    break
                address += 8
        finally:
            (
                pdf.num_type3_fonts, pdf.max_type3_fonts, pdf.orphans_max, pdf.orphans_count
            ) = saved
    except Exception:
        _JOURNAL_FIELD_OFFSET = None
    finally:
        document.close()
    return _JOURNAL_FIELD_OFFSET


def _forget_cached_resources(document: fitz.Document) -> bool:
    """Empty the tables MuPDF and PyMuPDF keep of objects to use again. For
    after an undo or redo, which may have taken those objects away."""
    for name, empty in (
        ("FontInfos", list), ("Graftmaps", dict), ("ShownPages", dict), ("InsertedImages", dict)
    ):
        if hasattr(document, name):
            setattr(document, name, empty())
    offset = _journal_field_offset()
    if offset is None:
        return False
    import ctypes
    from pymupdf import mupdf

    pdf = fitz._as_pdf_document(document).m_internal
    journal = int(pdf.this) + offset
    if ctypes.c_uint64.from_address(journal).value != int(pdf.journal):
        return False
    if _struct_ints(journal) != (
        pdf.num_type3_fonts, pdf.max_type3_fonts, pdf.orphans_max, pdf.orphans_count
    ):
        return False
    mupdf.ll_pdf_drop_resource_tables(pdf)
    for pointer in (journal - 48, journal - 40, journal - 32):
        ctypes.c_uint64.from_address(pointer).value = 0
    return True


class JournalMark:
    """A place in a document's journal: what an undo or redo entry holds
    instead of a copy of the document. The name of the step it follows
    tells whether the journal still leads there -- a change made after an
    undo cuts off the steps that were ahead of it."""

    __slots__ = ("document", "position", "step")

    def __init__(self, document: fitz.Document, position: int, step: str) -> None:
        self.document = document
        self.position = position
        self.step = step

    def __len__(self) -> int:
        # Nothing to count against the history's byte budget.
        return 0


def journal_attach(document: fitz.Document) -> bool:
    """Turn on the journal for `document`, with an operation open. False
    where undo has to keep to snapshots."""
    if not journal_available():
        return False
    try:
        document.journal_enable()
        document.journal_start_op(_next_journal_operation())
        return True
    except Exception:
        return False


def journal_mark(document: fitz.Document) -> JournalMark:
    """Close the open operation (a step, if it changed anything), note the
    place, and open the next one."""
    document.journal_stop_op()
    try:
        position = document.journal_position()[0]
        step = document.journal_op_name(position - 1) if position > 0 else ""
    finally:
        document.journal_start_op(_next_journal_operation())
    return JournalMark(document, position, step)


def journal_rewind(mark: JournalMark) -> bool:
    """Undo or redo `mark.document` to the place `mark` names. False, with
    nothing changed, when the journal no longer leads there."""
    document = mark.document
    if document.is_closed:
        return False
    document.journal_stop_op()
    try:
        position, total = document.journal_position()
        if mark.position > total:
            return False
        if mark.position > 0 and document.journal_op_name(mark.position - 1) != mark.step:
            return False
        while position > mark.position:
            document.journal_undo()
            position -= 1
        while position < mark.position:
            document.journal_redo()
            position += 1
        # Page objects loaded before now describe another state, and the
        # objects kept for use again may be gone.
        document._reset_page_refs()
        _forget_cached_resources(document)
        return True
    finally:
        document.journal_start_op(_next_journal_operation())


# ---- Undo: keeping the journal to what can still be undone (6.3) ------------
#
# MuPDF keeps every step of a journal until the document is closed, and has
# no call that drops the oldest ones: an undo history of 8 steps still held
# every picture ever deleted or replaced -- 30 photos of 6.4 MB put in and
# taken out again kept 210 MB. So when the steps no undo can reach any more
# hold enough to matter, the history is moved onto a copy of the document
# made at the oldest step still reachable, and the steps after it are made
# again on the copy, object by object: MuPDF writes out which objects each
# step changed (pdf_write_journal), and their values are read from the
# document as it stood after that step. The copy is then compared with the
# document, object by object; anything that does not match, and the copy
# is dropped and the document kept as it was. Only public MuPDF calls are
# used, and only on the PyMuPDF the journal's format was checked with.

_JOURNAL_FRAGMENT = re.compile(rb"(\d+) 0 (obj|newobj)\n")
_JOURNAL_LENGTH = re.compile(rb"/Length (\d+)(?![\d ]*R)")
_JOURNAL_DIRECT_LENGTH = re.compile(r"/Length \d+(?![\d ]*R)")


def _journal_dump(document: fitz.Document) -> bytes:
    """MuPDF's own account of a journal (pdf_write_journal). The document
    must have no operation open."""
    from pymupdf import mupdf

    buffer = mupdf.fz_new_buffer(1024)
    output = mupdf.FzOutput(buffer)
    mupdf.pdf_write_journal(fitz._as_pdf_document(document), output)
    mupdf.fz_close_output(output)
    return bytes(mupdf.fz_buffer_extract(buffer))


def parse_journal_dump(data: bytes) -> list[tuple[str, list[int], int]] | None:
    """The steps of a journal written by pdf_write_journal: (name, numbers
    of the objects it changed, bytes it holds) for each. None for anything
    that is not exactly that format -- nothing is guessed."""
    if not data.startswith(b"%!MuPDF-Journal-100\n"):
        return None
    head_end = data.find(b">>\n", data.find(b"\njournal\n<<"))
    if head_end < 0:
        return None
    at = head_end + 3
    steps: list[tuple[str, list[int], int]] = []
    while True:
        if data.startswith(b"endjournal", at):
            return steps
        if not data.startswith(b"entry\n(", at):
            return None
        title_end = data.find(b")\n", at + 7)
        if title_end < 0:
            return None
        title = data[at + 7:title_end]
        if b"\\" in title or b"(" in title:
            return None  # pdfNote's names are plain; anything else is not read
        start = at
        at = title_end + 2
        numbers: list[int] = []
        while True:
            match = _JOURNAL_FRAGMENT.match(data, at)
            if match is None:
                break
            numbers.append(int(match.group(1)))
            at = match.end()
            if match.group(2) == b"newobj":
                continue
            line_end = data.find(b"\n", at)
            if line_end < 0:
                return None
            text = data[at:line_end]
            at = line_end + 1
            if data.startswith(b"endobj\n", at):
                at += 7
                continue
            if not data.startswith(b"stream\n", at):
                return None
            at += 7
            ending = b"\nendstream\nendobj\n"
            length = _JOURNAL_LENGTH.search(text)
            end = at + int(length.group(1)) if length else -1
            if end < 0 or not data.startswith(ending, end):
                end = data.find(ending, at)
                if end < 0:
                    return None
            at = end + len(ending)
        steps.append((title.decode("latin-1"), numbers, at - start))


def journal_steps(document: fitz.Document) -> list[tuple[str, list[int], int]] | None:
    """parse_journal_dump() of `document`'s journal, checked against what
    the journal says of itself: as many steps, under the same names. The
    document must have no operation open."""
    try:
        steps = parse_journal_dump(_journal_dump(document))
        _position, total = document.journal_position()
        if steps is None or len(steps) != total:
            return None
        if any(document.journal_op_name(index) != steps[index][0] for index in range(total)):
            return None
        return steps
    except Exception:
        return None


def _object_state(document: fitz.Document, number: int) -> tuple[str, bytes | None]:
    """An object as text, with its stream as stored; ("null", None) for one
    that does not exist."""
    if not 0 < number < document.xref_length():
        return "null", None
    try:
        text = document.xref_object(number, compressed=True) or "null"
    except Exception:
        return "null", None
    try:
        stream = document.xref_stream_raw(number) if document.xref_is_stream(number) else None
    except Exception:
        stream = None
    if stream is not None:
        # The data is compared itself. Its stated length is how much an
        # encrypted file stores, padding and all, until the document is
        # written again.
        text = _JOURNAL_DIRECT_LENGTH.sub("", text)
    return text, stream


def _copy_object(source: fitz.Document, target: fitz.Document, number: int) -> None:
    """Make object `number` of `target` what it is in `source`, stream and
    all, as a change in the step open on `target`.

    Replacing an object whole (pdf_update_object) is not recorded by the
    journal: MuPDF records an object when a dictionary or array belonging
    to it is altered, keeping its value from before. So a key is first put
    into a scratch dictionary that names the object as its owner -- MuPDF
    then keeps the object as it is, as for any change -- and only then is
    it replaced."""
    from pymupdf import mupdf

    pdf = fitz._as_pdf_document(target)
    while target.xref_length() <= number:
        target.get_new_xref()
    scratch = mupdf.pdf_new_dict(pdf, 1)
    mupdf.pdf_set_obj_parent(scratch, number)
    mupdf.pdf_dict_put(scratch, mupdf.pdf_new_name("PdfNoteRebase"), mupdf.pdf_new_int(1))
    text, stream = _object_state(source, number)
    if stream is None and target.xref_is_stream(number):
        # A stream that is one no longer: only deleting the object lets go
        # of its data. What it was is kept for undo already.
        mupdf.pdf_delete_object(pdf, number)
    target.update_object(number, text)
    if stream is not None:
        # Stored as it is: its /Filter, copied with the dictionary, still
        # describes it.
        mupdf.pdf_update_stream(
            pdf, mupdf.pdf_new_indirect(pdf, number, 0),
            mupdf.fz_new_buffer_from_copied_data(stream), 1,
        )


def same_document_state(first: fitz.Document, second: fitz.Document) -> bool:
    """Do two documents hold the same objects under the same numbers? The
    object streams and cross-reference streams of the file one was read
    from are left out: they are how a file is stored, not what it holds."""
    if len(first) != len(second):
        return False
    for key in ("Root", "Info"):
        if first.xref_get_key(-1, key) != second.xref_get_key(-1, key):
            return False
    for number in range(1, max(first.xref_length(), second.xref_length())):
        one, two = _object_state(first, number), _object_state(second, number)
        if one == two:
            continue
        storage = ("/Type/ObjStm", "/Type/XRef")
        if any(kind in text for text in (one[0], two[0]) for kind in storage) and "null" in (one[0], two[0]):
            continue
        return False
    return True


def rebase_journal(
    document: fitz.Document,
    keep_from: int,
    keep_to: int,
    steps: list[tuple[str, list[int], int]],
    password: str | None = None,
) -> fitz.Document | None:
    """A copy of `document` in the same state, whose journal holds only
    its steps from `keep_from` to `keep_to`, under the same names. None,
    with `document` back where it was, when the copy does not come out
    the same. `document` must have no operation open; the copy has none
    open either."""
    position, total = document.journal_position()
    if not (0 <= keep_from <= position <= keep_to <= total) or len(steps) != total:
        return None
    copy: fitz.Document | None = None
    try:
        for _ in range(position - keep_from):
            document.journal_undo()
        copy = fitz.open(
            stream=serialize_document(document, compact=False, collect=False), filetype="pdf"
        )
        if copy.needs_pass and not (password and copy.authenticate(password)):
            raise RuntimeError("the copy could not be unlocked")
        copy.journal_enable()
        for index in range(keep_from, keep_to):
            document.journal_redo()
            copy.journal_start_op(steps[index][0])
            for number in dict.fromkeys(steps[index][1]):
                _copy_object(document, copy, number)
            copy.journal_stop_op()
        if tuple(copy.journal_position()) != (keep_to - keep_from, keep_to - keep_from):
            raise RuntimeError("the copy's history has another length")
        for _ in range(keep_to - position):
            document.journal_undo()
            copy.journal_undo()
        copy._reset_page_refs()
        if not same_document_state(document, copy):
            raise RuntimeError("the copy is not the same")
        return copy
    except Exception:
        if copy is not None:
            try:
                copy.close()
            except Exception:
                pass
        try:
            current = document.journal_position()[0]
            while current > position:
                document.journal_undo()
                current -= 1
            while current < position:
                document.journal_redo()
                current += 1
            document._reset_page_refs()
        except Exception:
            pass
        return None


def process_memory_bytes() -> int | None:
    """Memory this process holds: private bytes on Windows, the resident
    set elsewhere; None when it cannot be told."""
    try:
        if sys.platform == "win32":
            import ctypes
            from ctypes import wintypes

            class Counters(ctypes.Structure):
                _fields_ = [
                    ("cb", wintypes.DWORD), ("PageFaultCount", wintypes.DWORD),
                    ("PeakWorkingSetSize", ctypes.c_size_t), ("WorkingSetSize", ctypes.c_size_t),
                    ("QuotaPeakPagedPoolUsage", ctypes.c_size_t), ("QuotaPagedPoolUsage", ctypes.c_size_t),
                    ("QuotaPeakNonPagedPoolUsage", ctypes.c_size_t),
                    ("QuotaNonPagedPoolUsage", ctypes.c_size_t),
                    ("PagefileUsage", ctypes.c_size_t), ("PeakPagefileUsage", ctypes.c_size_t),
                ]

            kernel32 = ctypes.WinDLL("kernel32")
            kernel32.GetCurrentProcess.restype = wintypes.HANDLE
            kernel32.K32GetProcessMemoryInfo.argtypes = (
                wintypes.HANDLE, ctypes.POINTER(Counters), wintypes.DWORD,
            )
            kernel32.K32GetProcessMemoryInfo.restype = wintypes.BOOL
            counters = Counters()
            counters.cb = ctypes.sizeof(Counters)
            if kernel32.K32GetProcessMemoryInfo(
                kernel32.GetCurrentProcess(), ctypes.byref(counters), counters.cb
            ):
                return int(counters.PagefileUsage)
            return None
        with open("/proc/self/statm", encoding="ascii") as statm:
            return int(statm.read().split()[1]) * os.sysconf("SC_PAGE_SIZE")
    except Exception:
        return None


def open_pdf(path: str) -> fitz.Document:
    """Open a PDF file: into memory up to OPEN_IN_MEMORY_BYTES, so that
    the document does not hold the file; beyond that, read from the file
    as it is needed."""
    try:
        size = Path(path).stat().st_size
    except OSError:
        size = OPEN_IN_MEMORY_BYTES + 1
    if size <= OPEN_IN_MEMORY_BYTES:
        # No file type given: MuPDF looks at the content, as it does for a
        # file, so an image named .pdf is still told apart from a PDF.
        return fitz.open(stream=Path(path).read_bytes())
    return fitz.open(path)


@dataclass
class DocumentSession:
    document: fitz.Document
    file_path: str
    password: str | None = None
    page_index: int = 0
    zoom_mode: str = "fit_width"
    zoom_percent: int = 100
    extra_rotation: int = 0
    search_query: str = ""
    search_hits: list[tuple[int, fitz.Rect, str]] = field(default_factory=list)
    search_by_page: dict[int, list[fitz.Rect]] = field(default_factory=dict)
    current_match_index: int = -1
    # The page a search still running had reached when the tab was left.
    search_resume_page: int | None = None
    page_layout: str = "single"
    # Read when the session is made, so the test suite can pin the view.
    continuous: bool = field(default_factory=lambda: DEFAULT_CONTINUOUS_SCROLL)
    facing_cover_separate: bool = True
    # Where this tab left each viewer, as (horizontal, vertical). Both
    # scroll areas belong to the window and are shared by every tab, so
    # without this a tab arrived at whatever offset the one before it had
    # and lost its own.
    scroll_offset: tuple[int, int] = (0, 0)
    page_scroll_offset: tuple[int, int] = (0, 0)
    # (JournalMark -- or the document's bytes where the journal cannot be
    # used -- page index, state id); see _push_history.
    undo_stack: list[tuple] = field(default_factory=list)
    redo_stack: list[tuple] = field(default_factory=list)
    # Whether this document's undo runs on MuPDF's journal.
    journal: bool = False
    # Counts undos and redos. A background job (OCR) that started before
    # one no longer knows what the pages hold.
    history_generation: int = 0
    # Set once a snapshot of this document proves too big to hold; further
    # edits then skip serialising it entirely instead of paying the cost
    # again for a snapshot that would only be thrown away.
    history_suspended: bool = False
    history_notified: bool = False
    # The journal's upkeep (compact_history): steps since it was last looked
    # at, how large the process was then, and whether an edit has started
    # and not yet been marked done -- the journal is not touched meanwhile.
    journal_steps_since_check: int = 0
    journal_memory_at_check: int = 0
    edit_open: bool = False
    # Holds pages taken from a PDF with usage restrictions that this
    # document does not inherit; update_document_notices() says so.
    pages_from_protected_pdf: bool = False
    # The outline's sections folded in the Pages tab and in the annotations
    # tab (6.9), by their keys (see outline_sections) -- since 6.14 in the
    # オブジェクト tab, and in the 文字装飾 tab the marks' own.
    folded_page_sections: set[int] = field(default_factory=set)
    folded_note_sections: set[int] = field(default_factory=set)
    folded_mark_sections: set[int] = field(default_factory=set)
    dirty: bool = False
    # Bumped on every edit; the auto-save tick compares it against the
    # revision it last wrote so an idle document is never re-serialised.
    revision: int = 0
    autosaved_revision: int = -1
    # The revision handed to the writer and not yet confirmed written. Only
    # a confirmed write counts as saved: a failed one is tried again.
    autosave_pending_revision: int = -1
    # The edit state the document is in, and the one last saved. Undoing
    # back to the saved state makes the document clean again; the
    # unsaved-changes mark used to stay whatever was undone.
    state_id: int = 0
    saved_state_id: int = 0
    # Set once redactions have been applied: the next save must rebuild the
    # file with garbage collection so nothing removed can be recovered.
    needs_full_rewrite: bool = False
    recovery_id: str = field(default_factory=lambda: uuid.uuid4().hex)
    # (bytes on disk, bytes once saved) for a file an older pdfNote made
    # larger than it needs to be; the notice bar offers to save it (6.1).
    shrink_estimate: tuple[int, int] | None = None

    def __post_init__(self) -> None:
        # A new, merged or recovered document was never saved as it is.
        if self.dirty:
            self.saved_state_id = -1

    @property
    def title(self) -> str:
        marker = " *" if self.dirty else ""
        return f"{Path(self.file_path).name if self.file_path else tr('無題.pdf')}{marker}"


class OcrWorker(QObject):
    """Runs Tesseract over a copy of the document.

    It never touches the document the window has open: it works on its own
    copy of the bytes and hands back plain word rectangles for the window
    to apply. It runs in a process of its own (ocr_worker_main, started by
    OcrProcess): it used to run on a thread of pdfNote's, and PyMuPDF does
    not support being used from two threads at once -- separate documents
    or not, the library underneath is one (6.2).
    """

    pageReady = Signal(int, object)
    progress = Signal(int, int)
    # Emitted before `finished` when nothing could be recognised because of
    # an error (missing language data, a document that would not open...).
    # Without it a failed run ended as "OCR finished (0 pages)".
    failed = Signal(str)
    finished = Signal(bool)

    def __init__(
        self,
        data: bytes,
        page_indices: list[int],
        language: str = "eng",
        tessdata: str | None = None,
        skip_threshold: int | None = None,
        password: str | None = None,
    ) -> None:
        super().__init__()
        self._data = data
        self._pages = list(page_indices)
        self._language = language
        self._tessdata = tessdata
        # The copy keeps the document's encryption (serialize_document is the
        # one serializer and always preserves it), so a password-protected
        # document arrives here locked and has to be opened with the password
        # the user typed.
        self._password = password
        # Pages with at least this much text already are skipped here, on
        # this thread, rather than checked one by one on the GUI thread.
        self._skip_threshold = skip_threshold
        # How many pages turned out to need OCR.
        self.candidates = 0
        self._cancelled = False

    def cancel(self) -> None:
        self._cancelled = True

    @staticmethod
    def _has_text(page: fitz.Page, threshold: int) -> bool:
        try:
            return len(page.get_text().strip()) >= threshold
        except Exception:
            return False

    def events(self) -> Iterable[dict[str, Any]]:
        """The run, as the events it produces: {"page": index, "words": [...]},
        {"progress": [done, total]}, {"candidates": count} and, when nothing
        could be recognised because of an error, {"failed": message}."""
        total = len(self._pages)
        document = None
        first_error = ""
        recognised = 0
        try:
            document = fitz.open(stream=self._data, filetype="pdf")
            if document.needs_pass:
                if not self._password or not document.authenticate(self._password):
                    raise RuntimeError("could not unlock the copy of the document")
            for done, page_index in enumerate(self._pages, start=1):
                if self._cancelled:
                    break
                try:
                    page = document[page_index]
                    if self._skip_threshold is not None and self._has_text(page, self._skip_threshold):
                        yield {"progress": [done, total]}
                        continue
                    self.candidates += 1
                    yield {"candidates": self.candidates}
                    words = PDFReaderWindow._ocr_words(
                        page, language=self._language, tessdata=self._tessdata
                    )
                except Exception as exc:
                    words = []
                    first_error = first_error or str(exc)
                if words:
                    recognised += 1
                    yield {"page": page_index, "words": [list(word) for word in words]}
                yield {"progress": [done, total]}
        except Exception as exc:
            first_error = first_error or str(exc)
        finally:
            if document is not None:
                try:
                    document.close()
                except Exception:
                    pass
        if first_error and not recognised and not self._cancelled:
            yield {"failed": first_error}

    def run(self) -> None:
        """events() as signals, on the calling thread."""
        for event in self.events():
            if "page" in event:
                self.pageReady.emit(int(event["page"]), [tuple(word) for word in event["words"]])
            elif "progress" in event:
                self.progress.emit(*event["progress"])
            elif "failed" in event:
                self.failed.emit(str(event["failed"]))
        self.finished.emit(self._cancelled)


# ---- what a child process leaves when it ends early (6.23) -------------
# An export now and then ended "early, exit code 0" in the long test runs
# (6.18-6.22), and left nothing to go on. Each child -- OCR's, the export's
# -- now keeps a fault.log of its own in its job folder: faulthandler's
# account of every thread if it crashes outside Python, and a line for each
# step it gets to. When it ends without saying it has finished, the window
# keeps that file in crash.log with how the child ended -- on this PC only,
# as with pdfNote's own (6.21). Nothing is sent.
WORKER_FAULT_LOG = "fault.log"


def record_worker_faults(folder: Path, kind: str) -> Any:
    """Start the child's fault.log; the handle to write its steps to."""
    try:
        handle = open(folder / WORKER_FAULT_LOG, "w", encoding="utf-8")
        handle.write(f"{datetime.now().isoformat()} {APP_NAME} {APP_VERSION} {kind} pid {os.getpid()}\n")
        handle.flush()
    except OSError:
        return None
    faulthandler.enable(file=handle, all_threads=True)
    return handle


def worker_step(handle: Any, step: str) -> None:
    if handle is None:
        return
    try:
        handle.write(f"{datetime.now().isoformat()} {step}\n")
        handle.flush()
    except (OSError, ValueError):
        pass


def stop_worker_faults(handle: Any) -> None:
    if handle is None:
        return
    faulthandler.disable()
    try:
        handle.close()
    except OSError:
        pass


def worker_fault_record(child: Any) -> str:
    """What the child's own fault.log says."""
    folder = child._folder
    if folder is None:
        return ""
    try:
        return (folder / WORKER_FAULT_LOG).read_text(encoding="utf-8", errors="replace").rstrip()
    except OSError:
        return f"(no {WORKER_FAULT_LOG})"


def worker_crashed(child: Any) -> bool:
    """Whether a child crashed: as QProcess sees it, or as its fault.log
    says. On Windows a fatal signal that faulthandler reported ("Fatal
    Python error: Segmentation fault") ends the child through the C
    runtime's abort, exit code 3, which QProcess takes for an ordinary
    end: the crash was kept as "exited, exit code 3" (6.29)."""
    if child._process.exitStatus() == QProcess.CrashExit:
        return True
    record = worker_fault_record(child)
    return "Fatal Python error" in record or "Windows fatal exception" in record


def worker_exit_text(child: Any) -> str:
    """How a child ended, as the message gives its code: a crash's in
    hexadecimal, the way Windows writes it (0xC0000005)."""
    code = child._process.exitCode()
    if worker_crashed(child) or not 0 <= code <= 255:
        return f"0x{code & 0xFFFFFFFF:08X}"
    return str(code)


def keep_worker_fault(child: Any, kind: str) -> None:
    """A child that ended without saying it had finished: how it ended, the
    kinds of its last events and its fault.log, into crash.log. What it
    wrote of the document (the words OCR read) stays out."""
    folder = child._folder
    if folder is None:
        return
    record = worker_fault_record(child)
    try:
        events = (folder / "out.jsonl").read_bytes()
    except OSError:
        events = b""
    kinds = []
    for line in events.splitlines()[-5:]:
        try:
            kinds.append(",".join(sorted(json.loads(line.decode("utf-8")))))
        except (ValueError, UnicodeDecodeError, TypeError):
            kinds.append("?")
    status = "crashed" if worker_crashed(child) else "exited"
    write_crash_log(
        f"{datetime.now().isoformat()} {APP_NAME} {APP_VERSION} -- the {kind} process ended early: "
        f"{status}, exit code {worker_exit_text(child)}, out.jsonl {len(events)} bytes, "
        f"last events [{' | '.join(kinds)}]\n{record}\n\n"
    )


def ocr_worker_main(job: str) -> int:
    """`pdfNote --ocr-worker <folder>`: the OCR of one run, in a process of
    its own. The folder holds the copy of the document (input.pdf) and the
    run's settings (job.json); the events of OcrWorker.events() go to
    out.jsonl, one JSON object a line, each flushed as soon as it is known,
    and the last line is {"finished": true}. A protected copy is unlocked
    with the password in OCR_PASSWORD_VARIABLE."""
    folder = Path(job)
    faults = record_worker_faults(folder, "OCR")
    with open(folder / "out.jsonl", "a", encoding="utf-8") as out:

        def send(event: dict[str, Any]) -> None:
            out.write(json.dumps(event, ensure_ascii=False) + "\n")
            out.flush()

        try:
            settings = json.loads((folder / "job.json").read_text(encoding="utf-8"))
            worker_step(faults, f"reading {len(settings.get('pages', []))} pages")
            worker = OcrWorker(
                (folder / "input.pdf").read_bytes(),
                [int(index) for index in settings.get("pages", [])],
                str(settings.get("language") or "eng"),
                settings.get("tessdata"),
                skip_threshold=settings.get("skip_threshold"),
                password=os.environ.get(OCR_PASSWORD_VARIABLE) or None,
            )
            for event in worker.events():
                if "progress" in event:
                    worker_step(faults, "page {} of {}".format(*event["progress"]))
                send(event)
        except Exception as exc:
            worker_step(faults, f"failed: {exc.__class__.__name__}")
            send({"failed": str(exc) or exc.__class__.__name__})
        send({"finished": True})
        worker_step(faults, "said it has finished")
    stop_worker_faults(faults)
    return 0


def read_last_events(child: Any, seconds: float = 2.0) -> None:
    """Read what a child process (OcrProcess, ExportProcess) wrote last,
    once it has gone. Its last line says it finished; until that is read,
    the file is read again for a moment, a failed read passed over. Once,
    on the Windows QA (6.18), a PowerPoint export that had run its usual
    time was reported cut short with exit code 0; why that last read found
    nothing is not known (6.19)."""
    child._read_events()
    deadline = time.monotonic() + seconds
    while not child._worker_finished and not child._cancelled and time.monotonic() < deadline:
        time.sleep(0.05)
        child._read_events()


class OcrProcess(QObject):
    """An OCR run in a process of its own, with OcrWorker's signals.

    The copy of the document and the settings go into a private temporary
    folder, the child (ocr_worker_main) writes its events to a file there,
    and they are read back every 150 ms and turned into signals on the GUI
    thread -- which is the only thread of pdfNote that ever uses PyMuPDF
    (6.2). Cancelling ends the child at once. The folder goes when the run
    ends."""

    pageReady = Signal(int, object)
    progress = Signal(int, int)
    failed = Signal(str)
    finished = Signal(bool)
    # The test suite runs a stand-in worker instead of pdfNote's own; the
    # folder is appended to this command.
    command_override: list[str] | None = None

    def __init__(
        self,
        data: bytes,
        page_indices: list[int],
        language: str = "eng",
        tessdata: str | None = None,
        skip_threshold: int | None = None,
        password: str | None = None,
        parent: QObject | None = None,
    ) -> None:
        super().__init__(parent)
        self._data = data
        self._pages = list(page_indices)
        self._language = language
        self._tessdata = tessdata
        self._skip_threshold = skip_threshold
        self._password = password
        self.candidates = 0
        self._cancelled = False
        self._ended = False
        self._worker_finished = False
        self._read_offset = 0
        self._pending = b""
        self._folder: Path | None = None
        self._process = QProcess(self)
        self._process.finished.connect(self._process_finished)
        self._process.errorOccurred.connect(self._process_error)
        self._timer = QTimer(self)
        self._timer.setInterval(150)
        self._timer.timeout.connect(self._read_events)

    @staticmethod
    def command() -> list[str]:
        """pdfNote itself, in its OCR worker mode."""
        if getattr(sys, "frozen", False):
            return [sys.executable, "--ocr-worker"]
        return [sys.executable, str(Path(__file__).resolve()), "--ocr-worker"]

    def start(self) -> None:
        try:
            self._folder = Path(tempfile.mkdtemp(prefix="pdfnote-ocr-"))
            (self._folder / "input.pdf").write_bytes(self._data)
            (self._folder / "job.json").write_text(
                json.dumps(
                    {
                        "pages": self._pages,
                        "language": self._language,
                        "tessdata": self._tessdata,
                        "skip_threshold": self._skip_threshold,
                    }
                ),
                encoding="utf-8",
            )
            (self._folder / "out.jsonl").write_bytes(b"")
        except OSError as exc:
            # Read now: Python forgets `exc` when the except clause ends, and
            # the call below runs after it -- the failure was never told.
            message = str(exc)
            QTimer.singleShot(0, self, lambda: (self.failed.emit(message), self._end()))
            return
        self._data = b""
        environment = QProcessEnvironment.systemEnvironment()
        environment.remove(OCR_PASSWORD_VARIABLE)
        if self._password:
            environment.insert(OCR_PASSWORD_VARIABLE, self._password)
        self._process.setProcessEnvironment(environment)
        self._process.setProcessChannelMode(QProcess.ForwardedErrorChannel)
        program, *arguments = list(self.command_override or self.command()) + [str(self._folder)]
        self._timer.start()
        self._process.start(program, arguments)

    def cancel(self) -> None:
        self._cancelled = True
        if self._process.state() != QProcess.NotRunning:
            self._process.kill()

    def running(self) -> bool:
        return not self._ended

    def stop(self) -> None:
        """End the run without a word: the window is going."""
        self._cancelled = True
        self._ended = True
        self._timer.stop()
        if self._process.state() != QProcess.NotRunning:
            self._process.kill()
            self._process.waitForFinished(3000)
        self._remove_folder()

    def _read_events(self) -> None:
        if self._folder is None or self._ended:
            return
        try:
            with open(self._folder / "out.jsonl", "rb") as stream:
                stream.seek(self._read_offset)
                chunk = stream.read()
        except OSError:
            return
        self._read_offset += len(chunk)
        lines = (self._pending + chunk).split(b"\n")
        self._pending = lines.pop()
        for line in lines:
            if not line.strip():
                continue
            try:
                event = json.loads(line.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                continue
            if self._cancelled:
                continue  # nothing more is applied once cancelled
            if "page" in event:
                words = [tuple(word) for word in event.get("words") or []]
                self.pageReady.emit(int(event["page"]), words)
            elif "progress" in event:
                done, total = event["progress"]
                self.progress.emit(int(done), int(total))
            elif "candidates" in event:
                self.candidates = int(event["candidates"])
            elif "failed" in event:
                self.failed.emit(str(event["failed"]))
            elif event.get("finished"):
                self._worker_finished = True

    def _process_finished(self, *_args: Any) -> None:
        if self._ended:
            return
        read_last_events(self)
        if not self._worker_finished and not self._cancelled:
            keep_worker_fault(self, "OCR")
            self.failed.emit(
                tr("OCRの処理が途中で終了しました（終了コード {code}）").format(
                    code=worker_exit_text(self)
                )
            )
        self._end()

    def _process_error(self, error: Any) -> None:
        if error == QProcess.FailedToStart and not self._ended:
            self.failed.emit(self._process.errorString())
            self._end()

    def _end(self) -> None:
        if self._ended:
            return
        self._ended = True
        self._timer.stop()
        self._remove_folder()
        self.finished.emit(self._cancelled)

    def _remove_folder(self) -> None:
        if self._folder is not None:
            shutil.rmtree(self._folder, ignore_errors=True)
            self._folder = None


# ---- Export to Word, PowerPoint and Excel (6.7) -----------------------------
#
# File > Export writes the document as the screen shows it -- annotations and
# filled-in form fields drawn into the pages -- as a Word document, a
# PowerPoint presentation or an Excel workbook. It runs in a process of its
# own, as OCR does (export_worker_main, started by ExportProcess): the
# converters read the pages with PyMuPDF, which must not run on two threads,
# and a long document takes minutes.
#
# - Word: pdf2docx rebuilds the pages as paragraphs, tables and pictures in
#   sections of the page's size. A scanned page with an OCR layer becomes
#   its recognised text.
# - PowerPoint: a slide a page. The page without its text is the slide's
#   picture, and the text is laid over it in text boxes where the page shows
#   it, in its size, colour and weight, so it can be edited.
# - Excel: a sheet a page. Tables become cells with their borders, fills and
#   merged cells, figures become numbers with their format, the other text
#   goes in the cells where it stands, and pictures where they are.
#
# Fonts the PDF names that this PC does not have are replaced with the
# nearest one it has, so Office does not pick one of its own.

EXPORT_PASSWORD_VARIABLE = "PDFNOTE_EXPORT_PASSWORD"

# By the suffix of the file each writes. The name is the one the File menu,
# the dialogs and the messages use.
EXPORT_FORMATS: dict[str, dict[str, str]] = {
    "docx": {"name": "Word 文書", "filter": "Word 文書 (*.docx)"},
    "pptx": {"name": "PowerPoint プレゼンテーション", "filter": "PowerPoint プレゼンテーション (*.pptx)"},
    "xlsx": {"name": "Excel ブック", "filter": "Excel ブック (*.xlsx)"},
}

# A PDF's font, by its name without the subset prefix, and the Windows font
# that is the same face. The P (proportional) faces come before the others,
# which their names contain.
EXPORT_KNOWN_FONTS: tuple[tuple[str, str], ...] = (
    # Japanese names are written as escapes, so that they are not taken for
    # text the screen shows (the translation check reads every string).
    (r"biz\W*ud\W*p\W*(gothic|\u30b4\u30b7\u30c3\u30af)", "BIZ UDPGothic"),  # BIZ UDPゴシック
    (r"biz\W*ud\W*(gothic|\u30b4\u30b7\u30c3\u30af)", "BIZ UDGothic"),
    (r"biz\W*ud\W*p\W*(mincho|\u660e\u671d)", "BIZ UDPMincho"),  # BIZ UDP明朝
    (r"biz\W*ud\W*(mincho|\u660e\u671d)", "BIZ UDMincho"),
    (r"yu\W*gothic\W*ui", "Yu Gothic UI"),
    (r"yu\W*gothic|\u6e38\u30b4\u30b7\u30c3\u30af", "Yu Gothic"),  # 游ゴシック
    (r"yu\W*mincho|\u6e38\u660e\u671d", "Yu Mincho"),  # 游明朝
    (r"meiryo\W*ui", "Meiryo UI"),
    (r"meiryo|\u30e1\u30a4\u30ea\u30aa", "Meiryo"),  # メイリオ
    (r"ms\W*p\W*gothic|\uff2d\uff33\s*\uff30\u30b4\u30b7\u30c3\u30af", "MS PGothic"),  # ＭＳ Ｐゴシック
    (r"ms\W*gothic|\uff2d\uff33\s*\u30b4\u30b7\u30c3\u30af", "MS Gothic"),  # ＭＳ ゴシック
    (r"ms\W*p\W*mincho|\uff2d\uff33\s*\uff30\u660e\u671d", "MS PMincho"),  # ＭＳ Ｐ明朝
    (r"ms\W*mincho|\uff2d\uff33\s*\u660e\u671d", "MS Mincho"),  # ＭＳ 明朝
    (r"malgun", "Malgun Gothic"),
    (r"yahei", "Microsoft YaHei"),
    (r"jhenghei", "Microsoft JhengHei"),
    (r"simsun", "SimSun"),
    (r"simhei", "SimHei"),
    (r"arial\W*narrow", "Arial Narrow"),
    (r"arial|helvetica", "Arial"),
    (r"calibri", "Calibri"),
    (r"cambria", "Cambria"),
    (r"segoe\W*ui", "Segoe UI"),
    (r"century\W*gothic", "Century Gothic"),
    (r"century", "Century"),
    (r"georgia", "Georgia"),
    (r"verdana", "Verdana"),
    (r"tahoma", "Tahoma"),
    (r"consolas", "Consolas"),
    (r"courier", "Courier New"),
    (r"times", "Times New Roman"),
    (r"symbol", "Symbol"),
)
# What stands in for a face this PC does not have, by script and style, in
# order of preference.
EXPORT_FALLBACK_FONTS: dict[tuple[str, str], tuple[str, ...]] = {
    ("ja", "sans"): ("Yu Gothic", "Meiryo", "MS Gothic"),
    ("ja", "serif"): ("Yu Mincho", "MS Mincho"),
    ("zh_CN", "sans"): ("Microsoft YaHei", "SimHei"),
    ("zh_CN", "serif"): ("SimSun",),
    ("zh_TW", "sans"): ("Microsoft JhengHei",),
    ("zh_TW", "serif"): ("PMingLiU", "MingLiU"),
    ("ko", "sans"): ("Malgun Gothic", "Gulim"),
    ("ko", "serif"): ("Batang",),
    ("latin", "sans"): ("Arial",),
    ("latin", "serif"): ("Times New Roman",),
    ("latin", "mono"): ("Consolas", "Courier New"),
}
EXPORT_SERIF_WORDS = re.compile(
    r"mincho|\u660e\u671d|serif|ming|song|batang|myeongjo|times|roman|georgia|garamond|century|"
    r"book|kai|fangsong|kozmin|ryumin|hiramin|heiseimin",
    re.IGNORECASE,
)
EXPORT_SANS_WORDS = re.compile(
    r"gothic|\u30b4\u30b7\u30c3\u30af|sans|hei|kaku|gulim|dotum|goth", re.IGNORECASE
)
EXPORT_MONO_WORDS = re.compile(r"mono|courier|consolas|code", re.IGNORECASE)
EXPORT_CJK_FACE = re.compile(
    r"biz\W*ud|yu\W*(gothic|mincho)|meiryo|ms\W*p?\W*(gothic|mincho)|ms\W*ui\W*gothic|malgun|"
    r"yahei|jhenghei|simsun|simhei|mingliu|gulim|batang|dotum|nanum|cjk|source\W*han|"
    r"koz(min|go)|hiragino|hira(kaku|min|maru)|ryumin|midashi|shingo|futogo|gothicbbb|"
    r"heisei(min|kaku)|takao|ipa\W*(ex|p)?\W*(gothic|mincho)|vl\W*gothic|ud\W*(digi|shin)|"
    r"(jp|sc|tc|kr|hk)(?![a-z])|(?<![a-z])(JP|SC|TC|KR|HK)|"
    r"[\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af\uff00-\uffef]",
    re.IGNORECASE,
)
EXPORT_SUBSET_PREFIX = re.compile(r"^[A-Z]{6}\+")
# A PDF point in EMU, the unit of Office's drawings.
EXPORT_EMU_PER_POINT = 12700


def _export_script_of(name: str) -> str:
    """Which script a Japanese, Chinese or Korean face is made for, by its
    name ("SC", "TC", "KR" and the like are case-sensitive marks)."""
    lowered = name.lower()
    if re.search(r"korean|gulim|dotum|nanum|batang|myeongjo|malgun", lowered) or re.search(
        r"(KR|Kr)(?![a-z])", name
    ):
        return "ko"
    if re.search(r"jhenghei|mingliu|big5|traditional", lowered) or re.search(
        r"(TC|HK|TW)(?![a-z])", name
    ):
        return "zh_TW"
    if re.search(r"yahei|simsun|simhei|dengxian|simplified|fangsong|kaiti", lowered) or re.search(
        r"(SC|GB|CN)(?![a-z])", name
    ):
        return "zh_CN"
    return "ja"


def export_font_faces(pdf_font: str, installed: set[str] | None) -> tuple[str, str]:
    """The font a PDF names, as Office should name it: (the face for Latin
    text, the face for Japanese, Chinese and Korean). A face this PC has is
    kept; one it lacks becomes the nearest one it has. `installed` is None
    when that is not known, and then every face counts as there."""
    name = EXPORT_SUBSET_PREFIX.sub("", pdf_font or "").strip()
    folded = {face.casefold() for face in installed} if installed is not None else None

    def have(face: str) -> bool:
        return folded is None or face.casefold() in folded

    def fallback(script: str, style: str) -> str:
        choices = EXPORT_FALLBACK_FONTS.get((script, style)) or EXPORT_FALLBACK_FONTS[(script, "sans")]
        return next((face for face in choices if have(face)), choices[0])

    serif = EXPORT_SERIF_WORDS.search(name) and not EXPORT_SANS_WORDS.search(name)
    style = "serif" if serif else "sans"
    east_asian = fallback(_export_script_of(name), style)
    known = next(
        (face for pattern, face in EXPORT_KNOWN_FONTS if re.search(pattern, name, re.IGNORECASE)),
        None,
    )
    face = known or name
    if face and have(face):
        # A Japanese, Chinese or Korean face draws Latin letters too; a
        # Latin one leaves those scripts to the stand-in.
        return face, (face if EXPORT_CJK_FACE.search(face) else east_asian)
    if EXPORT_CJK_FACE.search(name):
        # Its Latin letters were its own: the stand-in draws both.
        return east_asian, east_asian
    return fallback("latin", "mono" if EXPORT_MONO_WORDS.search(name) else style), east_asian


def export_source(data: bytes, password: str | None = None) -> fitz.Document:
    """The document to export: a copy, unlocked, with its annotations and
    form fields drawn into the pages as they show on screen, and every page
    turned the way it shows (its rotation made part of its content), so
    the converters see what the reader sees."""
    document = fitz.open(stream=data, filetype="pdf")
    if document.needs_pass and not (password and document.authenticate(password)):
        document.close()
        raise RuntimeError("the document could not be unlocked")
    document.bake(annots=True, widgets=True)
    for page in document:
        if page.rotation:
            page.remove_rotation()
    return document


def export_ocr_pages(document: fitz.Document) -> set[int]:
    """Scanned pages with an OCR layer: nearly all of their text is the
    invisible text OCR puts over the picture of the page."""
    found: set[int] = set()
    for page in document:
        shown = hidden = 0
        try:
            spans = page.get_texttrace()
        except Exception:
            continue
        for span in spans:
            count = len(span.get("chars") or ())
            if span.get("type") == 3 or not span.get("opacity", 1):
                hidden += count
            else:
                shown += count
        if hidden >= 4 and shown < hidden * 0.1:
            found.add(page.number)
    return found


def _quiet_pdf2docx() -> None:
    """pdf2docx sets up logging for the whole process when it is imported
    (logging.basicConfig at INFO) and writes a line per page. A handler on
    the root logger first makes that a no-op, so nothing is written."""
    import logging

    root = logging.getLogger()
    if not root.handlers:
        root.addHandler(logging.NullHandler())
    root.setLevel(logging.WARNING)


# The pages of the running Word export that are scanned with an OCR layer;
# the reader below takes their invisible text instead of the picture.
_EXPORT_DOCX_OCR_PAGES: set[int] = set()


def _install_pdf2docx_ocr_pages() -> None:
    """pdf2docx leaves invisible text out, which on a scanned page with an
    OCR layer is all the text there is; its "ocr-ed PDF" mode takes that
    text and leaves the picture of the page out, but for every page at
    once. This applies the mode to the pages that need it."""
    from pdf2docx.page.RawPageFitz import RawPageFitz

    if getattr(RawPageFitz, "_pdfnote_ocr_pages", False):
        return
    read_text = RawPageFitz._preprocess_text
    read_images = RawPageFitz._preprocess_images

    def settings_for(page: Any, settings: dict[str, Any]) -> dict[str, Any]:
        if getattr(page.page_engine, "number", None) in _EXPORT_DOCX_OCR_PAGES:
            return {**settings, "ocr": 2}
        return settings

    RawPageFitz._preprocess_text = lambda self, **settings: read_text(
        self, **settings_for(self, settings)
    )
    RawPageFitz._preprocess_images = lambda self, **settings: read_images(
        self, **settings_for(self, settings)
    )
    RawPageFitz._pdfnote_ocr_pages = True


def export_docx(
    document: fitz.Document,
    target: str | Path,
    progress: Callable[[int, int], None],
    installed_fonts: set[str] | None = None,
) -> list[int]:
    """Word. Returns the pages (from 0) that could not be converted."""
    _quiet_pdf2docx()
    from docx import Document as WordDocument
    from docx.oxml.ns import qn
    from pdf2docx import Converter

    _install_pdf2docx_ocr_pages()
    _EXPORT_DOCX_OCR_PAGES.clear()
    _EXPORT_DOCX_OCR_PAGES.update(export_ocr_pages(document))
    data = document.tobytes(garbage=3, deflate=True, encryption=fitz.PDF_ENCRYPT_NONE)
    converter = Converter(stream=data)
    failed: list[int] = []
    try:
        settings = dict(converter.default_settings)
        # The steps of Converter.convert, one page at a time, to tell how
        # far it has got.
        converter.load_pages()
        pages = [page for page in converter.pages if not page.skip_parsing]
        total = 2 * len(pages) + 2
        progress(0, total)
        converter.parse_document(**settings)
        progress(2, total)
        for number, page in enumerate(pages, start=1):
            try:
                page.parse(**settings)
            except Exception:
                failed.append(page.id)
            progress(2 + number, total)
        output = WordDocument()
        for number, page in enumerate(pages, start=1):
            if page.finalized:
                try:
                    page.make_docx(output)
                except Exception:
                    failed.append(page.id)
            progress(2 + len(pages) + number, total)
        # pdf2docx names the face the PDF embedded; one this PC lacks would
        # be replaced by Word with a face of its own choosing.
        for fonts in output.element.body.iter(qn("w:rFonts")):
            named = fonts.get(qn("w:ascii")) or fonts.get(qn("w:eastAsia"))
            if not named:
                continue
            latin, east_asian = export_font_faces(named, installed_fonts)
            fonts.set(qn("w:ascii"), latin)
            fonts.set(qn("w:hAnsi"), latin)
            fonts.set(qn("w:eastAsia"), east_asian)
        output.save(str(target))
    finally:
        converter.close()
    return sorted(set(failed))


def _export_span_style(span: dict[str, Any]) -> dict[str, Any]:
    """A text span's look: size, colour, weight, slant and whether it shows
    (OCR's text is invisible, and stays so)."""
    font = str(span.get("font") or "")
    flags = int(span.get("flags") or 0)
    colour = int(span.get("color") or 0)
    return {
        "font": font,
        "size": float(span.get("size") or 0),
        "rgb": ((colour >> 16) & 255, (colour >> 8) & 255, colour & 255),
        "bold": bool(flags & 16) or bool(re.search(r"bold|black|heavy|semibold|demibold|w[6-9]\b", font, re.IGNORECASE)),
        "italic": bool(flags & 2) or bool(re.search(r"italic|oblique", font, re.IGNORECASE)),
        "hidden": int(span.get("alpha", 255)) == 0,
    }


def export_text_lines(page: fitz.Page) -> list[dict[str, Any]]:
    """The page's lines of text that run left to right, each with its
    spans. Vertical and slanted text is left out: it stays in the picture
    of the page."""
    lines: list[dict[str, Any]] = []
    flags = fitz.TEXTFLAGS_DICT & ~fitz.TEXT_PRESERVE_IMAGES
    for block in page.get_text("dict", flags=flags).get("blocks", []):
        for line in block.get("lines", []):
            dx, dy = line.get("dir", (1, 0))
            if abs(dy) > 0.02 or dx <= 0:
                continue
            spans = [span for span in line.get("spans", []) if span.get("text")]
            if not spans or not "".join(span["text"] for span in spans).strip():
                continue
            lines.append(
                {
                    "block": block.get("number", 0),
                    "bbox": fitz.Rect(line["bbox"]),
                    "baseline": float(spans[0]["origin"][1]),
                    "size": max(float(span.get("size") or 0) for span in spans),
                    "spans": spans,
                }
            )
    return lines


def _export_line_groups(lines: list[dict[str, Any]]) -> list[list[dict[str, Any]]]:
    """Lines that make one text box: the lines of a paragraph, one under the
    other at an even spacing, starting at the same place and in the same
    size. Anything else starts a box of its own."""
    groups: list[list[dict[str, Any]]] = []
    for line in lines:
        group = groups[-1] if groups else None
        if group is not None:
            last = group[-1]
            pitch = line["baseline"] - last["baseline"]
            same = (
                line["block"] == last["block"]
                and abs(line["bbox"].x0 - group[0]["bbox"].x0) <= 1.5
                and abs(line["size"] - group[0]["size"]) <= 0.5
                and 0.9 * line["size"] <= pitch <= 2.5 * line["size"]
            )
            if same and len(group) > 1:
                first_pitch = group[1]["baseline"] - group[0]["baseline"]
                same = abs(pitch - first_pitch) <= 1.0
            if same:
                group.append(line)
                continue
        groups.append([line])
    return groups


def _export_page_picture(page: fitz.Page, remove: list[fitz.Rect], dpi: int) -> tuple[bytes, str]:
    """The page drawn without the text in `remove`: a copy of the page with
    that text redacted -- the pictures and drawings stay. JPEG where the
    page holds a photo, PNG otherwise."""
    holder = fitz.open()
    try:
        holder.insert_pdf(page.parent, from_page=page.number, to_page=page.number)
        copy = holder[0]
        for rect in remove:
            if not rect.is_empty:
                copy.add_redact_annot(rect, fill=False)
        if remove:
            copy.apply_redactions(
                images=fitz.PDF_REDACT_IMAGE_NONE, graphics=fitz.PDF_REDACT_LINE_ART_NONE
            )
        # A huge page stays within what a slide picture needs.
        longest = max(copy.rect.width, copy.rect.height, 1)
        dpi = max(36, min(dpi, int(12000 * 72 / longest)))
        pixmap = copy.get_pixmap(dpi=dpi, alpha=False)
        if page.get_images():
            return pixmap.tobytes("jpeg", jpg_quality=92), "jpeg"
        return pixmap.tobytes("png"), "png"
    finally:
        holder.close()


def export_pptx(
    document: fitz.Document,
    target: str | Path,
    progress: Callable[[int, int], None],
    installed_fonts: set[str] | None = None,
    dpi: int = 200,
) -> list[int]:
    """PowerPoint. Returns the pages (from 0) that could not be converted."""
    import io

    from pptx import Presentation
    from pptx.dml.color import RGBColor
    from pptx.enum.text import MSO_AUTO_SIZE
    from pptx.oxml.ns import qn
    from pptx.util import Emu, Pt

    emu = EXPORT_EMU_PER_POINT
    total = len(document)
    progress(0, total)
    presentation = Presentation()
    # One slide size for the whole presentation: the first page's, within
    # what PowerPoint allows (1 to 56 inches). Pages of another shape are
    # fitted in, centred.
    first = document[0].rect if total else fitz.Rect(0, 0, 720, 540)
    limit = 56 * 72
    shrink = min(1.0, limit / max(first.width, first.height, 1))
    slide_width = max(72, min(limit, first.width * shrink))
    slide_height = max(72, min(limit, first.height * shrink))
    presentation.slide_width = Emu(round(slide_width * emu))
    presentation.slide_height = Emu(round(slide_height * emu))
    blank = presentation.slide_layouts[6]
    failed: list[int] = []
    for page in document:
        slide = presentation.slides.add_slide(blank)
        try:
            rect = page.rect
            scale = min(slide_width / max(rect.width, 1), slide_height / max(rect.height, 1))
            left = (slide_width - rect.width * scale) / 2
            top = (slide_height - rect.height * scale) / 2

            def at(value: float, origin: float) -> Emu:
                return Emu(round((origin + value * scale) * emu))

            lines = export_text_lines(page)
            remove = [fitz.Rect(span["bbox"]) for line in lines for span in line["spans"]]
            picture, _kind = _export_page_picture(page, remove, dpi)
            slide.shapes.add_picture(
                io.BytesIO(picture), at(0, left), at(0, top),
                Emu(round(rect.width * scale * emu)), Emu(round(rect.height * scale * emu)),
            )
            for group in _export_line_groups(lines):
                size = group[0]["size"]
                if len(group) > 1:
                    pitch = (group[-1]["baseline"] - group[0]["baseline"]) / (len(group) - 1)
                else:
                    pitch = 1.2 * size
                # With exact line spacing PowerPoint puts a line's baseline
                # four fifths of the way down its line.
                box_top = group[0]["baseline"] - 0.8 * pitch
                x0 = min(line["bbox"].x0 for line in group)
                width = max(line["bbox"].x1 for line in group) - x0
                box = slide.shapes.add_textbox(
                    at(x0, left), at(box_top, top),
                    Emu(round((width * 1.04 + 2) * scale * emu)),
                    Emu(round(pitch * len(group) * scale * emu)),
                )
                frame = box.text_frame
                frame.word_wrap = False
                frame.auto_size = MSO_AUTO_SIZE.NONE
                frame.margin_left = frame.margin_right = 0
                frame.margin_top = frame.margin_bottom = 0
                for index, line in enumerate(group):
                    paragraph = frame.paragraphs[0] if index == 0 else frame.add_paragraph()
                    paragraph.line_spacing = Pt(round(pitch * scale * 100) / 100)
                    for span in line["spans"]:
                        style = _export_span_style(span)
                        run = paragraph.add_run()
                        run.text = span["text"]
                        font = run.font
                        font.size = Pt(max(1, round(style["size"] * scale * 2) / 2))
                        font.bold = style["bold"]
                        font.italic = style["italic"]
                        font.color.rgb = RGBColor(*style["rgb"])
                        latin, east_asian = export_font_faces(style["font"], installed_fonts)
                        font.name = latin
                        properties = run._r.get_or_add_rPr()
                        for tag, face in (("a:ea", east_asian), ("a:cs", latin)):
                            element = properties.find(qn(tag))
                            if element is None:
                                element = properties.makeelement(qn(tag), {})
                                properties.append(element)
                            element.set("typeface", face)
                        if style["hidden"]:
                            # OCR's text over a scan: there to search and
                            # copy, not to be seen twice.
                            colour = properties.find(qn("a:solidFill")).find(qn("a:srgbClr"))
                            colour.append(colour.makeelement(qn("a:alpha"), {"val": "0"}))
        except Exception:
            failed.append(page.number)
        progress(page.number + 1, total)
    presentation.save(str(target))
    return failed


# A figure as Excel should hold it: an optional sign or bracket, a currency
# sign, digits with or without thousands separators, decimals, and a
# percent sign or 円. "△" and "▲" are the Japanese minus of accounts.
# Full-width digits stay text: a number would show them half-width.
EXPORT_NUMBER = re.compile(
    r"^(?P<lead>[-−‐‑△▲(（])?\s*(?P<currency>[¥￥$€£])?\s*(?P<minus>[-−])?"
    r"(?P<digits>(?:[0-9]{1,3}(?:[,，][0-9]{3})+|[0-9]+)(?:[.．][0-9]+)?)"
    r"\s*(?P<unit>%|％|\u5186)?\s*(?P<close>[)）])?$"
)
# 円, kept out of the strings the translation check reads.
EXPORT_YEN_UNIT = chr(0x5186)


def export_number(text: str) -> tuple[float, str] | None:
    """`text` as a number and the Excel format that shows it as it was
    written, or None for text that is not one figure. Codes with leading
    zeros (007, postcodes) stay text."""
    match = EXPORT_NUMBER.match(text.strip().replace("\xa0", " "))
    if match is None:
        return None
    lead, close = match["lead"], match["close"]
    if (lead in ("(", "（")) != bool(close):
        return None
    digits = match["digits"].replace(",", "").replace("，", "").replace("．", ".")
    if len(digits) > 1 and digits[0] == "0" and digits[1] != ".":
        return None
    whole, _point, fraction = digits.partition(".")
    if len(whole) > 15:
        return None  # beyond what a double keeps exactly
    value = float(digits)
    if lead or match["minus"]:
        value = -value
    grouped = "," in match["digits"] or "，" in match["digits"]
    body = "#,##0" if grouped else "0"
    if fraction:
        body += "." + "0" * len(fraction)
    unit = match["unit"]
    if unit in ("%", "％"):
        return value / 100, body.replace("#,##", "") + "%"
    if match["currency"]:
        body = f'"{match["currency"]}"{body}'
    if unit == EXPORT_YEN_UNIT:
        body += f'"{EXPORT_YEN_UNIT}"'
    if lead in ("(", "（"):
        return value, f"{body};({body})"
    if lead in ("△", "▲"):
        return value, f'{body};"{lead}"{body}'
    return value, body


def _export_sheet_name(pattern: str, page: int, taken: set[str]) -> str:
    name = re.sub(r"[\[\]:*?/\\]", " ", pattern.format(page=page)).strip("' ")[:31] or str(page)
    candidate, extra = name, 2
    while candidate.casefold() in taken:
        suffix = f" ({extra})"
        candidate, extra = name[: 31 - len(suffix)] + suffix, extra + 1
    taken.add(candidate.casefold())
    return candidate


def _export_text_items(page_dict: dict[str, Any]) -> list[dict[str, Any]]:
    """Runs of text for the cells: each line of the page, split where a gap
    wider than two characters separates its parts (the columns of a list
    set out with spaces)."""
    items: list[dict[str, Any]] = []
    for block in page_dict.get("blocks", []):
        for line in block.get("lines", []):
            dx, dy = line.get("dir", (1, 0))
            spans = [span for span in line.get("spans", []) if str(span.get("text") or "").strip()]
            if not spans:
                continue
            runs = [[spans[0]]]
            for span in spans[1:]:
                gap = span["bbox"][0] - runs[-1][-1]["bbox"][2]
                if abs(dy) < 0.02 and gap > 2 * max(span["size"], runs[-1][-1]["size"]):
                    runs.append([span])
                else:
                    runs[-1].append(span)
            for run in runs:
                box = fitz.Rect(run[0]["bbox"])
                for span in run[1:]:
                    box |= fitz.Rect(span["bbox"])
                items.append(
                    {
                        "bbox": box,
                        "spans": run,
                        "text": "".join(span["text"] for span in run).strip(),
                    }
                )
    return items


def _export_rect_fill(drawing: dict[str, Any]) -> bool:
    """A drawing that is nothing but a filled rectangle."""
    items = drawing.get("items") or []
    return bool(drawing.get("fill")) and bool(items) and all(item[0] in ("re", "qu") for item in items)


def export_xlsx(
    document: fitz.Document,
    target: str | Path,
    progress: Callable[[int, int], None],
    installed_fonts: set[str] | None = None,
    sheet_name: str = "{page}",
) -> list[int]:
    """Excel. Returns the pages (from 0) that could not be converted."""
    import xlsxwriter

    total = len(document)
    progress(0, total)
    ocr_pages = export_ocr_pages(document)
    workbook = xlsxwriter.Workbook(
        str(target),
        {"strings_to_numbers": False, "strings_to_formulas": False, "strings_to_urls": False},
    )
    formats: dict[tuple, Any] = {}

    def cell_format(properties: dict[str, Any]) -> Any:
        key = tuple(sorted(properties.items()))
        if key not in formats:
            formats[key] = workbook.add_format(dict(properties))
        return formats[key]

    def colour(fill: Iterable[float]) -> str:
        red, green, blue = (max(0, min(255, round(value * 255))) for value in list(fill)[:3])
        return f"#{red:02X}{green:02X}{blue:02X}"

    def text_properties(spans: list[dict[str, Any]], text: str) -> dict[str, Any]:
        span = max(spans, key=lambda item: len(str(item.get("text") or "")))
        style = _export_span_style(span)
        latin, east_asian = export_font_faces(style["font"], installed_fonts)
        cjk = re.search(r"[぀-ヿ㐀-鿿가-힯＀-￯]", text)
        properties: dict[str, Any] = {
            "font_name": east_asian if cjk else latin,
            "font_size": max(1, round(style["size"] * 2) / 2),
            "valign": "top",
        }
        if style["bold"]:
            properties["bold"] = True
        if style["italic"]:
            properties["italic"] = True
        if style["rgb"] != (0, 0, 0) and not style["hidden"]:
            properties["font_color"] = "#%02X%02X%02X" % style["rgb"]
        return properties

    taken: set[str] = set()
    failed: list[int] = []
    for page in document:
        sheet = workbook.add_worksheet(_export_sheet_name(sheet_name, page.number + 1, taken))
        try:
            _export_xlsx_page(
                page, sheet, page.number in ocr_pages, cell_format, colour, text_properties
            )
        except Exception:
            failed.append(page.number)
        progress(page.number + 1, total)
    workbook.close()
    return failed


def _export_xlsx_page(
    page: fitz.Page,
    sheet: Any,
    scanned: bool,
    cell_format: Callable[[dict[str, Any]], Any],
    colour: Callable[[Iterable[float]], str],
    text_properties: Callable[[list[dict[str, Any]], str], dict[str, Any]],
) -> None:
    """One page as one sheet; see export_xlsx."""
    import bisect
    import io

    pixels = 96 / 72  # Excel lays a sheet out in pixels at 96 dpi
    area = page.rect
    page_area = max(area.get_area(), 1)
    page_dict = page.get_text("dict", flags=fitz.TEXTFLAGS_DICT & ~fitz.TEXT_PRESERVE_IMAGES)
    tables = [table for table in page.find_tables().tables if table.row_count and table.col_count]
    table_boxes = [fitz.Rect(table.bbox) for table in tables]

    def in_table(rect: fitz.Rect) -> bool:
        centre = (rect.tl + rect.br) / 2
        return any(box.contains(centre) for box in table_boxes)

    items = [item for item in _export_text_items(page_dict) if not in_table(item["bbox"])]
    # What the page draws, but not a background as large as the page.
    drawings = [
        drawing for drawing in page.get_drawings()
        if fitz.Rect(drawing["rect"]).get_area() < 0.6 * page_area
    ]
    pictures: list[fitz.Rect] = []
    shades: list[tuple[fitz.Rect, str]] = []
    for info in page.get_image_info():
        box = fitz.Rect(info["bbox"]) & area
        if box.is_empty or box.width < 4 or box.height < 4:
            continue
        if scanned and box.get_area() > 0.5 * page_area:
            continue  # the scan under OCR's text: the text goes in the cells
        if any(box.intersects(table) for table in table_boxes):
            continue
        pictures.append(box)
    for region in page.cluster_drawings(drawings=drawings) if drawings else []:
        region = fitz.Rect(region)
        if region.width < 4 or region.height < 4:
            continue
        if any(region.intersects(table) for table in table_boxes):
            continue
        members = [d for d in drawings if (region + (-1, -1, 1, 1)).contains(fitz.Rect(d["rect"]))]
        touching = [item for item in items if item["bbox"].intersects(region)]
        covered = sum((item["bbox"] & region).get_area() for item in touching)
        if len(members) == 1 and _export_rect_fill(members[0]):
            # A box of colour: the cells under it take the colour.
            shades.append((region, colour(members[0]["fill"])))
            continue
        filled = [d for d in members if d.get("fill")]
        if touching and covered >= 0.25 * region.get_area() and filled:
            # A highlight, or a coloured band behind text: the text's cell
            # takes the colour, and the text stays text.
            fill = colour(max(filled, key=lambda d: fitz.Rect(d["rect"]).get_area())["fill"])
            for item in touching:
                item["fill"] = fill
            continue
        for item in touching:
            region |= item["bbox"]
        pictures.append(region & area)
    for picture in pictures:
        for item in items:
            centre = (item["bbox"].tl + item["bbox"].br) / 2
            if picture.contains(centre):
                item["in_picture"] = True
    items = [item for item in items if not item.get("in_picture")]

    # The grid: the tables' own lines, then where text and pictures begin.
    cells = [cell for table in tables for table_row in table.rows for cell in table_row.cells if cell]
    xs = sorted({0.0, area.width} | {value for cell in cells for value in (cell[0], cell[2])})
    ys = sorted({0.0, area.height} | {value for cell in cells for value in (cell[1], cell[3])})

    def add(edges: list[float], value: float, tolerance: float, spans: list[tuple[float, float]]) -> None:
        # Not inside a table: a new line there would split its cells.
        if any(low + 1 < value < high - 1 for low, high in spans):
            return
        index = bisect.bisect_left(edges, value)
        if index < len(edges) and edges[index] - value <= tolerance:
            return
        if index > 0 and value - edges[index - 1] <= tolerance:
            return
        edges.insert(index, value)

    across = [(box.x0, box.x1) for box in table_boxes]
    down = [(box.y0, box.y1) for box in table_boxes]
    for item in items:
        add(xs, item["bbox"].x0, 3.0, across)
        add(ys, item["bbox"].y0, 2.0, down)
        add(ys, item["bbox"].y1, 2.0, down)
    for box in pictures:
        add(xs, box.x0, 3.0, across)
        add(ys, box.y0, 2.0, down)
    for box, _fill in shades:
        add(xs, box.x0, 3.0, across)
        add(xs, box.x1, 3.0, across)
        add(ys, box.y0, 2.0, down)
        add(ys, box.y1, 2.0, down)
    # Excel's rows stop at 409 points.
    for index in range(len(ys) - 1, 0, -1):
        low, high = ys[index - 1], ys[index]
        steps = math.ceil((high - low) / 400)
        for step in range(1, steps):
            ys.insert(index, low + (high - low) * (steps - step) / steps)

    def nearest(edges: list[float], value: float) -> int:
        index = bisect.bisect_left(edges, value)
        if index <= 0:
            return 0
        if index >= len(edges):
            return len(edges) - 1
        return index if edges[index] - value < value - edges[index - 1] else index - 1

    def column(value: float) -> int:
        return max(0, min(len(xs) - 2, bisect.bisect_right(xs, value + 3.0) - 1))

    def row(value: float) -> int:
        return max(0, min(len(ys) - 2, bisect.bisect_right(ys, value + 2.0) - 1))

    for index in range(len(xs) - 1):
        sheet.set_column_pixels(index, index, max(1, round((xs[index + 1] - xs[index]) * pixels)))
    for index in range(len(ys) - 1):
        sheet.set_row_pixels(index, max(1, round((ys[index + 1] - ys[index]) * pixels)))

    # Colour under cells first; what is written later keeps it.
    background: dict[tuple[int, int], str] = {}
    for box, fill in shades:
        for r in range(nearest(ys, box.y0), max(nearest(ys, box.y0) + 1, nearest(ys, box.y1))):
            for c in range(nearest(xs, box.x0), max(nearest(xs, box.x0) + 1, nearest(xs, box.x1))):
                background[(r, c)] = fill
    written: set[tuple[int, int]] = set()

    def write(r: int, c: int, text: str, properties: dict[str, Any]) -> None:
        if (r, c) in background and "bg_color" not in properties:
            properties = {**properties, "bg_color": background[(r, c)]}
        number = export_number(text) if text else None
        if number is not None:
            sheet.write_number(r, c, number[0], cell_format({**properties, "num_format": number[1]}))
        else:
            sheet.write_string(r, c, text, cell_format(properties))
        written.add((r, c))

    for item in items:
        properties = text_properties(item["spans"], item["text"])
        if item.get("fill"):
            properties["bg_color"] = item["fill"]
        r, c = row(item["bbox"].y0), column(item["bbox"].x0)
        if (r, c) in written:
            continue  # two runs met in one cell: the first keeps it
        write(r, c, item["text"], properties)

    spans_of_page = [
        span for block in page_dict.get("blocks", []) for line in block.get("lines", [])
        for span in line.get("spans", []) if str(span.get("text") or "").strip()
    ]
    fills = [d for d in page.get_drawings() if _export_rect_fill(d)]
    for table in tables:
        values = table.extract()
        for row_index, table_row in enumerate(table.rows):
            for column_index, cell in enumerate(table_row.cells):
                if not cell:
                    continue
                box = fitz.Rect(cell)
                r0, c0 = nearest(ys, box.y0), nearest(xs, box.x0)
                r1 = max(r0, nearest(ys, box.y1) - 1)
                c1 = max(c0, nearest(xs, box.x1) - 1)
                text = ""
                if row_index < len(values) and column_index < len(values[row_index]):
                    text = str(values[row_index][column_index] or "").strip()
                inside = [
                    span for span in spans_of_page
                    if box.contains((fitz.Rect(span["bbox"]).tl + fitz.Rect(span["bbox"]).br) / 2)
                ]
                properties: dict[str, Any] = (
                    text_properties(inside, text) if inside else {"valign": "top"}
                )
                properties["border"] = 1
                properties["valign"] = "vcenter"
                if inside:
                    extent = fitz.Rect(inside[0]["bbox"])
                    for span in inside[1:]:
                        extent |= fitz.Rect(span["bbox"])
                    before, after = extent.x0 - box.x0, box.x1 - extent.x1
                    if abs(before - after) <= max(2.0, 0.12 * box.width):
                        properties["align"] = "center"
                    else:
                        properties["align"] = "right" if after < before else "left"
                if "\n" in text:
                    properties["text_wrap"] = True
                shade = [
                    d for d in fills
                    if (fitz.Rect(d["rect"]) + (-1, -1, 1, 1)).contains(box + (1, 1, -1, -1))
                    and fitz.Rect(d["rect"]).get_area() < 4 * max(box.get_area(), 1)
                ]
                if shade:
                    fill = shade[-1]["fill"]  # the last drawn shows
                    if tuple(fill[:3]) != (1.0, 1.0, 1.0):
                        properties["bg_color"] = colour(fill)
                if r1 > r0 or c1 > c0:
                    number = export_number(text) if text else None
                    merged = cell_format(
                        {**properties, "num_format": number[1]} if number else properties
                    )
                    sheet.merge_range(r0, c0, r1, c1, "", merged)
                    if number is not None:
                        sheet.write_number(r0, c0, number[0], merged)
                    else:
                        sheet.write_string(r0, c0, text, merged)
                    written.add((r0, c0))
                else:
                    write(r0, c0, text, properties)

    for (r, c), fill in background.items():
        if (r, c) not in written:
            sheet.write_blank(r, c, None, cell_format({"bg_color": fill}))

    for box in pictures:
        r, c = row(box.y0), column(box.x0)
        pixmap = page.get_pixmap(clip=box, dpi=192, alpha=False)
        sheet.insert_image(
            r, c, f"page{page.number + 1}.png",
            {
                "image_data": io.BytesIO(pixmap.tobytes("png")),
                "x_offset": max(0, round((box.x0 - xs[c]) * pixels)),
                "y_offset": max(0, round((box.y0 - ys[r]) * pixels)),
                # Drawn at 192 dpi, shown at 96: half size is the page's.
                "x_scale": box.width * pixels / max(pixmap.width, 1),
                "y_scale": box.height * pixels / max(pixmap.height, 1),
                "object_position": 1,
            },
        )
    # Printed as the page was: its paper, its orientation, one page wide.
    width, height = sorted((area.width, area.height))
    paper = {(595, 842): 9, (612, 792): 1, (842, 1191): 8, (420, 595): 11, (516, 729): 13}
    sheet.set_paper(next((code for (w, h), code in paper.items() if abs(width - w) < 6 and abs(height - h) < 6), 0))
    if area.width > area.height:
        sheet.set_landscape()
    sheet.fit_to_pages(1, 0)


EXPORTERS: dict[str, Callable[..., list[int]]] = {
    "docx": export_docx,
    "pptx": export_pptx,
    "xlsx": export_xlsx,
}


def export_worker_main(job: str) -> int:
    """`pdfNote --export-worker <folder>`: one export, in a process of its
    own. The folder holds the copy of the document (input.pdf) and the
    settings (job.json); progress goes to out.jsonl one JSON object a line,
    as OCR's does, the file is written to the folder as output.<suffix>,
    and the last line is {"finished": true}. A protected copy is unlocked
    with the password in EXPORT_PASSWORD_VARIABLE."""
    folder = Path(job)
    faults = record_worker_faults(folder, "export")
    with open(folder / "out.jsonl", "a", encoding="utf-8") as out:

        def send(event: dict[str, Any]) -> None:
            out.write(json.dumps(event, ensure_ascii=False) + "\n")
            out.flush()

        def progress(done: int, total: int) -> None:
            worker_step(faults, f"page {done} of {total}")
            send({"progress": [done, total]})

        try:
            settings = json.loads((folder / "job.json").read_text(encoding="utf-8"))
            kind = str(settings["format"])
            worker_step(faults, f"exporting as {kind}")
            fonts = settings.get("fonts")
            document = export_source(
                (folder / "input.pdf").read_bytes(),
                os.environ.get(EXPORT_PASSWORD_VARIABLE) or None,
            )
            try:
                extra = {"sheet_name": str(settings.get("sheet_name") or "{page}")} if kind == "xlsx" else {}
                skipped = EXPORTERS[kind](
                    document,
                    folder / f"output.{kind}",
                    progress,
                    set(fonts) if isinstance(fonts, list) else None,
                    **extra,
                )
            finally:
                document.close()
            worker_step(faults, "written")
            send({"done": True, "skipped": skipped})
        except Exception as exc:
            worker_step(faults, f"failed: {exc.__class__.__name__}")
            send({"failed": str(exc) or exc.__class__.__name__})
        send({"finished": True})
        worker_step(faults, "said it has finished")
    stop_worker_faults(faults)
    return 0


class ExportProcess(QObject):
    """An export in a process of its own (export_worker_main), the way
    OcrProcess runs OCR: the copy and the settings go into a private
    temporary folder, the child's events are read back every 150 ms and
    turned into signals, and cancelling ends the child at once. `output`
    is the file written, once `finished` says it is done; the folder goes
    when the object is told to clean up."""

    progress = Signal(int, int)
    failed = Signal(str)
    # cancelled, and the pages (from 0) that could not be converted
    finished = Signal(bool, list)
    command_override: list[str] | None = None

    def __init__(
        self,
        data: bytes,
        kind: str,
        password: str | None = None,
        fonts: list[str] | None = None,
        sheet_name: str = "{page}",
        parent: QObject | None = None,
    ) -> None:
        super().__init__(parent)
        self._data = data
        self.kind = kind
        self._password = password
        self._fonts = fonts
        self._sheet_name = sheet_name
        self._cancelled = False
        self._ended = False
        self._done = False
        self._skipped: list[int] = []
        self._worker_finished = False
        self._read_offset = 0
        self._pending = b""
        self._reading_events = False
        self._finish_pending = False
        self._folder: Path | None = None
        self._process = QProcess(self)
        self._process.finished.connect(self._process_finished)
        self._process.errorOccurred.connect(self._process_error)
        self._timer = QTimer(self)
        self._timer.setInterval(150)
        self._timer.timeout.connect(self._read_events)

    @staticmethod
    def command() -> list[str]:
        """pdfNote itself, in its export worker mode."""
        if getattr(sys, "frozen", False):
            return [sys.executable, "--export-worker"]
        return [sys.executable, str(Path(__file__).resolve()), "--export-worker"]

    @property
    def output(self) -> Path | None:
        if self._folder is None or not self._done:
            return None
        return self._folder / f"output.{self.kind}"

    def start(self) -> None:
        try:
            self._folder = Path(tempfile.mkdtemp(prefix="pdfnote-export-"))
            (self._folder / "input.pdf").write_bytes(self._data)
            (self._folder / "job.json").write_text(
                json.dumps(
                    {"format": self.kind, "fonts": self._fonts, "sheet_name": self._sheet_name},
                    ensure_ascii=False,
                ),
                encoding="utf-8",
            )
            (self._folder / "out.jsonl").write_bytes(b"")
        except OSError as exc:
            # Read now: Python forgets `exc` when the except clause ends, and
            # the call below runs after it -- the failure was never told.
            message = str(exc)
            QTimer.singleShot(0, self, lambda: (self.failed.emit(message), self._end()))
            return
        self._data = b""
        environment = QProcessEnvironment.systemEnvironment()
        environment.remove(EXPORT_PASSWORD_VARIABLE)
        if self._password:
            environment.insert(EXPORT_PASSWORD_VARIABLE, self._password)
        self._process.setProcessEnvironment(environment)
        self._process.setProcessChannelMode(QProcess.ForwardedErrorChannel)
        program, *arguments = list(self.command_override or self.command()) + [str(self._folder)]
        self._timer.start()
        self._process.start(program, arguments)

    def cancel(self) -> None:
        self._cancelled = True
        if self._process.state() != QProcess.NotRunning:
            self._process.kill()

    def running(self) -> bool:
        return not self._ended

    def stop(self) -> None:
        """End the export without a word: the window is going."""
        self._cancelled = True
        self._ended = True
        self._timer.stop()
        if self._process.state() != QProcess.NotRunning:
            self._process.kill()
            self._process.waitForFinished(3000)
        self.remove_folder()

    def _read_events(self) -> None:
        if self._folder is None or self._ended or self._reading_events:
            return
        self._reading_events = True
        try:
            self._read_event_batch()
        finally:
            self._reading_events = False
            if self._finish_pending:
                self._finish_pending = False
                self._process_finished()

    def _read_event_batch(self) -> None:
        try:
            with open(self._folder / "out.jsonl", "rb") as stream:
                stream.seek(self._read_offset)
                chunk = stream.read()
        except OSError:
            return
        self._read_offset += len(chunk)
        lines = (self._pending + chunk).split(b"\n")
        self._pending = lines.pop()
        for line in lines:
            if self._ended:
                break
            if not line.strip():
                continue
            try:
                event = json.loads(line.decode("utf-8"))
            except (ValueError, UnicodeDecodeError):
                continue
            if self._cancelled:
                continue
            if "progress" in event:
                done, total = event["progress"]
                self.progress.emit(int(done), int(total))
            elif event.get("done"):
                self._done = True
                self._skipped = [int(page) for page in event.get("skipped") or []]
            elif "failed" in event:
                self.failed.emit(str(event["failed"]))
            elif event.get("finished"):
                self._worker_finished = True

    def _process_finished(self, *_args: Any) -> None:
        if self._ended:
            return
        if self._reading_events:
            # A modal progress dialog pumps events in setValue(). Its
            # QProcess exit can arrive while done/finished are still in
            # the batch above, whose bytes have already been consumed.
            self._finish_pending = True
            return
        read_last_events(self)
        if not self._worker_finished and not self._cancelled:
            keep_worker_fault(self, "export")
            self.failed.emit(
                tr("エクスポートの処理が途中で終了しました（終了コード {code}）").format(
                    code=worker_exit_text(self)
                )
            )
        self._end()

    def _process_error(self, error: Any) -> None:
        if error == QProcess.FailedToStart and not self._ended:
            self.failed.emit(self._process.errorString())
            self._end()

    def _end(self) -> None:
        if self._ended:
            return
        self._ended = True
        self._timer.stop()
        if self._cancelled or not self._done:
            self.remove_folder()
        self.finished.emit(self._cancelled, list(self._skipped))

    def remove_folder(self) -> None:
        if self._folder is not None:
            shutil.rmtree(self._folder, ignore_errors=True)
            self._folder = None


def page_content_fingerprint(document: fitz.Document, index: int) -> str:
    """What page `index` draws, as a short digest: its content streams, the
    pictures it names, its rotation and size. Taken when OCR starts and
    compared before a page's result is written: a page changed meanwhile
    -- redacted, a picture deleted -- gets nothing from a copy of how it
    was (6.2)."""
    page = document[index]
    digest = hashlib.blake2b(digest_size=16)
    digest.update(repr((page.rotation, tuple(page.rect))).encode())
    for xref in page.get_contents():
        digest.update(b"%d:" % xref)
        try:
            digest.update(document.xref_stream_raw(xref))
        except Exception:
            digest.update(b"?")
    try:
        digest.update(repr(page.get_images(full=True)).encode())
    except Exception:
        digest.update(b"?")
    return digest.hexdigest()


class RecoverySnapshotWriter:
    """Writes crash-recovery snapshots on a background thread.

    Only the disk write happens here. Serialising a document stays on the
    GUI thread because a PyMuPDF document must not be touched from two
    threads at once -- but writing tens or hundreds of megabytes is the
    part that actually stalls the window, especially on a slow disk.

    Snapshots are keyed by destination, so a newer snapshot for the same
    document simply replaces a queued older one instead of queueing behind
    it.
    """

    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._ready = threading.Condition(self._lock)
        self._pending: dict[Path, tuple[Path, bytes, str, int]] = {}
        self._thread: threading.Thread | None = None
        self._closed = False
        # The snapshot being written right now, and snapshots whose document
        # was saved or closed while they were being written.
        self._in_flight: Path | None = None
        self._dropped: set[Path] = set()
        # Failed writes not yet reported, for the window (take_failure),
        # with the snapshot each was for. A snapshot that silently never
        # lands is no safety net. This was a single slot, which the next
        # write's outcome overwrote -- a failure followed quickly by a
        # success was never reported.
        self._failures: list[tuple[Path, str]] = []
        # (snapshot path, revision, error or None) of every finished write.
        self._results: list[tuple[Path, int | None, str | None]] = []

    def take_failure(self, paths: Iterable[Path] | None = None) -> str | None:
        """The latest failed write not yet reported, once; None if none.
        With `paths`, only the snapshots of those: one writer serves every
        window, and each reports its own tabs' (6.2)."""
        wanted = None if paths is None else set(paths)
        with self._lock:
            taken = [f for f in self._failures if wanted is None or f[0] in wanted]
            self._failures = [f for f in self._failures if wanted is not None and f[0] not in wanted]
        return taken[-1][1] if taken else None

    def take_results(
        self, paths: Iterable[Path] | None = None
    ) -> list[tuple[Path, int | None, str | None]]:
        """Every write that finished since the last call, with its outcome;
        with `paths`, only those of the snapshots named."""
        wanted = None if paths is None else set(paths)
        with self._lock:
            taken = [r for r in self._results if wanted is None or r[0] in wanted]
            self._results = [r for r in self._results if wanted is not None and r[0] not in wanted]
        return taken

    def submit(
        self, pdf_path: Path, meta_path: Path, data: bytes, meta: str,
        revision: int | None = None,
    ) -> None:
        with self._ready:
            if self._closed:
                return
            self._pending[pdf_path] = (meta_path, data, meta, revision)
            if self._thread is None:
                self._thread = threading.Thread(
                    target=self._run, name="pdfnote-recovery", daemon=True
                )
                self._thread.start()
            self._ready.notify()

    def cancel(self, pdf_path: Path, timeout: float = 5.0) -> None:
        """Drop a snapshot (the document was saved or closed, so it must not
        be resurrected after its files are removed).

        Removing it from the queue was not enough: a write already in
        progress finished after the caller had deleted the files, and the
        next start offered to "restore" a document that had been saved --
        leaving a copy of it on disk meanwhile. A write in progress is now
        marked, deleted by the writer when it lands, and waited for.
        """
        with self._ready:
            self._pending.pop(pdf_path, None)
            # No one is left to hear how its writes went.
            self._results = [r for r in self._results if r[0] != pdf_path]
            self._failures = [f for f in self._failures if f[0] != pdf_path]
            if self._in_flight != pdf_path:
                return
            self._dropped.add(pdf_path)
            deadline = time.monotonic() + timeout
            while self._in_flight == pdf_path:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                self._ready.wait(remaining)

    def close(self, timeout: float = 5.0) -> None:
        with self._ready:
            self._closed = True
            self._ready.notify_all()
            thread = self._thread
        if thread is not None:
            thread.join(timeout)

    def _run(self) -> None:
        while True:
            with self._ready:
                while not self._pending and not self._closed:
                    self._ready.wait()
                if not self._pending:
                    self._thread = None
                    return
                pdf_path, (meta_path, data, meta, revision) = self._pending.popitem()
                self._in_flight = pdf_path
                self._dropped.discard(pdf_path)
            partial = pdf_path.with_suffix(".part")
            meta_partial = meta_path.with_suffix(".json.part")
            failure: str | None = None
            try:
                self._write(partial, pdf_path, meta_path, data, meta)
            except OSError as exc:
                failure = str(exc) or exc.__class__.__name__
                for leftover in (partial, meta_partial):
                    try:
                        leftover.unlink(missing_ok=True)
                    except OSError:
                        pass
            finally:
                with self._ready:
                    if failure is not None:
                        self._failures.append((pdf_path, failure))
                    if pdf_path in self._dropped:
                        self._dropped.discard(pdf_path)
                        for leftover in (partial, meta_partial, pdf_path, meta_path):
                            try:
                                leftover.unlink(missing_ok=True)
                            except OSError:
                                pass
                    else:
                        self._results.append((pdf_path, revision, failure))
                    self._in_flight = None
                    self._ready.notify_all()

    @staticmethod
    def _write(partial: Path, pdf_path: Path, meta_path: Path, data: bytes, meta: str) -> None:
        """Both files go through a temporary copy that is flushed to disk
        and then swapped in, so neither is ever seen half written. The
        metadata was written in place: a crash in the middle left JSON that
        did not parse, and the start-up check silently skipped the
        snapshot it described."""
        RecoverySnapshotWriter._replace_atomically(partial, pdf_path, data)
        RecoverySnapshotWriter._replace_atomically(
            meta_path.with_suffix(".json.part"), meta_path, meta.encode("utf-8")
        )

    @staticmethod
    def _replace_atomically(partial: Path, target: Path, data: bytes) -> None:
        with open(partial, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(partial, target)


_SHARED_RECOVERY_WRITER: RecoverySnapshotWriter | None = None


def shared_recovery_writer() -> RecoverySnapshotWriter:
    """The one recovery writer of this process, for every window.

    Each window had its own. A tab moved to another window while its
    snapshot was being written left the outcome with the first window,
    which no longer held the tab: a failed write was never tried again,
    and two writers could land an older snapshot over a newer one. One
    writer keeps the writes of a snapshot in order, and each window takes
    the outcomes of the tabs it holds at the time (6.2)."""
    global _SHARED_RECOVERY_WRITER
    if _SHARED_RECOVERY_WRITER is None or _SHARED_RECOVERY_WRITER._closed:
        _SHARED_RECOVERY_WRITER = RecoverySnapshotWriter()
    return _SHARED_RECOVERY_WRITER


# Office draws its ribbon in colour: a document is a pale sheet, not an empty
# outline, and the mark on it is a filled badge in a colour that means
# something -- green adds, red removes, blue navigates, gold annotates. This
# app's icons used to be white strokes with the accent colour scribbled over
# them, which read as unfinished next to any Office app.
ICON_COLORS = {
    "paper": "#EEF1F4",
    "paper_line": "#8D98A6",
    "fold": "#C3CBD5",
    "blue": "#4A97E0",
    "blue_deep": "#2F6EB0",
    "green": "#5AAE5E",
    "red": "#D9544F",
    "gold": "#F0B429",
    "gold_deep": "#C08A15",
    "steel": "#AEB7C2",
    "steel_deep": "#77828F",
    "ink": "#39424E",
}


# File > Export's icons: the word on each, and its colour (6.21).
EXPORT_ICON_LABELS = {
    "export_docx": ("DOCX", "#2B5FA8"),
    "export_pptx": ("PPTX", "#B84A26"),
    "export_xlsx": ("XLSX", "#23763A"),
}


# The letter on the bold, underline and font colour buttons, as Office draws
# it in each language: German bolds an F (fett), French a G (gras) and
# underlines an S (souligné), Spanish and Portuguese N and S, Russian Ж and
# Ч, Korean 가 for all three (6.25). English, Japanese, Chinese and the rest
# write B, U and A, as their Office does or as English does.
FORMAT_GLYPHS: dict[str, dict[str, str]] = {
    "bold": {"de": "F", "fr": "G", "es": "N", "pt_BR": "N", "pt_PT": "N", "ru": "Ж", "ko": "가"},
    "underline": {"fr": "S", "es": "S", "pt_BR": "S", "pt_PT": "S", "ru": "Ч", "ko": "가"},
    "color": {"ko": "가"},
}
DEFAULT_FORMAT_GLYPHS = {"bold": "B", "underline": "U", "color": "A"}


def format_glyph(kind: str) -> str:
    """The letter of a formatting button in the UI language."""
    return FORMAT_GLYPHS[kind].get(I18N.current, DEFAULT_FORMAT_GLYPHS[kind])


def render_ribbon_icon(kind: str, color: QColor | None = None) -> QIcon:
    """Draw one ribbon icon, Office-style, without external assets.

    Module level on purpose: pure drawing, no window state.
    """
    # The export icons carry a word, drawn at twice the size so that it
    # stays sharp on a scaled display; the drawing is in 22 px units either
    # way.
    scale = 2 if kind in EXPORT_ICON_LABELS else 1
    pixmap = QPixmap(22 * scale, 22 * scale)
    pixmap.setDevicePixelRatio(scale)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.Antialiasing, True)
    foreground = QColor(COLORS["icon_ink"])
    accent = QColor(color or COLORS["accent"])
    hue = {name: QColor(value) for name, value in ICON_COLORS.items()}
    painter.setPen(QPen(foreground, 1.7, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
    painter.setBrush(Qt.NoBrush)

    def stroke(pen_color: QColor, width: float = 1.7, join: Any = Qt.RoundJoin) -> None:
        painter.setPen(QPen(pen_color, width, Qt.SolidLine, Qt.RoundCap, join))
        painter.setBrush(Qt.NoBrush)

    def fill(brush_color: QColor, pen_color: QColor | None = None, width: float = 1.1) -> None:
        painter.setBrush(brush_color)
        painter.setPen(
            QPen(pen_color, width, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin)
            if pen_color is not None
            else Qt.NoPen
        )

    def sheet(rect: QRectF, fold: float = 5.0) -> None:
        """A sheet of paper with a folded top-right corner."""
        x0, y0, x1, y1 = rect.left(), rect.top(), rect.right(), rect.bottom()
        fill(hue["paper"], hue["paper_line"])
        painter.drawPolygon(
            QPolygonF([
                QPointF(x0, y0), QPointF(x1 - fold, y0), QPointF(x1, y0 + fold),
                QPointF(x1, y1), QPointF(x0, y1),
            ])
        )
        fill(hue["fold"], hue["paper_line"])
        painter.drawPolygon(
            QPolygonF([
                QPointF(x1 - fold, y0), QPointF(x1, y0 + fold), QPointF(x1 - fold, y0 + fold),
            ])
        )
        painter.setBrush(Qt.NoBrush)

    def plain_sheet(rect: QRectF) -> None:
        """A page with no fold -- used where several pages sit together."""
        fill(hue["paper"], hue["paper_line"])
        painter.drawRect(rect)
        painter.setBrush(Qt.NoBrush)

    def text_lines(rect: QRectF, count: int = 3) -> None:
        """The ruled lines that say "this sheet has writing on it"."""
        stroke(hue["paper_line"], 1.1)
        step = rect.height() / max(1, count)
        for index in range(count):
            y = rect.top() + step * (index + 0.5)
            width = rect.width() if index < count - 1 else rect.width() * 0.6
            painter.drawLine(QPointF(rect.left(), y), QPointF(rect.left() + width, y))

    def badge(center: QPointF, mark: str, tint: QColor, radius: float = 5.2) -> None:
        """Office's corner badge: a filled disc with a white glyph."""
        fill(tint)
        painter.drawEllipse(center, radius, radius)
        arm = radius * 0.52
        stroke(QColor("#FFFFFF"), 1.9, Qt.MiterJoin)
        if mark == "plus":
            painter.drawLine(
                QPointF(center.x() - arm, center.y()), QPointF(center.x() + arm, center.y())
            )
            painter.drawLine(
                QPointF(center.x(), center.y() - arm), QPointF(center.x(), center.y() + arm)
            )
        elif mark == "cross":
            painter.drawLine(
                QPointF(center.x() - arm, center.y() - arm),
                QPointF(center.x() + arm, center.y() + arm),
            )
            painter.drawLine(
                QPointF(center.x() + arm, center.y() - arm),
                QPointF(center.x() - arm, center.y() + arm),
            )
        elif mark in ("right", "left"):
            way = 1.0 if mark == "right" else -1.0
            painter.drawLine(
                QPointF(center.x() - arm * way, center.y()),
                QPointF(center.x() + arm * 0.7 * way, center.y()),
            )
            painter.drawPolyline(
                QPolygonF([
                    QPointF(center.x() + arm * 0.1 * way, center.y() - arm * 0.8),
                    QPointF(center.x() + arm * 0.9 * way, center.y()),
                    QPointF(center.x() + arm * 0.1 * way, center.y() + arm * 0.8),
                ])
            )
        elif mark == "check":
            painter.drawPolyline(
                QPolygonF([
                    QPointF(center.x() - arm, center.y() + arm * 0.05),
                    QPointF(center.x() - arm * 0.25, center.y() + arm * 0.8),
                    QPointF(center.x() + arm, center.y() - arm * 0.75),
                ])
            )

    def arrow(start: QPointF, end: QPointF, tint: QColor, width: float = 2.0) -> None:
        """A shaft with an open chevron head.

        Open, not filled: a triangle this small antialiases into a blob.
        """
        stroke(tint, width, Qt.MiterJoin)
        painter.drawLine(start, end)
        span = QPointF(end.x() - start.x(), end.y() - start.y())
        length = max(0.001, (span.x() ** 2 + span.y() ** 2) ** 0.5)
        ux, uy = span.x() / length, span.y() / length
        barb = 3.4
        painter.drawPolyline(
            QPolygonF([
                QPointF(end.x() - barb * (ux + uy * 0.9), end.y() - barb * (uy - ux * 0.9)),
                end,
                QPointF(end.x() - barb * (ux - uy * 0.9), end.y() - barb * (uy + ux * 0.9)),
            ])
        )

    def letter(value: str, size: int = 11, tint: QColor | None = None) -> None:
        font = QFont("Segoe UI", size)
        font.setBold(True)
        # Grayscale antialiasing: subpixel rendering fringes these glyphs
        # with colour, very visible over a coloured band.
        font.setStyleStrategy(QFont.PreferAntialias | QFont.NoSubpixelAntialias)
        painter.setFont(font)
        painter.setPen(QPen(tint if tint is not None else foreground))
        painter.drawText(QRectF(1, 0, 20, 19), Qt.AlignCenter, value)

    def color_band() -> None:
        """PowerPoint's colour band: the strip under the tool's pictogram.

        One band, in the icon. The button used to paint a second one with a
        4px border-bottom, which is what made these look like two stacked
        underlines.
        """
        # A neutral hairline, not a darker shade of the colour itself: the
        # default font colour is near-black, and a black band on a black
        # toolbar is no indicator at all.
        fill(accent, hue["paper_line"], 1.0)
        painter.drawRect(QRectF(3.5, 16.4, 15, 4.2))
        painter.setBrush(Qt.NoBrush)

    def glyph_over_band(value: str, size: int) -> None:
        """A letter sitting above the colour band, PowerPoint's Font Color."""
        font = QFont("Segoe UI", size)
        font.setBold(True)
        metrics = QFontMetrics(font)
        bounds = metrics.tightBoundingRect(value)
        path = QPainterPath()
        path.addText(
            11.0 - bounds.width() / 2.0 - bounds.x(),
            8.0 + bounds.height() / 2.0,
            font,
            value,
        )
        fill(foreground)
        painter.drawPath(path)
        painter.setBrush(Qt.NoBrush)

    def marker_pen() -> None:
        """PowerPoint's highlighter: a silver chisel marker, tilted."""
        body = [(7.8, 10.4), (14.6, 1.4), (18.9, 4.6), (12.1, 13.6)]
        tip = [(7.8, 10.4), (12.1, 13.6), (4.6, 15.9)]
        fill(hue["steel"], hue["steel_deep"])
        painter.drawPolygon(QPolygonF([QPointF(x, y) for x, y in body]))
        fill(hue["gold"], hue["gold_deep"])
        painter.drawPolygon(QPolygonF([QPointF(x, y) for x, y in tip]))
        painter.setBrush(Qt.NoBrush)

    def line_mark(start: QPointF, end: QPointF) -> None:
        """Underline's and strikethrough's line, in the colour the markup
        will be drawn in when one is given (v5.20) -- with a pale halo when
        that colour is too dark to see on the toolbar, as the shape tools."""
        if color is None:
            stroke(foreground, 1.7)
        else:
            if accent.lightness() < 96:
                stroke(QColor("#C9D1DA"), 3.8)
                painter.drawLine(start, end)
            stroke(accent, 2.2)
        painter.drawLine(start, end)

    # ---- files -------------------------------------------------------
    if kind == "new":
        sheet(QRectF(3, 2, 12.5, 17))
        badge(QPointF(16.6, 16.4), "plus", hue["green"])
    elif kind == "open":
        fill(hue["gold_deep"])
        painter.drawPolygon(
            QPolygonF([
                QPointF(2, 6), QPointF(8.5, 6), QPointF(10.5, 8.6),
                QPointF(19.5, 8.6), QPointF(19.5, 18), QPointF(2, 18),
            ])
        )
        fill(hue["gold"])
        painter.drawPolygon(
            QPolygonF([
                QPointF(3.6, 10.4), QPointF(21, 10.4), QPointF(18.4, 18.6), QPointF(1, 18.6),
            ])
        )
        painter.setBrush(Qt.NoBrush)
    elif kind in ("save", "save_as"):
        fill(hue["blue"], hue["blue_deep"])
        painter.drawRoundedRect(QRectF(2.5, 2.5, 17, 17), 1.6, 1.6)
        fill(hue["paper"])
        painter.drawRect(QRectF(6, 3.5, 10, 6))          # shutter
        fill(hue["blue_deep"])
        painter.drawRect(QRectF(12.5, 4.6, 2.4, 3.8))    # its window
        fill(hue["paper"])
        painter.drawRect(QRectF(5.5, 12, 11, 7))         # label
        painter.setBrush(Qt.NoBrush)
        if kind == "save_as":
            # Office badges "save under another name" with a pencil.
            fill(hue["gold"], hue["gold_deep"])
            painter.drawPolygon(
                QPolygonF([
                    QPointF(13.4, 21.2), QPointF(14.2, 17.6), QPointF(16.9, 20.1),
                ])
            )
            stroke(hue["gold"], 2.6)
            painter.drawLine(QPointF(16.2, 18.6), QPointF(20.4, 14.4))
            stroke(hue["gold_deep"], 1.0)
            painter.drawLine(QPointF(15.4, 19.4), QPointF(19.6, 15.2))
    elif kind == "print":
        fill(hue["paper"], hue["paper_line"])
        painter.drawRect(QRectF(5.5, 1.8, 11, 6))
        fill(hue["steel"], hue["steel_deep"])
        painter.drawRoundedRect(QRectF(2, 7.5, 18, 8.5), 1.8, 1.8)
        fill(hue["blue"])
        painter.drawRect(QRectF(15.5, 9.6, 2.6, 2.2))
        fill(hue["paper"], hue["paper_line"])
        painter.drawRect(QRectF(5.5, 13, 11, 7))
        text_lines(QRectF(7.4, 14.4, 7.2, 4.2), 2)
        painter.setBrush(Qt.NoBrush)
    elif kind in ("undo", "redo"):
        path = QPainterPath()
        if kind == "undo":
            path.moveTo(18, 17.5)
            path.cubicTo(18, 8.5, 10, 5.5, 5.5, 10)
            head = QPointF(5.5, 10)
            tail = QPointF(9.5, 8.2)
        else:
            path.moveTo(4, 17.5)
            path.cubicTo(4, 8.5, 12, 5.5, 16.5, 10)
            head = QPointF(16.5, 10)
            tail = QPointF(12.5, 8.2)
        stroke(hue["blue"], 2.4)
        painter.drawPath(path)
        arrow(tail, head, hue["blue"], 2.4)
    # ---- clipboard ---------------------------------------------------
    elif kind == "copy":
        plain_sheet(QRectF(3, 2, 10.5, 13))
        sheet(QRectF(8.5, 6.5, 10.5, 13), 4.0)
        text_lines(QRectF(10.4, 11, 6.6, 5.4), 3)
        painter.setBrush(Qt.NoBrush)
    elif kind == "cut":
        # Scissors: each blade runs past the pivot into the ring on the
        # *other* side, which is what makes it read as scissors.
        stroke(hue["steel"], 2.0)
        painter.drawPolyline(
            QPolygonF([QPointF(5.8, 2.6), QPointF(11, 11), QPointF(15.2, 17.2)])
        )
        painter.drawPolyline(
            QPolygonF([QPointF(16.2, 2.6), QPointF(11, 11), QPointF(6.8, 17.2)])
        )
        fill(Qt.transparent, hue["blue"], 1.9)
        painter.drawEllipse(QPointF(6.4, 18.4), 2.5, 2.5)
        painter.drawEllipse(QPointF(15.6, 18.4), 2.5, 2.5)
        fill(hue["steel_deep"])
        painter.drawEllipse(QPointF(11, 11), 1.2, 1.2)
        painter.setBrush(Qt.NoBrush)
    elif kind == "paste":
        fill(hue["gold_deep"])
        painter.drawRoundedRect(QRectF(3.5, 3.5, 15, 16.5), 1.8, 1.8)
        fill(hue["steel"], hue["steel_deep"])
        painter.drawRoundedRect(QRectF(7.5, 1.6, 7, 4.2), 1.2, 1.2)
        fill(hue["paper"], hue["paper_line"])
        painter.drawRect(QRectF(6, 8, 10, 11))
        text_lines(QRectF(7.6, 9.6, 6.8, 7.4), 3)
        painter.setBrush(Qt.NoBrush)
    # ---- page management --------------------------------------------
    elif kind.startswith("page_edit_"):
        command = kind.removeprefix("page_edit_")
        if command == "blank":
            sheet(QRectF(2, 2, 12, 16))
            badge(QPointF(16.4, 16.2), "plus", hue["green"])
        elif command == "delete":
            sheet(QRectF(2, 2, 12, 16))
            badge(QPointF(16.4, 16.2), "cross", hue["red"])
        elif command == "pdf":
            # Pages dropping in from another file. Vertical on purpose:
            # laid out horizontally it was one rectangle away from merge.
            plain_sheet(QRectF(7.5, 0.5, 7, 5.5))
            plain_sheet(QRectF(2.5, 12, 17, 9))
            arrow(QPointF(11, 6.8), QPointF(11, 13.6), hue["green"], 2.1)
        elif command == "duplicate":
            plain_sheet(QRectF(1.5, 5, 10.5, 15))
            sheet(QRectF(8.5, 1.5, 10.5, 15), 4.0)
        elif command == "rotate":
            plain_sheet(QRectF(4, 8.5, 14, 11.5))
            path = QPainterPath()
            path.moveTo(4.5, 7.2)
            path.quadTo(11, -0.4, 17.5, 7.2)
            stroke(hue["blue"], 2.1)
            painter.drawPath(path)
            # Barbs trail back along the curve's own tangent at its end,
            # so the head sits on the arc instead of beside it.
            painter.drawPolyline(
                QPolygonF([
                    QPointF(17.0, 3.3), QPointF(17.5, 7.2), QPointF(13.7, 6.2),
                ])
            )
        elif command == "extract":
            plain_sheet(QRectF(1.5, 2, 10.5, 17))
            arrow(QPointF(13.4, 11), QPointF(20.4, 11), hue["blue"], 2.1)
        elif command == "merge":
            plain_sheet(QRectF(0.8, 1.5, 6.4, 8))
            plain_sheet(QRectF(0.8, 12.5, 6.4, 8))
            plain_sheet(QRectF(14.8, 5, 6.4, 12))
            arrow(QPointF(8.2, 11), QPointF(14.2, 11), hue["blue"], 2.1)
        elif command == "split":
            plain_sheet(QRectF(0.8, 5, 6.4, 12))
            plain_sheet(QRectF(14.8, 1.5, 6.4, 8))
            plain_sheet(QRectF(14.8, 12.5, 6.4, 8))
            arrow(QPointF(8.2, 11), QPointF(14.2, 11), hue["blue"], 2.1)
    # ---- File > Export (6.7, 6.21) -----------------------------------
    # A sheet with what is in such a file, and the kind of file written on
    # a band of a colour of its own. Not the Office icons, which were asked
    # for (6.21): Microsoft's trademark guidelines allow its app icons only
    # under an express licence. The arrow badges they had looked alike.
    elif kind in EXPORT_ICON_LABELS:
        label, tint = EXPORT_ICON_LABELS[kind]
        sheet(QRectF(4, 1, 15, 20))
        if kind == "export_docx":
            text_lines(QRectF(6.5, 4, 7.5, 7.5), 3)
        elif kind == "export_pptx":
            fill(hue["paper"], hue["paper_line"], 1.0)
            painter.drawRect(QRectF(6.5, 4.2, 9.5, 6.8))
            fill(QColor(tint))
            painter.drawRect(QRectF(8, 5.7, 6.5, 1.6))
            fill(hue["steel"])
            painter.drawRect(QRectF(8, 8.2, 3.6, 1.8))
        else:
            stroke(hue["paper_line"], 1.0)
            painter.drawRect(QRectF(6.5, 4.2, 9.5, 7))
            for x in (9.7, 12.9):
                painter.drawLine(QPointF(x, 4.2), QPointF(x, 11.2))
            painter.drawLine(QPointF(6.5, 7.7), QPointF(16, 7.7))
        band = QRectF(0.5, 12.4, 21, 7.8)
        fill(QColor(tint))
        painter.drawRoundedRect(band, 1.5, 1.5)
        font = QFont("Segoe UI")
        font.setPixelSize(6)
        font.setBold(True)
        # Four letters across the band in any font Windows falls back to.
        width = QFontMetricsF(font).horizontalAdvance(label)
        if width > band.width() - 1.5:
            font.setStretch(max(50, int(100 * (band.width() - 1.5) / width)))
        font.setStyleStrategy(QFont.PreferAntialias | QFont.NoSubpixelAntialias)
        painter.setFont(font)
        painter.setPen(QPen(QColor("#FFFFFF")))
        painter.drawText(band, Qt.AlignCenter, label)
    # ---- annotation tools -------------------------------------------
    elif kind == "text":
        fill(hue["paper"], hue["paper_line"])
        painter.drawRect(QRectF(3, 4.5, 16, 13))
        painter.setBrush(Qt.NoBrush)
        letter("A", 9, hue["ink"])
        stroke(hue["blue"], 1.4, Qt.MiterJoin)
        for corner in (QPointF(3, 4.5), QPointF(19, 4.5), QPointF(3, 17.5), QPointF(19, 17.5)):
            painter.drawRect(QRectF(corner.x() - 1.4, corner.y() - 1.4, 2.8, 2.8))
    elif kind == "note":
        # A sticky note with its corner peeled, in the colour a new note
        # would be (5.32; it was always gold before, because a note had no
        # colour anything could set). A dark one gets a pale edge, as the
        # drawing tools do, so it still shows on the toolbar.
        paper = QColor(color) if color is not None else QColor(hue["gold"])
        pale = paper.lightness() < 96
        edge = QColor("#C9D1DA") if pale else paper.darker(140)
        rule = QColor("#C9D1DA") if pale else paper.darker(205)
        fill(paper, edge)
        painter.drawPolygon(
            QPolygonF([
                QPointF(3.5, 3), QPointF(18.5, 3), QPointF(18.5, 13.5),
                QPointF(13, 19), QPointF(3.5, 19),
            ])
        )
        fill(edge)
        painter.drawPolygon(
            QPolygonF([QPointF(18.5, 13.5), QPointF(13, 13.5), QPointF(13, 19)])
        )
        stroke(rule, 1.1)
        painter.drawLine(QPointF(6, 7.5), QPointF(16, 7.5))
        painter.drawLine(QPointF(6, 10.6), QPointF(16, 10.6))
        painter.drawLine(QPointF(6, 13.7), QPointF(11.5, 13.7))
        painter.setBrush(Qt.NoBrush)
    elif kind in SHAPE_TOOL_KINDS:
        # The drawing tools. Given the colour they draw in, they show it:
        # always-blue tools hid which colour a new shape would get (v5.18).
        # A dark colour gets a pale edge so it still shows on the toolbar.
        tint = QColor(color) if color is not None else None
        halo = QColor("#C9D1DA") if tint is not None and tint.lightness() < 96 else None
        if kind == "ink":
            squiggle = QPolygonF(
                [QPointF(3, 19), QPointF(7, 17.2), QPointF(11.5, 19), QPointF(16.5, 16.8)]
            )
            if halo is not None:
                stroke(halo, 3.8)
                painter.drawPolyline(squiggle)
            stroke(tint or accent, 2.0)
            painter.drawPolyline(squiggle)
            if tint is None:
                fill(hue["blue"], hue["blue_deep"])
            else:
                fill(tint, halo or tint.darker(150))
            painter.drawPolygon(
                QPolygonF([QPointF(9, 11), QPointF(15.5, 3.5), QPointF(18.5, 6), QPointF(12, 13.5)])
            )
            fill(hue["steel"], hue["steel_deep"])
            painter.drawPolygon(
                QPolygonF([QPointF(9, 11), QPointF(12, 13.5), QPointF(7.2, 15.2)])
            )
        elif kind == "rectangle":
            frame = QRectF(3, 5, 16, 12)
            if tint is None:
                fill(QColor("#7EB4E4"), hue["blue_deep"], 1.5)
            else:
                if halo is not None:
                    stroke(halo, 4.2, Qt.MiterJoin)
                    painter.drawRect(frame)
                face = QColor(tint)
                face.setAlpha(90)
                fill(face, tint, 2.2)
            painter.drawRect(frame)
        elif kind == "arrow":
            if halo is not None:
                arrow(QPointF(3.5, 17.5), QPointF(18, 5), halo, 4.2)
            arrow(QPointF(3.5, 17.5), QPointF(18, 5), tint or hue["blue"], 2.2)
        else:
            if halo is not None:
                stroke(halo, 4.2)
                painter.drawLine(QPointF(3, 17.5), QPointF(19, 4.5))
            stroke(tint or hue["blue"], 2.2)
            painter.drawLine(QPointF(3, 17.5), QPointF(19, 4.5))
        painter.setBrush(Qt.NoBrush)
    elif kind == "image":
        # The classic Office picture: sky, hills, a sun.
        fill(QColor("#BFE0F5"), hue["paper_line"])
        painter.drawRect(QRectF(2.5, 4, 17, 14))
        fill(hue["gold"])
        painter.drawEllipse(QPointF(15.2, 8.2), 2.0, 2.0)
        fill(QColor("#5AAE5E"))
        painter.drawPolygon(
            QPolygonF([
                QPointF(2.5, 18), QPointF(8.5, 10.5), QPointF(13, 15),
                QPointF(15.5, 12.6), QPointF(19.5, 18),
            ])
        )
        fill(Qt.transparent, hue["paper_line"], 1.1)
        painter.drawRect(QRectF(2.5, 4, 17, 14))
        painter.setBrush(Qt.NoBrush)
    # ---- navigation --------------------------------------------------
    elif kind in ("page_prev", "page_next", "page_first", "page_last"):
        left = kind in ("page_prev", "page_first")
        x1, x2 = (16, 7) if left else (6, 15)
        stroke(hue["blue"], 2.2, Qt.MiterJoin)
        painter.drawPolyline(
            QPolygonF([QPointF(x1, 5.5), QPointF(x2, 11), QPointF(x1, 16.5)])
        )
        if kind in ("page_first", "page_last"):
            edge = 4.0 if left else 18.0
            painter.drawLine(QPointF(edge, 5), QPointF(edge, 17))
    elif kind == "page_jump":
        sheet(QRectF(2.5, 2, 16.5, 18), 4.5)
        stroke(hue["blue"], 1.9)
        painter.drawLine(QPointF(9.2, 7), QPointF(7.8, 15.4))
        painter.drawLine(QPointF(13.8, 7), QPointF(12.4, 15.4))
        painter.drawLine(QPointF(5.8, 9.9), QPointF(15.2, 9.9))
        painter.drawLine(QPointF(5.3, 12.9), QPointF(14.7, 12.9))
    elif kind == "filter":
        # A funnel, as Excel's filter (6.10).
        fill(hue["blue"], hue["blue_deep"])
        painter.drawPolygon(
            QPolygonF([
                QPointF(3, 4), QPointF(19, 4), QPointF(12.6, 11.4), QPointF(12.6, 18.5),
                QPointF(9.4, 16.6), QPointF(9.4, 11.4),
            ])
        )
        painter.setBrush(Qt.NoBrush)
    elif kind == "outline_add":
        # An outline -- headings, one under another -- and a new entry (6.9).
        for top, left in ((3.5, 2.5), (8.5, 6.0), (13.5, 2.5)):
            fill(hue["blue"])
            painter.drawRect(QRectF(left, top, 2.6, 2.6))
            stroke(foreground, 1.6)
            painter.drawLine(QPointF(left + 4.4, top + 1.3), QPointF(13.5, top + 1.3))
        badge(QPointF(16.4, 16.2), "plus", hue["green"])
    elif kind in ("zoom_in", "zoom_out", "find"):
        stroke(hue["blue"], 2.0)
        painter.drawEllipse(QRectF(3, 3, 12, 12))
        painter.setBrush(Qt.NoBrush)
        stroke(hue["blue_deep"], 2.6)
        painter.drawLine(QPointF(13.4, 13.4), QPointF(19, 19))
        if kind != "find":
            stroke(hue["blue_deep"], 1.9)
            painter.drawLine(QPointF(6, 9), QPointF(12, 9))
            if kind == "zoom_in":
                painter.drawLine(QPointF(9, 6), QPointF(9, 12))
    elif kind == "actual_size":
        letter("1:1", 7, hue["blue"])
    elif kind == "fit_width":
        plain_sheet(QRectF(3, 3, 16, 16))
        arrow(QPointF(11, 11), QPointF(5.2, 11), hue["blue"], 1.9)
        arrow(QPointF(11, 11), QPointF(16.8, 11), hue["blue"], 1.9)
    elif kind == "fit_page":
        plain_sheet(QRectF(5, 2, 12, 18))
        stroke(hue["blue"], 1.9, Qt.MiterJoin)
        painter.drawPolyline(
            QPolygonF([QPointF(2, 9), QPointF(2, 5), QPointF(6, 5)])
        )
        painter.drawPolyline(
            QPolygonF([QPointF(20, 9), QPointF(20, 5), QPointF(16, 5)])
        )
        painter.drawPolyline(
            QPolygonF([QPointF(2, 13), QPointF(2, 17), QPointF(6, 17)])
        )
        painter.drawPolyline(
            QPolygonF([QPointF(20, 13), QPointF(20, 17), QPointF(16, 17)])
        )
    elif kind == "single_page":
        sheet(QRectF(6, 2, 11, 18), 4.5)
    elif kind == "facing_pages":
        plain_sheet(QRectF(2, 4, 8, 15))
        plain_sheet(QRectF(12, 4, 8, 15))
        stroke(hue["blue"], 1.6)
        painter.drawLine(QPointF(11, 3.5), QPointF(11, 19.5))
    elif kind == "freeze_page":
        # Freeze Page (v5.25): one page held by a push pin.
        plain_sheet(QRectF(4, 5, 12.5, 15))
        stroke(hue["red"], 1.8)
        painter.drawLine(QPointF(10.2, 7.5), QPointF(10.2, 12.5))
        fill(hue["red"], hue["ink"], 0.9)
        painter.drawEllipse(QPointF(10.2, 5.2), 3.4, 3.4)
    elif kind == "refresh":
        stroke(hue["blue"], 2.0)
        painter.setBrush(Qt.NoBrush)
        # A ring with a quarter cut out of it, and a head on the open end.
        painter.drawArc(QRectF(3.5, 3.5, 15, 15), 60 * 16, 280 * 16)
        painter.setBrush(hue["blue"])
        painter.setPen(Qt.NoPen)
        painter.drawPolygon(
            QPolygonF([QPointF(14.6, 1.6), QPointF(19.4, 5.2), QPointF(13.6, 6.6)])
        )
        painter.setBrush(Qt.NoBrush)
    elif kind == "sidebar":
        fill(hue["paper"], hue["paper_line"])
        painter.drawRect(QRectF(2, 3, 18, 16))
        fill(hue["blue"])
        painter.drawRect(QRectF(2.6, 3.6, 5.4, 14.8))
        stroke(hue["paper_line"], 1.1)
        painter.drawLine(QPointF(8, 3), QPointF(8, 19))
        painter.setBrush(Qt.NoBrush)
    elif kind in ("match_next", "match_prev"):
        stroke(hue["blue"], 1.9)
        painter.drawEllipse(QRectF(2, 3, 10, 10))
        painter.setBrush(Qt.NoBrush)
        stroke(hue["blue_deep"], 2.2)
        painter.drawLine(QPointF(10.4, 11.4), QPointF(14, 15))
        up = kind == "match_prev"
        arrow(
            QPointF(18, 17 if up else 11),
            QPointF(18, 11 if up else 17),
            hue["green"] if not up else hue["blue"],
            2.0,
        )
    elif kind in ("tab_next", "tab_prev"):
        # Two document tabs on their bar, and the direction underneath.
        forward = kind == "tab_next"
        fill(hue["paper"], hue["paper_line"])
        painter.drawRect(QRectF(2, 4.5, 8, 7))
        fill(hue["steel"], hue["paper_line"])
        painter.drawRect(QRectF(11.5, 4.5, 8, 7))
        stroke(hue["paper_line"], 1.4)
        painter.drawLine(QPointF(1.5, 12), QPointF(20.5, 12))
        painter.setBrush(Qt.NoBrush)
        arrow(
            QPointF(11.0 if forward else 11.0, 17),
            QPointF(16.5 if forward else 5.5, 17),
            hue["blue"],
            2.0,
        )
    # ---- character formatting ---------------------------------------
    elif kind == "text_color":
        # PowerPoint's Font Color: the letter, and the colour under it.
        glyph_over_band(format_glyph("color"), 12)
        color_band()
    elif kind == "text_bold_run":
        letter(format_glyph("bold"), 12)
    elif kind == "text_underline_run":
        letter(format_glyph("underline"), 12)
        line_mark(QPointF(5, 19), QPointF(17, 19))
    elif kind == "text_strike_run":
        # Office's Strikethrough, a light "abc" in every language: an S
        # struck through sat beside an underlined S in French, Spanish and
        # Portuguese (6.25). The line goes through the middle of the small
        # letters, wherever the font puts them, and out past them: in the
        # letters' own colour it is lost in them otherwise.
        font = QFont("Segoe UI", 9)
        font.setStyleStrategy(QFont.PreferAntialias | QFont.NoSubpixelAntialias)
        painter.setFont(font)
        painter.setPen(QPen(foreground))
        painter.drawText(QRectF(1, 0, 20, 19), Qt.AlignCenter, "abc")
        metrics = QFontMetricsF(font)
        middle = 9.5 + (metrics.ascent() - metrics.descent()) / 2 - metrics.xHeight() / 2
        line_mark(QPointF(1, middle), QPointF(21, middle))
    elif kind == "text_highlight_run":
        # PowerPoint's Text Highlight Color: the marker, and the colour
        # under it.
        marker_pen()
        color_band()
    elif kind == "drawing_color":
        # PowerPoint's Shape Outline: a shape drawn in the colour, and the
        # colour under it.
        fill(Qt.transparent, accent, 2.2)
        painter.drawRoundedRect(QRectF(4.5, 2.8, 13, 10), 1.8, 1.8)
        painter.setBrush(Qt.NoBrush)
        color_band()
    elif kind in ("nup_across", "nup_down"):
        # The path the pages follow across a 2x2 sheet: a Z for across, an
        # N for down. Drawn rather than labelled, because "horizontal" and
        # "vertical" are easy to mix up with the paper orientation.
        cells = [
            QRectF(1.5, 1.5, 8.5, 8.5), QRectF(12, 1.5, 8.5, 8.5),
            QRectF(1.5, 12, 8.5, 8.5), QRectF(12, 12, 8.5, 8.5),
        ]
        # Pale cells so the path drawn over them stays the thing you see.
        fill(QColor("#DDE3EA"), hue["paper_line"], 0.9)
        for cell in cells:
            painter.drawRect(cell)
        painter.setBrush(Qt.NoBrush)
        order = (0, 1, 2, 3) if kind == "nup_across" else (0, 2, 1, 3)
        centres = [cells[index].center() for index in order]
        stroke(accent, 2.2, Qt.MiterJoin)
        painter.drawPolyline(QPolygonF(centres))
        last, previous = centres[-1], centres[-2]
        span = QPointF(last.x() - previous.x(), last.y() - previous.y())
        length = max(0.001, (span.x() ** 2 + span.y() ** 2) ** 0.5)
        ux, uy = span.x() / length, span.y() / length
        barb = 3.2
        painter.drawPolyline(
            QPolygonF([
                QPointF(last.x() - barb * (ux + uy * 0.9), last.y() - barb * (uy - ux * 0.9)),
                last,
                QPointF(last.x() - barb * (ux - uy * 0.9), last.y() - barb * (uy + ux * 0.9)),
            ])
        )
    elif kind == "language":
        fill(hue["blue"], hue["blue_deep"])
        painter.drawEllipse(QRectF(2, 2, 18, 18))
        stroke(QColor("#DCEBFA"), 1.2)
        painter.drawEllipse(QRectF(7.5, 2, 7, 18))
        painter.drawLine(QPointF(2.6, 11), QPointF(19.4, 11))
        painter.drawLine(QPointF(4.2, 6.6), QPointF(17.8, 6.6))
        painter.drawLine(QPointF(4.2, 15.4), QPointF(17.8, 15.4))
    elif kind == "lock":
        # A padlock, for the notice about a PDF's usage restrictions.
        stroke(hue["steel_deep"], 2.2)
        shackle = QPainterPath()
        shackle.moveTo(7, 10)
        shackle.lineTo(7, 7)
        shackle.cubicTo(7, 2.4, 15, 2.4, 15, 7)
        shackle.lineTo(15, 10)
        painter.drawPath(shackle)
        fill(hue["gold"], hue["gold_deep"])
        painter.drawRoundedRect(QRectF(4, 9.5, 14, 10.5), 1.8, 1.8)
        fill(hue["ink"])
        painter.drawEllipse(QPointF(11, 13.8), 1.7, 1.7)
        painter.drawRect(QRectF(10.3, 14.4, 1.4, 3.2))
    # ---- right-click menu commands (v5.17) ---------------------------
    # The pictures Office's context menus give the same commands; where
    # the ribbon already has one (copy, paste, note ...) it is reused.
    elif kind == "delete":
        # A red cross on its own: remove what is selected.
        stroke(hue["red"], 2.8, Qt.MiterJoin)
        painter.drawLine(QPointF(5.5, 5.5), QPointF(16.5, 16.5))
        painter.drawLine(QPointF(16.5, 5.5), QPointF(5.5, 16.5))
    elif kind == "select_all":
        # A dashed frame around lines of text.
        painter.setPen(QPen(hue["blue"], 1.4, Qt.DashLine, Qt.FlatCap, Qt.MiterJoin))
        painter.setBrush(Qt.NoBrush)
        painter.drawRect(QRectF(2.5, 3.5, 17, 15))
        stroke(foreground, 1.6)
        for y, right in ((7.5, 16.5), (11.0, 16.5), (14.5, 12.5)):
            painter.drawLine(QPointF(5.5, y), QPointF(right, y))
    elif kind in ("redact", "redact_apply"):
        # Acrobat's redaction: lines of text, a black bar laid over one.
        # Applying the marks adds the tick.
        stroke(hue["paper_line"], 1.6)
        painter.drawLine(QPointF(3, 4.5), QPointF(19, 4.5))
        painter.drawLine(QPointF(3, 17.5), QPointF(11, 17.5))
        fill(QColor("#111111"), hue["steel_deep"], 1.0)
        painter.drawRect(QRectF(2.5, 8, 17, 5.5))
        painter.setBrush(Qt.NoBrush)
        if kind == "redact_apply":
            badge(QPointF(16.6, 16.8), "check", hue["green"])
    elif kind == "duplicate":
        # PowerPoint's Duplicate: the same shape twice, the copy in front.
        fill(hue["steel"], hue["steel_deep"], 1.2)
        painter.drawRoundedRect(QRectF(2.5, 2.5, 11, 10), 1.5, 1.5)
        fill(QColor("#7EB4E4"), hue["blue_deep"], 1.4)
        painter.drawRoundedRect(QRectF(8.5, 9.5, 11, 10), 1.5, 1.5)
        painter.setBrush(Qt.NoBrush)
    elif kind in ("bring_front", "bring_forward", "send_backward", "send_back"):
        # PowerPoint's Arrange pictures: the selected shape (blue) over or
        # under the others (grey) -- one other for a single step, two for
        # all the way to the front or the back.
        def shape(rect: QRectF, selected: bool) -> None:
            if selected:
                fill(hue["blue"], hue["blue_deep"], 1.3)
            else:
                fill(hue["steel"], hue["steel_deep"], 1.1)
            painter.drawRect(rect)

        if kind in ("bring_forward", "send_backward"):
            back, front = QRectF(2.5, 2.5, 11, 10), QRectF(8.5, 9.5, 11, 10)
            shape(back, kind == "send_backward")
            shape(front, kind == "bring_forward")
        else:
            middle = QRectF(6, 6.5, 10, 9)
            if kind == "send_back":
                shape(middle, True)
            for rect in (QRectF(1.5, 1.5, 9, 8), QRectF(11.5, 12.5, 9, 8)):
                shape(rect, False)
            if kind == "bring_front":
                shape(middle, True)
        painter.setBrush(Qt.NoBrush)
    elif kind == "crop":
        # Office's Crop: two corner marks overlapping.
        stroke(foreground, 2.0, Qt.MiterJoin)
        painter.drawPolyline(QPolygonF([QPointF(6, 1.5), QPointF(6, 16), QPointF(20.5, 16)]))
        painter.drawPolyline(QPolygonF([QPointF(1.5, 6), QPointF(16, 6), QPointF(16, 20.5)]))
    elif kind == "font":
        letter("Aa", 10)
    elif kind == "font_size":
        # A large A and a small one, like Office's Grow / Shrink Font.
        for value, size, box in (
            ("A", 12, QRectF(0, 1, 13, 19)),
            ("A", 8, QRectF(11, 6, 10, 14)),
        ):
            font = QFont("Segoe UI", size)
            font.setBold(True)
            font.setStyleStrategy(QFont.PreferAntialias | QFont.NoSubpixelAntialias)
            painter.setFont(font)
            painter.setPen(QPen(foreground))
            painter.drawText(box, Qt.AlignCenter, value)
    elif kind in ("align_left", "align_center", "align_right"):
        stroke(foreground, 1.8)
        for index, width in enumerate((16.0, 10.0, 16.0, 10.0)):
            y = 4.5 + index * 4.3
            if kind == "align_left":
                x0 = 3.0
            elif kind == "align_right":
                x0 = 19.0 - width
            else:
                x0 = 11.0 - width / 2
            painter.drawLine(QPointF(x0, y), QPointF(x0 + width, y))
    elif kind == "confirm":
        # A tick: the text is done.
        stroke(hue["green"], 3.0)
        painter.drawPolyline(QPolygonF([QPointF(4, 11.5), QPointF(9, 16.5), QPointF(18.5, 5.5)]))
    elif kind == "line_width":
        # Office's Weight: three lines, thin to thick.
        for y, width in ((5.0, 1.2), (10.5, 2.4), (16.5, 4.2)):
            painter.setPen(QPen(foreground, width, Qt.SolidLine, Qt.FlatCap))
            painter.drawLine(QPointF(3, y), QPointF(19, y))
    elif kind.startswith("line_weight_"):
        # One line at the weight the entry sets.
        points = float(kind.removeprefix("line_weight_") or 1)
        painter.setPen(QPen(foreground, max(1.6, points * 1.4), Qt.SolidLine, Qt.FlatCap))
        painter.drawLine(QPointF(2.5, 11), QPointF(19.5, 11))
    elif kind == "properties":
        # A document with Office's blue information badge.
        sheet(QRectF(2.5, 2, 12.5, 17))
        text_lines(QRectF(4.5, 7, 7, 8), 3)
        fill(hue["blue"])
        painter.drawEllipse(QPointF(15.8, 15.6), 5.2, 5.2)
        stroke(QColor("#FFFFFF"), 1.9)
        painter.drawLine(QPointF(15.8, 14.8), QPointF(15.8, 18.4))
        fill(QColor("#FFFFFF"))
        painter.drawEllipse(QPointF(15.8, 12.5), 1.0, 1.0)
        painter.setBrush(Qt.NoBrush)
    elif kind == "form":
        # A form: two fields, the text cursor in the first.
        fill(hue["paper"], hue["paper_line"])
        painter.drawRect(QRectF(2, 2, 18, 18))
        fill(Qt.transparent, hue["blue"], 1.4)
        painter.drawRect(QRectF(4.5, 5, 13, 4.5))
        painter.drawRect(QRectF(4.5, 12.5, 13, 4.5))
        stroke(hue["ink"], 1.3)
        painter.drawLine(QPointF(7, 5.8), QPointF(7, 8.7))
    elif kind in ("ocr", "ocr_document"):
        # A scanner's corner marks around what gets read: letters for one
        # page, a stack of pages for the whole document.
        stroke(hue["blue"], 1.9, Qt.MiterJoin)
        for x, y, dx, dy in ((2, 2, 1, 1), (20, 2, -1, 1), (2, 20, 1, -1), (20, 20, -1, -1)):
            painter.drawPolyline(QPolygonF([
                QPointF(x, y + 4.5 * dy), QPointF(x, y), QPointF(x + 4.5 * dx, y),
            ]))
        if kind == "ocr":
            letter("Ab", 9)
        else:
            plain_sheet(QRectF(8, 4.5, 9, 11))
            plain_sheet(QRectF(5, 7, 9, 11))
            text_lines(QRectF(6.5, 9.5, 6, 6), 3)
    elif kind == "sanitize":
        # A shield with a tick: a copy cleared of hidden content.
        shield = QPainterPath()
        shield.moveTo(11, 1.8)
        shield.lineTo(19, 4.8)
        shield.lineTo(19, 10.5)
        shield.cubicTo(19, 15.5, 15.5, 18.6, 11, 20.4)
        shield.cubicTo(6.5, 18.6, 3, 15.5, 3, 10.5)
        shield.lineTo(3, 4.8)
        shield.closeSubpath()
        fill(hue["green"], QColor("#3C8540"), 1.1)
        painter.drawPath(shield)
        stroke(QColor("#FFFFFF"), 2.2)
        painter.drawPolyline(QPolygonF([QPointF(7, 11), QPointF(10, 14), QPointF(15.5, 7.5)]))
    elif kind == "tools":
        # A spanner.
        stroke(hue["steel"], 3.2)
        painter.drawLine(QPointF(4.5, 17.5), QPointF(11.8, 10.2))
        painter.drawArc(QRectF(10.6, 3.0, 8.4, 8.4), 70 * 16, 290 * 16)
    elif kind == "view":
        # An eye.
        eye = QPainterPath()
        eye.moveTo(2, 11)
        eye.quadTo(11, 2, 20, 11)
        eye.quadTo(11, 20, 2, 11)
        fill(hue["paper"], hue["paper_line"], 1.2)
        painter.drawPath(eye)
        fill(hue["blue"])
        painter.drawEllipse(QPointF(11, 11), 3.6, 3.6)
        fill(hue["ink"])
        painter.drawEllipse(QPointF(11, 11), 1.5, 1.5)
        painter.setBrush(Qt.NoBrush)
    elif kind == "insert":
        # PowerPoint's Insert: a shape and the green plus.
        fill(QColor("#7EB4E4"), hue["blue_deep"], 1.4)
        painter.drawRoundedRect(QRectF(2.5, 3, 13, 11), 1.6, 1.6)
        painter.setBrush(Qt.NoBrush)
        badge(QPointF(16.2, 16.2), "plus", hue["green"])
    elif kind == "format":
        # A brush, as on Office's Format Painter.
        fill(hue["gold"], hue["gold_deep"])
        painter.drawRoundedRect(QRectF(3, 2.5, 16, 6), 1.4, 1.4)
        fill(hue["steel"], hue["steel_deep"])
        painter.drawRect(QRectF(9.5, 8.5, 3, 3))
        painter.setBrush(Qt.NoBrush)
        stroke(hue["steel_deep"], 3.0)
        painter.drawLine(QPointF(11, 12), QPointF(11, 19.5))
    elif kind in ("tab_close", "tab_close_others", "tab_close_right"):
        # Document tabs on their bar, the red close badge under each one
        # that goes. The pale tab is the one right-clicked.
        stroke(hue["paper_line"], 1.4)
        painter.drawLine(QPointF(1.5, 12), QPointF(20.5, 12))
        if kind == "tab_close":
            fill(hue["paper"], hue["paper_line"])
            painter.drawRect(QRectF(4, 4.5, 11, 7))
            badge(QPointF(15.8, 16.2), "cross", hue["red"])
        else:
            tabs = (QRectF(1.5, 4.5, 6, 7), QRectF(8, 4.5, 6, 7), QRectF(14.5, 4.5, 6, 7))
            current = 0 if kind == "tab_close_right" else 1
            for index, rect in enumerate(tabs):
                fill(hue["paper"] if index == current else hue["steel"], hue["paper_line"])
                painter.drawRect(rect)
            for index, rect in enumerate(tabs):
                if index != current and (kind == "tab_close_others" or index > current):
                    badge(QPointF(rect.center().x(), 17), "cross", hue["red"], 3.6)
        painter.setBrush(Qt.NoBrush)
    elif kind == "tab_detach":
        # A tab lifted off the strip and standing as a window of its own.
        stroke(hue["paper_line"], 1.4)
        painter.drawLine(QPointF(1.5, 17.5), QPointF(12.5, 17.5))
        for rect in (QRectF(1.5, 11, 5, 6.5), QRectF(7.5, 11, 5, 6.5)):
            fill(hue["steel"], hue["paper_line"])
            painter.drawRect(rect)
        fill(hue["paper"], hue["paper_line"])
        painter.drawRect(QRectF(10.5, 3, 10, 9.5))
        fill(hue["blue"], hue["blue_deep"])
        painter.drawRect(QRectF(10.5, 3, 10, 2.8))
        painter.setBrush(Qt.NoBrush)
    elif kind == "more_colors":
        # Office's More Colors: a few swatches of the palette.
        for index, swatch in enumerate(("#F05252", "#FFD633", "#22C55E", "#57A0FF")):
            fill(QColor(swatch), hue["paper_line"], 0.9)
            painter.drawRect(QRectF(2.5 + (index % 2) * 9, 2.5 + (index // 2) * 9, 8, 8))
        painter.setBrush(Qt.NoBrush)
    painter.end()
    return QIcon(pixmap)


# Six numbers and "c": one Bezier segment in a content stream.
_APPEARANCE_CURVE = re.compile(
    rb"(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s+c\b"
)


def snap_to_45_degrees(start: QPointF, end: QPointF) -> QPointF:
    """`end` moved onto the nearest line from `start` at a multiple of 45
    degrees -- level, upright or diagonal -- as Shift does in PowerPoint
    (6.12): the point on that line nearest to `end`, so a level line ends
    where the pointer is across."""
    dx, dy = end.x() - start.x(), end.y() - start.y()
    if not dx and not dy:
        return QPointF(end)
    angle = round(math.atan2(dy, dx) / (math.pi / 4)) * (math.pi / 4)
    ux, uy = math.cos(angle), math.sin(angle)
    if abs(ux) < 1e-9:
        ux = 0.0
    if abs(uy) < 1e-9:
        uy = 0.0
    along = dx * ux + dy * uy
    return QPointF(start.x() + along * ux, start.y() + along * uy)


def square_from(start: QPointF, end: QPointF) -> QPointF:
    """The corner of the square from `start` towards `end`: Shift while
    drawing a rectangle, as in PowerPoint (6.12)."""
    dx, dy = end.x() - start.x(), end.y() - start.y()
    side = max(abs(dx), abs(dy))
    return QPointF(
        start.x() + (side if dx >= 0 else -side), start.y() + (side if dy >= 0 else -side)
    )


def keyboard_shift_held() -> bool:
    """Whether Shift is down now -- for drags whose events do not carry it,
    a handle's. The checks put their own function here."""
    return bool(QApplication.keyboardModifiers() & Qt.ShiftModifier)


# Where an annotation keeps its geometry (6.12): every key of these that
# it has holds x y pairs, in arrays nested or not.
ANNOTATION_POINT_KEYS = ("Rect", "L", "Vertices", "InkList", "QuadPoints", "CL")
_PDF_ARRAY_TOKEN = re.compile(r"\[|\]|[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?")


def shift_pdf_points(text: str, dx: float, dy: float) -> str:
    """A PDF array of x y pairs -- nested, as an /InkList, or not -- with
    every pair moved by (dx, dy)."""
    parts: list[str] = []
    counts: list[int] = []
    for token in _PDF_ARRAY_TOKEN.findall(text):
        if token == "[":
            counts.append(0)
            parts.append("[")
        elif token == "]":
            if counts:
                counts.pop()
            parts.append("]")
        else:
            index = counts[-1] if counts else 0
            value = float(token) + (dx if index % 2 == 0 else dy)
            if counts:
                counts[-1] += 1
            parts.append(f"{value:.4f}".rstrip("0").rstrip("."))
    return " ".join(parts).replace("[ ", "[").replace(" ]", "]")


def shift_annotation_geometry(
    document: fitz.Document, page: fitz.Page, xref: int, dx: float, dy: float
) -> None:
    """Move an annotation by (dx, dy) in page coordinates, in every key that
    holds where it is. Moving its /Rect alone, the only thing set_rect()
    does, moved a square; MuPDF refuses it for a line or an ink drawing
    ("Line annotations have no Rect property"), and a copy of one stayed on
    the original, where it could not be seen (6.12)."""
    inverse = ~page.transformation_matrix
    origin = fitz.Point(0, 0) * inverse
    moved = fitz.Point(dx, dy) * inverse
    pdf_dx, pdf_dy = moved.x - origin.x, moved.y - origin.y
    for key in ANNOTATION_POINT_KEYS:
        kind, value = document.xref_get_key(xref, key)
        if kind == "array":
            document.xref_set_key(xref, key, shift_pdf_points(value, pdf_dx, pdf_dy))


def square_highlight_appearance(annot: fitz.Annot) -> bool:
    """Give a Highlight annotation square ends, as pdfNote's highlights had
    before 5.14 and as Office's text highlight looks.

    MuPDF draws each highlighted line as a band with a half-ellipse at both
    ends. The appearance is a filled path per line -- move, curve, line,
    curve, fill -- so turning each curve into a straight line to its end
    point leaves exactly the rectangle of the line. Every annot.update()
    draws the curves again, so this has to follow each one. Other readers
    show the stored appearance, so the saved file keeps the square ends.
    """
    try:
        if annot.type[0] != fitz.PDF_ANNOT_HIGHLIGHT:
            return False
        stream = annot._getAP()
    except Exception:
        return False
    if not stream:
        return False
    squared = _APPEARANCE_CURVE.sub(lambda match: match.group(5) + b" " + match.group(6) + b" l", stream)
    if squared == stream:
        return False
    try:
        annot._setAP(squared)
    except Exception:
        return False
    return True


def clipboard_mime() -> QMimeData | None:
    """The clipboard's contents, or None.

    mimeData() is None where there is no real clipboard (a headless session,
    some remote desktops). The menus already checked for that; Ctrl+V and
    paste_clipboard_image chained straight through it and would have taken
    the app down. One accessor so the next reader cannot forget.
    """
    clipboard = QApplication.clipboard()
    return clipboard.mimeData() if clipboard is not None else None


class ElidingLabel(QLabel):
    """A QLabel that ends long text with an ellipsis instead of clipping it.

    QLabel just cuts the text off at its edge, so a deep folder ended
    mid-character on the welcome screen with nothing to say it had been
    truncated.
    """

    def __init__(self, text: str = "", parent: QWidget | None = None) -> None:
        super().__init__(text, parent)
        self._full_text = text
        self.setMinimumWidth(0)
        self.setSizePolicy(QSizePolicy.Ignored, QSizePolicy.Preferred)

    def setText(self, text: str) -> None:
        self._full_text = text
        self._apply_elision()

    def resizeEvent(self, event: Any) -> None:
        super().resizeEvent(event)
        self._apply_elision()

    def _apply_elision(self) -> None:
        metrics = QFontMetrics(self.font())
        super().setText(metrics.elidedText(self._full_text, Qt.ElideMiddle, max(0, self.width())))


def neutralize_marker_xrefs(document: fitz.Document) -> None:
    """Blank the cached object numbers in pdfNote's own annotation markers.

    A garbage-collecting save renumbers objects, so a cached number would
    afterwards name an unrelated one. The lookups fall back to finding the
    right object again.
    """
    for page in document:
        for xref, _kind, _name in page.annot_xrefs():
            try:
                annot = page.load_annot(xref)
                subject = str(annot.info.get("subject") or "")
            except Exception:
                continue
            parts = subject.split("|")
            if subject.startswith("SumiRichText|") and len(parts) >= 5:
                parts[4] = "0"
            elif subject.startswith("SumiEditableImage|") and len(parts) >= 4:
                parts[1] = parts[2] = parts[3] = "0"
            else:
                continue
            try:
                annot.set_info(subject="|".join(parts))
                annot.update()
                if subject.startswith("SumiEditableImage|") and _kind != fitz.PDF_ANNOT_STAMP:
                    # The original it kept goes with the number naming it. A
                    # stamp's picture is the one it draws, and its original
                    # is a reference the save renumbers with it (6.19).
                    delete_pdf_key(document, xref, "SumiSource")
            except Exception:
                continue


def serialize_session(session: "DocumentSession", compact: bool = True) -> bytes:
    """A session's document as bytes. Once redactions have been applied it
    gets the full rewrite, so the removed objects are really gone."""
    if session.document is None:
        return b""
    return serialize_document(
        session.document, session.needs_full_rewrite, compact, password=session.password
    )


def serialize_document(
    document: fitz.Document,
    full_rewrite: bool = False,
    compact: bool = True,
    password: str | None = None,
    collect: bool = True,
) -> bytes:
    """Turn a document into bytes -- the only place that does.

    Every caller gets the same two guarantees, which is the point: a full
    rewrite rebuilds the file with garbage collection so removed objects
    are really gone, and encryption is always preserved. It raises rather
    than falling back to an unencrypted write: a save that quietly strips
    the password is worse than a save that fails.

    A garbage-collecting write renumbers the objects of the document it
    runs on, in memory too, and a journal (the undo history) recorded
    against the old numbers then undoes the wrong objects -- silently. A
    journalled document is therefore copied as it is, and the copy is
    rebuilt; the document itself is left alone. `password` unlocks that
    copy when the document has a user password.

    `collect=False` keeps every object, used or not, under its number: the
    copy rebase_journal() builds its history on (6.3).
    """
    if full_rewrite and _journalled(document):
        staged = serialize_document(document, full_rewrite=False)
        copy = fitz.open(stream=staged, filetype="pdf")
        try:
            if copy.needs_pass and not (password and copy.authenticate(password)):
                raise RuntimeError("the copy of the document could not be unlocked")
            return serialize_document(copy, full_rewrite=True)
        finally:
            copy.close()
    if full_rewrite:
        neutralize_marker_xrefs(document)
        garbage, clean, deflate = 4, True, True
    else:
        # Garbage collection at level 1 leaves out what nothing refers to
        # -- a deleted page, the drawing of a box written again -- and
        # renumbers nothing: the marks keep naming their objects by number,
        # in this document and in the file it is reopened from. Level 0 kept
        # everything, and a file only ever grew (6.1). What a mark needs
        # beyond what is drawn, the original kept for cropping again, is
        # referred to from the mark itself (/SumiSource).
        garbage, clean, deflate = (1 if collect else 0), False, compact
    return document.tobytes(
        garbage=garbage,
        clean=clean,
        deflate=deflate,
        deflate_images=deflate,
        deflate_fonts=deflate,
        encryption=fitz.PDF_ENCRYPT_KEEP,
    )


def pdf_permissions(document: fitz.Document) -> int:
    """The document's permission bits (-4 is what PyMuPDF reports for a PDF
    without restrictions)."""
    try:
        return int(document.permissions)
    except Exception:
        return -4


def pdf_is_protected(document: fitz.Document) -> bool:
    """Encrypted, or carrying usage restrictions set by its author."""
    if (document.metadata or {}).get("encryption"):
        return True
    granted = pdf_permissions(document)
    return any(not granted & bit for bit, _key in PDF_PERMISSION_LABELS)


def protection_settings(permissions: int, user_password: str = "") -> dict[str, Any]:
    """Save options for a new file that keeps the given restrictions. The
    original owner password is not known, so a new random one is set."""
    return {
        "encryption": fitz.PDF_ENCRYPT_AES_256,
        "owner_pw": secrets.token_urlsafe(24),
        "user_pw": user_password,
        "permissions": permissions,
    }


def protection_options(document: fitz.Document, password: str | None = None) -> dict[str, Any]:
    """Save options that keep a protected PDF's encryption and usage
    restrictions on a new file made from its pages (an extracted page, the
    pieces of a split). Empty for a PDF with neither.

    pdfNote shows a PDF's restrictions without enforcing them, but it must
    not strip them out of the files it writes. METI's commentary on the
    Unfair Competition Prevention Act puts a program that merely does not
    act on a restriction outside article 2(1)(xvii); removing the signal is
    what the Copyright Act names as circumvention (article 30(1)(ii)). A
    user password carries over as the one the document was opened with.
    """
    if not pdf_is_protected(document):
        return {}
    return protection_settings(pdf_permissions(document), password or "")


def protected_document(document: fitz.Document, options: dict[str, Any]) -> fitz.Document:
    """An in-memory copy of `document` with `options` applied, for a new
    document that has no file yet (a merge). It only ever adds protection,
    which is why it may turn a document into bytes besides
    serialize_document()."""
    return fitz.open(stream=document.tobytes(**options), filetype="pdf")


# ---- keeping files small (6.1) ---------------------------------------------
#
# Up to 6.0 pdfNote made a PDF far larger than what it held. Measured on 6.0
# with a 6 MB Japanese font: one text box 4.3 MB, the same box edited three
# times 17.4 MB, a 3.6 MB photo moved once +21 MB, six of ten pages deleted
# -0 MB. Four things did it:
# - a text box carried a whole copy of its font, however few characters it
#   had, one copy per box and per edit (subset_scratch_fonts);
# - an edit emptied the old drawing but left what it drew -- the box's font,
#   the picture's old copy -- listed in the page's resources, where every
#   save found it (drop_undrawn_xobjects);
# - a moved or resized picture was decoded and stored again as PNG;
# - and a save never left out what nothing used any more (serialize_document).
# The helpers below only ever take out what nothing draws, so a page looks
# and reads -- selects, searches -- exactly as before.

_PDF_NAME_TOKEN = re.compile(rb"/([^\s/\[\]()<>{}%]*)")
_PDF_NAME_ESCAPE = re.compile(rb"#([0-9A-Fa-f]{2})")
# A page's own resources may carry a few kilobytes of what nothing draws
# without anyone minding; these are what the check on opening counts.
SHRINK_NOTICE_MIN_BYTES = 256 * 1024
# A cropped photo, or a photo pasted from the clipboard, is stored as JPEG at
# this quality: well above what shows on screen or paper.
IMAGE_JPEG_QUALITY = 92
# Printing to Microsoft Print to PDF writes the PDF directly (6.1). Pictures
# finer than this on the sheet are brought down to it -- MuPDF halves, thirds
# and so on, so they end between this and twice this -- and photos are
# stored as JPEG at the quality below; black-and-white scans keep twice it.
PRINT_PDF_IMAGE_DPI = 200
PRINT_PDF_JPEG_QUALITY = 85


def is_pdf_writer_printer(name: str) -> bool:
    """Is this Windows' own "Microsoft Print to PDF"? By the queue name or,
    for a renamed queue, the driver's."""
    wanted = "microsoft print to pdf"
    if not name:
        return False
    if wanted in name.lower():
        return True
    try:
        info = QPrinterInfo.printerInfo(name)
        return not info.isNull() and wanted in info.makeAndModel().lower()
    except Exception:
        return False


def pdf_names_in(stream: bytes) -> set[str]:
    """Every name a content stream mentions, as a resource dictionary spells
    it (#xx escapes decoded). Anything that looks like a name counts, an
    operand of any operator or bytes inside an inline image too: a resource
    is only ever taken out when its name appears nowhere."""
    names: set[str] = set()
    for raw in _PDF_NAME_TOKEN.findall(stream):
        if b"#" in raw:
            raw = _PDF_NAME_ESCAPE.sub(lambda match: bytes([int(match.group(1), 16)]), raw)
        names.add(raw.decode("latin-1"))
    return names


def _pdf_of(document: fitz.Document) -> Any:
    return fitz._as_pdf_document(document)


def delete_pdf_key(document: fitz.Document, xref: int, key: str) -> None:
    """Remove `key` from object `xref`. xref_set_key(..., "null") leaves the
    key behind, and in a nested path a placeholder string."""
    from pymupdf import mupdf

    mupdf.pdf_dict_dels(mupdf.pdf_load_object(_pdf_of(document), xref), key)


def _page_resources(document: fitz.Document, index: int) -> tuple[Any, tuple | None]:
    """The resource dictionary page `index` draws from and who it belongs to:
    ("ref", n) when it is object n of its own, which other pages may share;
    ("in", n) when it is written inside object n, the page itself or the
    page-tree node the page inherits it from."""
    from pymupdf import mupdf

    pdf = _pdf_of(document)
    node = mupdf.pdf_lookup_page_obj(pdf, index)
    holder = document.page_xref(index)
    for _depth in range(64):
        if not node.m_internal:
            break
        value = mupdf.pdf_dict_get(node, mupdf.PDF_ENUM_NAME_Resources)
        if value.m_internal:
            if mupdf.pdf_is_indirect(value):
                resolved = mupdf.pdf_resolve_indirect(value)
                if mupdf.pdf_is_dict(resolved):
                    return resolved, ("ref", mupdf.pdf_to_num(value))
                return None, None
            if mupdf.pdf_is_dict(value):
                return value, ("in", holder)
            return None, None
        parent = mupdf.pdf_dict_get(node, mupdf.PDF_ENUM_NAME_Parent)
        if not parent.m_internal:
            break
        holder = mupdf.pdf_to_num(parent)
        node = mupdf.pdf_resolve_indirect(parent)
    return None, None


def _resource_category(resources: Any, owner: tuple, category: str) -> tuple[Any, tuple | None]:
    """The /XObject or /Font dictionary of `resources`, and who it belongs
    to -- it may be an object of its own, shared with other resources."""
    from pymupdf import mupdf

    if resources is None or not resources.m_internal:
        return None, None
    value = mupdf.pdf_dict_gets(resources, category)
    if not value.m_internal:
        return None, None
    if mupdf.pdf_is_indirect(value):
        resolved = mupdf.pdf_resolve_indirect(value)
        return (resolved, ("ref", mupdf.pdf_to_num(value))) if mupdf.pdf_is_dict(resolved) else (None, None)
    return (value, (category,) + owner) if mupdf.pdf_is_dict(value) else (None, None)


def _dict_names(dictionary: Any) -> list[str]:
    from pymupdf import mupdf

    return [
        mupdf.pdf_to_name(mupdf.pdf_dict_get_key(dictionary, index))
        for index in range(mupdf.pdf_dict_len(dictionary))
    ]


def _stream_names(document: fitz.Document, xref: int) -> set[str]:
    try:
        return pdf_names_in(document.xref_stream(xref))
    except Exception:
        # Unreadable: treat it as naming everything, so nothing is dropped.
        return {"*"}


def _borrowed_names(document: fitz.Document, resources: Any) -> set[str]:
    """Names that streams without resources of their own look up in
    `resources`: tiling patterns, soft-mask groups and Type 3 glyphs written
    that way (the specification asks for resources; not every PDF has them)."""
    from pymupdf import mupdf

    names: set[str] = set()
    if resources is None or not resources.m_internal:
        return names

    def entries(category: str) -> list[Any]:
        found = mupdf.pdf_resolve_indirect(mupdf.pdf_dict_gets(resources, category))
        if not found.m_internal or not mupdf.pdf_is_dict(found):
            return []
        return [mupdf.pdf_dict_get_val(found, i) for i in range(mupdf.pdf_dict_len(found))]

    def lacks_resources(obj: Any) -> bool:
        return not mupdf.pdf_dict_get(
            mupdf.pdf_resolve_indirect(obj), mupdf.PDF_ENUM_NAME_Resources
        ).m_internal

    for pattern in entries("Pattern"):
        if mupdf.pdf_is_stream(mupdf.pdf_resolve_indirect(pattern)) and lacks_resources(pattern):
            names |= _stream_names(document, mupdf.pdf_to_num(pattern))
    for state in entries("ExtGState"):
        mask = mupdf.pdf_dict_get(mupdf.pdf_resolve_indirect(state), mupdf.PDF_ENUM_NAME_SMask)
        group = mupdf.pdf_dict_get(mupdf.pdf_resolve_indirect(mask), mupdf.PDF_ENUM_NAME_G) if mask.m_internal else None
        if group is not None and group.m_internal and lacks_resources(group):
            names |= _stream_names(document, mupdf.pdf_to_num(group))
    for font in entries("Font"):
        resolved = mupdf.pdf_resolve_indirect(font)
        if not mupdf.pdf_name_eq(
            mupdf.pdf_dict_get(resolved, mupdf.PDF_ENUM_NAME_Subtype), mupdf.PDF_ENUM_NAME_Type3
        ) or not lacks_resources(font):
            continue
        procs = mupdf.pdf_resolve_indirect(mupdf.pdf_dict_get(resolved, mupdf.PDF_ENUM_NAME_CharProcs))
        for glyph in range(mupdf.pdf_dict_len(procs) if procs.m_internal else 0):
            names |= _stream_names(document, mupdf.pdf_to_num(mupdf.pdf_dict_get_val(procs, glyph)))
    return names


def _form_reads_from(form: Any, resources_owner: tuple, xobjects_owner: tuple) -> bool:
    """Does this form XObject look its names up in the given resources --
    by having none of its own (PDF 1.1 allowed that), or the very same?"""
    from pymupdf import mupdf

    own = mupdf.pdf_dict_get(form, mupdf.PDF_ENUM_NAME_Resources)
    if not own.m_internal:
        return True
    if mupdf.pdf_is_indirect(own):
        number = mupdf.pdf_to_num(own)
        return ("ref", number) in (resources_owner, xobjects_owner)
    return False


def _names_a_page_uses(
    document: fitz.Document, index: int, resources_owner: tuple, xobjects: Any, xobjects_owner: tuple
) -> set[str]:
    """Every name page `index` may look up in its resources: its content
    streams, and whatever draws from the same dictionaries -- forms that
    have no resources of their own or share these, annotation appearances
    without resources."""
    from pymupdf import mupdf

    page = document[index]
    names: set[str] = set()
    for xref in page.get_contents():
        names |= _stream_names(document, xref)
    names |= _borrowed_names(document, _page_resources(document, index)[0])
    try:
        annotation_xrefs = [xref for xref, _kind, _name in page.annot_xrefs()]
    except Exception:
        annotation_xrefs = []
    for annotation in annotation_xrefs:
        for state in ("N", "D", "R"):
            kind, value = document.xref_get_key(annotation, f"AP/{state}")
            if kind != "xref":
                continue
            try:
                appearance = int(value.split()[0])
            except (ValueError, IndexError):
                continue
            if document.xref_get_key(appearance, "Resources")[0] == "null":
                names |= _stream_names(document, appearance)
    if xobjects is not None:
        for position in range(mupdf.pdf_dict_len(xobjects)):
            reference = mupdf.pdf_dict_get_val(xobjects, position)
            form = mupdf.pdf_resolve_indirect(reference)
            if not mupdf.pdf_name_eq(
                mupdf.pdf_dict_get(form, mupdf.PDF_ENUM_NAME_Subtype), mupdf.PDF_ENUM_NAME_Form
            ):
                continue
            if _form_reads_from(form, resources_owner, xobjects_owner):
                names |= _stream_names(document, mupdf.pdf_to_num(reference))
    return names


def drop_undrawn_xobjects(document: fitz.Document, index: int, names: set[str]) -> int:
    """Take the XObjects `names` out of the resources of page `index` when
    no page that shares those resources draws them any more.

    An edit that lifts something off a page -- a text box written again,
    a picture moved or deleted -- empties the drawing and used to leave the
    object listed in the page's resources: the old box with its font, the
    old copy of the picture. Listed, it was reachable, and every save wrote
    it out again. Runs inside the edit, so undo puts the entry back.
    Returns how many entries were taken out."""
    from pymupdf import mupdf

    try:
        resources, owner = _page_resources(document, index)
        xobjects, key = _resource_category(resources, owner, "XObject")
        if xobjects is None or key is None or owner is None:
            return 0
        candidates = {
            name for name in names
            if name.isascii() and mupdf.pdf_dict_gets(xobjects, name).m_internal
        }
        if not candidates:
            return 0
        page_local = owner == ("in", document.page_xref(index)) and key[0] != "ref"
        sharing = [index]
        if not page_local:
            for other in range(len(document)):
                if other == index:
                    continue
                other_resources, other_owner = _page_resources(document, other)
                _other_xobjects, other_key = _resource_category(
                    other_resources, other_owner, "XObject"
                )
                if other_key == key:
                    sharing.append(other)
        for page_number in sharing:
            other_resources, other_owner = _page_resources(document, page_number)
            used = _names_a_page_uses(document, page_number, other_owner, xobjects, key)
            if "*" in used:
                return 0
            candidates -= used
            if not candidates:
                return 0
        for name in candidates:
            mupdf.pdf_dict_dels(xobjects, name)
        return len(candidates)
    except Exception:
        return 0


def prune_unused_resources(document: fitz.Document) -> int:
    """Take out of every page's and form's resources the XObjects and fonts
    nothing draws. For a document pdfNote has just made from some pages of
    another -- an extracted page, the pieces of a split, a print to PDF.

    Many PDFs list every page's pictures and fonts in one dictionary that
    all pages share; a page copied out of one took all of them along, so a
    one-page extract of a ten-page scan was as large as the scan. Only
    names that appear nowhere in what draws from a dictionary are taken
    out, and dictionaries a form field fills from (/DR) are left alone.
    Returns how many entries were taken out."""
    from pymupdf import mupdf

    pdf = _pdf_of(document)
    groups: dict[tuple, list] = {}
    protected: set[tuple] = set()
    try:
        form = mupdf.pdf_dict_getp(mupdf.pdf_trailer(pdf), "Root/AcroForm")
        defaults = mupdf.pdf_dict_gets(form, "DR") if form.m_internal else None
        if defaults is not None and defaults.m_internal:
            if mupdf.pdf_is_indirect(defaults):
                owner: tuple = ("ref", mupdf.pdf_to_num(defaults))
            else:
                owner = ("in", mupdf.pdf_to_num(mupdf.pdf_dict_getp(mupdf.pdf_trailer(pdf), "Root")))
            for category in ("XObject", "Font"):
                _dictionary, key = _resource_category(
                    mupdf.pdf_resolve_indirect(defaults), owner, category
                )
                if key is not None:
                    protected.add(key)
    except Exception:
        pass
    visited_forms: set[int] = set()

    def record(resources: Any, owner: tuple, names: set[str]) -> None:
        xobjects, xobjects_key = _resource_category(resources, owner, "XObject")
        fonts, fonts_key = _resource_category(resources, owner, "Font")
        names = set(names) | _borrowed_names(document, resources)
        if xobjects is not None:
            # Forms that read their names from here add theirs, as far down
            # as such forms go.
            pending = True
            seen: set[int] = set()
            while pending:
                pending = False
                for position in range(mupdf.pdf_dict_len(xobjects)):
                    name = mupdf.pdf_to_name(mupdf.pdf_dict_get_key(xobjects, position))
                    reference = mupdf.pdf_dict_get_val(xobjects, position)
                    number = mupdf.pdf_to_num(reference)
                    if number in seen or (name not in names and "*" not in names):
                        continue
                    form = mupdf.pdf_resolve_indirect(reference)
                    if not mupdf.pdf_name_eq(
                        mupdf.pdf_dict_get(form, mupdf.PDF_ENUM_NAME_Subtype), mupdf.PDF_ENUM_NAME_Form
                    ):
                        continue
                    seen.add(number)
                    if _form_reads_from(form, owner, xobjects_key or ()):
                        names |= _stream_names(document, number)
                        pending = True
        for dictionary, key in ((xobjects, xobjects_key), (fonts, fonts_key)):
            if dictionary is None or key is None:
                continue
            group = groups.setdefault(key, [dictionary, set()])
            group[1] |= names
        if xobjects is not None:
            for position in range(mupdf.pdf_dict_len(xobjects)):
                reference = mupdf.pdf_dict_get_val(xobjects, position)
                visit_form(reference)

    def visit_form(reference: Any) -> None:
        number = mupdf.pdf_to_num(reference)
        if not number or number in visited_forms:
            return
        form = mupdf.pdf_resolve_indirect(reference)
        if not mupdf.pdf_name_eq(
            mupdf.pdf_dict_get(form, mupdf.PDF_ENUM_NAME_Subtype), mupdf.PDF_ENUM_NAME_Form
        ):
            return
        visited_forms.add(number)
        own = mupdf.pdf_dict_get(form, mupdf.PDF_ENUM_NAME_Resources)
        if not own.m_internal:
            return
        if mupdf.pdf_is_indirect(own):
            resources, owner = mupdf.pdf_resolve_indirect(own), ("ref", mupdf.pdf_to_num(own))
        else:
            resources, owner = own, ("in", number)
        record(resources, owner, _stream_names(document, number))

    for index in range(len(document)):
        resources, owner = _page_resources(document, index)
        if resources is None or owner is None:
            continue
        xobjects, xobjects_key = _resource_category(resources, owner, "XObject")
        record(
            resources, owner,
            _names_a_page_uses(document, index, owner, xobjects, xobjects_key or ()),
        )
        page = document[index]
        for annotation, _kind, _name in page.annot_xrefs():
            for state in ("N", "D", "R"):
                kind, value = document.xref_get_key(annotation, f"AP/{state}")
                if kind == "xref":
                    try:
                        visit_form(mupdf.pdf_new_indirect(pdf, int(value.split()[0]), 0))
                    except (ValueError, IndexError):
                        continue
    removed = 0
    for key, (dictionary, names) in groups.items():
        if key in protected or "*" in names:
            continue
        for name in _dict_names(dictionary):
            if name.isascii() and name not in names:
                mupdf.pdf_dict_dels(dictionary, name)
                removed += 1
    return removed


def write_file_atomically(target: str | Path, data: bytes) -> None:
    """Put `data` at `target` whole or not at all: written to a temporary
    file beside it, flushed to the disk, then swapped in. What was there
    before stays until the new file is complete."""
    target = Path(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    file_descriptor, temp_name = tempfile.mkstemp(
        prefix=f".{target.stem}-", suffix=".sumi.tmp", dir=str(target.parent)
    )
    temp_path: Path | None = Path(temp_name)
    try:
        with os.fdopen(file_descriptor, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp_path, target)
        temp_path = None
    finally:
        if temp_path is not None:
            try:
                temp_path.unlink(missing_ok=True)
            except OSError:
                pass


def page_list_label(pages: list[int]) -> str:
    """Pages (from 0) as a reader numbers them, in runs: "2-4,7"."""
    runs: list[str] = []
    start = previous = None
    for page in [*sorted(pages), None]:
        if page is not None and previous is not None and page == previous + 1:
            previous = page
            continue
        if start is not None:
            runs.append(f"{start + 1}" if start == previous else f"{start + 1}-{previous + 1}")
        start = previous = page
    return ",".join(runs)


def compact_page_copy(document: fitz.Document) -> dict[str, Any]:
    """Get a document made of pages copied out of another -- an extracted
    page, a piece of a split, a page on the clipboard -- ready to write, and
    the save options for it.

    Its marks are blanked, since their numbers named the other document's
    objects, and what the copied pages do not draw is taken out of their
    resources: a page copied from a PDF whose pages share one dictionary
    took every page's pictures along (6.1). The options rebuild the file
    with every object written once, compressed."""
    neutralize_marker_xrefs_on(document, range(len(document)))
    prune_unused_resources(document)
    return {"garbage": 4, "deflate": True, "deflate_images": True, "deflate_fonts": True}


def neutralize_marker_xrefs_on(document: fitz.Document, pages: Iterable[int]) -> None:
    """neutralize_marker_xrefs() for some pages only: the pages just copied
    in from elsewhere -- another document, the clipboard, a duplicate.

    A mark's cached numbers named the objects of the page it was made on.
    On a copy they named the original's: writing the copy's text box again
    emptied the original's, and moving the copy's picture took the
    original's off its page. Blanked, the lookups find the copy's own."""
    wanted = set(pages)
    for index in sorted(wanted):
        if not 0 <= index < len(document):
            continue
        page = document[index]
        for xref, _kind, _name in page.annot_xrefs():
            try:
                annot = page.load_annot(xref)
                subject = str(annot.info.get("subject") or "")
            except Exception:
                continue
            parts = subject.split("|")
            if subject.startswith("SumiRichText|") and len(parts) >= 5:
                parts[4] = "0"
            elif subject.startswith("SumiEditableImage|") and len(parts) >= 4:
                parts[1] = parts[2] = parts[3] = "0"
            else:
                continue
            try:
                annot.set_info(subject="|".join(parts))
                annot.update()
                if subject.startswith("SumiEditableImage|") and _kind != fitz.PDF_ANNOT_STAMP:
                    # A stamp's original is a reference, copied with it (6.19).
                    delete_pdf_key(document, xref, "SumiSource")
            except Exception:
                continue


def remap_copied_marks(document: fitz.Document, source: int, copy: int) -> None:
    """Make the marks of page `copy`, a duplicate of page `source` in the same
    document, name the copy's own objects.

    Content streams correspond by their place in /Contents; pictures are
    the source's own once share_resources_with() has run, or found again
    under the mark when not. Anything that cannot be matched is blanked,
    which the lookups treat as unknown (neutralize_marker_xrefs_on)."""
    try:
        source_contents = document[source].get_contents()
        page = document[copy]
        copy_contents = page.get_contents()
        images = {int(item[0]) for item in page.get_images(full=True)}
    except Exception:
        neutralize_marker_xrefs_on(document, [copy])
        return

    def mapped(value: str) -> str:
        try:
            position = source_contents.index(int(value))
            return str(copy_contents[position])
        except (ValueError, IndexError):
            return "0"

    for xref, _kind, _name in page.annot_xrefs():
        try:
            annot = page.load_annot(xref)
            subject = str(annot.info.get("subject") or "")
        except Exception:
            continue
        parts = subject.split("|")
        if subject.startswith("SumiRichText|") and len(parts) >= 5:
            parts[4] = mapped(parts[4])
        elif subject.startswith("SumiEditableImage|") and len(parts) >= 4 and _kind == fitz.PDF_ANNOT_STAMP:
            # A stamp refers to its pictures itself (6.19), shared with the
            # source's by share_stamp_pictures().
            drawn = PDFReaderWindow._stamp_image_xref(annot)
            parts[1], parts[2] = str(drawn), "0"
            parts[3] = str(PDFReaderWindow._stamp_source_xref(annot) or drawn)
        elif subject.startswith("SumiEditableImage|") and len(parts) >= 4:
            try:
                visible, source_image = int(parts[1]), int(parts[3])
            except ValueError:
                visible = source_image = 0
            parts[1] = str(visible) if visible in images else "0"
            parts[2] = mapped(parts[2]) if parts[1] != "0" else "0"
            keep_source = (
                parts[1] != "0"
                and source_image > 0
                and document.xref_get_key(source_image, "Subtype")[1] == "/Image"
            )
            parts[3] = str(source_image) if keep_source else parts[1]
        else:
            continue
        try:
            annot.set_info(subject="|".join(parts))
            annot.update()
            if subject.startswith("SumiEditableImage|"):
                # The copy came with a copy of the kept original; it now
                # names the original's own, and the copy goes unused.
                if parts[3] not in ("0", parts[1]):
                    document.xref_set_key(xref, "SumiSource", f"{parts[3]} 0 R")
                elif document.xref_get_key(xref, "SumiSource")[0] != "null":
                    delete_pdf_key(document, xref, "SumiSource")
        except Exception:
            continue


def share_resources_with(document: fitz.Document, source: int, copy: int) -> int:
    """Point the resources of page `copy`, just made from page `source`, at
    the source's own pictures, forms and fonts instead of copies of them.

    A duplicated page used to carry a second copy of every picture and font
    on it: a scanned page duplicated was a second scan. The copy's own
    resource dictionaries stay its own, so what an edit takes out of one
    page is still drawn on the other. Returns how many entries now share."""
    from pymupdf import mupdf

    shared = 0
    try:
        source_resources, source_owner = _page_resources(document, source)
        copy_resources, copy_owner = _page_resources(document, copy)
        if source_owner is None or copy_owner is None or source_owner == copy_owner:
            return 0
        pdf = _pdf_of(document)
        for category in ("XObject", "Font"):
            original, original_key = _resource_category(source_resources, source_owner, category)
            duplicate, duplicate_key = _resource_category(copy_resources, copy_owner, category)
            if original is None or duplicate is None or original_key == duplicate_key:
                continue
            for name in _dict_names(duplicate):
                theirs = mupdf.pdf_dict_gets(original, name)
                ours = mupdf.pdf_dict_gets(duplicate, name)
                if not (mupdf.pdf_is_indirect(theirs) and mupdf.pdf_is_indirect(ours)):
                    continue
                if mupdf.pdf_to_num(theirs) == mupdf.pdf_to_num(ours):
                    continue
                first = mupdf.pdf_resolve_indirect(theirs)
                second = mupdf.pdf_resolve_indirect(ours)
                same_kind = all(
                    mupdf.pdf_name_eq(mupdf.pdf_dict_get(first, key), mupdf.pdf_dict_get(second, key))
                    for key in (mupdf.PDF_ENUM_NAME_Type, mupdf.PDF_ENUM_NAME_Subtype)
                )
                if not same_kind:
                    continue
                if mupdf.pdf_is_stream(first):
                    if document.xref_stream_raw(mupdf.pdf_to_num(theirs)) != document.xref_stream_raw(
                        mupdf.pdf_to_num(ours)
                    ):
                        continue
                mupdf.pdf_dict_puts(duplicate, name, mupdf.pdf_new_indirect(pdf, mupdf.pdf_to_num(theirs), 0))
                shared += 1
    except Exception:
        return shared
    return shared


def _same_image(document: fitz.Document, first: int, second: int) -> bool:
    """The two pictures are the same, byte for byte, mask included."""
    try:
        if document.xref_stream_raw(first) != document.xref_stream_raw(second):
            return False
        masks = [document.xref_get_key(xref, "SMask") for xref in (first, second)]
        if masks[0][0] != masks[1][0]:
            return False
        if masks[0][0] == "xref":
            return _same_image(
                document, int(masks[0][1].split()[0]), int(masks[1][1].split()[0])
            )
        return True
    except Exception:
        return False


def _stamp_picture_refs(document: fitz.Document, index: int) -> list[tuple[int, str, int]]:
    """(object, key, picture) for every picture the stamps on page `index`
    refer to (6.19): the one each draws, named in its appearance, and the
    original a cropped one keeps."""
    found: list[tuple[int, str, int]] = []
    try:
        entries = document[index].annot_xrefs()
    except Exception:
        return found
    for xref, kind, _name in entries:
        if kind != fitz.PDF_ANNOT_STAMP:
            continue
        try:
            held, value = document.xref_get_key(xref, "AP/N")
            if held == "xref":
                appearance = int(value.split()[0])
                held, value = document.xref_get_key(appearance, "Resources/XObject/I")
                if held == "xref":
                    found.append((appearance, "Resources/XObject/I", int(value.split()[0])))
            held, value = document.xref_get_key(xref, "SumiSource")
            if held == "xref":
                found.append((xref, "SumiSource", int(value.split()[0])))
        except Exception:
            continue
    return [
        item for item in found
        if document.xref_get_key(item[2], "Subtype")[1] == "/Image"
    ]


def share_stamp_pictures(
    document: fitz.Document, new_pages: Iterable[int], among: Iterable[int]
) -> int:
    """Point the stamps on `new_pages` at identical pictures the stamps on
    the pages `among` already refer to. A copied page brings a copy of
    every picture its stamps draw, as it brings its own content; a picture
    page duplicated was a second picture (6.19). Returns how many now
    share."""

    def size(xref: int) -> tuple[str, ...]:
        return tuple(document.xref_get_key(xref, key)[1] for key in ("Width", "Height", "Length"))

    known: dict[tuple[str, ...], list[int]] = {}
    for index in among:
        for _holder, _key, picture in _stamp_picture_refs(document, index):
            known.setdefault(size(picture), []).append(picture)
    if not known:
        return 0
    shared = 0
    for index in new_pages:
        for holder, key, picture in _stamp_picture_refs(document, index):
            for candidate in known.get(size(picture), []):
                if candidate != picture and _same_image(document, candidate, picture):
                    document.xref_set_key(holder, key, f"{candidate} 0 R")
                    shared += 1
                    break
    return shared


def share_identical_images(document: fitz.Document, new_pages: Iterable[int]) -> int:
    """Point the pictures on `new_pages` at identical pictures already on the
    other pages, so a page pasted back into its own document does not bring
    a second copy of each. Compared byte for byte, mask included."""
    from pymupdf import mupdf

    wanted = set(new_pages)
    pdf = _pdf_of(document)
    # The pictures stamps draw (6.19) first: they are not page content.
    stamped = share_stamp_pictures(
        document, wanted, [index for index in range(len(document)) if index not in wanted]
    )
    known: dict[tuple, list[int]] = {}
    for index in range(len(document)):
        if index in wanted:
            continue
        try:
            for item in document.get_page_images(index, full=True):
                xref = int(item[0])
                known.setdefault((item[2], item[3], item[4], item[8]), []).append(xref)
        except Exception:
            continue
    if not known:
        return stamped

    def same(first: int, second: int) -> bool:
        return _same_image(document, first, second)

    shared = stamped
    for index in sorted(wanted):
        if not 0 <= index < len(document):
            continue
        resources, owner = _page_resources(document, index)
        xobjects, _key = _resource_category(resources, owner, "XObject")
        if xobjects is None:
            continue
        try:
            images = document.get_page_images(index, full=True)
        except Exception:
            continue
        for item in images:
            if item[9] != 0:
                continue  # drawn inside a form, not listed on the page
            xref, name = int(item[0]), str(item[7])
            for candidate in known.get((item[2], item[3], item[4], item[8]), []):
                if candidate != xref and same(candidate, xref):
                    mupdf.pdf_dict_puts(xobjects, name, mupdf.pdf_new_indirect(pdf, candidate, 0))
                    shared += 1
                    break
    return shared


# A ToUnicode CMap as MuPDF writes it for a whole font: every glyph mapped,
# 150 KB for a Japanese one, in each text box -- after the font itself was
# cut down to a few glyphs, this was most of what a box weighed.
_CMAP_RANGE = re.compile(
    rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*(?:<([0-9A-Fa-f]*)>|\[([^\]]*)\])"
)
_CMAP_CHAR = re.compile(rb"<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]*)>")


def _tounicode_map(cmap: bytes) -> dict[int, str] | None:
    """Code -> UTF-16BE hex of a ToUnicode CMap's bfchar and bfrange
    entries. None when it holds anything else."""
    mapping: dict[int, str] = {}
    for block in re.findall(rb"beginbfrange(.*?)endbfrange", cmap, re.S):
        for low, high, start, array in _CMAP_RANGE.findall(block):
            first, last = int(low, 16), int(high, 16)
            if last < first or last - first > 0xFFFF:
                return None
            if array:
                targets = re.findall(rb"<([0-9A-Fa-f]*)>", array)
                for offset, target in enumerate(targets[: last - first + 1]):
                    mapping[first + offset] = target.decode("ascii")
            else:
                value = int(start, 16)
                width = len(start)
                for offset in range(last - first + 1):
                    mapping[first + offset] = format(value + offset, f"0{width}X")
    for block in re.findall(rb"beginbfchar(.*?)endbfchar", cmap, re.S):
        for code, target in _CMAP_CHAR.findall(block):
            mapping[int(code, 16)] = target.decode("ascii")
    return mapping


def _tounicode_cmap(mapping: dict[int, str]) -> bytes:
    lines = [
        "/CIDInit /ProcSet findresource begin",
        "12 dict begin",
        "begincmap",
        "/CIDSystemInfo <</Registry(Adobe)/Ordering(UCS)/Supplement 0>> def",
        "/CMapName /Adobe-Identity-UCS def",
        "/CMapType 2 def",
        "1 begincodespacerange",
        "<0000> <FFFF>",
        "endcodespacerange",
    ]
    codes = sorted(mapping)
    for start in range(0, len(codes), 100):
        chunk = codes[start:start + 100]
        lines.append(f"{len(chunk)} beginbfchar")
        lines.extend(f"<{code:04X}> <{mapping[code]}>" for code in chunk)
        lines.append("endbfchar")
    lines += [
        "endcmap",
        "CMapName currentdict /CMap defineresource pop",
        "end",
        "end",
    ]
    return ("\n".join(lines) + "\n").encode("ascii")


_TEXT_FONT_OR_STRING = re.compile(
    rb"/([^\s/\[\]()<>{}%]+)\s+[-+0-9.]+\s+Tf|<([0-9A-Fa-f\s]*)>|(\()"
)


def _codes_by_font(stream: bytes) -> dict[str, set[int]] | None:
    """Which two-byte codes each font (by resource name) shows in a content
    stream written by MuPDF. None if it shows text any other way."""
    used: dict[str, set[int]] = {}
    current: str | None = None
    for match in _TEXT_FONT_OR_STRING.finditer(stream):
        if match.group(1) is not None:
            current = match.group(1).decode("latin-1")
            used.setdefault(current, set())
        elif match.group(3) is not None:
            return None
        elif current is not None:
            digits = re.sub(rb"\s", b"", match.group(2))
            if len(digits) % 4:
                return None
            used[current].update(int(digits[i:i + 4], 16) for i in range(0, len(digits), 4))
    return used


def subset_scratch_fonts(scratch: fitz.Document) -> None:
    """Cut the fonts of a scratch document down to the glyphs its pages
    show: MuPDF's subsetter, then the ToUnicode maps to the same glyphs.
    The scratch documents are a text box laid out by MuPDF, or text boxes
    of an older pdfNote copied out of a document. Text stays selectable
    and searchable: every glyph shown keeps its Unicode. Anything that does
    not go as expected leaves that font as it was."""
    try:
        scratch.subset_fonts()
    except Exception:
        return
    used_by_font: dict[int, set[int]] = {}
    unknown: set[int] = set()
    for index in range(len(scratch)):
        page = scratch[index]
        fonts = {name: xref for xref, _ext, _type, _base, name, _enc, *_rest in page.get_fonts(full=True)}
        codes: dict[str, set[int]] | None = {}
        for content in page.get_contents():
            found = _codes_by_font(scratch.xref_stream(content))
            if found is None:
                codes = None
                break
            for name, values in found.items():
                codes.setdefault(name, set()).update(values)
        if codes is None:
            unknown.update(fonts.values())
            continue
        for name, values in codes.items():
            if name in fonts:
                used_by_font.setdefault(fonts[name], set()).update(values)
    for font, codes in used_by_font.items():
        if font in unknown:
            continue
        try:
            if scratch.xref_get_key(font, "Encoding")[1] != "/Identity-H":
                continue
            kind, value = scratch.xref_get_key(font, "ToUnicode")
            if kind != "xref":
                continue
            cmap_xref = int(value.split()[0])
            mapping = _tounicode_map(scratch.xref_stream(cmap_xref))
            if mapping is None or not codes <= set(mapping):
                continue
            trimmed = {code: mapping[code] for code in codes}
            scratch.update_stream(cmap_xref, _tounicode_cmap(trimmed))
        except Exception:
            continue


def insert_html_subset(
    page: fitz.Page,
    rect: fitz.Rect,
    html: str,
    *,
    css: str = "",
    archive: Any = None,
    scale_low: float = 0,
    scale_word_width: bool = True,
) -> tuple[float, float]:
    """Page.insert_htmlbox, with the fonts cut down to what the box shows.

    insert_htmlbox lays the HTML out on a page of a scratch document and
    shows that page here; the scratch page embeds every font whole -- a
    Japanese one is several megabytes -- and each box brought its own copy.
    This does the same steps as PyMuPDF 1.28's insert_htmlbox (rotation 0,
    full opacity, no links, which a text box never has) and subsets the
    scratch fonts before the page is shown. Same return values."""
    from pymupdf import mupdf

    rect = fitz.Rect(rect)
    if not 0 <= scale_low <= 1:
        raise ValueError("'scale_low' must be in [0, 1]")
    story = fitz.Story(html=html, user_css="body {margin:1px;}" + (css or ""), archive=archive)
    fit = story.fit_scale(
        fitz.Rect(0, 0, rect.width, rect.height),
        scale_min=1,
        scale_max=None if scale_low == 0 else 1 / scale_low,
        flags=mupdf.FZ_PLACE_STORY_FLAG_NO_OVERFLOW if scale_word_width else 0,
    )
    if not fit.big_enough:
        return (-1, 1 / fit.parameter)
    filled = fitz.Rect(fit.filled)
    scale = 1 / fit.parameter
    spare_height = max((fit.rect.y1 - filled.y1) * scale, 0)
    scratch = story.write_with_links(lambda *_args: (fit.rect, fit.rect, None))
    try:
        subset_scratch_fonts(scratch)
        page.show_pdf_page(rect, scratch, 0)
    finally:
        scratch.close()
    return (spare_height, scale)


def _is_subset_font_name(base_font: str) -> bool:
    name = base_font.lstrip("/")
    return len(name) > 7 and name[6] == "+" and name[:6].isalpha() and name[:6].isupper()


def subset_form_fonts(document: fitz.Document, forms: Iterable[int]) -> int:
    """Cut the whole fonts the given form XObjects use down to what they show.

    For text boxes an older pdfNote baked with a whole font each. The forms
    are copied into a scratch document, one per page, the fonts are cut
    down there (subset_scratch_fonts), and each form's font entry is pointed
    at the cut-down copy brought back. The whole font is then drawn by
    nothing and the next save leaves it out. Returns how many fonts."""
    from pymupdf import mupdf

    pdf = _pdf_of(document)
    scratch = fitz.open()
    replaced = 0
    try:
        spdf = _pdf_of(scratch)
        to_scratch = mupdf.pdf_new_graft_map(spdf)
        entries: list[tuple[Any, str, int]] = []
        scratch_fonts: dict[int, Any] = {}
        for xref in forms:
            try:
                form = mupdf.pdf_load_object(pdf, xref)
                resources = mupdf.pdf_dict_get(form, mupdf.PDF_ENUM_NAME_Resources)
                if not resources.m_internal:
                    continue
                fonts = mupdf.pdf_resolve_indirect(
                    mupdf.pdf_dict_get(mupdf.pdf_resolve_indirect(resources), mupdf.PDF_ENUM_NAME_Font)
                )
                if not fonts.m_internal or not mupdf.pdf_dict_len(fonts):
                    continue
                whole = []
                for name in _dict_names(fonts):
                    reference = mupdf.pdf_dict_gets(fonts, name)
                    if not mupdf.pdf_is_indirect(reference):
                        continue
                    number = mupdf.pdf_to_num(reference)
                    base = document.xref_get_key(number, "BaseFont")[1]
                    if document.xref_get_key(number, "Subtype")[1] != "/Type0" or _is_subset_font_name(base):
                        continue
                    whole.append((name, number, reference))
                if not whole:
                    continue
                try:
                    bbox = fitz.Rect(
                        [float(value) for value in document.xref_get_key(xref, "BBox")[1].strip("[]").split()[:4]]
                    )
                except (ValueError, TypeError):
                    bbox = fitz.Rect(0, 0, 595, 842)
                # Only the glyphs shown matter here, not where they land.
                page = scratch.new_page(width=max(1.0, bbox.width), height=max(1.0, bbox.height))
                page_object = mupdf.pdf_lookup_page_obj(spdf, page.number)
                mupdf.pdf_dict_put(
                    page_object, mupdf.PDF_ENUM_NAME_Resources,
                    mupdf.pdf_graft_mapped_object(to_scratch, resources),
                )
                # A new page has no content stream: give it the form's.
                content = scratch.get_new_xref()
                scratch.update_object(content, "<<>>")
                scratch.update_stream(content, document.xref_stream(xref))
                scratch.xref_set_key(page.xref, "Contents", f"{content} 0 R")
                for name, number, reference in whole:
                    scratch_fonts[number] = mupdf.pdf_graft_mapped_object(to_scratch, reference)
                    entries.append((fonts, name, number))
            except Exception:
                continue
        if not scratch_fonts:
            return 0
        subset_scratch_fonts(scratch)
        back = mupdf.pdf_new_graft_map(pdf)
        brought: dict[int, Any] = {}
        for number, scratch_reference in scratch_fonts.items():
            base = scratch.xref_get_key(mupdf.pdf_to_num(scratch_reference), "BaseFont")[1]
            if not _is_subset_font_name(base):
                continue  # the subsetter left it alone; so does this
            brought[number] = mupdf.pdf_graft_mapped_object(back, scratch_reference)
        for fonts, name, number in entries:
            if number in brought:
                mupdf.pdf_dict_puts(fonts, name, brought[number])
                replaced += 1
    finally:
        scratch.close()
    return replaced


def _pages_with_pdfnote_marks(document: fitz.Document) -> list[int]:
    pages: list[int] = []
    for index in range(len(document)):
        try:
            annotations = [xref for xref, _kind, _name in document[index].annot_xrefs()]
        except Exception:
            continue
        for xref in annotations:
            kind, subject = document.xref_get_key(xref, "Subj")
            if kind == "string" and subject.startswith(("SumiRichText", "SumiEditableImage")):
                pages.append(index)
                break
    return pages


def _forms_with_whole_fonts(document: fitz.Document, index: int) -> list[int]:
    """The form XObjects page `index` draws that use a whole embedded Type 0
    font -- what an older pdfNote baked each text box into."""
    from pymupdf import mupdf

    found: list[int] = []
    resources, owner = _page_resources(document, index)
    xobjects, _key = _resource_category(resources, owner, "XObject")
    pending = []
    if xobjects is not None:
        pending = [mupdf.pdf_dict_get_val(xobjects, i) for i in range(mupdf.pdf_dict_len(xobjects))]
    seen: set[int] = set()
    while pending:
        reference = pending.pop()
        number = mupdf.pdf_to_num(reference)
        if not number or number in seen or len(seen) > 2000:
            continue
        seen.add(number)
        form = mupdf.pdf_resolve_indirect(reference)
        if not mupdf.pdf_name_eq(
            mupdf.pdf_dict_get(form, mupdf.PDF_ENUM_NAME_Subtype), mupdf.PDF_ENUM_NAME_Form
        ):
            continue
        own = mupdf.pdf_resolve_indirect(mupdf.pdf_dict_get(form, mupdf.PDF_ENUM_NAME_Resources))
        if not own.m_internal:
            continue
        inner = mupdf.pdf_resolve_indirect(mupdf.pdf_dict_get(own, mupdf.PDF_ENUM_NAME_XObject))
        if inner.m_internal:
            pending += [mupdf.pdf_dict_get_val(inner, i) for i in range(mupdf.pdf_dict_len(inner))]
        fonts = mupdf.pdf_resolve_indirect(mupdf.pdf_dict_get(own, mupdf.PDF_ENUM_NAME_Font))
        for position in range(mupdf.pdf_dict_len(fonts) if fonts.m_internal else 0):
            font = mupdf.pdf_dict_get_val(fonts, position)
            font_number = mupdf.pdf_to_num(font)
            if not font_number:
                continue
            if document.xref_get_key(font_number, "Subtype")[1] != "/Type0":
                continue
            if _is_subset_font_name(document.xref_get_key(font_number, "BaseFont")[1]):
                continue
            found.append(number)
            break
    return found


def _drop_undrawn_on(document: fitz.Document, pages: list[int]) -> int:
    """drop_undrawn_xobjects() for every XObject of the given pages, each
    shared dictionary looked at once: what nothing on any page sharing it
    draws goes. Returns how many entries."""
    from pymupdf import mupdf

    wanted = set(pages)
    groups: dict[tuple, list] = {}
    for index in range(len(document)):
        resources, owner = _page_resources(document, index)
        xobjects, key = _resource_category(resources, owner, "XObject")
        if xobjects is None or key is None or owner is None:
            continue
        group = groups.setdefault(key, [xobjects, []])
        group[1].append((index, owner))
    removed = 0
    for key, (xobjects, members) in groups.items():
        if not any(index in wanted for index, _owner in members):
            continue
        used: set[str] = set()
        for index, owner in members:
            used |= _names_a_page_uses(document, index, owner, xobjects, key)
        if "*" in used:
            continue
        for name in _dict_names(xobjects):
            if name.isascii() and name not in used:
                mupdf.pdf_dict_dels(xobjects, name)
                removed += 1
    return removed


def _same_picture(document: fitz.Document, first: int, second: int) -> bool:
    """Do two image objects show the same picture? Decoded and compared,
    every few hundredth sample: a JPEG decoded by Qt and by MuPDF differs by
    a level or two here and there, which no one can see."""
    try:
        if document.xref_get_key(first, "SMask")[0] != document.xref_get_key(second, "SMask")[0]:
            return False
        one, two = fitz.Pixmap(document, first), fitz.Pixmap(document, second)
        if (one.width, one.height, one.n, one.alpha) != (two.width, two.height, two.n, two.alpha):
            return False
        if one.width * one.height > 60_000_000:
            return False
        a, b = one.samples, two.samples
        step = max(1, len(a) // 400_000) | 1
        total = worst = count = 0
        for x, y in zip(a[::step], b[::step]):
            difference = abs(x - y)
            total += difference
            worst = max(worst, difference)
            count += 1
        return count > 0 and worst <= 8 and total <= count * 0.5
    except Exception:
        return False


def _image_size(document: fitz.Document, xref: int) -> tuple[int, int] | None:
    try:
        if document.xref_get_key(xref, "Subtype")[1] != "/Image":
            return None
        width, height = document.xref_get_key(xref, "Width"), document.xref_get_key(xref, "Height")
        if width[0] != "int" or height[0] != "int":
            return None
        return int(width[1]), int(height[1])
    except Exception:
        return None


def image_source_fits(
    document: fitz.Document, visible: int, source: int,
    crop: tuple[float, float, float, float],
) -> bool:
    """Can the picture `visible` have been cut from `source` by `crop`?

    A mark names the original it keeps by number, and a number means
    something only in its own file. 1.0.0 pasted a picture into another
    document with the number of the original in the first one; moving or
    cropping the copy later took whatever picture had that number here
    (6.2). A crop keeps the original's pixels, so the picture on the page
    is the original's size times the crop's -- a stranger rarely is."""
    if source == visible:
        return True
    shown, kept = _image_size(document, visible), _image_size(document, source)
    if shown is None or kept is None:
        return False
    left, top, right, bottom = crop
    wanted = (max(1.0, (right - left) * kept[0]), max(1.0, (bottom - top) * kept[1]))
    return all(
        abs(actual - expected) <= max(2.0, expected * 0.02)
        for actual, expected in zip(shown, wanted)
    )


def tidy_pdfnote_leftovers(document: fitz.Document) -> int:
    """Undo, in a document an older pdfNote saved, what made it large.

    On every page with pdfNote's text boxes or pictures: what nothing draws
    leaves the resources -- boxes written again and moved pictures left
    their old drawing listed, a whole font in each -- the whole fonts of the
    boxes still drawn are cut down to their characters, and the original a
    cropped picture keeps is referred to from its mark, so that leaving out
    what nothing uses does not take it too. Nothing drawn changes, and all
    text stays selectable and searchable. Runs before the document's undo
    history starts. Returns how many changes were made."""
    from pymupdf import mupdf

    changes = 0
    pages = _pages_with_pdfnote_marks(document)
    for index in pages:
        page = document[index]
        for xref, annotation_kind, _name in page.annot_xrefs():
            kind, subject = document.xref_get_key(xref, "Subj")
            if kind != "string" or not subject.startswith("SumiEditableImage|"):
                continue
            if annotation_kind == fitz.PDF_ANNOT_STAMP:
                continue  # draws its own picture: nothing of it is page content (6.19)
            parts = subject.split("|")
            try:
                visible, source = int(parts[1]), int(parts[3])
                crop = [float(value) for value in parts[4].split(",")] if len(parts) > 4 else [0, 0, 1, 1]
            except (ValueError, IndexError):
                continue
            if (
                len(crop) == 4
                and source > 0
                and visible > 0
                and source != visible
                and _image_size(document, visible) is not None
                and not image_source_fits(document, visible, source, tuple(crop))
            ):
                # The original named belongs to another file (see
                # image_source_fits): the picture on the page becomes its
                # own original, whole.
                annot = page.load_annot(xref)
                parts[3] = str(visible)
                if len(parts) > 4:
                    parts[4] = "0.000000,0.000000,1.000000,1.000000"
                annot.set_info(subject="|".join(parts))
                annot.update()
                if document.xref_get_key(xref, "SumiSource")[0] != "null":
                    delete_pdf_key(document, xref, "SumiSource")
                changes += 1
                continue
            uncropped = len(crop) == 4 and all(
                abs(value - whole) < 1e-4 for value, whole in zip(crop, (0, 0, 1, 1))
            )
            if (
                uncropped
                and source > 0
                and visible != source
                and document.xref_get_key(source, "Subtype")[1] == "/Image"
                and _same_picture(document, visible, source)
            ):
                # A picture an older pdfNote moved or resized: the page shows
                # a lossless copy of the original, several times its size --
                # a 3.6 MB photo became 21 MB. The original is drawn again.
                resources, owner = _page_resources(document, index)
                xobjects, _key = _resource_category(resources, owner, "XObject")
                if xobjects is not None:
                    for name in _dict_names(xobjects):
                        reference = mupdf.pdf_dict_gets(xobjects, name)
                        if mupdf.pdf_to_num(reference) == visible:
                            mupdf.pdf_dict_puts(
                                xobjects, name, mupdf.pdf_new_indirect(_pdf_of(document), source, 0)
                            )
                    parts[1] = str(source)
                    annot = page.load_annot(xref)
                    annot.set_info(subject="|".join(parts))
                    annot.update()
                    if document.xref_get_key(xref, "SumiSource")[0] != "null":
                        delete_pdf_key(document, xref, "SumiSource")
                    changes += 1
                    continue
            if (
                source > 0
                and source != visible
                and document.xref_get_key(source, "Subtype")[1] == "/Image"
                and document.xref_get_key(xref, "SumiSource")[0] == "null"
            ):
                document.xref_set_key(xref, "SumiSource", f"{source} 0 R")
                changes += 1
    changes += _drop_undrawn_on(document, pages)
    forms: list[int] = []
    for index in pages:
        for form in _forms_with_whole_fonts(document, index):
            if form not in forms:
                forms.append(form)
    if forms:
        changes += subset_form_fonts(document, forms)
    return changes


def printer_tray_names(printer_name: str) -> dict[int, str]:
    """Tray names straight from the Windows driver, keyed by DMBIN value.

    Qt reports which trays exist but names only the standard ones, so a
    multifunction printer's trays come back as bare numbers. This asks the
    driver for the names it shows in its own UI. Read-only, and it falls
    back to numbers if anything about it fails.
    """
    if sys.platform != "win32" or not printer_name:
        return {}
    try:
        import ctypes

        winspool = ctypes.WinDLL("winspool.drv")
        DC_BINS, DC_BINNAMES, NAME_LENGTH = 6, 12, 24
        count = winspool.DeviceCapabilitiesW(printer_name, None, DC_BINNAMES, None, None)
        if count <= 0:
            return {}
        names = ctypes.create_unicode_buffer(NAME_LENGTH * count)
        winspool.DeviceCapabilitiesW(printer_name, None, DC_BINNAMES, names, None)
        bins = (ctypes.c_ushort * count)()
        if winspool.DeviceCapabilitiesW(printer_name, None, DC_BINS, bins, None) <= 0:
            return {}
        result: dict[int, str] = {}
        for index in range(count):
            chunk = names[index * NAME_LENGTH:(index + 1) * NAME_LENGTH]
            label = chunk.split("\0")[0].strip()
            if label:
                result[int(bins[index])] = label
        return result
    except Exception:
        return {}


class CappedComboBox(QComboBox):
    """A combo whose popup stops at a readable height.

    Fusion ignores maxVisibleItems for the popup, so a 54-entry paper-size
    list opened as one column the full height of the screen. The documented
    fix is the `combobox-popup: 0` stylesheet property, but styling any
    QComboBox property hands the widget to the stylesheet engine and it
    loses the look every other combo in the app has -- so the popup
    container is resized directly instead, once Qt has created it.
    """

    def showPopup(self) -> None:
        super().showPopup()
        rows = max(4, self.maxVisibleItems())
        if self.count() <= rows:
            return
        view = self.view()
        container = view.parentWidget()
        if container is None:
            return
        row_height = view.sizeHintForRow(0) or 22
        height = row_height * rows + 2 * view.frameWidth() + 4
        if container.height() > height:
            container.setMaximumHeight(height)
            container.resize(container.width(), height)


class PrintDialog(QDialog):
    """pdfNote's print dialog. The system one is never shown.

    Windows 11 reserves a preview pane in its own dialog and fills it only
    through the modern printing APIs, which Qt does not use -- so under Qt
    that pane reads "this app does not support print preview". Everything
    is here instead, and every control is populated from what the chosen
    printer reports it supports.

    Finishing options (stapling, punching) are not here and cannot be: they
    live in the driver's private DEVMODE, and QPrintEngine has no property
    key that carries a DEVMODE into the job. N-up and scaling are not in
    that category -- the app decides where each page lands on the sheet --
    so they are done here, which is also why the preview shows them.
    """

    def __init__(self, window: "PDFReaderWindow", printer: QPrinter) -> None:
        super().__init__(window)
        self.window = window
        self.printer = printer
        self._loading = False
        self._sheet = 0
        self._sheet_total = 1
        self.setWindowTitle(tr("印刷"))
        self.setModal(True)
        self.resize(1020, 720)

        layout = QHBoxLayout(self)
        layout.setContentsMargins(14, 14, 14, 14)
        layout.setSpacing(14)
        layout.addWidget(self._build_settings_panel(), 0)

        preview_column = QVBoxLayout()
        preview_column.setSpacing(8)
        layout.addLayout(preview_column, 1)
        self.preview = QPrintPreviewWidget(self.printer, self)
        self.preview.setZoomMode(QPrintPreviewWidget.FitInView)
        self.preview.paintRequested.connect(self._paint_preview)
        preview_column.addWidget(self.preview, 1)
        preview_column.addLayout(self._build_preview_bar())

        buttons = QHBoxLayout()
        buttons.addStretch(1)
        self.print_button = QPushButton(tr("印刷"))
        self.print_button.setDefault(True)
        self.print_button.clicked.connect(self.accept)
        cancel_button = QPushButton(tr("キャンセル"))
        cancel_button.clicked.connect(self.reject)
        buttons.addWidget(self.print_button)
        buttons.addWidget(cancel_button)
        preview_column.addLayout(buttons)

        self._connect_signals()
        self._reload_printer_options()

    # ---- construction ------------------------------------------------
    def _build_settings_panel(self) -> QWidget:
        """The settings column, scrollable so it never outgrows the dialog."""
        page_count = len(self.window.document) if self.window.document is not None else 1
        form = QFormLayout()
        form.setLabelAlignment(Qt.AlignRight | Qt.AlignVCenter)
        form.setSpacing(9)
        form.setContentsMargins(0, 0, 10, 0)
        inner = QWidget()
        inner.setLayout(form)

        self.printer_box = CappedComboBox()
        for info in QPrinterInfo.availablePrinters():
            self.printer_box.addItem(info.printerName())
        current = self.printer.printerName() or QPrinterInfo.defaultPrinterName()
        if current:
            index = self.printer_box.findText(current)
            if index >= 0:
                self.printer_box.setCurrentIndex(index)
        form.addRow(tr("プリンター"), self.printer_box)
        # Microsoft Print to PDF gets the PDF from pdfNote itself (6.1).
        self.pdf_writer_note = QLabel(
            tr("pdfNote が PDF を直接作ります。文字は選択・検索でき、ファイルは小さくなります")
        )
        self.pdf_writer_note.setWordWrap(True)
        self.pdf_writer_note.setMaximumWidth(300)
        self.pdf_writer_note.setStyleSheet(f"color: {COLORS['muted']}; font-size: 10px;")
        self.pdf_writer_note.setVisible(is_pdf_writer_printer(self.printer_box.currentText()))
        form.addRow("", self.pdf_writer_note)

        self.range_all = QRadioButton(tr("すべてのページ"))
        self.range_current = QRadioButton(tr("現在のページ"))
        # Not "ページ指定": that key belongs to the navigation command
        # (Ctrl+G / Alt+J), whose English is "Go to Page" -- which is what this
        # radio button said.
        self.range_custom = QRadioButton(tr("範囲を指定"))
        self.range_all.setChecked(True)
        range_column = QVBoxLayout()
        range_column.setSpacing(4)
        for button in (self.range_all, self.range_current, self.range_custom):
            range_column.addWidget(button)
        range_row = QHBoxLayout()
        range_row.setContentsMargins(22, 0, 0, 0)
        self.range_from = QSpinBox()
        self.range_from.setRange(1, max(1, page_count))
        self.range_to = QSpinBox()
        self.range_to.setRange(1, max(1, page_count))
        self.range_to.setValue(max(1, page_count))
        range_row.addWidget(self.range_from)
        range_row.addWidget(QLabel("–"))
        range_row.addWidget(self.range_to)
        range_row.addStretch(1)
        range_column.addLayout(range_row)
        form.addRow(tr("印刷範囲"), range_column)

        copies_row = QHBoxLayout()
        self.copies = QSpinBox()
        self.copies.setRange(1, 999)
        self.copies.setValue(max(1, self.printer.copyCount()))
        # Word's and Windows' own wording. The printer jargon it replaces
        # (丁合い) said nothing to most people, so the order it produces is
        # spelled out underneath, the way Word's print pane does.
        collate_tip = tr(
            "複数部を印刷するとき、1部ずつページ順にそろえて出力します（1,2,3 → 1,2,3）。"
            "オフにすると同じページをまとめて出力します（1,1 → 2,2 → 3,3）。"
        )
        self.collate = QCheckBox(tr("部単位で印刷"))
        self.collate.setChecked(True)
        self.collate.setToolTip(collate_tip)
        self.collate_hint = QLabel()
        self.collate_hint.setToolTip(collate_tip)
        self.collate_hint.setStyleSheet(f"color: {COLORS['muted']};")
        copies_row.addWidget(self.copies)
        copies_row.addWidget(self.collate)
        copies_row.addStretch(1)
        copies_column = QVBoxLayout()
        copies_column.setSpacing(2)
        copies_column.addLayout(copies_row)
        copies_column.addWidget(self.collate_hint)
        form.addRow(tr("部数"), copies_column)
        self.copies.valueChanged.connect(self._update_collate_hint)
        self.collate.toggled.connect(self._update_collate_hint)
        self._update_collate_hint()
        form.addRow(self._separator())

        self.page_size = CappedComboBox()
        self.page_size_row = self._row(form, tr("用紙サイズ"), self.page_size)
        self.orientation = CappedComboBox()
        self.orientation.addItem(tr("縦"), QPageLayout.Portrait)
        self.orientation.addItem(tr("横"), QPageLayout.Landscape)
        form.addRow(tr("印刷の向き"), self.orientation)
        self.paper_source = CappedComboBox()
        self.paper_source_row = self._row(form, tr("給紙方法"), self.paper_source)
        self.duplex = CappedComboBox()
        self.duplex_row = self._row(form, tr("両面"), self.duplex)
        self.color_mode = CappedComboBox()
        self.color_row = self._row(form, tr("カラー〔見出し〕"), self.color_mode)
        self.resolution = CappedComboBox()
        self.resolution_row = self._row(form, tr("解像度"), self.resolution)
        form.addRow(self._separator())

        self.per_sheet = CappedComboBox()
        for count in (1, 2, 4, 6, 9, 16):
            self.per_sheet.addItem(tr("{count}ページ/枚").format(count=count), count)
        self.per_sheet.addItem(tr("カスタム…"), 0)
        form.addRow(tr("集約"), self.per_sheet)
        grid_row = QHBoxLayout()
        grid_row.setContentsMargins(0, 0, 0, 0)
        self.grid_columns = QSpinBox()
        self.grid_columns.setRange(1, 8)
        self.grid_columns.setValue(2)
        self.grid_rows = QSpinBox()
        self.grid_rows.setRange(1, 8)
        self.grid_rows.setValue(2)
        grid_row.addWidget(self.grid_columns)
        grid_row.addWidget(QLabel("×"))
        grid_row.addWidget(self.grid_rows)
        grid_row.addStretch(1)
        self.grid_widget = QWidget()
        self.grid_widget.setLayout(grid_row)
        self.grid_row_label = self._row(form, tr("横×縦"), self.grid_widget)

        order_row = QHBoxLayout()
        order_row.setContentsMargins(0, 0, 0, 0)
        order_row.setSpacing(6)
        self.order_buttons = QButtonGroup(self)
        self.order_buttons.setExclusive(True)
        for value, icon_kind, tip in (
            ("across", "nup_across", "左上から右へ"),
            ("down", "nup_down", "左上から下へ"),
        ):
            button = QToolButton()
            button.setCheckable(True)
            button.setIcon(render_ribbon_icon(icon_kind))
            button.setIconSize(QSize(26, 26))
            button.setToolTip(tr(tip))
            button.setProperty("order", value)
            order_row.addWidget(button)
            self.order_buttons.addButton(button)
        first = self.order_buttons.buttons()[0]
        first.setChecked(True)
        order_row.addStretch(1)
        self.order_widget = QWidget()
        self.order_widget.setLayout(order_row)
        self.order_row_label = self._row(form, tr("ページの順序"), self.order_widget)
        self.order_hint = QLabel()
        self.order_hint.setWordWrap(True)
        self.order_hint.setMaximumWidth(300)
        self.order_hint.setStyleSheet(f"color: {COLORS['muted']}; font-size: 10px;")
        self.order_hint_label = self._row(form, "", self.order_hint)

        scale_row = QHBoxLayout()
        scale_row.setContentsMargins(0, 0, 0, 0)
        self.scale_mode = CappedComboBox()
        self.scale_mode.addItem(tr("用紙に合わせる"), "fit")
        self.scale_mode.addItem(tr("実際のサイズ"), "actual")
        self.scale_mode.addItem(tr("倍率指定"), "percent")
        self.scale_percent = QSpinBox()
        self.scale_percent.setRange(10, 400)
        self.scale_percent.setValue(100)
        set_unit_suffix(self.scale_percent, "%", 76)
        self.scale_percent.setEnabled(False)
        scale_row.addWidget(self.scale_mode, 1)
        scale_row.addWidget(self.scale_percent)
        scale_widget = QWidget()
        scale_widget.setLayout(scale_row)
        form.addRow(tr("拡大縮小"), scale_widget)

        margin_row = QHBoxLayout()
        margin_row.setContentsMargins(0, 0, 0, 0)
        margin_row.setSpacing(4)
        # Two rows of two: four across did not fit, and the last box was
        # simply cut off at the edge of the column.
        margin_grid = QGridLayout()
        margin_grid.setContentsMargins(0, 0, 0, 0)
        margin_grid.setHorizontalSpacing(8)
        margin_grid.setVerticalSpacing(4)
        self.margins: list[QDoubleSpinBox] = []
        # Their own keys: "下" is the format bar's underline button, whose
        # English is the single letter "U".
        for position, label in enumerate(("上余白", "下余白", "左余白", "右余白")):
            caption = QLabel(tr(label))
            # 11px, as the preview's note: at 10px the strokes of "上余白"
            # were too thin to reach their own colour (3.9:1 drawn, 6.23).
            caption.setStyleSheet(f"color: {COLORS['muted']}; font-size: 11px;")
            spin = QDoubleSpinBox()
            spin.setRange(0.0, 50.0)
            spin.setDecimals(1)
            spin.setSingleStep(1.0)
            # At least as wide as the largest value needs.
            spin.setFixedWidth(max(62, spin.sizeHint().width()))
            row, column = divmod(position, 2)
            margin_grid.addWidget(caption, row, column * 2)
            margin_grid.addWidget(spin, row, column * 2 + 1)
            self.margins.append(spin)
        margin_grid.setColumnStretch(4, 1)
        margin_widget = QWidget()
        margin_widget.setLayout(margin_grid)
        form.addRow(tr("余白 (mm)"), margin_widget)

        note = QLabel(tr("ホチキス留めとパンチ穴あけは、プリンターの設定で指定してください"))
        note.setWordWrap(True)
        # A form field will not wrap on its own; without a ceiling this ran
        # straight off the edge of the column.
        note.setMaximumWidth(300)
        note.setStyleSheet(f"color: {COLORS['muted']}; font-size: 10px;")
        form.addRow("", note)

        for box in (
            self.printer_box, self.page_size, self.orientation, self.paper_source,
            self.duplex, self.color_mode, self.resolution, self.per_sheet,
            self.scale_mode,
        ):
            # Otherwise a long list -- 54 paper sizes on some drivers --
            # opens as a single column taller than the screen.
            box.setMaxVisibleItems(12)

        scroller = QScrollArea()
        scroller.setWidget(inner)
        scroller.setWidgetResizable(True)
        scroller.setFrameShape(QFrame.NoFrame)
        scroller.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        # As wide as the column needs, 392 at least: with no horizontal
        # scrolling, a fixed 392 cut the right end off every box behind a
        # long label -- Ancient Greek's "pages per sheet" (6.4).
        scroller.setFixedWidth(
            max(392, inner.minimumSizeHint().width() + scroller.verticalScrollBar().sizeHint().width())
        )
        # A QScrollArea paints its own light Base colour, which put white
        # behind near-white label text and made the whole column unreadable.
        # Selector-scoped on purpose: a bare "background: transparent" set on
        # the panel cascades to every widget inside it, which drained the
        # colour out of all the combo boxes and spin boxes.
        scroller.setStyleSheet(
            "QScrollArea { background: transparent; border: none; }"
            " QScrollArea > QWidget > QWidget { background: transparent; }"
        )
        return scroller

    def _build_preview_bar(self) -> QHBoxLayout:
        """Sheet navigation. Without it only the first sheet is ever visible,
        which is no way to check a 4-up layout."""
        bar = QHBoxLayout()
        bar.setSpacing(6)
        # Right to left, the previous sheet is to the right, and its
        # button points there.
        backward, forward = ("›", "‹") if QApplication.isRightToLeft() else ("‹", "›")
        self.previous_sheet = QPushButton(backward)
        self.previous_sheet.setFixedWidth(34)
        self.previous_sheet.clicked.connect(lambda: self._step_sheet(-1))
        self.next_sheet = QPushButton(forward)
        self.next_sheet.setFixedWidth(34)
        self.next_sheet.clicked.connect(lambda: self._step_sheet(1))
        # A larger arrow: at the text's size the thin "‹" drew no pixel in
        # its own colour, and greyed out on the first sheet it all but
        # vanished (2.3:1 drawn, 6.23).
        for button in (self.previous_sheet, self.next_sheet):
            button.setStyleSheet("font-size: 16px;")
        self.sheet_label = QLabel()
        self.sheet_label.setAlignment(Qt.AlignCenter)
        self.sheet_label.setMinimumWidth(72)
        self.preview_note = QLabel()
        self.preview_note.setStyleSheet(f"color: {COLORS['muted']}; font-size: 11px;")
        self.fit_mode = CappedComboBox()
        self.fit_mode.addItem(tr("全体表示"), "fit")
        self.fit_mode.addItem(tr("幅に合わせる"), "width")
        self.fit_mode.setMaxVisibleItems(6)
        self.fit_mode.currentIndexChanged.connect(self._apply_zoom_mode)
        bar.addWidget(self.previous_sheet)
        bar.addWidget(self.sheet_label)
        bar.addWidget(self.next_sheet)
        bar.addSpacing(10)
        bar.addWidget(self.preview_note, 1)
        bar.addWidget(self.fit_mode)
        return bar

    def _connect_signals(self) -> None:
        self.printer_box.currentIndexChanged.connect(self._printer_changed)
        for widget in (
            self.orientation, self.color_mode, self.duplex, self.page_size,
            self.paper_source, self.resolution, self.per_sheet, self.scale_mode,
        ):
            widget.currentIndexChanged.connect(self._settings_changed)
        for spin in (
            self.copies, self.range_from, self.range_to,
            self.grid_columns, self.grid_rows, self.scale_percent,
        ):
            spin.valueChanged.connect(self._settings_changed)
        for spin in self.margins:
            spin.valueChanged.connect(self._settings_changed)
        self.order_buttons.buttonToggled.connect(self._settings_changed)
        self.collate.toggled.connect(self._settings_changed)
        for button in (self.range_all, self.range_current, self.range_custom):
            button.toggled.connect(self._settings_changed)

    @staticmethod
    def _separator() -> QFrame:
        line = QFrame()
        line.setFrameShape(QFrame.HLine)
        line.setFixedHeight(1)
        line.setStyleSheet(f"background: {COLORS['border']}; border: none;")
        return line

    @staticmethod
    def _row(form: QFormLayout, label: str, widget: QWidget) -> QLabel:
        caption = QLabel(label)
        form.addRow(caption, widget)
        return caption

    def _update_collate_hint(self, *_args: object) -> None:
        """Collating only means something with two or more copies."""
        several = self.copies.value() > 1
        self.collate.setEnabled(several)
        self.collate_hint.setEnabled(several)
        self.collate_hint.setText(
            "1, 2, 3   1, 2, 3" if self.collate.isChecked() else "1, 1   2, 2   3, 3"
        )

    @staticmethod
    def _select_data(box: QComboBox, value: object) -> None:
        box.setCurrentIndex(box.findData(value))

    @staticmethod
    def _set_row_visible(caption: QLabel, widget: QWidget, visible: bool) -> None:
        caption.setVisible(visible)
        widget.setVisible(visible)

    # ---- printer capabilities ---------------------------------------
    def _printer_changed(self) -> None:
        name = self.printer_box.currentText()
        if name and name != self.printer.printerName():
            # Changing the printer rebuilds the driver's settings block, so
            # every option list has to be rebuilt from the new one.
            self.printer.setPrinterName(name)
        self._reload_printer_options()

    def _reload_printer_options(self) -> None:
        """Offer exactly what the chosen printer says it can do."""
        self._loading = True
        try:
            self.pdf_writer_note.setVisible(is_pdf_writer_printer(self.printer_box.currentText()))
            info = QPrinterInfo.printerInfo(self.printer_box.currentText())
            duplex_labels = {
                QPrinter.DuplexNone: "片面",
                QPrinter.DuplexAuto: "自動",
                QPrinter.DuplexLongSide: "両面（長辺とじ）",
                QPrinter.DuplexShortSide: "両面（短辺とじ）",
            }
            modes = list(info.supportedDuplexModes()) if not info.isNull() else []
            self.duplex.clear()
            for mode in modes:
                self.duplex.addItem(tr(duplex_labels.get(mode, "片面")), mode)
            self._select_data(self.duplex, self.printer.duplex())
            if self.duplex.currentIndex() < 0 and not info.isNull():
                self._select_data(self.duplex, info.defaultDuplexMode())
            self._set_row_visible(self.duplex_row, self.duplex, len(modes) > 1)

            colours = list(info.supportedColorModes()) if not info.isNull() else []
            self.color_mode.clear()
            for mode in colours:
                self.color_mode.addItem(
                    tr("カラー") if mode == QPrinter.Color else tr("グレースケール"), mode
                )
            if not info.isNull():
                self._select_data(self.color_mode, info.defaultColorMode())
            if self.color_mode.currentIndex() < 0 and self.color_mode.count():
                self.color_mode.setCurrentIndex(0)
            self._set_row_visible(self.color_row, self.color_mode, len(colours) > 1)

            sizes = list(info.supportedPageSizes()) if not info.isNull() else []
            self.page_size.clear()
            for size in sizes:
                self.page_size.addItem(size.name(), size)
            index = self.page_size.findText(self.printer.pageLayout().pageSize().name())
            if index >= 0:
                self.page_size.setCurrentIndex(index)
            self._set_row_visible(self.page_size_row, self.page_size, len(sizes) > 1)

            resolutions = list(info.supportedResolutions()) if not info.isNull() else []
            self.resolution.clear()
            for value in resolutions:
                self.resolution.addItem(tr("{value} dpi").format(value=value), value)
            self._select_data(self.resolution, self.printer.resolution())
            if self.resolution.currentIndex() < 0 and self.resolution.count():
                self.resolution.setCurrentIndex(self.resolution.count() - 1)
            self._set_row_visible(
                self.resolution_row, self.resolution, len(resolutions) > 1
            )

            engine = self.printer.printEngine()
            raw_sources = engine.property(QPrintEngine.PPK_PaperSources) or []
            names = printer_tray_names(self.printer_box.currentText())
            self.paper_source.clear()
            for position, value in enumerate(raw_sources, start=1):
                label = names.get(int(value)) or tr("トレイ {number}").format(number=position)
                self.paper_source.addItem(label, int(value))
            self._set_row_visible(
                self.paper_source_row, self.paper_source, len(raw_sources) > 1
            )

            margins = self.printer.pageLayout().margins(QPageLayout.Millimeter)
            for spin, value in zip(
                self.margins,
                (margins.top(), margins.bottom(), margins.left(), margins.right()),
            ):
                spin.setValue(round(float(value), 1))
        finally:
            self._loading = False
        self._settings_changed()

    # ---- what gets printed -------------------------------------------
    def selected_pages(self) -> list[int]:
        """Zero-based page indices this dialog will print."""
        document = self.window.document
        if document is None:
            return []
        page_count = len(document)
        if self.range_current.isChecked():
            return [min(self.window.page_index, page_count - 1)]
        if self.range_custom.isChecked():
            start = max(0, self.range_from.value() - 1)
            end = min(page_count - 1, self.range_to.value() - 1)
            return list(range(start, end + 1)) if end >= start else []
        return list(range(page_count))

    def layout_options(self) -> dict[str, object]:
        """How the pages are placed on each sheet."""
        custom = self.per_sheet.currentData() == 0
        grid = (
            (self.grid_columns.value(), self.grid_rows.value()) if custom else None
        )
        per_sheet = (
            self.grid_columns.value() * self.grid_rows.value()
            if custom
            else int(self.per_sheet.currentData() or 1)
        )
        checked = self.order_buttons.checkedButton()
        return {
            "per_sheet": per_sheet,
            "grid": grid,
            "order": str(checked.property("order")) if checked else "across",
            "scale_mode": str(self.scale_mode.currentData() or "fit"),
            "scale_percent": float(self.scale_percent.value()),
        }

    def apply_to_printer(self) -> None:
        name = self.printer_box.currentText()
        if name and name != self.printer.printerName():
            self.printer.setPrinterName(name)
        self.printer.setCopyCount(self.copies.value())
        self.printer.setCollateCopies(self.collate.isChecked())
        self.printer.setPageOrientation(self.orientation.currentData())
        if self.color_mode.count():
            self.printer.setColorMode(self.color_mode.currentData())
        if self.duplex.count():
            self.printer.setDuplex(self.duplex.currentData())
        if self.page_size.count() and self.page_size.currentData() is not None:
            self.printer.setPageSize(self.page_size.currentData())
        if self.resolution.count():
            self.printer.setResolution(self.resolution.currentData())
        if self.paper_source.count():
            try:
                self.printer.setPaperSource(
                    QPrinter.PaperSource(self.paper_source.currentData())
                )
            except Exception:
                # A driver-private tray value Qt will not accept: leave the
                # printer on its own default rather than guess.
                pass
        top, bottom, left, right = (spin.value() for spin in self.margins)
        self.printer.setPageMargins(
            QMarginsF(left, top, right, bottom), QPageLayout.Millimeter
        )

    # ---- preview ------------------------------------------------------
    def _apply_zoom_mode(self) -> None:
        self.preview.setZoomMode(
            QPrintPreviewWidget.FitToWidth
            if self.fit_mode.currentData() == "width"
            else QPrintPreviewWidget.FitInView
        )

    def _step_sheet(self, delta: int) -> None:
        self._sheet = max(0, min(self._sheet_total - 1, self._sheet + delta))
        self._update_sheet_controls()
        self.preview.updatePreview()

    def _update_sheet_controls(self) -> None:
        self.sheet_label.setText(f"{self._sheet + 1} / {self._sheet_total}")
        self.previous_sheet.setEnabled(self._sheet > 0)
        self.next_sheet.setEnabled(self._sheet + 1 < self._sheet_total)

    def _settings_changed(self) -> None:
        if self._loading:
            return
        custom = self.per_sheet.currentData() == 0
        self._set_row_visible(self.grid_row_label, self.grid_widget, custom)
        self.range_from.setEnabled(self.range_custom.isChecked())
        self.range_to.setEnabled(self.range_custom.isChecked())
        self.scale_percent.setEnabled(self.scale_mode.currentData() == "percent")
        self.apply_to_printer()

        pages = self.selected_pages()
        options = self.layout_options()
        per_sheet = max(1, int(options["per_sheet"]))
        # Page order only means something once more than one page shares a
        # sheet, so the row is not offered before that.
        self._set_row_visible(self.order_row_label, self.order_widget, per_sheet > 1)
        self._set_row_visible(self.order_hint_label, self.order_hint, per_sheet > 1)
        self.order_hint.setText(
            tr("左上から右へ") if options["order"] == "across"
            else tr("左上から下へ")
        )
        # An empty range (say 5–3) used to leave Print enabled, and pressing
        # it printed nothing without a word.
        if getattr(self, "print_button", None) is not None:
            self.print_button.setEnabled(bool(pages))
        self._sheet_total = max(1, -(-len(pages) // per_sheet)) if pages else 1
        self._sheet = min(self._sheet, self._sheet_total - 1)
        self._update_sheet_controls()
        if not pages:
            self.preview_note.setText(tr("印刷するページがありません"))
        elif per_sheet > 1:
            self.preview_note.setText(
                tr("{total}ページを{sheets}枚に印刷します").format(
                    total=len(pages), sheets=self._sheet_total
                )
            )
        else:
            self.preview_note.setText(
                tr_n("{total}ページを印刷します", len(pages)).format(total=len(pages))
            )
        self.preview.updatePreview()

    def _paint_preview(self, printer: QPrinter) -> None:
        """Only the sheet on screen is rendered, so a 500-page document does
        not have to be laid out before the dialog can be shown."""
        options = self.layout_options()
        per_sheet = max(1, int(options["per_sheet"]))
        pages = self.selected_pages()
        start = self._sheet * per_sheet
        self.window._paint_pages_to_printer(
            printer, pages[start:start + per_sheet], preview=True, **options
        )


def _character_class(character: str) -> int:
    """Word classes for Ctrl+arrow: a run of one class is a word. Japanese
    has no spaces, so hiragana, katakana and kanji runs are told apart the
    way Japanese editors do."""
    if not character or character.isspace():
        return 0
    code = ord(character[0])
    if 0x3040 <= code <= 0x309F:
        return 2
    if 0x30A0 <= code <= 0x30FF or 0x31F0 <= code <= 0x31FF or 0xFF66 <= code <= 0xFF9F:
        return 3
    if (
        0x4E00 <= code <= 0x9FFF
        or 0x3400 <= code <= 0x4DBF
        or 0xF900 <= code <= 0xFAFF
        or code in (0x3005, 0x3006, 0x303B)
    ):
        return 4
    if character[0].isalnum() or character[0] == "_":
        return 1
    return 5


class PageCanvasMixin:
    """Pointer, selection and overlay behaviour shared by the page widgets.

    The single-page surface centres the page inside a larger widget, so its
    page coordinates are offset by image_rect.topLeft(); the
    continuous-scroll label *is* the page, so its offset is zero.
    `_canvas_origin()` is the only difference, and everything below is
    written once against it.
    """

    def _init_canvas_state(self) -> None:
        self.selectable_text_boxes: list[QRectF] = []
        self.editable_text_boxes: list[QRectF] = []
        self.selected_annotation_boxes: list[QRectF] = []
        self.form_field_boxes: list[QRectF] = []
        self.link_boxes: list[tuple[QRectF, dict[str, Any]]] = []
        self.text_selection_range: tuple[int, int] | None = None
        self._text_drag_active = False
        self.edit_mode = "select"
        self.drag_start: QPointF | None = None
        self.drag_current: QPointF | None = None
        self.ink_points: list[QPointF] = []
        self.line_preview: tuple[QPointF, QPointF, str, QColor, float] | None = None
        self.shape_preview: tuple[list[QPointF], QColor, float] | None = None
        self.ink_preview: tuple[list[list[QPointF]], QColor, float] | None = None
        # What the tool in hand would draw: its colour, and its width in
        # screen pixels at the zoom in use. Every preview is drawn with
        # it, so that what is on screen while drawing or editing is what
        # ends up on the page.
        self.preview_color = QColor(TOOL_DEFAULT_COLORS["rectangle"])
        self.preview_width = 2.0
        # A text cursor in the page text. Positions fall between characters
        # (0..len(selectable_text_boxes)); the anchor is the fixed end of a
        # Shift-extended selection, so what is selected is anchor..caret.
        # `text_segments` names the page each run of boxes belongs to -- a
        # two-page spread holds two -- and a selection never leaves one.
        self.caret_position: int | None = None
        self.selection_anchor: int | None = None
        self._caret_segment = 0
        # At a line break one position is both the end of a line and the
        # start of the next; this says which of the two the caret shows.
        self._caret_after = False
        self._caret_column: float | None = None
        self._caret_visible = True
        self._press_caret: tuple[int, bool, int] | None = None
        self._press_index: int | None = None
        self._extending_by_mouse = False
        self.text_characters: list[str] = []
        self.text_line_ids: list[int] = []
        self.text_segments: list[tuple[int, int, int]] = []
        self._text_layout_signature: tuple[object, ...] | None = None
        # (page, caret, anchor, after) to restore once this widget has text.
        self._pending_caret: tuple[int, int, int, bool] | None = None
        flash = QApplication.cursorFlashTime()
        self._caret_blinks = flash > 0
        self._caret_timer = QTimer(self)
        self._caret_timer.setInterval(max(250, flash // 2) if flash > 0 else 530)
        self._caret_timer.timeout.connect(self._blink_caret)

    def _canvas_origin(self) -> QPointF:
        raise NotImplementedError

    # ---- hit testing -------------------------------------------------
    def _hit_kind(self, local: QPointF) -> str:
        """What is under the pointer, in the order the click will resolve."""
        if any(box.contains(local) for box, _link in self.link_boxes):
            return "link"
        if any(box.contains(local) for box in self.form_field_boxes):
            return "field"
        if any(box.contains(local) for box in self.editable_text_boxes):
            return "text_box"
        if any(
            box.adjusted(-2, -2, 2, 2).contains(local)
            for box in self.selectable_text_boxes
        ):
            return "text"
        return "page"

    def _apply_hover_cursor(self, local: QPointF) -> None:
        if self.edit_mode != "select":
            return
        kind = self._hit_kind(local)
        if kind == "link":
            shape = Qt.PointingHandCursor
        elif kind in ("field", "text_box", "text"):
            # A fillable field is typed into, so it gets the text cursor
            # like any other input.
            shape = Qt.IBeamCursor
        else:
            shape = Qt.ArrowCursor
        self.setCursor(shape)

    def _begins_text_drag(self, local: QPointF) -> bool:
        return self.edit_mode == "select" and self._hit_kind(local) == "text"

    # ---- selection ---------------------------------------------------
    def _clear_text_selection(self) -> bool:
        """Drop the selection; the caret, if there is one, stays put."""
        if self.text_selection_range is None:
            return False
        self.text_selection_range = None
        if self.caret_position is not None:
            self.selection_anchor = self.caret_position
        self.textSelectionChanged.emit()
        self.update()
        return True

    # ---- text cursor -------------------------------------------------
    def set_text_layout(
        self,
        characters: list[str],
        line_ids: list[int],
        segments: list[tuple[int, int, int]],
        memory: tuple[Any, ...] | None = None,
    ) -> None:
        """The characters and line numbers behind selectable_text_boxes.

        The same pages with the same characters keep the caret where it
        was (a zoom, a re-render after an edit). The same page with the
        same text shown elsewhere -- one page becoming two side by side --
        keeps it on the same character. The same page with different text
        (a text box baked into it) puts it back at the nearest point.
        Anything else drops it.
        """
        signature = (tuple(segments), len(characters))
        unchanged = signature == self._text_layout_signature
        self.text_characters = characters
        self.text_line_ids = line_ids
        self.text_segments = segments
        self._text_layout_signature = signature
        pending, self._pending_caret = self._pending_caret, None
        if pending is not None:
            page, caret, anchor, after = pending
            number = self.segment_for_page(page)
            if number is not None:
                start, end = self._segments()[number][1:]
                if start + max(caret, anchor) <= end:
                    self.set_caret(
                        start + caret, start + anchor, after=after, segment=number, reveal=False
                    )
                    return
        if unchanged or self.caret_position is None:
            if self.caret_position is not None:
                self.update()
            return
        if memory is not None:
            page, caret_point, anchor_point, after, caret_local, anchor_local, length = memory
            number = self.segment_for_page(page)
            if number is not None:
                _page, start, end = self._segments()[number]
                if end - start == length:
                    # Screen points are useless here: the page itself moved.
                    self.set_caret(
                        start + caret_local, start + anchor_local,
                        after=after, segment=number, reveal=False,
                    )
                    return
                caret = self._caret_target_at(caret_point, only=number)
                anchor = self._caret_target_at(anchor_point, only=number)
                if caret is not None and anchor is not None:
                    self.set_caret(
                        caret[0], anchor[0], after=caret[1], segment=number, reveal=False
                    )
                    return
        self.set_caret(None, reveal=False)

    def caret_memory(self) -> tuple[Any, ...] | None:
        """The caret and anchor by character (within their page) and by
        screen point, to find them again after a re-render."""
        line = self.caret_line()
        if line is None or self.selection_anchor is None:
            return None
        page, start, end = self._current_segment()
        anchor_point = self._position_point(self.selection_anchor)
        return (
            page, line.center(), anchor_point or line.center(), self._caret_after,
            self.caret_position - start, self.selection_anchor - start, end - start,
        )

    def caret_location(self) -> tuple[int, int, int, bool] | None:
        """(page, caret, anchor, after) relative to the page's own text, to
        carry the caret to another widget showing the same page."""
        if self.caret_position is None or self.selection_anchor is None:
            return None
        page, start, _end = self._current_segment()
        if page < 0:
            return None
        return page, self.caret_position - start, self.selection_anchor - start, self._caret_after

    def _segments(self) -> list[tuple[int, int, int]]:
        """(page, first, end) runs of selectable_text_boxes, one per page."""
        count = len(self.selectable_text_boxes)
        segments = [segment for segment in self.text_segments if segment[2] <= count]
        return segments or [(-1, 0, count)]

    def _current_segment(self) -> tuple[int, int, int]:
        segments = self._segments()
        return segments[min(max(0, self._caret_segment), len(segments) - 1)]

    def segment_for_page(self, page_index: int) -> int | None:
        for number, segment in enumerate(self._segments()):
            if segment[0] in (page_index, -1):
                return number
        return None

    def _line_of(self, index: int) -> int:
        ids = self.text_line_ids
        return ids[index] if 0 <= index < len(ids) else 0

    def _line_range(self, index: int, segment: tuple[int, int, int]) -> tuple[int, int]:
        """[first, end) of the line holding character `index`."""
        start, end = segment[1], segment[2]
        line = self._line_of(index)
        first = index
        while first > start and self._line_of(first - 1) == line:
            first -= 1
        last = index + 1
        while last < end and self._line_of(last) == line:
            last += 1
        return first, last

    def _is_line_start(self, position: int, segment: tuple[int, int, int]) -> bool:
        return (
            segment[1] < position < segment[2]
            and self._line_of(position) != self._line_of(position - 1)
        )

    def _natural_after(self, position: int, segment: tuple[int, int, int]) -> bool:
        """A caret arriving at a line break from the left shows at the end
        of that line, not the start of the next."""
        return position == segment[2] or self._is_line_start(position, segment)

    def _line_direction(self, index: int, segment: tuple[int, int, int]) -> str:
        """"ltr", "rtl" or "vertical", judged from the line's first and
        last glyph -- vertical Japanese runs down the page."""
        first, last = self._line_range(index, segment)
        if last - first < 2:
            return "ltr"
        head = self.selectable_text_boxes[first].center()
        tail = self.selectable_text_boxes[last - 1].center()
        if abs(tail.y() - head.y()) > abs(tail.x() - head.x()):
            return "vertical"
        return "rtl" if tail.x() < head.x() else "ltr"

    def _caret_character(self) -> int | None:
        """The character whose line the caret is drawn on."""
        if self.caret_position is None:
            return None
        start, end = self._current_segment()[1:]
        if end <= start or end > len(self.selectable_text_boxes):
            return None
        position = min(max(self.caret_position, start), end)
        if position == end or (self._caret_after and position > start):
            return position - 1
        return position

    def _position_edge(self, position: int, character: int, direction: str) -> float:
        """Where the caret for `position` sits along its line: x across
        horizontal text, y down vertical text."""
        box = self.selectable_text_boxes[character]
        before = position <= character
        if direction == "vertical":
            return box.top() if before else box.bottom()
        if direction == "rtl":
            return box.right() if before else box.left()
        return box.left() if before else box.right()

    def _position_point(self, position: int) -> QPointF | None:
        start, end = self._current_segment()[1:]
        if end <= start:
            return None
        character = min(max(position, start), end - 1)
        box = self.selectable_text_boxes[character]
        direction = self._line_direction(character, self._current_segment())
        edge = self._position_edge(position, character, direction)
        if direction == "vertical":
            return QPointF(box.center().x(), edge)
        return QPointF(edge, box.center().y())

    def caret_line(self) -> QLineF | None:
        """The caret in page-canvas coordinates (origin not applied)."""
        character = self._caret_character()
        if character is None:
            return None
        segment = self._current_segment()
        direction = self._line_direction(character, segment)
        box = self.selectable_text_boxes[character]
        edge = self._position_edge(self.caret_position, character, direction)
        if direction == "vertical":
            return QLineF(box.left(), edge, box.right(), edge)
        return QLineF(edge, box.top(), edge, box.bottom())

    def caret_rect(self) -> QRectF | None:
        """The caret's area in widget coordinates."""
        line = self.caret_line()
        if line is None:
            return None
        return (
            QRectF(line.p1(), line.p2()).normalized().adjusted(-3, -3, 3, 3)
            .translated(self._canvas_origin())
        )

    def set_caret(
        self,
        position: int | None,
        anchor: int | None = None,
        *,
        after: bool = False,
        segment: int | None = None,
        keep_column: bool = False,
        quiet: bool = False,
        reveal: bool = True,
    ) -> None:
        """Put the caret at `position`; `anchor` (the caret itself when
        omitted) is the other end of the selection."""
        previous = self.text_selection_range
        if position is None or not self.selectable_text_boxes:
            self.caret_position = None
            self.selection_anchor = None
            self._caret_after = False
            self._caret_timer.stop()
            self.text_selection_range = None
        else:
            if segment is not None:
                self._caret_segment = segment
            start, end = self._current_segment()[1:]
            position = min(max(position, start), end)
            anchor = position if anchor is None else min(max(anchor, start), end)
            self.caret_position = position
            self.selection_anchor = anchor
            self._caret_after = after
            low, high = sorted((anchor, position))
            self.text_selection_range = (low, high - 1) if high > low else None
            self._caret_visible = True
            if self._caret_blinks:
                self._caret_timer.start()
        if not keep_column:
            self._caret_column = None
        self.update()
        if quiet:
            return
        if self.text_selection_range != previous:
            self.textSelectionChanged.emit()
        if reveal:
            self.caretMoved.emit()

    def clear_caret(self) -> None:
        if self.caret_position is not None or self.text_selection_range is not None:
            self.set_caret(None, reveal=False)

    def _blink_caret(self) -> None:
        if self.caret_position is None or not self.isVisible():
            self._caret_timer.stop()
            self._caret_visible = True
            return
        self._caret_visible = not self._caret_visible
        rect = self.caret_rect()
        if rect is not None:
            self.update(rect.toAlignedRect())

    def select_segment(self, number: int) -> bool:
        """Select all of one page's text."""
        segments = self._segments()
        if not 0 <= number < len(segments):
            return False
        _page, start, end = segments[number]
        if end <= start:
            return False
        self.set_caret(end, start, after=True, segment=number)
        return True

    def _caret_target_at(
        self, point: QPointF, *, only: int | None = None
    ) -> tuple[int, bool, int, int] | None:
        """(position, after, segment, character) for the caret nearest a
        point, optionally within one segment."""
        segments = self._segments()
        numbers = range(len(segments)) if only is None else [only]
        best: tuple[float, int, int] | None = None
        for number in numbers:
            if not 0 <= number < len(segments):
                continue
            _page, start, end = segments[number]
            for index in range(start, min(end, len(self.selectable_text_boxes))):
                center = self.selectable_text_boxes[index].center()
                distance = (center.x() - point.x()) ** 2 + (center.y() - point.y()) ** 2
                if best is None or distance < best[0]:
                    best = (distance, index, number)
        if best is None:
            return None
        _distance, index, number = best
        segment = segments[number]
        box = self.selectable_text_boxes[index]
        direction = self._line_direction(index, segment)
        if direction == "vertical":
            past = point.y() > box.center().y()
        elif direction == "rtl":
            past = point.x() < box.center().x()
        else:
            past = point.x() > box.center().x()
        position = index + 1 if past else index
        return position, past and self._natural_after(position, segment), number, index

    def _word_range(self, index: int, segment: tuple[int, int, int]) -> tuple[int, int]:
        characters = self.text_characters
        if not 0 <= index < len(characters):
            return index, index + 1
        kind = _character_class(characters[index])
        line = self._line_of(index)
        first = index
        while (
            first > segment[1]
            and _character_class(characters[first - 1]) == kind
            and self._line_of(first - 1) == line
        ):
            first -= 1
        last = index + 1
        while (
            last < segment[2]
            and _character_class(characters[last]) == kind
            and self._line_of(last) == line
        ):
            last += 1
        return first, last

    def _word_end_after(self, position: int, segment: tuple[int, int, int]) -> int:
        end = segment[2]
        characters = self.text_characters
        if position >= end or position >= len(characters):
            return end
        kind = _character_class(characters[position])
        line = self._line_of(position)
        index = position
        while (
            index < end
            and _character_class(characters[index]) == kind
            and self._line_of(index) == line
        ):
            index += 1
        while index < end and characters[index].isspace() and self._line_of(index) == line:
            index += 1
        return index

    def _word_start_before(self, position: int, segment: tuple[int, int, int]) -> int:
        start = segment[1]
        characters = self.text_characters
        if position <= start or position > len(characters):
            return start
        index = position
        line = self._line_of(index - 1)
        while (
            index > start
            and characters[index - 1].isspace()
            and self._line_of(index - 1) == line
        ):
            index -= 1
        if index > start:
            kind = _character_class(characters[index - 1])
            line = self._line_of(index - 1)
            while (
                index > start
                and _character_class(characters[index - 1]) == kind
                and self._line_of(index - 1) == line
            ):
                index -= 1
        return index

    def _closest_in_line(
        self, character: int, segment: tuple[int, int, int], column: float
    ) -> tuple[int, bool]:
        first, last = self._line_range(character, segment)
        direction = self._line_direction(first, segment)
        best, best_distance = first, None
        for position in range(first, last + 1):
            glyph = min(position, last - 1)
            distance = abs(self._position_edge(position, glyph, direction) - column)
            if best_distance is None or distance < best_distance:
                best, best_distance = position, distance
        return best, best == last

    def _leave_segment(self, number: int, step: int, extend: bool) -> int:
        """Past the first or last character: into the other page of a
        spread, or report the step for the window to take."""
        if extend:
            return 0
        segments = self._segments()
        target = number + step
        if 0 <= target < len(segments):
            _page, start, end = segments[target]
            self.set_caret(start if step > 0 else end, segment=target, after=step < 0)
            return 0
        return step

    def handle_caret_key(self, key: int, extend: bool, by_word: bool) -> int:
        """Move the caret for an arrow, Home or End key.

        Returns 0 once handled here, or +1 / -1 when the caret should carry
        on to the next or previous page, which only the window can show.
        """
        if self.caret_position is None:
            return 0
        segments = self._segments()
        number = min(max(0, self._caret_segment), len(segments) - 1)
        segment = segments[number]
        start, end = segment[1], segment[2]
        position = min(max(self.caret_position, start), end)
        character = self._caret_character()
        direction = "ltr" if character is None else self._line_direction(character, segment)
        if direction == "vertical":
            moves = {
                Qt.Key_Up: "back", Qt.Key_Down: "forward",
                Qt.Key_Left: "next_line", Qt.Key_Right: "previous_line",
            }
        elif direction == "rtl":
            moves = {
                Qt.Key_Left: "forward", Qt.Key_Right: "back",
                Qt.Key_Up: "previous_line", Qt.Key_Down: "next_line",
            }
        else:
            moves = {
                Qt.Key_Left: "back", Qt.Key_Right: "forward",
                Qt.Key_Up: "previous_line", Qt.Key_Down: "next_line",
            }
        moves[Qt.Key_Home] = "line_start"
        moves[Qt.Key_End] = "line_end"
        move = moves.get(key)
        if move is None:
            return 0
        backwards = move in ("back", "previous_line", "line_start")
        if character is None:
            return self._leave_segment(number, -1 if backwards else 1, extend)
        if (
            not extend
            and not by_word
            and move in ("back", "forward")
            and self.text_selection_range is not None
            and self.selection_anchor is not None
        ):
            # With a selection, Left and Right land on its near end, as in
            # any editor, instead of moving one past it.
            low, high = sorted((self.selection_anchor, position))
            if move == "back":
                self.set_caret(low, segment=number)
            else:
                self.set_caret(high, after=self._natural_after(high, segment), segment=number)
            return 0
        after = False
        keep_column = False
        if move == "back":
            if not self._caret_after and not by_word and self._is_line_start(position, segment):
                # A line break counts as one step, like the newline it is.
                new, after = position, True
            elif position <= start:
                return self._leave_segment(number, -1, extend)
            elif by_word:
                new = self._word_start_before(position, segment)
            else:
                new = position - 1
        elif move == "forward":
            if self._caret_after and self._is_line_start(position, segment):
                new = position
            elif position >= end:
                return self._leave_segment(number, 1, extend)
            else:
                new = self._word_end_after(position, segment) if by_word else position + 1
                after = self._natural_after(new, segment)
        elif move in ("line_start", "line_end"):
            first, last = self._line_range(character, segment)
            new, after = (first, False) if move == "line_start" else (last, True)
        else:
            first, last = self._line_range(character, segment)
            target = first - 1 if move == "previous_line" else last
            if not start <= target < end:
                if not extend:
                    return self._leave_segment(number, -1 if backwards else 1, extend)
                new = start if backwards else end
                after = new == end
            else:
                if self._caret_column is None:
                    self._caret_column = self._position_edge(position, character, direction)
                new, after = self._closest_in_line(target, segment, self._caret_column)
                keep_column = True
        anchor = None
        if extend:
            anchor = self.selection_anchor if self.selection_anchor is not None else position
        self.set_caret(new, anchor, after=after, segment=number, keep_column=keep_column)
        return 0

    # ---- overlays ----------------------------------------------------
    def _paint_line_preview(
        self,
        painter: QPainter,
        start: QPointF,
        end: QPointF,
        kind: str,
        color: QColor,
        width: float,
    ) -> None:
        """A line, or a line with a solid head, in one place.

        Used both while a new one is being dragged out and while an
        existing one is being edited, so the two cannot drift apart.
        The head grows with the stroke, as it does in the PDF, where the
        size of a line ending follows the border width.
        """
        painter.setPen(QPen(color, width, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
        painter.setBrush(color)
        painter.drawLine(start, end)
        if kind != "arrow":
            return
        scale = max(1.0, width / 2.0)
        angle = math.atan2(end.y() - start.y(), end.x() - start.x())
        base = QPointF(
            end.x() - math.cos(angle) * ARROW_PREVIEW_HEAD_LENGTH * scale,
            end.y() - math.sin(angle) * ARROW_PREVIEW_HEAD_LENGTH * scale,
        )
        normal = QPointF(
            -math.sin(angle) * ARROW_PREVIEW_HEAD_HALF_WIDTH * scale,
            math.cos(angle) * ARROW_PREVIEW_HEAD_HALF_WIDTH * scale,
        )
        painter.drawPolygon(QPolygonF([end, base + normal, base - normal]))

    def _paint_canvas_overlays(self, painter: QPainter) -> None:
        """Everything drawn on top of the page image."""
        # Smoothed, because the page underneath is: MuPDF antialiases the
        # marks it draws, and a hard-edged preview of the same stroke came
        # out a different thickness -- a 2.53px pen landed as 2 solid rows
        # against the page's 2.47 rows of coverage.
        painter.setRenderHint(QPainter.Antialiasing, True)
        offset = self._canvas_origin()
        if self.line_preview is not None:
            first, second, kind, color, width = self.line_preview
            self._paint_line_preview(
                painter, first + offset, second + offset, kind, color, width
            )
        if self.shape_preview is not None:
            points, color, width = self.shape_preview
            painter.setBrush(Qt.NoBrush)
            painter.setPen(QPen(color, width, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
            painter.drawPolygon(QPolygonF([point + offset for point in points]))
        if self.ink_preview is not None:
            strokes, color, width = self.ink_preview
            painter.setBrush(Qt.NoBrush)
            painter.setPen(QPen(color, width, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin))
            for stroke in strokes:
                # Open runs, not a closed outline: this is handwriting.
                painter.drawPolyline(QPolygonF([point + offset for point in stroke]))
        if self.form_field_boxes:
            # Tint fillable fields, the way a browser shades form inputs --
            # otherwise nothing says the page can be typed into.
            painter.setPen(QPen(QColor(49, 130, 246, 150), 1))
            painter.setBrush(QColor(49, 130, 246, 38))
            for box in self.form_field_boxes:
                painter.drawRect(box.translated(offset))
        if self.selected_annotation_boxes:
            # A thin frame round each, as PowerPoint marks every object of
            # a selection, a little off it so a shape's own line shows; no
            # handles -- those are for one thing held (6.24). It was a thick
            # dashed box, unlike the frame of one held thing.
            painter.setBrush(Qt.NoBrush)
            painter.setPen(QPen(QColor(SELECTION_FRAME_COLOR), 1, Qt.SolidLine))
            for box in self.selected_annotation_boxes:
                painter.drawRect(box.translated(offset).adjusted(-2, -2, 2, 2))
        if self.text_selection_range is not None:
            painter.setPen(Qt.NoPen)
            painter.setBrush(QColor(48, 126, 255, 115))
            low, high = self.text_selection_range
            for box in self.selectable_text_boxes[low : high + 1]:
                painter.drawRect(box.translated(offset))
        if self.caret_position is not None and self._caret_visible:
            caret = self.caret_line()
            if caret is not None:
                # Dark on a light halo: readable on white paper and on a
                # dark scanned page alike.
                caret = caret.translated(offset)
                painter.setBrush(Qt.NoBrush)
                painter.setPen(QPen(QColor(255, 255, 255, 210), 4, Qt.SolidLine, Qt.FlatCap))
                painter.drawLine(caret)
                painter.setPen(QPen(QColor(18, 18, 22), 2, Qt.SolidLine, Qt.FlatCap))
                painter.drawLine(caret)
        if self.drag_start is None or self.drag_current is None:
            return
        if getattr(self, "_moving_selection", False):
            # The selection where it is going (6.12).
            shift = self.drag_current - self.drag_start
            painter.setBrush(Qt.NoBrush)
            painter.setPen(QPen(QColor("#3182F6"), 1.5, Qt.DashLine))
            for box in self.selected_annotation_boxes:
                painter.drawRect(box.translated(offset + shift))
            return
        if self.edit_mode == "ink" and len(self.ink_points) > 1:
            painter.setPen(
                QPen(
                    self.preview_color, self.preview_width,
                    Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin,
                )
            )
            for first, second in zip(self.ink_points, self.ink_points[1:]):
                painter.drawLine(first + offset, second + offset)
        elif self.edit_mode in ("rectangle", "arrow", "line"):
            # The shape itself from the first few pixels of the drag, not
            # a marquee: a range-selection box is what `select` does, and
            # seeing one while drawing an arrow says the wrong thing.
            start, end = self.drag_start + offset, self.drag_current + offset
            if self.edit_mode == "rectangle":
                painter.setBrush(Qt.NoBrush)
                painter.setPen(
                    QPen(
                        self.preview_color, self.preview_width,
                        Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin,
                    )
                )
                painter.drawRect(QRectF(start, end).normalized())
            else:
                self._paint_line_preview(
                    painter, start, end, self.edit_mode,
                    self.preview_color, self.preview_width,
                )
        elif not self._text_drag_active:
            # Selecting text shows the highlighted characters, not a
            # marquee -- a rubber-band box over words is not how text
            # selection looks anywhere else.
            painter.setBrush(QColor(255, 198, 32, 45))
            painter.setPen(QPen(QColor(255, 106, 66), 2, Qt.DashLine))
            painter.drawRect(
                QRectF(self.drag_start + offset, self.drag_current + offset).normalized()
            )

    # ---- pointer -----------------------------------------------------
    #
    # These three handlers were written out separately in both widgets and
    # had already drifted: right-clicking the margin around the page did
    # nothing in single-page view but opened the menu in continuous view,
    # and the hover cursor was measured from a clipped point in one and an
    # unclipped one in the other. Everything that actually differs is a
    # hook below.

    def _canvas_size(self) -> QSizeF:
        """Size of the page itself inside this widget."""
        raise NotImplementedError

    def _has_page(self) -> bool:
        """False while there is nothing to click on."""
        return True

    def _emit_gesture(self, mode: str, payload: object) -> None:
        """Report a finished gesture. The continuous view names its page."""
        raise NotImplementedError

    def _notify_activated(self) -> None:
        """The continuous view also reports which page was clicked."""

    def _local(self, position: QPointF) -> QPointF:
        """Widget point in page coordinates, off-page values kept."""
        return position - self._canvas_origin()

    def _clipped(self, position: QPointF) -> QPointF:
        """Widget point in page coordinates, clamped onto the page."""
        local = self._local(position)
        size = self._canvas_size()
        return QPointF(
            min(max(0.0, local.x()), max(0.0, size.width())),
            min(max(0.0, local.y()), max(0.0, size.height())),
        )

    def set_edit_mode(self, mode: str) -> None:
        self.edit_mode = mode
        self.drag_start = None
        self.drag_current = None
        self.ink_points.clear()
        self._text_drag_active = False
        # Tools come and go; the text cursor stays, marking where Enter
        # puts the next note or shape. Only the selection is dropped.
        if self.caret_position is not None:
            self.set_caret(self.caret_position, after=self._caret_after, quiet=True)
        else:
            self.text_selection_range = None
        self.setCursor(Qt.ArrowCursor if mode == "select" else Qt.CrossCursor)
        self.update()

    def mousePressEvent(self, event: Any) -> None:
        if not self._has_page():
            super().mousePressEvent(event)
            return
        if event.button() == Qt.RightButton:
            self._emit_gesture(
                "context_select",
                (self._clipped(event.position()), event.globalPosition().toPoint()),
            )
            event.accept()
            return
        if event.button() == Qt.LeftButton:
            local = self._clipped(event.position())
            self.drag_start = local
            self.drag_current = local
            self.ink_points = [local]
            # Pressed on a selected mark, the selection is dragged as one,
            # as in PowerPoint (6.12); a click there still selects it alone.
            self._moving_selection = (
                self.edit_mode == "select"
                and not event.modifiers() & (Qt.ControlModifier | Qt.ShiftModifier)
                and any(box.contains(local) for box in self.selected_annotation_boxes)
            )
            self._text_drag_active = not self._moving_selection and self._begins_text_drag(local)
            self._extending_by_mouse = False
            self._press_caret = None
            self._notify_activated()
            if self._text_drag_active:
                # Clicking text puts the caret there; Shift+click extends
                # the selection from wherever the caret already was.
                self._emit_gesture("text_caret", local)
                extend = (
                    bool(event.modifiers() & Qt.ShiftModifier)
                    and self.caret_position is not None
                )
                target = self._caret_target_at(
                    local, only=self._caret_segment if extend else None
                )
                if target is not None:
                    position, after, number, index = target
                    self._press_caret = (position, after, number)
                    self._press_index = index
                    self._extending_by_mouse = extend
                    self.set_caret(
                        position,
                        self.selection_anchor if extend else None,
                        after=after,
                        segment=number,
                        reveal=False,
                    )
            else:
                self.clear_caret()
            self.update()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event: Any) -> None:
        """Double-clicking text selects the word under the pointer."""
        if (
            event.button() == Qt.LeftButton
            and self._has_page()
            and self.edit_mode == "select"
        ):
            local = self._clipped(event.position())
            if self._hit_kind(local) == "text":
                target = self._caret_target_at(local)
                if target is not None:
                    _position, _after, number, index = target
                    segment = self._segments()[number]
                    first, last = self._word_range(index, segment)
                    self.set_caret(
                        last, first, after=self._natural_after(last, segment),
                        segment=number, reveal=False,
                    )
                    event.accept()
                    return
        super().mouseDoubleClickEvent(event)

    def _constrained(self, point: QPointF, modifiers: Any) -> QPointF:
        """With Shift, a line or an arrow at a multiple of 45 degrees and a
        rectangle a square, as PowerPoint draws them (6.12) -- kept on the
        page."""
        if not modifiers & Qt.ShiftModifier or self.drag_start is None:
            return point
        if self.edit_mode in ("arrow", "line"):
            end = snap_to_45_degrees(self.drag_start, point)
        elif self.edit_mode == "rectangle":
            end = square_from(self.drag_start, point)
        else:
            return point
        size = self._canvas_size()
        width, height = max(0.0, size.width()), max(0.0, size.height())
        start = self.drag_start
        dx, dy = end.x() - start.x(), end.y() - start.y()
        # Shortened along the same line, never bent, where the page ends.
        scale = 1.0
        for delta, origin, limit in ((dx, start.x(), width), (dy, start.y(), height)):
            if delta > 0 and origin + delta > limit:
                scale = min(scale, (limit - origin) / delta)
            elif delta < 0 and origin + delta < 0:
                scale = min(scale, origin / -delta)
        if self.edit_mode == "rectangle" or scale < 1.0:
            return QPointF(start.x() + dx * scale, start.y() + dy * scale)
        return end

    def mouseMoveEvent(self, event: Any) -> None:
        if self.drag_start is not None:
            local = self._constrained(self._clipped(event.position()), event.modifiers())
            self.drag_current = local
            if self.edit_mode == "ink":
                self.ink_points.append(local)
            if self._text_drag_active and self.caret_position is not None:
                target = self._caret_target_at(local, only=self._caret_segment)
                if target is not None:
                    position, after, _number, index = target
                    pressed = self._press_index
                    if self._extending_by_mouse or pressed is None:
                        self.set_caret(position, self.selection_anchor, after=after, quiet=True)
                    elif index >= pressed:
                        # A drag takes in both the character it started on
                        # and the one under the pointer now.
                        end = index + 1
                        self.set_caret(
                            end, pressed,
                            after=self._natural_after(end, self._current_segment()),
                            quiet=True,
                        )
                    else:
                        self.set_caret(index, pressed + 1, quiet=True)
            self.update()
            event.accept()
            return
        # Hovering uses the unclipped point: clamping it would put an I-beam
        # on the margin whenever the page edge happens to carry text.
        self._apply_hover_cursor(self._local(event.position()))
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: Any) -> None:
        if event.button() != Qt.LeftButton or self.drag_start is None:
            super().mouseReleaseEvent(event)
            return
        self.drag_current = self._constrained(self._clipped(event.position()), event.modifiers())
        selection = QRectF(self.drag_start, self.drag_current).normalized()
        is_click = selection.width() <= 4 and selection.height() <= 4
        moving, self._moving_selection = getattr(self, "_moving_selection", False), False
        if self._text_drag_active:
            # The caret went down at the press and a drag has carried it
            # since. A plain click leaves it where it landed, without the
            # one-character selection a few pixels of jitter would make.
            if is_click and not self._extending_by_mouse and self._press_caret is not None:
                position, after, number = self._press_caret
                self.set_caret(position, after=after, segment=number, quiet=True)
            self.drag_start = None
            self.drag_current = None
            self._text_drag_active = False
            self._extending_by_mouse = False
            self._press_caret = None
            self.textSelectionChanged.emit()
            self.update()
            event.accept()
            return
        if is_click:
            self._clear_text_selection()
        self._text_drag_active = False
        if is_click and self.edit_mode == "select":
            for box, link in self.link_boxes:
                if box.contains(self.drag_current):
                    self.drag_start = None
                    self.drag_current = None
                    self.update()
                    self._notify_activated()
                    self.linkActivated.emit(link)
                    event.accept()
                    return
        if self.edit_mode == "select":
            if is_click:
                # Ctrl+click means "this one as well", as in Office.
                mode = (
                    "select_toggle"
                    if event.modifiers() & Qt.ControlModifier
                    else "select_at"
                )
            elif moving:
                mode = "move_selection"
            else:
                mode = "select_range"
            payload: object = (
                self.drag_current if is_click
                else QPointF(self.drag_current - self.drag_start) if moving
                else selection
            )
        elif self.edit_mode == "note":
            mode, payload = self.edit_mode, self.drag_current
        elif self.edit_mode == "text":
            mode, payload = self.edit_mode, (
                QPointF(self.drag_start), QPointF(self.drag_current)
            )
        elif self.edit_mode == "ink":
            mode, payload = self.edit_mode, list(self.ink_points)
        elif self.edit_mode in ("arrow", "line"):
            # Both ends, in the order they were drawn. A normalised
            # rectangle has no direction in it, so every arrow used to
            # point from its top-left corner to its bottom-right one.
            mode, payload = self.edit_mode, (
                QPointF(self.drag_start), QPointF(self.drag_current)
            )
        else:
            mode, payload = self.edit_mode, selection
        self.drag_start = None
        self.drag_current = None
        self.ink_points.clear()
        self.update()
        self._emit_gesture(mode, payload)
        event.accept()

    # ---- previews ----------------------------------------------------
    def set_preview_ink(self, color: QColor, width: float) -> None:
        """The colour and the screen width a new mark would be drawn in."""
        self.preview_color = QColor(color)
        self.preview_width = max(0.5, float(width))
        if self.drag_start is not None:
            self.update()

    def set_line_preview(
        self,
        first: QPointF | None,
        second: QPointF | None = None,
        kind: str = "line",
        color: QColor | None = None,
        width: float | None = None,
    ) -> None:
        if first is None or second is None:
            self.line_preview = None
        else:
            self.line_preview = (
                first, second, kind,
                color or QColor(self.preview_color),
                max(0.5, float(width if width is not None else self.preview_width)),
            )
        self.update()

    def set_ink_preview(
        self,
        strokes: list[list[QPointF]] | None,
        color: QColor | None = None,
        width: float | None = None,
    ) -> None:
        if not strokes:
            self.ink_preview = None
        else:
            self.ink_preview = (
                [list(stroke) for stroke in strokes],
                color or QColor(self.preview_color),
                max(0.5, float(width if width is not None else self.preview_width)),
            )
        self.update()

    def set_shape_preview(
        self,
        points: list[QPointF] | None,
        color: QColor | None = None,
        width: float | None = None,
    ) -> None:
        if not points:
            self.shape_preview = None
        else:
            self.shape_preview = (
                list(points),
                color or QColor(self.preview_color),
                max(0.5, float(width if width is not None else self.preview_width)),
            )
        self.update()


class PageSurface(PageCanvasMixin, QWidget):
    linkActivated = Signal(object)
    editGesture = Signal(str, object)
    # Raised when the page-text selection settles, so the window can show
    # what formatting that selection already carries.
    textSelectionChanged = Signal()
    # Raised when the keyboard moves the caret, to scroll it into view.
    caretMoved = Signal()

    def __init__(self) -> None:
        super().__init__()
        self._init_canvas_state()
        self.page_pixmap = QPixmap()
        self.viewport_size = QSize(640, 480)
        self.image_rect = QRect()
        self.setMouseTracking(True)
        self.setCursor(Qt.ArrowCursor)
        # Clicking the page makes it the active pane (Tab switches away).
        self.setFocusPolicy(Qt.ClickFocus)

    def set_page(
        self,
        pixmap: QPixmap,
        viewport_size: QSize,
        links: list[tuple[QRectF, dict[str, Any]]],
        selectable_text_boxes: list[QRectF] | None = None,
        editable_text_boxes: list[QRectF] | None = None,
        selected_annotation_boxes: list[QRectF] | None = None,
        text_layout: tuple[list[str], list[int], list[tuple[int, int, int]]] | None = None,
    ) -> None:
        memory = self.caret_memory()
        self.page_pixmap = pixmap
        self.link_boxes = links
        self.selectable_text_boxes = selectable_text_boxes or []
        self.editable_text_boxes = editable_text_boxes or []
        self.selected_annotation_boxes = selected_annotation_boxes or []
        characters, line_ids, segments = text_layout or ([], [], [])
        if not self.selectable_text_boxes:
            characters, line_ids, segments = [], [], []
        self.set_text_layout(characters, line_ids, segments, memory)
        self.resize_for_viewport(viewport_size)

    def resize_for_viewport(self, viewport_size: QSize) -> None:
        self.viewport_size = viewport_size
        if self.page_pixmap.isNull():
            self.setFixedSize(max(1, viewport_size.width()), max(1, viewport_size.height()))
            return
        # In logical pixels: the pixmap is drawn in the screen's (1.0.0),
        # and its width() counts those.
        logical = self.page_pixmap.deviceIndependentSize()
        page_width = math.ceil(logical.width() - 0.01)
        page_height = math.ceil(logical.height() - 0.01)
        width = max(viewport_size.width(), page_width + 52)
        height = max(viewport_size.height(), page_height + 52)
        self.setFixedSize(width, height)
        self.image_rect = QRect(
            (width - page_width) // 2,
            (height - page_height) // 2,
            page_width,
            page_height,
        )
        self.update()

    def clear_page(self, viewport_size: QSize) -> None:
        self.page_pixmap = QPixmap()
        self.link_boxes.clear()
        self.set_caret(None, quiet=True)
        self.selectable_text_boxes = []
        self.set_text_layout([], [], [])
        self.editable_text_boxes.clear()
        self.selected_annotation_boxes.clear()
        self.text_selection_range = None
        self.line_preview = None
        self.ink_preview = None
        self.resize_for_viewport(viewport_size)
        self.update()

    def _canvas_origin(self) -> QPointF:
        return QPointF(self.image_rect.topLeft())

    def _canvas_size(self) -> QSizeF:
        return QSizeF(self.image_rect.size())

    def _has_page(self) -> bool:
        return not self.page_pixmap.isNull()

    def _emit_gesture(self, mode: str, payload: object) -> None:
        self.editGesture.emit(mode, payload)

    def paintEvent(self, _event: Any) -> None:
        painter = QPainter(self)
        painter.fillRect(self.rect(), QColor(COLORS["canvas"]))
        if self.page_pixmap.isNull():
            return
        shadow = self.image_rect.adjusted(6, 7, 8, 9)
        painter.fillRect(shadow, QColor(42, 44, 49, 145))
        painter.drawPixmap(self.image_rect.topLeft(), self.page_pixmap)
        self._paint_canvas_overlays(painter)


class TriangleScrollBar(QScrollBar):
    """Vertical scroll bar whose arrow buttons step the view.

    The arrows themselves are drawn by the stylesheet, for every scroll bar
    in the program; this adds the stepping, which the two page viewers need
    over their long documents.
    """

    BUTTON_SIZE = 15

    def mousePressEvent(self, event: Any) -> None:
        if self.orientation() == Qt.Vertical and event.button() == Qt.LeftButton:
            if event.position().y() < self.BUTTON_SIZE:
                self.setValue(self.value() - self.singleStep())
                event.accept()
                return
            if event.position().y() >= self.height() - self.BUTTON_SIZE:
                self.setValue(self.value() + self.singleStep())
                event.accept()
                return
        super().mousePressEvent(event)


# Where a thumbnail item keeps the page as drawn, for ThumbnailDelegate.
THUMBNAIL_PIXMAP_ROLE = Qt.UserRole + 1

# The outline's entries as sections of the Pages tab (6.9), PowerPoint's
# way: a header above the page each starts on, which folds the section.
SECTION_BAND_HEIGHT = 24
SECTION_INDENT = 12


@dataclass
class PageSectionBand:
    """One section header drawn above a thumbnail."""

    key: int
    title: str
    level: int
    pages: int
    folded: bool
    here: bool


class ThumbnailDelegate(QStyledItemDelegate):
    """Paints a page thumbnail at its own size.

    QIcon draws into a rectangle of whole logical pixels, and a thumbnail
    drawn for a 125 % screen is 144.8 logical pixels wide: Qt stretched it
    by a fraction of a pixel, which smoothed every line of it (1.0.0). The
    item keeps its icon, which drag and drop shows; what the list draws is
    the pixmap under THUMBNAIL_PIXMAP_ROLE, in the icon's place.

    Above the page go the headers of the outline's sections that start on
    it (6.9); a page whose section is folded shows its headers only.
    """

    def _bands(self, index: Any) -> tuple[list[PageSectionBand], bool]:
        listing = self.parent()
        bands = getattr(listing, "section_bands", {}).get(index.row(), [])
        return bands, index.row() in getattr(listing, "headers_only", ())

    def sizeHint(self, option: QStyleOptionViewItem, index: Any) -> QSize:  # noqa: N802 - Qt's name
        size = super().sizeHint(option, index)
        bands, headers_only = self._bands(index)
        if not bands:
            return size
        height = len(bands) * SECTION_BAND_HEIGHT
        return QSize(size.width(), height + 2 if headers_only else size.height() + height)

    def _paint_band(
        self, painter: QPainter, option: QStyleOptionViewItem, rect: QRect, band: PageSectionBand
    ) -> None:
        """PowerPoint's section header: a triangle that says whether it is
        open, the name, and when folded the number of pages in it. The
        section being read is in the accent."""
        painter.save()
        painter.setRenderHint(QPainter.Antialiasing, True)
        right_to_left = option.direction == Qt.RightToLeft
        color = QColor(COLORS["accent"]) if band.here else option.palette.color(QPalette.Text)
        indent = 4 + (band.level - 1) * SECTION_INDENT
        middle = rect.center().y() + 0.5
        start = rect.right() - indent if right_to_left else rect.left() + indent
        way = -1 if right_to_left else 1
        painter.setPen(Qt.NoPen)
        painter.setBrush(color)
        if band.folded:
            # Pointing along the line: there is more inside.
            points = [
                QPointF(start + way * 2, middle - 4.5),
                QPointF(start + way * 7, middle),
                QPointF(start + way * 2, middle + 4.5),
            ]
        else:
            # PowerPoint's open section: a corner pointing down.
            points = [
                QPointF(start + way * 7.5, middle - 3.5),
                QPointF(start + way * 7.5, middle + 3.5),
                QPointF(start + way * 0.5, middle + 3.5),
            ]
        painter.drawPolygon(QPolygonF(points))
        font = QFont(option.font)
        font.setBold(True)
        painter.setFont(font)
        painter.setPen(color)
        text = band.title + (f" ({band.pages})" if band.folded else "")
        area = QRect(rect)
        if right_to_left:
            area.setRight(rect.right() - indent - 12)
            area.setLeft(rect.left() + 4)
        else:
            area.setLeft(rect.left() + indent + 12)
            area.setRight(rect.right() - 4)
        painter.drawText(
            area,
            Qt.AlignVCenter | (Qt.AlignRight if right_to_left else Qt.AlignLeft),
            QFontMetrics(font).elidedText(text, Qt.ElideRight, max(0, area.width())),
        )
        painter.restore()

    def paint(self, painter: QPainter, option: QStyleOptionViewItem, index: Any) -> None:
        bands, headers_only = self._bands(index)
        if bands:
            option = QStyleOptionViewItem(option)
            for number, band in enumerate(bands):
                rect = QRect(
                    option.rect.left(),
                    option.rect.top() + number * SECTION_BAND_HEIGHT,
                    option.rect.width(),
                    SECTION_BAND_HEIGHT,
                )
                self._paint_band(painter, option, rect, band)
            if headers_only:
                return
            option.rect = option.rect.adjusted(0, len(bands) * SECTION_BAND_HEIGHT, 0, 0)
        pixmap = index.data(THUMBNAIL_PIXMAP_ROLE)
        if not isinstance(pixmap, QPixmap) or pixmap.isNull():
            super().paint(painter, option, index)
            return
        item_option = QStyleOptionViewItem(option)
        self.initStyleOption(item_option, index)
        # The icon keeps its place in the layout, with nothing drawn there.
        item_option.icon = QIcon()
        item_option.features |= QStyleOptionViewItem.HasDecoration
        widget = item_option.widget
        style = widget.style() if widget is not None else QApplication.style()
        style.drawControl(QStyle.CE_ItemViewItem, item_option, painter, widget)
        area = style.subElementRect(QStyle.SE_ItemViewItemDecoration, item_option, widget)
        size = pixmap.deviceIndependentSize()
        painter.drawPixmap(
            QPointF(
                area.x() + (area.width() - size.width()) / 2,
                area.y() + (area.height() - size.height()) / 2,
            ),
            pixmap,
        )


class ThumbnailListWidget(QListWidget):
    """Page-thumbnail list supporting PowerPoint-style drag-and-drop
    reordering. Hooked at the drop event rather than a model signal, since
    QListWidget's built-in InternalMove drop goes through remove+insert
    (rowsRemoved/rowsInserted), not a true moveRows (rowsMoved) call."""

    pageReordered = Signal(int)
    # A section header (6.9) clicked: its key (see outline_sections).
    sectionClicked = Signal(int)

    def __init__(self) -> None:
        super().__init__()
        self._dragged_page_index: int | None = None
        # The outline's sections (6.9): the headers above each row, the
        # rows that show their headers only, and the rows folded away.
        self.section_bands: dict[int, list[PageSectionBand]] = {}
        self.headers_only: set[int] = set()
        self._section_layout: tuple = ()
        self.setItemDelegate(ThumbnailDelegate(self))

    def set_sections(
        self, bands: dict[int, list[PageSectionBand]], headers_only: set[int], hidden: set[int]
    ) -> None:
        self.section_bands = bands
        self.headers_only = headers_only
        for row in range(self.count()):
            if self.isRowHidden(row) != (row in hidden):
                self.setRowHidden(row, row in hidden)
        # Heights change only when headers come or go, or a page folds.
        layout = (
            tuple((row, len(row_bands)) for row, row_bands in sorted(bands.items())),
            tuple(sorted(headers_only)),
            self.count(),
        )
        if layout != self._section_layout:
            self._section_layout = layout
            self.scheduleDelayedItemsLayout()
        self.viewport().update()

    def section_rect(self, row: int, number: int) -> QRect:
        """Where header `number` of `row` is, in the viewport."""
        rect = self.visualRect(self.model().index(row, 0))
        return QRect(
            rect.left(), rect.top() + number * SECTION_BAND_HEIGHT, rect.width(), SECTION_BAND_HEIGHT
        )

    def section_at(self, position: QPoint) -> PageSectionBand | None:
        index = self.indexAt(position)
        if not index.isValid():
            return None
        bands = self.section_bands.get(index.row(), [])
        offset = position.y() - self.visualRect(index).top()
        if 0 <= offset < len(bands) * SECTION_BAND_HEIGHT:
            return bands[offset // SECTION_BAND_HEIGHT]
        return None

    def mousePressEvent(self, event: Any) -> None:  # noqa: N802 - Qt's name
        # A header folds its section; it is not the page below it.
        band = self.section_at(event.position().toPoint())
        if band is not None:
            if event.button() == Qt.LeftButton:
                self.sectionClicked.emit(band.key)
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event: Any) -> None:  # noqa: N802 - Qt's name
        if self.section_at(event.position().toPoint()) is not None:
            event.accept()
            return
        super().mouseDoubleClickEvent(event)

    def startDrag(self, supported_actions: Qt.DropActions) -> None:
        item = self.currentItem()
        self._dragged_page_index = item.data(Qt.UserRole) if item is not None else None
        super().startDrag(supported_actions)

    def dropEvent(self, event: Any) -> None:
        super().dropEvent(event)
        dragged = self._dragged_page_index
        self._dragged_page_index = None
        if isinstance(dragged, int):
            self.pageReordered.emit(dragged)


class TextBoxMoveHandle(QLabel):
    moveRequested = Signal(QPoint)
    moveFinished = Signal()

    def __init__(self, parent: QWidget, label: str | None = None) -> None:
        super().__init__(label if label is not None else tr("⋮⋮  テキスト ボックス"), parent)
        self._last_global: QPointF | None = None
        self.setCursor(Qt.SizeAllCursor)
        self.setStyleSheet(
            "background:#D94B45; color:white; font-size:10px; font-weight:600; padding:1px 5px;"
        )

    def mousePressEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton:
            self._last_global = event.globalPosition()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: Any) -> None:
        if self._last_global is not None and event.buttons() & Qt.LeftButton:
            current = event.globalPosition()
            delta = current - self._last_global
            self._last_global = current
            self.moveRequested.emit(QPoint(round(delta.x()), round(delta.y())))
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton and self._last_global is not None:
            self._last_global = None
            self.moveFinished.emit()
            event.accept()
            return
        super().mouseReleaseEvent(event)


class OverlayResizeHandle(QFrame):
    resizeRequested = Signal(str, QPoint)
    resizeFinished = Signal()

    CURSORS = {
        "nw": Qt.SizeFDiagCursor,
        "n": Qt.SizeVerCursor,
        "ne": Qt.SizeBDiagCursor,
        "e": Qt.SizeHorCursor,
        "se": Qt.SizeFDiagCursor,
        "s": Qt.SizeVerCursor,
        "sw": Qt.SizeBDiagCursor,
        "w": Qt.SizeHorCursor,
    }

    def __init__(self, parent: QWidget, direction: str) -> None:
        super().__init__(parent)
        self.direction = direction
        self._last_global: QPointF | None = None
        self.setFixedSize(10, 10)
        self.setCursor(self.CURSORS[direction])
        self.setStyleSheet(
            "background:#FFFFFF; border:2px solid #D94B45; border-radius:1px;"
        )

    def mousePressEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton:
            self._last_global = event.globalPosition()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: Any) -> None:
        if self._last_global is not None and event.buttons() & Qt.LeftButton:
            current = event.globalPosition()
            delta = current - self._last_global
            self._last_global = current
            self.resizeRequested.emit(
                self.direction, QPoint(round(delta.x()), round(delta.y()))
            )
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton and self._last_global is not None:
            self._last_global = None
            self.resizeFinished.emit()
            event.accept()
            return
        super().mouseReleaseEvent(event)


class LineEndpointHandle(QFrame):
    """A PowerPoint-style free endpoint handle for lines and arrows."""

    moved = Signal(int, QPoint)
    moveFinished = Signal()

    def __init__(self, parent: QWidget, endpoint_index: int, is_head: bool) -> None:
        super().__init__(parent)
        self.endpoint_index = endpoint_index
        self.is_head = is_head
        self._last_global: QPointF | None = None
        self.setFixedSize(14, 14)
        self.setCursor(Qt.CrossCursor)
        self.setToolTip(tr("ドラッグして矢印の先端を移動") if is_head else tr("ドラッグして線の始点を移動"))
        self.set_color(QColor(COLORS["accent"]))

    def set_color(self, color: QColor) -> None:
        background = color.name() if self.is_head else "#FFFFFF"
        border = "#FFFFFF" if self.is_head else color.name()
        self.setStyleSheet(
            f"background:{background}; border:2px solid {border}; border-radius:7px;"
        )

    def mousePressEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton:
            self._last_global = event.globalPosition()
            self.grabMouse()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: Any) -> None:
        if self._last_global is not None and event.buttons() & Qt.LeftButton:
            current = event.globalPosition()
            delta = current - self._last_global
            self._last_global = current
            self.moved.emit(
                self.endpoint_index, QPoint(round(delta.x()), round(delta.y()))
            )
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton and self._last_global is not None:
            self._last_global = None
            self.releaseMouse()
            self.moveFinished.emit()
            event.accept()
            return
        super().mouseReleaseEvent(event)


class ShapeRotationHandle(QFrame):
    """PowerPoint-style rotation handle positioned above a selected shape."""

    rotated = Signal(float)
    rotationFinished = Signal()

    def __init__(self, parent: QWidget) -> None:
        super().__init__(parent)
        self._last_angle: float | None = None
        self._rotation_center_global = QPoint()
        self.setFixedSize(16, 16)
        self.setCursor(Qt.CrossCursor)
        self.setToolTip(tr("ドラッグして図形を回転"))
        self.setStyleSheet(
            "background:#64C466; border:2px solid #FFFFFF; border-radius:8px;"
        )

    def _angle_at(self, global_position: QPointF) -> float:
        center = self._rotation_center_global
        return math.degrees(
            math.atan2(global_position.y() - center.y(), global_position.x() - center.x())
        )

    def set_rotation_center(self, global_point: QPoint) -> None:
        self._rotation_center_global = QPoint(global_point)

    def mousePressEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton:
            self._last_angle = self._angle_at(event.globalPosition())
            self.grabMouse()
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: Any) -> None:
        if self._last_angle is not None and event.buttons() & Qt.LeftButton:
            current = self._angle_at(event.globalPosition())
            delta = (current - self._last_angle + 180.0) % 360.0 - 180.0
            self._last_angle = current
            self.rotated.emit(delta)
            event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton and self._last_angle is not None:
            self._last_angle = None
            self.releaseMouse()
            self.rotationFinished.emit()
            event.accept()
            return
        super().mouseReleaseEvent(event)


# The frame round each item of a selection on the page (6.24).
SELECTION_FRAME_COLOR = "#3182F6"


class ResizableCanvasFrame(QFrame):
    geometryEdited = Signal()
    # A right-click on the frame or a handle, where on the screen: the
    # window opens the held object's menu, the one its page shows (6.20).
    menuRequested = Signal(QPoint)

    def __init__(
        self,
        parent: QWidget,
        minimum_size: QSize,
        lock_corner_aspect: bool = False,
    ) -> None:
        super().__init__(parent)
        self.setMinimumSize(minimum_size)
        self.lock_corner_aspect = lock_corner_aspect
        # The frame as a corner drag last left it, and the proportions it
        # keeps (_resize_by).
        self._corner_drag: tuple[QRect, float] | None = None
        self.resize_handles: dict[str, OverlayResizeHandle] = {}
        for direction in ("nw", "n", "ne", "e", "se", "s", "sw", "w"):
            handle = OverlayResizeHandle(self, direction)
            handle.resizeRequested.connect(self._resize_by)
            handle.resizeFinished.connect(self.geometryEdited)
            self.resize_handles[direction] = handle

    # Pixels between the frame's edges and what it holds, where it has no
    # content widget to measure them from (content_insets).
    CONTENT_INSETS: tuple[int, int, int, int] = (0, 0, 0, 0)

    def content_widget(self) -> QWidget | None:
        """The child whose rectangle maps 1:1 onto the PDF rectangle.

        None means the frame has no such child (a shape box only outlines
        something painted on the canvas below it).
        """
        return None

    def content_insets(self, fallback: tuple[int, int, int, int]) -> tuple[int, int, int, int]:
        """Pixels between this frame's edges and its content widget.

        Measured from the live layout rather than assumed. The frame's
        stylesheet border stacks on top of the QVBoxLayout margin, so the
        image preview really sits 4px in and is 8px narrower than the frame
        -- not the 2px/4px the placement code used to hard-code. Writing the
        geometry with one set of numbers and reading it back with another
        made every resync (each drag, handle resize or keyboard nudge) shrink
        the image by 4px and push it 2px down-right, and it accumulated.
        """
        content = self.content_widget()
        if content is None:
            return fallback
        layout = self.layout()
        if layout is not None:
            layout.activate()
        geometry = content.geometry()
        if geometry.width() <= 0 or geometry.height() <= 0:
            return fallback
        return (
            geometry.x(),
            geometry.y(),
            self.width() - geometry.x() - geometry.width(),
            self.height() - geometry.y() - geometry.height(),
        )

    def _resize_by(self, direction: str, delta: QPoint) -> None:
        geometry = self.geometry()
        left, top = geometry.x(), geometry.y()
        right, bottom = left + geometry.width(), top + geometry.height()
        minimum_width = self.minimumWidth()
        minimum_height = self.minimumHeight()
        parent = self.parentWidget()
        maximum_width = parent.width() if parent is not None else right + abs(delta.x())
        maximum_height = parent.height() if parent is not None else bottom + abs(delta.y())

        if "w" in direction:
            left += delta.x()
        if "e" in direction:
            right += delta.x()
        if "n" in direction:
            top += delta.y()
        if "s" in direction:
            bottom += delta.y()

        # A picture always keeps its proportions at a corner; a shape does
        # while Shift is held, as in PowerPoint (6.12). The proportions are
        # those of what the frame holds: counted with its title bar and
        # border, a small picture taken by a corner came out taller than it
        # was -- a 3:2 picture held at 53% became 4:3 (6.27).
        corner_kept = (self.lock_corner_aspect or keyboard_shift_held()) and len(direction) == 2
        if corner_kept:
            inset_left, inset_top, inset_right, inset_bottom = self.content_insets(self.CONTENT_INSETS)
            extra_width, extra_height = inset_left + inset_right, inset_top + inset_bottom
            # The proportions it had when the corner was taken, for the
            # whole drag: worked out again from the size rounded at every
            # step, they drifted -- a thin picture came out 8% shorter
            # after four steps of the mouse (6.27).
            if self._corner_drag is not None and self._corner_drag[0] == geometry:
                ratio = self._corner_drag[1]
            else:
                ratio = max(
                    0.05, (geometry.width() - extra_width) / max(1, geometry.height() - extra_height)
                )
            requested_width = max(minimum_width, right - left) - extra_width
            requested_height = max(minimum_height, bottom - top) - extra_height
            if abs(delta.x()) >= abs(delta.y()):
                requested_height = round(requested_width / ratio)
            else:
                requested_width = round(requested_height * ratio)
            requested_width = max(minimum_width, requested_width + extra_width)
            requested_height = max(minimum_height, requested_height + extra_height)
            if "w" in direction:
                left = right - requested_width
            else:
                right = left + requested_width
            if "n" in direction:
                top = bottom - requested_height
            else:
                bottom = top + requested_height

        left = max(0, min(left, right - minimum_width))
        top = max(0, min(top, bottom - minimum_height))
        right = min(maximum_width, max(right, left + minimum_width))
        bottom = min(maximum_height, max(bottom, top + minimum_height))
        if "w" in direction and right - left < minimum_width:
            left = right - minimum_width
        if "n" in direction and bottom - top < minimum_height:
            top = bottom - minimum_height
        left, top = max(0, left), max(0, top)
        self.setGeometry(left, top, max(minimum_width, right - left), max(minimum_height, bottom - top))
        self._corner_drag = (QRect(self.geometry()), ratio) if corner_kept else None
        self.geometryEdited.emit()

    def _position_resize_handles(self) -> None:
        half = 5
        positions = {
            "nw": QPoint(half, half),
            "n": QPoint(self.width() // 2, half),
            "ne": QPoint(self.width() - half, half),
            "e": QPoint(self.width() - half, self.height() // 2),
            "se": QPoint(self.width() - half, self.height() - half),
            "s": QPoint(self.width() // 2, self.height() - half),
            "sw": QPoint(half, self.height() - half),
            "w": QPoint(half, self.height() // 2),
        }
        for direction, point in positions.items():
            handle = self.resize_handles[direction]
            handle.move(point.x() - half, point.y() - half)
            handle.raise_()

    def resizeEvent(self, event: Any) -> None:
        super().resizeEvent(event)
        self._position_resize_handles()
        self.geometryEdited.emit()

    def mousePressEvent(self, event: Any) -> None:
        # A right press opens the held object's menu, as one on the page
        # does. Left to the page under it, in continuous scrolling it found
        # none: the frame stands over the column of pages there (6.16), and
        # no menu opened (6.20). A handle hands its press on to here.
        if event.button() == Qt.RightButton:
            self.menuRequested.emit(event.globalPosition().toPoint())
            event.accept()
            return
        super().mousePressEvent(event)

    def contextMenuEvent(self, event: Any) -> None:
        # The press has opened it already; the menu key has not.
        if event.reason() != QContextMenuEvent.Mouse:
            self.menuRequested.emit(event.globalPos())
        event.accept()


# Curated, free-to-use text-box fonts. Each is either genuinely fixed-pitch
# (identical advance width per half-width character, identical again per
# full-width character, no kerning) or at least ships a real, separately
# drawn bold weight file rather than a synthesized/emboldened fake one --
# picking any of these fixes bold looking almost the same as regular.
# Ordered by preference; filtered at startup to whatever the running
# machine's C:/Windows/Fonts actually has, so an unusual Windows install
# missing one candidate still gets a working, if shorter, list.
# (display name, Qt font family, regular filename, bold filename or None)
_TEXT_BOX_FONT_CANDIDATES: list[tuple[str, str, str, str | None]] = [
    ("BIZ UDゴシック", "BIZ UDGothic", "BIZ-UDGothicR.ttc", "BIZ-UDGothicB.ttc"),
    ("游ゴシック", "Yu Gothic", "YuGothR.ttc", "YuGothB.ttc"),
    ("メイリオ", "Meiryo", "meiryo.ttc", "meiryob.ttc"),
    ("MS ゴシック", "MS Gothic", "msgothic.ttc", None),
    # Mincho (serif). No Windows-bundled Mincho ships a genuine bold weight
    # file (checked BIZ UDMincho, MS Mincho, Yu Mincho), so bold here falls
    # back to the OS's synthesized emboldening. BIZ UDMincho is genuinely
    # fixed-pitch, unlike MS Mincho/Yu Mincho.
    ("BIZ UD明朝", "BIZ UDMincho", "BIZ-UDMinchoM.ttc", None),
    ("Consolas", "Consolas", "consola.ttf", "consolab.ttf"),
]


def _windows_fonts_dir() -> Path:
    return Path(os.environ.get("WINDIR", "C:/Windows")) / "Fonts"


# Fonts installed for one user only (Windows 10 1809 and later) live in the
# user's own folder; a text box names them "user/<file>" (6.3).
USER_FONT_PREFIX = "user/"


def _user_fonts_dir() -> Path | None:
    base = os.environ.get("LOCALAPPDATA")
    return Path(base) / "Microsoft" / "Windows" / "Fonts" if base else None


def text_box_font_path(name: str) -> Path:
    """The file of a text-box font named as TEXT_BOX_FONTS names it."""
    if name.startswith(USER_FONT_PREFIX):
        folder = _user_fonts_dir() or Path(".")
        return folder / name[len(USER_FONT_PREFIX):]
    return _windows_fonts_dir() / name


def text_box_font_archive() -> fitz.Archive:
    """Where insert_htmlbox finds the text-box fonts: the Windows folder,
    and the user's own under "user/"."""
    archive = fitz.Archive(str(_windows_fonts_dir()))
    user = _user_fonts_dir()
    if user is not None and user.is_dir():
        archive.add(str(user), path=USER_FONT_PREFIX.rstrip("/"))
    return archive


def _font_embedding_allowed(path: Path) -> bool:
    """May this font be embedded in a document? pdfNote embeds the text-box
    fonts in the PDFs it saves, and the Windows licence allows that only as
    permitted by the embedding restrictions in the fonts -- the OS/2 table's
    fsType (OpenType spec). Bits 0-3 alone equal to 2 is "Restricted License
    embedding" (must not be embedded); 0x0200 allows bitmaps only. Every
    face of a collection (.ttc) has to allow it. Reads a few bytes, not the
    whole file: the collections are tens of megabytes."""
    try:
        with open(path, "rb") as handle:

            def read(offset: int, size: int) -> bytes:
                handle.seek(offset)
                data = handle.read(size)
                if len(data) != size:
                    raise ValueError("truncated font file")
                return data

            bases = [0]
            if read(0, 4) == b"ttcf":
                count = struct.unpack(">I", read(8, 4))[0]
                bases = list(struct.unpack(f">{count}I", read(12, 4 * count)))
            found = False
            for base in bases:
                tables = struct.unpack(">H", read(base + 4, 2))[0]
                directory = read(base + 12, 16 * tables)
                for index in range(tables):
                    entry = directory[16 * index : 16 * index + 16]
                    if entry[:4] != b"OS/2":
                        continue
                    found = True
                    offset = struct.unpack(">I", entry[8:12])[0]
                    fs_type = struct.unpack(">H", read(offset + 8, 2))[0]
                    if (fs_type & 0x000F) == 0x0002 or fs_type & 0x0200:
                        return False
            return found
    except (OSError, ValueError, struct.error):
        return False


def _available_text_box_fonts() -> dict[str, tuple[str, str, str | None]]:
    fonts_dir = _windows_fonts_dir()
    available: dict[str, tuple[str, str, str | None]] = {}
    for display, family, regular, bold in _TEXT_BOX_FONT_CANDIDATES:
        if (fonts_dir / regular).exists() and _font_embedding_allowed(fonts_dir / regular):
            bold_path = (
                bold
                if bold
                and (fonts_dir / bold).exists()
                and _font_embedding_allowed(fonts_dir / bold)
                else None
            )
            available[display] = (family, regular, bold_path)
    return available


TEXT_BOX_FONTS = _available_text_box_fonts()
# The fonts the right-click menus offer -- the ones above and the common
# ones below; the toolbar's list has every font (6.3).
MAIN_TEXT_BOX_FONT_KEYS: set[str] = set(TEXT_BOX_FONTS)
# Japanese names of the fonts added from what is installed, for the
# Japanese UI; the six above are keyed by theirs.
TEXT_BOX_FONT_LABELS_JA: dict[str, str] = {}
# Fonts most people look for, by family, offered first after the six above
# when the PC has them.
_COMMON_TEXT_BOX_FAMILIES = (
    "Yu Mincho", "MS Mincho", "UD Digi Kyokasho N-R", "UD Digi Kyokasho NK-R",
    "Noto Sans JP", "Noto Serif JP", "Arial", "Times New Roman", "Calibri",
    "Cambria", "Century", "Century Gothic", "Segoe UI", "Georgia", "Verdana",
    "Tahoma", "Courier New",
)
_TEXT_BOX_FONTS_EXTENDED = False


def _font_face_summary(path: Path) -> dict[str, Any] | None:
    """What face 0 of a font file is: its family names (English and
    Japanese), weight, whether it is italic, and whether it has a Unicode
    character map or is a symbol font. Face 0 because that is the face
    insert_htmlbox takes from a file. Reads its tables' directory and three
    small tables, not the file."""
    try:
        with open(path, "rb") as handle:

            def read(offset: int, size: int) -> bytes:
                handle.seek(offset)
                data = handle.read(size)
                if len(data) != size:
                    raise ValueError("truncated font file")
                return data

            base = 0
            if read(0, 4) == b"ttcf":
                base = struct.unpack(">I", read(12, 4))[0]
            if read(base, 4) not in (b"\x00\x01\x00\x00", b"OTTO", b"true"):
                return None
            count = struct.unpack(">H", read(base + 4, 2))[0]
            directory = read(base + 12, 16 * count)
            tables: dict[bytes, tuple[int, int]] = {}
            for index in range(count):
                entry = directory[16 * index:16 * index + 16]
                tables[entry[:4]] = struct.unpack(">II", entry[8:16])
            if not all(tag in tables for tag in (b"name", b"OS/2", b"cmap")):
                return None
            offset, length = tables[b"name"]
            name_table = read(offset, min(length, 1 << 20))
            _format, records, strings = struct.unpack(">HHH", name_table[:6])
            names: dict[tuple[int, int], str] = {}
            for index in range(records):
                platform, encoding, language, name_id, size, at = struct.unpack(
                    ">HHHHHH", name_table[6 + 12 * index:18 + 12 * index]
                )
                if platform != 3 or encoding not in (1, 10) or name_id not in (1, 2, 16, 17):
                    continue
                raw = name_table[strings + at:strings + at + size]
                try:
                    names[(name_id, language)] = raw.decode("utf-16-be")
                except UnicodeDecodeError:
                    continue
            os2 = tables[b"OS/2"][0]
            weight = struct.unpack(">H", read(os2 + 4, 2))[0]
            selection = struct.unpack(">H", read(os2 + 62, 2))[0]
            cmap = tables[b"cmap"][0]
            subtables = struct.unpack(">H", read(cmap + 2, 2))[0]
            encodings = {
                struct.unpack(">HH", read(cmap + 4 + 8 * index, 4)) for index in range(subtables)
            }

            def named(name_id: int, language: int | None) -> str | None:
                if language is not None:
                    return names.get((name_id, language))
                return next((text for (key, _l), text in sorted(names.items()) if key == name_id), None)

            legacy = named(1, 0x0409) or named(1, None)
            family = named(16, 0x0409) or named(16, None) or legacy
            if not family:
                return None
            return {
                "family": family,
                "legacy": legacy or family,
                "family_ja": named(16, 0x0411) or named(1, 0x0411),
                "weight": weight,
                "italic": bool(selection & 0x0001),
                "bold": bool(selection & 0x0020),
                "symbol": (3, 0) in encodings,
                "unicode": bool({(3, 1), (3, 10), (0, 3), (0, 4)} & encodings),
            }
    except (OSError, ValueError, struct.error):
        return None


def installed_text_box_fonts(
    known_families: set[str],
) -> list[tuple[str, str, str | None, str | None]]:
    """The fonts installed on this PC that a text box can use: (family as
    Qt knows it, regular file, bold file or None, Japanese name or None),
    files named as TEXT_BOX_FONTS names them.

    A font is offered when Qt draws it under that family name (so the box
    looks while typing as it does on the page), it has Unicode characters
    (symbol fonts do not), and its licence allows embedding (see
    _font_embedding_allowed). Only the first face of a collection can be
    used, so the faces after it -- MS PGothic, Meiryo UI -- are not."""
    faces: dict[str, list[tuple[str, dict[str, Any]]]] = {}
    for prefix, folder in (("", _windows_fonts_dir()), (USER_FONT_PREFIX, _user_fonts_dir())):
        if folder is None:
            continue
        try:
            files = sorted(folder.iterdir())
        except OSError:
            continue
        for path in files:
            if path.suffix.lower() not in (".ttf", ".ttc", ".otf"):
                continue
            face = _font_face_summary(path)
            if face is None or face["symbol"] or not face["unicode"] or face["italic"]:
                continue
            family = next(
                (name for name in (face["family"], face["legacy"]) if name in known_families), None
            )
            if family is not None:
                faces.setdefault(family, []).append((prefix + path.name, face))
    found: list[tuple[str, str, str | None, str | None]] = []
    for family, entries in faces.items():
        regular_name, regular = min(
            entries, key=lambda item: (abs(item[1]["weight"] - 400), item[1]["bold"], item[0])
        )
        if not _font_embedding_allowed(text_box_font_path(regular_name)):
            continue
        heavier = [
            item for item in entries
            if item[0] != regular_name and (item[1]["bold"] or item[1]["weight"] >= 600)
        ]
        bold_name = None
        if heavier and regular["weight"] < 600:
            candidate = min(heavier, key=lambda item: (abs(item[1]["weight"] - 700), item[0]))[0]
            if _font_embedding_allowed(text_box_font_path(candidate)):
                bold_name = candidate
        found.append((family, regular_name, bold_name, regular["family_ja"]))
    return found


def extend_text_box_fonts() -> None:
    """Add the fonts installed on this PC to TEXT_BOX_FONTS, once, after
    the six chosen ones: the common ones next, then the rest by name. Only
    the six were offered, and only from the Windows folder (6.3). Needs the
    QApplication, which knows what Qt can draw."""
    global _TEXT_BOX_FONTS_EXTENDED
    if _TEXT_BOX_FONTS_EXTENDED or QGuiApplication.instance() is None:
        return
    _TEXT_BOX_FONTS_EXTENDED = True
    known = set(QFontDatabase.families())
    present = {family for family, _regular, _bold in TEXT_BOX_FONTS.values()}
    found = {
        family: (regular, bold, japanese)
        for family, regular, bold, japanese in installed_text_box_fonts(known)
        if family not in present
    }
    common = [family for family in _COMMON_TEXT_BOX_FAMILIES if family in found]
    rest = sorted((family for family in found if family not in common), key=str.casefold)
    for family in (*common, *rest):
        regular, bold, japanese = found[family]
        TEXT_BOX_FONTS[family] = (family, regular, bold)
        if japanese and japanese != family:
            TEXT_BOX_FONT_LABELS_JA[family] = japanese
    MAIN_TEXT_BOX_FONT_KEYS.update(common)
# Fall back to the previous hardcoded font if none of the curated
# candidates exist on this machine at all (very old/stripped-down Windows).
# DEFAULT_TEXT_BOX_FONT is the *display* name (combo box item / dict key,
# also what's persisted); DEFAULT_TEXT_BOX_QT_FAMILY is the actual Qt font
# family it resolves to (what CanvasTextBox puts directly into CSS).
DEFAULT_TEXT_BOX_FONT = next(iter(TEXT_BOX_FONTS), "Yu Gothic UI")
DEFAULT_TEXT_BOX_QT_FAMILY = TEXT_BOX_FONTS.get(
    DEFAULT_TEXT_BOX_FONT, (DEFAULT_TEXT_BOX_FONT, "", None)
)[0]


# ---- one layout for the editor and the page (1.0.0) ------------------------
#
# A text box is typed into a QTextEdit and committed as page content that
# MuPDF lays out from HTML (insert_htmlbox). The two did not look alike.
# MuPDF puts lines 1.2 em apart with the baseline 0.8 em plus half the
# leading down, whatever the font, where Qt uses each font's own ascent and
# descent (Meiryo's lines are 1.5 em apart); MuPDF's default body margin
# moved the text 1pt; and Qt draws text at whole pixels only, so at a zoom
# that makes 10.5 pt 13.35 px it laid out 13 px text and broke the lines
# elsewhere. So both are laid out the same way on purpose:
# - in the editor, every paragraph has a fixed line height (below) times its
#   largest size, which Qt fills with the baseline at 0.8 of it; the glyphs
#   are spaced to their exact size; there are no margins;
# - on the page, pdfNote writes the HTML itself: no body margin, every
#   paragraph at its own size and padded down to where Qt has its baseline,
#   and the lines broken where the editor broke them.
# The lines are 1.2 em apart, as every pdfNote up to 5.40 put them on the
# page: the line height and the paragraph gap below add up to that. (1.2 of
# line height made them 1.26 em apart, and a box made by 5.40 no longer held
# its own text.) Any line height from 1.0 up keeps editor and page together;
# below 1.0 the gap would have to be negative.
TEXT_BOX_LINE_PITCH = 1.2
TEXT_BOX_LINE_HEIGHT = (TEXT_BOX_LINE_PITCH + 0.3) / 1.3
# Where each puts the first baseline, per em of the paragraph's size: Qt 0.8
# of the line height, MuPDF 0.8 em plus half the leading. The page pads each
# paragraph by the difference, and the editor leaves the same space below.
TEXT_BOX_PARAGRAPH_GAP = 0.8 * TEXT_BOX_LINE_HEIGHT - (0.8 + (TEXT_BOX_LINE_HEIGHT - 1) / 2)
# A run's size in PDF points, kept on its format; the editor shows it scaled.
TEXT_BOX_SIZE = QTextFormat.UserProperty + 11
# Tab stops every four characters of the box's size, as Word's in Japanese
# are (6.20). Qt's own were every 80 screen pixels: 60pt at 100 %, 30pt at
# 200 %, so a box's tabs moved with the zoom.
TEXT_BOX_TAB_EMS = 4.0


def text_box_set_tabs(document: QTextDocument, size: float, scale: float) -> None:
    """The box's tab stops on its document, laid out at `scale`."""
    option = document.defaultTextOption()
    option.setTabStopDistance(TEXT_BOX_TAB_EMS * size * scale)
    document.setDefaultTextOption(option)


_FIXED_LINE_HEIGHT = QTextBlockFormat.FixedHeight.value


def text_box_font_key(qt_family: str) -> str:
    """The name a text-box font is stored under, from Qt's family name."""
    return next(
        (key for key, (family, _regular, _bold) in TEXT_BOX_FONTS.items() if family == qt_family),
        DEFAULT_TEXT_BOX_FONT,
    )


def text_box_run_format(size: float, scale: float) -> QTextCharFormat:
    """A run of `size` points as the editor shows it, `scale` pixels to the point.

    Qt draws text at whole pixels only: the glyphs get the nearest whole
    size and their advances are spaced to the exact one, so every line is
    as long as MuPDF makes it and breaks in the same place.
    """
    target = max(0.25, float(size) * scale)
    pixels = max(1, round(target))
    fmt = QTextCharFormat()
    fmt.setProperty(TEXT_BOX_SIZE, float(size))
    fmt.setProperty(QTextFormat.FontPixelSize, pixels)
    fmt.setFontLetterSpacingType(QFont.PercentageSpacing)
    fmt.setFontLetterSpacing(100.0 * target / pixels)
    fmt.setFontHintingPreference(QFont.PreferNoHinting)
    return fmt


def text_box_font(family: str, size: float, scale: float) -> QFont:
    fmt = text_box_run_format(size, scale)
    fmt.setFontFamilies([family])
    return fmt.font()


def text_box_run_size(fmt: QTextCharFormat, default: float) -> float:
    value = fmt.property(TEXT_BOX_SIZE)
    return float(value) if isinstance(value, (int, float)) and value > 0 else default


def text_box_run_family(fmt: QTextCharFormat, default: str) -> str:
    families = fmt.fontFamilies() if fmt.hasProperty(QTextFormat.FontFamilies) else None
    if isinstance(families, (list, tuple)) and families and families[0]:
        return str(families[0])
    return default


def _text_box_stored_size(fmt: QTextCharFormat, default: float) -> float:
    """The size of a run just read from stored HTML, in points.

    Every pdfNote wrote those sizes in PDF points -- as px before 1.0.0, as
    pt since; MuPDF reads both as points. Qt keeps a px size as a whole
    number, so a 10.5 box read back as 10: within a point of the box's own
    size means the box's own size.
    """
    if fmt.hasProperty(QTextFormat.FontPointSize) and fmt.fontPointSize() > 0:
        return float(fmt.fontPointSize())
    pixels = fmt.property(QTextFormat.FontPixelSize)
    if isinstance(pixels, (int, float)) and pixels > 0:
        return default if abs(pixels - default) < 1 else float(pixels)
    return default


def text_box_block_size(block: Any, default: float) -> float:
    """The largest size in a paragraph, which sets its line height."""
    largest = 0.0
    iterator = block.begin()
    while not iterator.atEnd():
        fragment = iterator.fragment()
        if fragment.isValid() and fragment.length():
            largest = max(largest, text_box_run_size(fragment.charFormat(), default))
        iterator += 1
    return largest or text_box_run_size(block.charFormat(), default)


def _text_box_blocks_to_fit(document: QTextDocument, scale: float, default: float) -> list[tuple[int, QTextBlockFormat]]:
    out: list[tuple[int, QTextBlockFormat]] = []
    block = document.begin()
    while block.isValid():
        size = text_box_block_size(block, default)
        height = TEXT_BOX_LINE_HEIGHT * size * scale
        gap = TEXT_BOX_PARAGRAPH_GAP * size * scale
        fmt = block.blockFormat()
        if (
            fmt.lineHeightType() != _FIXED_LINE_HEIGHT
            or abs(fmt.lineHeight() - height) > 1e-3
            or abs(fmt.bottomMargin() - gap) > 1e-3
            or fmt.topMargin() != 0
        ):
            fitted = QTextBlockFormat(fmt)
            fitted.setLineHeight(height, _FIXED_LINE_HEIGHT)
            fitted.setTopMargin(0)
            fitted.setBottomMargin(gap)
            out.append((block.position(), fitted))
        block = block.next()
    return out


def text_box_fit_blocks(document: QTextDocument, scale: float, default: float) -> bool:
    """Give each paragraph the line height and the space below that put its
    lines where the page puts them. True when anything changed."""
    changes = _text_box_blocks_to_fit(document, scale, default)
    cursor = QTextCursor(document)
    for position, fmt in changes:
        cursor.setPosition(position)
        cursor.setBlockFormat(fmt)
    return bool(changes)


def text_box_normalize(
    document: QTextDocument, size: float, color: QColor, family: str, scale: float,
    shrink: float = 1.0,
) -> None:
    """Put a document just read from stored HTML (or plain text) into the
    editor's form: each run's size kept in points and shown scaled, its font
    and colour written out, each paragraph laid out as on the page.

    `size` is the box's stored size, which a stored run's own size is read
    against; `shrink` is how much smaller than stored the page draws it (a
    box made by 5.40 that did not hold its text), and every size is taken
    down by it, so that the box opens as the page shows it."""
    runs: list[tuple[int, int, QTextCharFormat]] = []
    block = document.begin()
    while block.isValid():
        iterator = block.begin()
        while not iterator.atEnd():
            fragment = iterator.fragment()
            if fragment.isValid() and fragment.length():
                runs.append(
                    (fragment.position(), fragment.length(), QTextCharFormat(fragment.charFormat()))
                )
            iterator += 1
        block = block.next()
    cursor = QTextCursor(document)

    def editor_form(fmt: QTextCharFormat) -> QTextCharFormat:
        run_size = _text_box_stored_size(fmt, size) * shrink
        fmt.clearProperty(QTextFormat.FontPointSize)
        fmt.clearProperty(QTextFormat.FontPixelSize)
        fmt.merge(text_box_run_format(run_size, scale))
        fmt.setFontFamilies([text_box_run_family(fmt, family)])
        if not fmt.hasProperty(QTextFormat.ForegroundBrush):
            fmt.setForeground(QColor(color))
        return fmt

    for position, length, fmt in runs:
        cursor.setPosition(position)
        cursor.setPosition(position + length, QTextCursor.KeepAnchor)
        cursor.setCharFormat(editor_form(fmt))
    block = document.begin()
    while block.isValid():
        cursor.setPosition(block.position())
        cursor.setBlockCharFormat(editor_form(QTextCharFormat(block.charFormat())))
        block = block.next()
    text_box_fit_blocks(document, scale, size * shrink)


def _text_box_span_style(
    fmt: QTextCharFormat, size: float, color: QColor, family: str, families: set[str]
) -> str:
    run_family = text_box_run_family(fmt, family)
    families.add(run_family)
    foreground = fmt.foreground()
    run_color = foreground.color() if foreground.style() != Qt.NoBrush else color
    styles = [
        f"font-family:'{run_family}'",
        f"font-size:{text_box_run_size(fmt, size):g}pt",
        f"color:{run_color.name()}",
    ]
    if fmt.fontWeight() > QFont.Normal:
        styles.append("font-weight:bold")
    if fmt.fontItalic():
        styles.append("font-style:italic")
    decorations = [
        name for name, on in (("underline", fmt.fontUnderline()), ("line-through", fmt.fontStrikeOut()))
        if on
    ]
    if decorations:
        styles.append("text-decoration:" + " ".join(decorations))
    if char_format_highlighted(fmt):
        styles.append(f"background-color:{fmt.background().color().name()}")
    return "; ".join(styles)


def char_format_highlighted(fmt: QTextCharFormat) -> bool:
    """Has this text a highlight? A format without a background brush still
    reports a valid colour (black, the brush's default), so the colour alone
    called every plain character highlighted: the toggle then took away a
    highlight that was not there and could never add one (6.2)."""
    background = fmt.background()
    return background.style() != Qt.NoBrush and background.color().alpha() > 0


def _python_indices(text: str) -> list[int]:
    """Qt positions in `text` (UTF-16 units) as Python indices: an emoji or
    another character beyond U+FFFF is two units to Qt and one character to
    Python. Index i of the list is Qt's position i; the last entry is the
    end of the text."""
    indices: list[int] = []
    for index, character in enumerate(text):
        indices.append(index)
        if ord(character) > 0xFFFF:
            indices.append(index)
    indices.append(len(text))
    return indices


def text_box_html(
    document: QTextDocument, size: float, color: QColor, family: str, lines: bool = False,
    scale: float | None = None,
) -> tuple[str, set[str]]:
    """A text box's HTML, sizes in PDF points, and the fonts it uses.

    Stored with the box, it is read back into the editor. With `lines` it
    is what the page is given: every line of the editor's layout (which
    must be up to date) ends in a break, so MuPDF breaks nowhere else, and
    a line whose text is smaller than its paragraph's largest carries an
    invisible character of that size -- MuPDF sizes each line by the text
    on it, where the editor gives a paragraph one line height.

    MuPDF has no tab stops: it drew a tab as four spaces, so the text after
    one stood far from where the editor had it (6.20). Given the `scale`
    the document is laid out at, a line with tabs is a row of cells, each
    piece of text starting where the editor's layout puts it.
    """
    families = {family}
    alignments = {Qt.AlignHCenter: "center", Qt.AlignRight: "right", Qt.AlignJustify: "justify"}
    parts = [
        "<html><head><meta charset=\"utf-8\"/></head>"
        f"<body style=\"margin:0; padding:0; font-family:'{family}'; font-size:{size:g}pt; "
        f"color:{color.name()}; line-height:{TEXT_BOX_LINE_HEIGHT:g}; "
        f"white-space:{'pre' if lines else 'pre-wrap'};\">"
    ]
    block = document.begin()
    while block.isValid():
        block_size = text_box_block_size(block, size)
        horizontal = block.blockFormat().alignment() & Qt.AlignHorizontal_Mask
        align = next((name for flag, name in alignments.items() if horizontal & flag), "left")
        style = (
            f"margin:0; padding:{TEXT_BOX_PARAGRAPH_GAP * block_size:.4f}pt 0 0 0; "
            f"font-size:{block_size:g}pt; text-align:{align};"
        )
        text = block.text()
        # Qt counts positions in UTF-16 units, Python strings in characters.
        # Mixed, a run after an emoji was cut one character short for each
        # emoji before its end: "😀AB" with AB bold lost the B, on the page
        # and in the box kept for editing (6.2).
        index_of = _python_indices(text)

        def to_index(position: int) -> int:
            return index_of[max(0, min(position, len(index_of) - 1))]

        runs: list[tuple[int, str, QTextCharFormat]] = []
        iterator = block.begin()
        while not iterator.atEnd():
            fragment = iterator.fragment()
            if fragment.isValid() and fragment.length():
                runs.append(
                    (to_index(fragment.position() - block.position()), fragment.text(), fragment.charFormat())
                )
            iterator += 1
        if not text:
            parts.append(f"<p style=\"-qt-paragraph-type:empty; {style}\"><br/></p>")
            block = block.next()
            continue
        spans: list[tuple[int, int]] = [(0, len(text))]
        layout = block.layout()
        if lines and layout is not None and layout.lineCount():
            starts = [to_index(layout.lineAt(i).textStart()) for i in range(layout.lineCount())]
            spans = list(zip(starts, starts[1:] + [len(text)]))
        tabbed = [
            bool(lines and scale and layout is not None and "\t" in text[start:end])
            for start, end in spans
        ]
        # Qt's position of each Python index, for the editor's layout.
        position_of: dict[int, int] = {}
        for position, index in enumerate(index_of):
            position_of.setdefault(index, position)

        def run_pieces(start: int, end: int) -> list[tuple[str, QTextCharFormat]]:
            pieces: list[tuple[str, QTextCharFormat]] = []
            for run_start, run_text, fmt in runs:
                first, last = max(start, run_start), min(end, run_start + len(run_text))
                if first < last:
                    pieces.append((run_text[first - run_start:last - run_start], fmt))
            return pieces

        def spans_of(pieces: list[tuple[str, QTextCharFormat]]) -> str:
            out: list[str] = []
            for piece, fmt in pieces:
                if piece:
                    escaped = html.escape(piece, quote=False).replace("\u2028", "<br/>")
                    style_text = _text_box_span_style(fmt, size, color, family, families)
                    out.append(f"<span style=\"{style_text}\">{escaped}</span>")
            return "".join(out)

        def row(number: int, start: int, end: int) -> str:
            # The pieces between the tabs, each in a cell as wide as the
            # editor has it, so the next starts where the editor's does.
            line = layout.lineAt(number)
            line_end = end - 1 if text[end - 1:end] == "\u2028" else end
            cuts = [index for index in range(start, line_end) if text[index] == "\t"]
            bounds = list(zip([start] + [cut + 1 for cut in cuts], cuts + [line_end]))
            starts = [line.cursorToX(position_of[first])[0] / scale for first, _last in bounds]
            cells: list[str] = []
            if starts[0] > 0.01:
                cells.append(f"<td style=\"padding:0; width:{starts[0]:.3f}pt\"></td>")
            for place, (first, last) in enumerate(bounds):
                # Each cell lays out a line of its own: each is given the
                # paragraph's line height, or one with smaller text sat
                # higher than the rest.
                content = (
                    f"<span style=\"font-size:{block_size:g}pt\">&#8203;</span>"
                    + spans_of(run_pieces(first, last))
                )
                if place + 1 < len(bounds):
                    width = max(0.0, starts[place + 1] - starts[place])
                    cells.append(f"<td style=\"padding:0; width:{width:.3f}pt\">{content}</td>")
                else:
                    cells.append(f"<td style=\"padding:0\">{content}</td>")
            # Left-aligned in their cells: where the line starts already
            # holds the paragraph's alignment.
            return (
                "<table style=\"border-collapse:collapse; border-spacing:0; margin:0; "
                f"text-align:left; font-size:{block_size:g}pt\"><tr>{''.join(cells)}</tr></table>"
            )

        # Lines without tabs stay together in a paragraph; a line with them
        # is a block of its own.
        groups: list[tuple[bool, list[str]]] = []
        for number, (start, end) in enumerate(spans):
            if tabbed[number]:
                groups.append((True, [row(number, start, end)]))
                continue
            next_is_row = number + 1 < len(spans) and tabbed[number + 1]
            line_end = end - 1 if next_is_row and text[end - 1:end] == "\u2028" else end
            pieces = run_pieces(start, line_end)
            wrapped = lines and number < len(spans) - 1 and not text[end - 1:end] == "\u2028"
            soft_break = wrapped and not next_is_row
            if wrapped and pieces:
                # The spaces a line was broken at hang past its end in the
                # editor; on the page they would count towards centring.
                trimmed = pieces[-1][0].rstrip(" ")
                pieces[-1] = (trimmed, pieces[-1][1])
            body: list[str] = []
            if lines:
                largest = max(
                    (text_box_run_size(fmt, size) for piece, fmt in pieces if piece.strip()),
                    default=block_size,
                )
                if largest < block_size - 1e-6:
                    body.append(f"<span style=\"font-size:{block_size:g}pt\">&#8203;</span>")
            body.append(spans_of(pieces))
            if soft_break:
                body.append("<br/>")
            if groups and not groups[-1][0]:
                groups[-1][1].append("".join(body))
            else:
                groups.append((False, ["".join(body)]))
        for number, (is_row, items) in enumerate(groups):
            # The gap above the paragraph goes above its first part only.
            group_style = style if not number else style.replace(
                f"padding:{TEXT_BOX_PARAGRAPH_GAP * block_size:.4f}pt", "padding:0pt"
            )
            if is_row:
                parts.append(f"<div style=\"{group_style}\">{items[0]}</div>")
            else:
                parts.append(f"<p style=\"{group_style}\">{''.join(items)}</p>")
        block = block.next()
    parts.append("</body></html>")
    return "".join(parts), families


def text_box_document(
    stored_html: str, size: float, color: QColor, family: str, width: float, scale: float = 2.0
) -> QTextDocument:
    """A committed box laid out as its editor would lay it out, `width`
    points wide -- for baking it again without opening it."""
    document = QTextDocument()
    document.setDocumentMargin(0)
    document.setDefaultFont(text_box_font(family, size, scale))
    document.setHtml(stored_html)
    document.setDocumentMargin(0)
    text_box_set_tabs(document, size, scale)
    text_box_normalize(document, size, color, family, scale)
    document.setTextWidth(width * scale)
    document.documentLayout().documentSize()
    return document


class CanvasTextEdit(QTextEdit):
    finishRequested = Signal()
    deleteRequested = Signal()

    def mousePressEvent(self, event: Any) -> None:
        super().mousePressEvent(event)
        if event.button() == Qt.RightButton:
            # Qt's text control leaves a right press unaccepted, so it went
            # on up to the page canvas, which reads any press as a click
            # away and commits the box. Selecting a word and right-clicking
            # it therefore closed the box and opened the menu for the object
            # instead of the one for the text.
            event.accept()

    def keyPressEvent(self, event: Any) -> None:
        if event.key() in (Qt.Key_Return, Qt.Key_Enter) and event.modifiers() & Qt.ControlModifier:
            self.finishRequested.emit()
            event.accept()
            return
        if event.key() == Qt.Key_Delete and event.modifiers() & Qt.ControlModifier:
            self.deleteRequested.emit()
            event.accept()
            return
        super().keyPressEvent(event)


class RichTextFormatMixin:
    """Shared bold/underline/strikethrough/color mini-toolbar and per-run
    formatting helpers for any widget with a `self.editor` QTextEdit --
    reused by CanvasTextBox (on-page text boxes) and StickyNoteEditDialog
    (sticky notes) so both get the same character-formatting UX."""

    def _merge_char_format(self, fmt: QTextCharFormat) -> None:
        cursor = self.editor.textCursor()
        if cursor.hasSelection():
            cursor.mergeCharFormat(fmt)
            self.editor.setTextCursor(cursor)
        else:
            self.editor.mergeCurrentCharFormat(fmt)
        self.editor.setFocus()

    def _toggle_bold(self) -> None:
        bold = self.editor.textCursor().charFormat().fontWeight() > QFont.Normal
        fmt = QTextCharFormat()
        fmt.setFontWeight(QFont.Normal if bold else QFont.Bold)
        self._merge_char_format(fmt)

    def _toggle_underline(self) -> None:
        fmt = QTextCharFormat()
        fmt.setFontUnderline(not self.editor.textCursor().charFormat().fontUnderline())
        self._merge_char_format(fmt)

    def _toggle_strike(self) -> None:
        fmt = QTextCharFormat()
        fmt.setFontStrikeOut(not self.editor.textCursor().charFormat().fontStrikeOut())
        self._merge_char_format(fmt)

    def _toggle_highlight(self, color: QColor) -> None:
        is_highlighted = char_format_highlighted(self.editor.textCursor().charFormat())
        fmt = QTextCharFormat()
        fmt.setBackground(Qt.NoBrush if is_highlighted else QColor(color))
        self._merge_char_format(fmt)

    def _choose_char_color(self) -> None:
        current = self.editor.textCursor().charFormat().foreground().color()
        if not current.isValid():
            current = QColor("#151515")
        color = QColorDialog.getColor(current, self, tr("フォントの色を選択"))
        if not color.isValid():
            return
        fmt = QTextCharFormat()
        fmt.setForeground(color)
        self._merge_char_format(fmt)

    def _set_alignment(self, alignment: Any) -> None:
        self.editor.setAlignment(alignment)
        self.editor.setFocus()

    def _set_char_font_size(self, size: float) -> None:
        fmt = QTextCharFormat()
        fmt.setFontPointSize(float(size))
        self._merge_char_format(fmt)

    def _set_char_font_family(self, qt_family: str) -> None:
        fmt = QTextCharFormat()
        fmt.setFontFamilies([qt_family])
        self._merge_char_format(fmt)

    def _finish_editing(self) -> None:
        """What "confirm" does. A text box tells the page it is done; the
        sticky note's dialog accepts."""
        signal = getattr(self, "finishRequested", None)
        if signal is not None:
            signal.emit()
            return
        accept = getattr(self, "accept", None)
        if callable(accept):
            accept()

    def _reader_window(self) -> Any:
        """The reader window, for reading the real shortcut keys off its
        actions. A dialog's own window() is the dialog."""
        widget = self.window()
        if isinstance(widget, QDialog):
            parent = self.parent()
            widget = parent.window() if parent is not None else widget
        return widget

    def _install_editor_context_menu(self) -> None:
        self.editor.setContextMenuPolicy(Qt.CustomContextMenu)
        self.editor.customContextMenuRequested.connect(self._show_editor_context_menu)

    def _build_editor_context_menu(self, _point: QPoint) -> QMenu:
        # PowerPoint-style: right-clicking selected/caret text also offers
        # the same character formatting the main toolbar does, not just
        # cut/copy/paste.
        # Built by hand rather than createStandardContextMenu(): the menu
        # carries pdfNote's own wording and shortcut hints next to the
        # formatting commands, in every UI language.
        menu = QMenu(self.editor)
        cursor = self.editor.textCursor()
        has_selection = cursor.hasSelection()
        document = self.editor.document()
        mime = clipboard_mime()

        window = self._reader_window()

        def keys_of(name: str, fallback: str) -> str:
            # The key of the window's action for the same command, so this
            # menu cannot advertise a key that has moved.
            return PDFReaderWindow._action_shortcut(getattr(window, name, None)) or fallback

        def entry(
            target: QMenu, label: str, slot: Any, icon: str | QIcon, keys: str | None = None
        ) -> QAction:
            # Keys after a tab, as in pdfNote's other menus: Qt right-aligns them.
            text = f"{tr(label)}\t{key_text(keys)}" if keys else tr(label)
            action = target.addAction(text, slot)
            action.setProperty("pdfnoteKey", label)  # for assign_access_keys
            action.setIcon(icon if isinstance(icon, QIcon) else menu_icon(icon))
            return action

        def submenu(key: str, icon: str) -> QMenu:
            child = QMenu(tr(key), menu)
            child.setIcon(menu_icon(icon))
            child.menuAction().setProperty("pdfnoteKey", key)
            return child

        # The Windows edit-box entries -- undo, redo, the clipboard, delete,
        # select all, as the search box's menu has them -- then Exit Edit
        # Text and the font and paragraph commands PowerPoint offers on text
        # in a shape, and the box itself.
        entry(menu, "元に戻す", self.editor.undo, "undo", "Ctrl+Z").setEnabled(
            document.isUndoAvailable()
        )
        entry(menu, "やり直す", self.editor.redo, "redo", "Ctrl+Y").setEnabled(
            document.isRedoAvailable()
        )
        menu.addSeparator()
        entry(menu, "切り取り", self.editor.cut, "cut", "Ctrl+X").setEnabled(has_selection)
        entry(menu, "コピー", self.editor.copy, "copy", "Ctrl+C").setEnabled(has_selection)
        entry(menu, "貼り付け", self.editor.paste, "paste", "Ctrl+V").setEnabled(
            bool(mime is not None and mime.hasText())
        )
        entry(
            menu, "削除", lambda: self.editor.textCursor().removeSelectedText(), "delete", "Del"
        ).setEnabled(has_selection)
        menu.addSeparator()
        entry(menu, "すべて選択", self.editor.selectAll, "select_all", "Ctrl+A")
        menu.addSeparator()
        entry(
            menu, "入力を確定", self._finish_editing, "confirm",
            keys_of("act_finish_text", "Ctrl+Return"),
        )
        menu.addSeparator()
        format_menu = submenu("書式", "format")
        char_format = self.editor.textCursor().charFormat()
        bold_action = entry(
            format_menu, "太字", self._toggle_bold, "text_bold_run",
            keys_of("act_text_bold", "Ctrl+B"),
        )
        bold_action.setCheckable(True)
        bold_action.setChecked(char_format.fontWeight() > QFont.Normal)
        highlight_color = getattr(window, "_markup_color", QColor("#FFD633"))
        highlight_action = entry(
            format_menu, "ハイライト", lambda: self._toggle_highlight(highlight_color),
            menu_icon("text_highlight_run", highlight_color),
            keys_of("act_unified_highlight", "Ctrl+H"),
        )
        highlight_action.setCheckable(True)
        highlight_action.setChecked(char_format_highlighted(char_format))
        underline_action = entry(
            format_menu, "下線", self._toggle_underline, "text_underline_run",
            keys_of("act_unified_underline", "Ctrl+U"),
        )
        underline_action.setCheckable(True)
        underline_action.setChecked(char_format.fontUnderline())
        strike_action = entry(
            format_menu, "取り消し線", self._toggle_strike, "text_strike_run",
            keys_of("act_unified_strikeout", "Ctrl+K"),
        )
        strike_action.setCheckable(True)
        strike_action.setChecked(char_format.fontStrikeOut())
        format_menu.addSeparator()
        entry(
            format_menu, "フォントの色...", self._choose_char_color,
            menu_icon("text_color", getattr(window, "_text_color", None)),
        )
        # Font and size sit at the top level, not buried under "書式":
        # they are the two things most often reached for, and PowerPoint
        # surfaces them directly on the text right-click too.
        font_menu = submenu("フォント", "font")
        menu.addMenu(font_menu)
        for display_name, (qt_family, _regular, _bold) in TEXT_BOX_FONTS.items():
            if display_name not in MAIN_TEXT_BOX_FONT_KEYS:
                continue  # the toolbar's list has every font
            # Same localised label the toolbar's font picker shows.
            font_menu.addAction(
                PDFReaderWindow.font_display_name(display_name),
                lambda _checked=False, family=qt_family: self._set_char_font_family(family),
            )
        size_menu = submenu("フォント サイズ", "font_size")
        menu.addMenu(size_menu)
        for size in (8, 9, 10, 11, 12, 14, 16, 18, 20, 24, 28, 36, 48):
            size_menu.addAction(
                str(size),
                lambda _checked=False, value=size: self._set_char_font_size(value),
            )
        menu.addMenu(format_menu)
        # PowerPoint's Paragraph group offers alignment here too. The
        # submenu carries the picture of the alignment in effect.
        align_menu = submenu("配置", "align_left")
        menu.addMenu(align_menu)
        current = self.editor.alignment()
        alignments = (
            ("左揃え", Qt.AlignLeft, "align_left", "act_align_left", "Ctrl+L"),
            ("中央揃え", Qt.AlignHCenter, "align_center", "act_align_center", "Ctrl+E"),
            ("右揃え", Qt.AlignRight, "align_right", "act_align_right", "Ctrl+R"),
        )
        align_menu.setIcon(menu_icon(next(
            (icon for _label, flag, icon, _name, _key in alignments if current & flag),
            "align_left",
        )))
        for label, flag, icon, name, fallback in alignments:
            action = entry(
                align_menu, label, lambda _checked=False, value=flag: self._set_alignment(value),
                icon, keys_of(name, fallback),
            )
            action.setCheckable(True)
            action.setChecked(bool(current & flag))
        # Only a text box can be deleted from here. A sticky note is
        # deleted on the page, not from inside its own editor.
        delete_requested = getattr(self, "deleteRequested", None)
        if delete_requested is not None:
            menu.addSeparator()
            entry(menu, "テキスト ボックスを削除", delete_requested.emit, "delete")
        # Pin the submenus as attributes of the menu itself: nothing else
        # holds a Python reference to them once this method returns, and
        # PySide's Python wrapper for a QMenu without one can be collected
        # (taking the underlying C++ object with it, since nothing else
        # references it either) before a caller gets to inspect it.
        menu._pdfnote_format_menu = format_menu
        menu._pdfnote_font_menu = font_menu
        menu._pdfnote_size_menu = size_menu
        menu._pdfnote_align_menu = align_menu
        return assign_access_keys(menu)

    def _show_editor_context_menu(self, point: QPoint) -> None:
        if premium_menu_blocked(self):
            return
        self._build_editor_context_menu(point).exec(self.editor.mapToGlobal(point))

    def has_mixed_formatting(self) -> bool:
        """True when any run of text in the editor differs from the first
        run's color/bold/underline/strikeout (i.e. per-character formatting
        was actually used, not just the box's single overall style)."""
        block = self.editor.document().begin()
        baseline: tuple[Any, bool, bool, bool] | None = None
        while block.isValid():
            it = block.begin()
            while not it.atEnd():
                fragment = it.fragment()
                if fragment.isValid() and fragment.text():
                    fmt = fragment.charFormat()
                    signature = (
                        fmt.foreground().color().name(),
                        fmt.fontWeight() > QFont.Normal,
                        fmt.fontUnderline(),
                        fmt.fontStrikeOut(),
                    )
                    if baseline is None:
                        baseline = signature
                    elif signature != baseline:
                        return True
                it += 1
            block = block.next()
        return False


class CanvasTextBox(RichTextFormatMixin, ResizableCanvasFrame):
    finishRequested = Signal()
    deleteRequested = Signal()
    # A click on the box held as an object: where (in the box), and whether
    # it was the second of a double-click.
    objectClicked = Signal(QPointF, bool)
    # A font, size or colour was applied from the box's own menu: the
    # toolbar shows what it now is.
    formatApplied = Signal()

    def __init__(
        self,
        parent: QWidget,
        text: str,
        font_size: float,
        color: QColor,
        scale: float,
        font_family: str = DEFAULT_TEXT_BOX_QT_FAMILY,
        html: str | None = None,
        shrink: float = 1.0,
    ) -> None:
        super().__init__(parent, QSize(36, 22))
        self.setObjectName("canvasTextBox")
        self.setMouseTracking(True)
        self._drag_last_global: QPointF | None = None
        self._drag_moved = False
        layout = QVBoxLayout(self)
        layout.setContentsMargins(4, 4, 4, 4)
        layout.setSpacing(0)
        self.editor = CanvasTextEdit(self)
        self.editor.setAcceptRichText(False)
        self.editor.setFrameShape(QFrame.NoFrame)
        # PowerPoint's shapes: no scroll bar, and the first line stays at
        # the top of the box. Text beyond the box shows once it is on the
        # page; while the box is open, typing grows the box to hold it.
        # (A box made by 5.40 used to open with a scroll bar and its first
        # line scrolled out of sight.)
        self.editor.setVerticalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.editor.setHorizontalScrollBarPolicy(Qt.ScrollBarAlwaysOff)
        self.editor.verticalScrollBar().valueChanged.connect(self._keep_first_line_at_top)
        self.editor.setContextMenuPolicy(Qt.CustomContextMenu)
        self.editor.customContextMenuRequested.connect(self._show_editor_context_menu)
        layout.addWidget(self.editor, 1)
        self.editor.finishRequested.connect(self.finishRequested)
        self.editor.deleteRequested.connect(self.deleteRequested)
        # The box's own font, size and colour: what text that has none of
        # its own is shown and committed in, and what is typed next.
        self._font_size_pt = float(font_size)
        self._format_color = QColor(color)
        self._format_scale = scale
        self._font_family = font_family
        self.last_applied_color: QColor | None = None
        self._fit_pending = False
        self._style_editor()
        self._load(text, html, shrink)
        if abs(shrink - 1.0) > 1e-6:
            # The size it is drawn at is the box's own from now on.
            self._font_size_pt *= shrink
            self._style_editor()
        self.editor.document().contentsChanged.connect(self._schedule_fit)
        self.editor.textChanged.connect(self._grow_to_fit_content)
        self.set_mode("editing")

    def set_mode(self, mode: str) -> None:
        # PowerPoint-style chrome: a thin border and no fill, always -- gray
        # while actively typing, accent blue once selected as an object
        # (resize handles active, arrow keys move/resize, caret not blinking).
        # No separate move handle or embedded toolbar: dragging the frame
        # itself (border while editing, anywhere on the box once selected)
        # moves it, and formatting lives in the main toolbar.
        editing = mode == "editing"
        border = COLORS["box_border_editing"] if editing else COLORS["box_border_object"]
        self.setStyleSheet(
            f"QFrame#canvasTextBox {{ background:transparent; border:1px solid {border}; }}"
        )
        self.editor.setReadOnly(not editing)
        self.editor.setAttribute(Qt.WA_TransparentForMouseEvents, not editing)

    def content_widget(self) -> QWidget | None:
        return self.editor

    def _position_resize_handles(self) -> None:
        """Round a box 12 px or less across on screen, the four corners
        only, as round a picture (6.28, decided for text boxes 2026-10-19):
        a line of text at a low zoom has the frame at its least, 36 x 22 px,
        and the handles in the middles of its sides covered all of it but
        two gaps 3 px wide -- a press on the box took a handle and sized it
        (6.29)."""
        super()._position_resize_handles()
        if getattr(self, "editor", None) is None:
            return
        left, top, right, bottom = self.content_insets((5, 5, 5, 5))
        small = min(self.width() - left - right, self.height() - top - bottom) <= 12
        for direction, handle in self.resize_handles.items():
            if len(direction) == 1:
                handle.setVisible(not small)

    def mousePressEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton:
            self._drag_last_global = event.globalPosition()
            self._drag_moved = False
            self.setCursor(Qt.SizeAllCursor)
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: Any) -> None:
        if self._drag_last_global is not None and event.buttons() & Qt.LeftButton:
            current = event.globalPosition()
            delta = current - self._drag_last_global
            if delta.manhattanLength() > 0:
                self._drag_moved = True
            self._drag_last_global = current
            self._move_by(QPoint(round(delta.x()), round(delta.y())))
            event.accept()
            return
        # Hover feedback (border while editing, anywhere while object-selected):
        # PowerPoint shows the 4-way move cursor before you even press down.
        self.setCursor(Qt.SizeAllCursor)
        super().mouseMoveEvent(event)

    def mouseDoubleClickEvent(self, event: Any) -> None:
        # The second press of a double-click, which Qt sends as one of its
        # own: a press like the first, whose release selects the word.
        if event.button() == Qt.LeftButton:
            self._double_click = True
        self.mousePressEvent(event)

    def mouseReleaseEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton and self._drag_last_global is not None:
            was_click = not self._drag_moved
            double, self._double_click = getattr(self, "_double_click", False), False
            self._drag_last_global = None
            self.setCursor(Qt.SizeAllCursor)
            self.geometryEdited.emit()
            event.accept()
            if was_click:
                self.objectClicked.emit(QPointF(event.position()), double)
            return
        super().mouseReleaseEvent(event)

    def place_caret_at(self, position: QPointF, select_word: bool = False) -> None:
        """The caret where the box was clicked (`position`, in the box), or
        the word there selected, as PowerPoint does once a box is typed in.
        It went to the end of the text, wherever the click was (6.20)."""
        point = self.editor.viewport().mapFrom(self, position.toPoint())
        cursor = self.editor.cursorForPosition(point)
        if select_word:
            cursor.select(QTextCursor.WordUnderCursor)
        self.editor.setTextCursor(cursor)

    def _grow_to_fit_content(self) -> None:
        # PowerPoint-style auto-grow: the box only ever grows to fit typed
        # content, never auto-shrinks below a size the user set by dragging.
        self.editor.document().setTextWidth(self.editor.viewport().width())
        content_height = self.editor.document().size().height()
        chrome_height = self.height() - self.editor.height()
        desired_height = math.ceil(content_height) + chrome_height + 4
        if desired_height <= self.height():
            return
        parent = self.parentWidget()
        maximum_height = parent.height() - self.y() if parent is not None else desired_height
        new_height = min(desired_height, max(self.height(), maximum_height))
        if new_height > self.height():
            self.resize(self.width(), new_height)

    def _move_by(self, delta: QPoint) -> None:
        bounds = self.parentWidget().rect().adjusted(0, 0, -self.width(), -self.height())
        target = self.pos() + delta
        target.setX(min(max(bounds.left(), target.x()), max(bounds.left(), bounds.right())))
        target.setY(min(max(bounds.top(), target.y()), max(bounds.top(), bounds.bottom())))
        self.move(target)
        self.geometryEdited.emit()

    def _style_editor(self) -> None:
        """The box's own font and colour on the editor itself, for text that
        carries none of its own. No padding and no document margin: the
        page puts the first glyph at the box's corner, and so must this."""
        font = text_box_font(self._font_family, self._font_size_pt, self._format_scale)
        self.editor.setStyleSheet(
            f"QTextEdit {{ background:transparent; color:{self._format_color.name()}; "
            f"border:none; padding:0px; }}"
        )
        self.editor.setFont(font)
        document = self.editor.document()
        document.setDefaultFont(font)
        document.setDocumentMargin(0)
        text_box_set_tabs(document, self._font_size_pt, self._format_scale)

    def _load(self, text: str | None, html: str | None, shrink: float = 1.0) -> None:
        """Fill the editor from stored HTML (sizes in PDF points) or plain
        text, in the editor's form, with nothing to undo. `shrink`: see
        text_box_normalize."""
        if html is not None:
            self.editor.setHtml(html)
        else:
            self.editor.setPlainText(text or "")
        document = self.editor.document()
        document.setDocumentMargin(0)
        text_box_normalize(
            document, self._font_size_pt, self._format_color, self._font_family, self._format_scale,
            shrink,
        )
        cursor = self.editor.textCursor()
        cursor.movePosition(QTextCursor.End)
        self.editor.setTextCursor(cursor)
        self.editor.setCurrentCharFormat(cursor.charFormat())
        document.clearUndoRedoStacks()

    def refresh_scale(self, scale: float) -> None:
        """Show the box at another zoom. Every size in the editor is scaled
        for the zoom, so the text is read back in at the new one; the
        editor's own undo history does not survive that."""
        if abs(scale - self._format_scale) < 1e-9:
            return
        stored = self.storage_html()
        cursor = self.editor.textCursor()
        anchor, position = cursor.anchor(), cursor.position()
        self._format_scale = scale
        self._style_editor()
        self._load(None, stored)
        last = max(0, self.editor.document().characterCount() - 1)
        cursor = self.editor.textCursor()
        cursor.setPosition(min(anchor, last))
        cursor.setPosition(min(position, last), QTextCursor.KeepAnchor)
        self.editor.setTextCursor(cursor)

    def _keep_first_line_at_top(self, value: int) -> None:
        """The editor scrolls to keep the caret in sight; a text box does
        not: its first line stays where the page has it."""
        if value:
            self.editor.verticalScrollBar().setValue(0)

    def _schedule_fit(self) -> None:
        """After an edit, a paragraph may have gained or lost its largest
        text: its line height follows, once the edit is done."""
        if self._fit_pending:
            return
        self._fit_pending = True
        QTimer.singleShot(0, self, self._fit_now)

    def _fit_now(self) -> None:
        self._fit_pending = False
        document = self.editor.document()
        if not _text_box_blocks_to_fit(document, self._format_scale, self._font_size_pt):
            return
        # Part of the edit that made it necessary, so that undoing the one
        # undoes the other -- and nothing is added after an undo, which
        # would throw away the redo.
        cursor = QTextCursor(document)
        cursor.joinPreviousEditBlock()
        try:
            text_box_fit_blocks(document, self._format_scale, self._font_size_pt)
        finally:
            cursor.endEditBlock()

    def _format_scope(self, whole: bool | None) -> tuple[int, int, bool]:
        """What a font, size or colour applies to: the selected text while
        the box is typed in, else -- nothing selected, all of it selected,
        or the box held as an object -- the whole box, whose own font it
        then becomes for what is typed next."""
        document = self.editor.document()
        last = max(0, document.characterCount() - 1)
        cursor = self.editor.textCursor()
        if whole is None:
            whole = (
                self.editor.isReadOnly()
                or not cursor.hasSelection()
                or (cursor.selectionStart() == 0 and cursor.selectionEnd() >= last)
            )
        if whole:
            return 0, last, True
        return cursor.selectionStart(), cursor.selectionEnd(), False

    def _change_format(
        self, whole: bool | None, change: QTextCharFormat, set_base: Callable[[], None]
    ) -> None:
        start, end, whole = self._format_scope(whole)
        document = self.editor.document()
        cursor = QTextCursor(document)
        cursor.beginEditBlock()
        try:
            if whole:
                set_base()
            if start < end:
                cursor.setPosition(start)
                cursor.setPosition(end, QTextCursor.KeepAnchor)
                cursor.mergeCharFormat(change)
            if whole:
                # And each paragraph's own, which an empty line is shown in.
                block = document.begin()
                while block.isValid():
                    cursor.setPosition(block.position())
                    cursor.mergeBlockCharFormat(change)
                    block = block.next()
            text_box_fit_blocks(document, self._format_scale, self._font_size_pt)
        finally:
            cursor.endEditBlock()
        if whole:
            self._style_editor()
            if not self.editor.textCursor().hasSelection():
                self.editor.mergeCurrentCharFormat(change)
        self._grow_to_fit_content()

    def apply_text_size(self, size: float, whole: bool | None = None) -> None:
        size = float(size)
        self._change_format(
            whole, text_box_run_format(size, self._format_scale),
            lambda: setattr(self, "_font_size_pt", size),
        )

    def apply_text_color(self, color: QColor, whole: bool | None = None) -> None:
        change = QTextCharFormat()
        change.setForeground(QColor(color))
        self.last_applied_color = QColor(color)
        self._change_format(whole, change, lambda: setattr(self, "_format_color", QColor(color)))

    def apply_text_family(self, qt_family: str, whole: bool | None = None) -> None:
        change = QTextCharFormat()
        change.setFontFamilies([qt_family])
        self._change_format(whole, change, lambda: setattr(self, "_font_family", qt_family))

    # The box's own menu applies them the same way as the toolbar.
    def _choose_char_color(self) -> None:
        current = self.editor.textCursor().charFormat().foreground().color()
        if not current.isValid() or self.editor.textCursor().charFormat().foreground().style() == Qt.NoBrush:
            current = QColor(self._format_color)
        color = QColorDialog.getColor(current, self, tr("フォントの色を選択"))
        if color.isValid():
            self.apply_text_color(color)
            self.formatApplied.emit()
        self.editor.setFocus()

    def _set_char_font_size(self, size: float) -> None:
        self.apply_text_size(size)
        self.formatApplied.emit()
        self.editor.setFocus()

    def _set_char_font_family(self, qt_family: str) -> None:
        self.apply_text_family(qt_family)
        self.formatApplied.emit()
        self.editor.setFocus()

    def format_at_caret(self) -> tuple[float, str]:
        """The size and font the toolbar shows: the text at the caret's, as
        Office's do, or the box's own while it is held as an object."""
        if self.editor.isReadOnly():
            return self._font_size_pt, self._font_family
        fmt = self.editor.currentCharFormat()
        return text_box_run_size(fmt, self._font_size_pt), text_box_run_family(fmt, self._font_family)

    def storage_html(self) -> str:
        """The HTML kept with the committed box, to open it again."""
        return text_box_html(
            self.editor.document(), self._font_size_pt, self._format_color, self._font_family
        )[0]

    def page_html(self) -> tuple[str, set[str], float, float]:
        """What the page is given: the HTML with the editor's own line
        breaks, the fonts it uses, and the width and height the text takes
        in the editor, in points."""
        document = self.editor.document()
        text_box_fit_blocks(document, self._format_scale, self._font_size_pt)
        document.documentLayout().documentSize()
        scale = max(self._format_scale, 1e-6)
        html_text, families = text_box_html(
            document, self._font_size_pt, self._format_color, self._font_family, lines=True,
            scale=scale,
        )
        return (
            html_text, families,
            self.editor.viewport().width() / scale, document.size().height() / scale,
        )

    def focus_editor(self, select_all: bool = False) -> None:
        self.editor.setFocus()
        if select_all:
            self.editor.selectAll()


class StickyNoteEditDialog(RichTextFormatMixin, QDialog):
    """Sticky-note editor, formatted the way a text box is.

    It used to carry a bar of four one-character buttons of its own --
    bold, underline, strikethrough, colour -- from before text boxes were
    formatted from the toolbar and the right-click menu. The note now
    uses that same menu and the same keys (5.35).
    """

    def __init__(self, parent: QWidget, title: str, text: str, html: str | None) -> None:
        super().__init__(parent)
        self.setWindowTitle(title)
        self.resize(360, 260)
        # Not modal: the toolbar has to stay reachable, because the buttons
        # that format this text are on it (5.36). A window of its own, kept
        # above the reader.
        self.setModal(False)
        self.setWindowFlag(Qt.Tool, True)
        layout = QVBoxLayout(self)
        self.editor = QTextEdit()
        self.editor.setAcceptRichText(False)
        self._install_editor_context_menu()
        layout.addWidget(self.editor, 1)
        if html is not None:
            self.editor.setHtml(html)
        else:
            self.editor.setPlainText(text)
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.button(QDialogButtonBox.Ok).setText(tr("OK"))
        buttons.button(QDialogButtonBox.Cancel).setText(tr("キャンセル"))
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        layout.addWidget(buttons)
        self.editor.moveCursor(QTextCursor.End)
        self.editor.setFocus()
        self.editor.installEventFilter(self)

    def eventFilter(self, watched: Any, event: Any) -> bool:  # noqa: N802 - Qt's name
        # Ctrl+Enter puts the note down, as it does a text box: the note is
        # written with a text box's keys (5.35). With the keyboard alone
        # there was no way to OK -- Tab is a tab in the text, and Ctrl+Enter
        # did nothing (6.29).
        if (
            watched is self.editor
            and event.type() == QEvent.KeyPress
            and event.key() in (Qt.Key_Return, Qt.Key_Enter)
            and event.modifiers() & Qt.ControlModifier
        ):
            self.accept()
            return True
        return super().eventFilter(watched, event)

    def plain_text(self) -> str:
        return self.editor.toPlainText()

    def rich_html(self) -> str | None:
        """The note's HTML, whenever anything was formatted at all.

        A text box carries one overall style of its own -- its font, size
        and colour -- so it only needs the HTML when the runs differ from
        each other. A note has no such carrier: a note that is bold all
        the way through would lose its bold, so any formatting at all is
        reason to keep the HTML (5.35).
        """
        if self.has_mixed_formatting() or self._has_any_formatting():
            return self.editor.document().toHtml()
        return None

    def _has_any_formatting(self) -> bool:
        block = self.editor.document().begin()
        while block.isValid():
            it = block.begin()
            while not it.atEnd():
                fragment = it.fragment()
                if fragment.isValid() and fragment.text():
                    fmt = fragment.charFormat()
                    if (
                        fmt.fontWeight() > QFont.Normal
                        or fmt.fontUnderline()
                        or fmt.fontStrikeOut()
                        or fmt.background().style() != Qt.NoBrush
                    ):
                        return True
                it += 1
            block = block.next()
        return False


class CropPreview(QWidget):
    cropEdited = Signal()

    def __init__(self, pixmap: QPixmap, parent: QWidget) -> None:
        super().__init__(parent)
        self.pixmap = pixmap
        self.crop_rect = QRectF(0.0, 0.0, 1.0, 1.0)
        self.crop_mode = False
        # True while the picture is still drawn by the page underneath
        # (selected, not yet changed): drawn here as well, a picture with
        # transparent parts came out darker, laid over itself.
        self.page_shows_it = False
        self._drag_mode: str | None = None
        self._last_position = QPointF()
        # As small as a picture can be on screen: a preview held larger
        # than a small picture showed it larger than it is (6.27).
        self.setMinimumSize(2, 2)
        self.setMouseTracking(True)

    def set_crop_mode(self, enabled: bool) -> None:
        """Flip the flag only. The frame around this widget has to change
        size at the same time -- see CanvasImageBox.set_crop_mode, which is
        what everything calls."""
        self.crop_mode = bool(enabled)
        self._drag_mode = None
        self.setCursor(Qt.ArrowCursor)
        self.update()

    def _crop_pixels(self) -> QRectF:
        return QRectF(
            self.crop_rect.x() * self.width(),
            self.crop_rect.y() * self.height(),
            self.crop_rect.width() * self.width(),
            self.crop_rect.height() * self.height(),
        )

    @staticmethod
    def _handle_points(crop: QRectF) -> dict[str, QPointF]:
        return {
            "nw": crop.topLeft(),
            "n": QPointF(crop.center().x(), crop.top()),
            "ne": crop.topRight(),
            "e": QPointF(crop.right(), crop.center().y()),
            "se": crop.bottomRight(),
            "s": QPointF(crop.center().x(), crop.bottom()),
            "sw": crop.bottomLeft(),
            "w": QPointF(crop.left(), crop.center().y()),
        }

    def _hit_handle(self, point: QPointF) -> str | None:
        points = self._handle_points(self._crop_pixels())
        matches = [
            (direction, (handle.x() - point.x()) ** 2 + (handle.y() - point.y()) ** 2)
            for direction, handle in points.items()
        ]
        direction, distance = min(matches, key=lambda item: item[1])
        # A wider hit radius than the drawn handle size makes small handles
        # easier to grab, matching PowerPoint's forgiving crop-handle hit area.
        return direction if distance <= 196 else None

    @staticmethod
    def _cursor_for_direction(direction: str | None) -> Qt.CursorShape:
        return {
            "nw": Qt.SizeFDiagCursor,
            "n": Qt.SizeVerCursor,
            "ne": Qt.SizeBDiagCursor,
            "e": Qt.SizeHorCursor,
            "se": Qt.SizeFDiagCursor,
            "s": Qt.SizeVerCursor,
            "sw": Qt.SizeBDiagCursor,
            "w": Qt.SizeHorCursor,
            "move": Qt.SizeAllCursor,
        }.get(direction, Qt.ArrowCursor)

    def paintEvent(self, _event: Any) -> None:
        painter = QPainter(self)
        painter.setRenderHint(QPainter.SmoothPixmapTransform)
        if not self.crop_mode:
            if self.page_shows_it:
                return
            source = QRectF(
                self.crop_rect.left() * self.pixmap.width(),
                self.crop_rect.top() * self.pixmap.height(),
                self.crop_rect.width() * self.pixmap.width(),
                self.crop_rect.height() * self.pixmap.height(),
            )
            painter.drawPixmap(QRectF(self.rect()), self.pixmap, source)
            return
        painter.drawPixmap(self.rect(), self.pixmap)
        crop = self._crop_pixels()
        shade = QColor(15, 17, 20, 145)
        painter.fillRect(QRectF(0, 0, self.width(), crop.top()), shade)
        painter.fillRect(QRectF(0, crop.bottom(), self.width(), self.height() - crop.bottom()), shade)
        painter.fillRect(QRectF(0, crop.top(), crop.left(), crop.height()), shade)
        painter.fillRect(QRectF(crop.right(), crop.top(), self.width() - crop.right(), crop.height()), shade)
        painter.setPen(QPen(QColor("#FFFFFF"), 1, Qt.DashLine))
        painter.drawRect(crop)
        painter.setBrush(QColor("#000000"))
        painter.setPen(QPen(QColor("#FFFFFF"), 1))
        for direction, point in self._handle_points(crop).items():
            if len(direction) == 1:
                size = QSize(18, 8) if direction in ("n", "s") else QSize(8, 18)
            else:
                size = QSize(14, 14)
            painter.drawRect(
                QRectF(
                    point.x() - size.width() / 2,
                    point.y() - size.height() / 2,
                    size.width(),
                    size.height(),
                )
            )

    def mousePressEvent(self, event: Any) -> None:
        if event.button() != Qt.LeftButton or not self.crop_mode:
            super().mousePressEvent(event)
            return
        point = event.position()
        self._drag_mode = self._hit_handle(point)
        if self._drag_mode is None and self._crop_pixels().contains(point):
            self._drag_mode = "move"
        self._last_position = QPointF(point)
        self.setCursor(self._cursor_for_direction(self._drag_mode))
        event.accept()

    def mouseMoveEvent(self, event: Any) -> None:
        if not self.crop_mode:
            super().mouseMoveEvent(event)
            return
        if self._drag_mode is None:
            direction = self._hit_handle(event.position())
            if direction is None and self._crop_pixels().contains(event.position()):
                direction = "move"
            self.setCursor(self._cursor_for_direction(direction))
            super().mouseMoveEvent(event)
            return
        x = min(1.0, max(0.0, event.position().x() / max(1, self.width())))
        y = min(1.0, max(0.0, event.position().y() / max(1, self.height())))
        left, top, right, bottom = (
            self.crop_rect.left(), self.crop_rect.top(),
            self.crop_rect.right(), self.crop_rect.bottom(),
        )
        minimum = 0.05
        if self._drag_mode == "move":
            dx = (event.position().x() - self._last_position.x()) / max(1, self.width())
            dy = (event.position().y() - self._last_position.y()) / max(1, self.height())
            width, height = self.crop_rect.width(), self.crop_rect.height()
            left = min(max(0.0, left + dx), 1.0 - width)
            top = min(max(0.0, top + dy), 1.0 - height)
            right, bottom = left + width, top + height
            self._last_position = QPointF(event.position())
        elif "w" in self._drag_mode:
            left = min(x, right - minimum)
        elif "e" in self._drag_mode:
            right = max(x, left + minimum)
        if self._drag_mode != "move" and "n" in self._drag_mode:
            top = min(y, bottom - minimum)
        elif self._drag_mode != "move" and "s" in self._drag_mode:
            bottom = max(y, top + minimum)
        self.crop_rect = QRectF(left, top, right - left, bottom - top)
        self.cropEdited.emit()
        self.update()
        event.accept()

    def mouseReleaseEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton and self._drag_mode is not None:
            self._drag_mode = None
            self.cropEdited.emit()
            self.setCursor(Qt.ArrowCursor)
            event.accept()
            return
        super().mouseReleaseEvent(event)


class CanvasObjectBox(ResizableCanvasFrame):
    deleteRequested = Signal()
    copyRequested = Signal()

    def __init__(
        self,
        parent: QWidget,
        title: str | None = None,
        lock_corner_aspect: bool = False,
    ) -> None:
        super().__init__(parent, QSize(60, 45), lock_corner_aspect)
        self.setObjectName("canvasObjectBox")
        self.setStyleSheet(
            "QFrame#canvasObjectBox { background:rgba(255,255,255,20); border:2px solid #D94B45; }"
        )
        layout = QVBoxLayout(self)
        layout.setContentsMargins(2, 2, 2, 2)
        layout.setSpacing(0)
        self.handle = TextBoxMoveHandle(self, title if title is not None else tr("⋮⋮  図形"))
        self.handle.setFixedHeight(18)
        layout.addWidget(self.handle)
        layout.addStretch(1)
        self.handle.moveRequested.connect(self._move_by)
        self.handle.moveFinished.connect(self.geometryEdited)
        self._drag_last_global: QPointF | None = None
        self.setMouseTracking(True)

    # A shape's outline lies 2 px inside the border, under the 18 px title
    # bar (_active_object_geometry_changed reads it back the same way).
    CONTENT_INSETS = (2, 20, 2, 2)

    # A press this near the frame's edge takes the box, as a text box's
    # border does (6.16): the title bar alone did, and a picture pasted at
    # the top of a page had it above the page, cut off -- nothing moved it.
    EDGE_GRAB = 10
    # The title bar and the margin above the content.
    TOP_GRAB = 22

    def _grabs(self, point: QPointF) -> bool:
        """Is `point` (in the box) where a press takes the box?"""
        whole = QRectF(self.rect())
        band = self.EDGE_GRAB
        inside = whole.adjusted(band, self.TOP_GRAB, -band, -band)
        return whole.contains(point) and not inside.contains(point)

    def _passes_through(self) -> bool:
        """Clicks inside the frame go to the page under it: a shape's box
        only outlines what the page draws, and what lies under it is still
        there to click."""
        return self.content_widget() is None

    def _update_mask(self) -> None:
        if not self._passes_through():
            self.clearMask()
            return
        whole = self.rect()
        band = self.EDGE_GRAB
        inside = whole.adjusted(band, self.TOP_GRAB, -band, -band)
        if inside.width() <= 0 or inside.height() <= 0:
            self.clearMask()
            return
        self.setMask(QRegion(whole).subtracted(QRegion(inside)))

    def resizeEvent(self, event: Any) -> None:
        super().resizeEvent(event)
        self._update_mask()

    def mousePressEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton and self._grabs(event.position()):
            self._drag_last_global = event.globalPosition()
            self.setCursor(Qt.SizeAllCursor)
            event.accept()
            return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: Any) -> None:
        if self._drag_last_global is not None and event.buttons() & Qt.LeftButton:
            current = event.globalPosition()
            delta = current - self._drag_last_global
            step = QPoint(round(delta.x()), round(delta.y()))
            if not step.isNull():
                # What rounding leaves is kept for the next move.
                self._drag_last_global += QPointF(step)
                self._move_by(step)
            event.accept()
            return
        self.setCursor(Qt.SizeAllCursor if self._grabs(event.position()) else Qt.ArrowCursor)
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton and self._drag_last_global is not None:
            self._drag_last_global = None
            self.geometryEdited.emit()
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def set_accent_color(self, color: QColor) -> None:
        self.setStyleSheet(
            f"QFrame#canvasObjectBox {{ background:rgba(255,255,255,20); border:2px solid {color.name()}; }}"
        )
        self.handle.setStyleSheet(
            f"background:{color.name()}; color:white; font-size:10px; font-weight:600; padding:1px 5px;"
        )
        for handle in self.resize_handles.values():
            handle.setStyleSheet(
                f"background:#FFFFFF; border:2px solid {color.name()}; border-radius:1px;"
            )

    def _move_by(self, delta: QPoint) -> None:
        bounds = self.parentWidget().rect().adjusted(0, 0, -self.width(), -self.height())
        target = self.pos() + delta
        target.setX(min(max(bounds.left(), target.x()), max(bounds.left(), bounds.right())))
        target.setY(min(max(bounds.top(), target.y()), max(bounds.top(), bounds.bottom())))
        self.move(target)
        self.geometryEdited.emit()


class CanvasImageBox(CanvasObjectBox):
    cropEdited = Signal()
    cropModeChanged = Signal(bool)

    def __init__(self, parent: QWidget, pixmap: QPixmap) -> None:
        super().__init__(parent, tr("⋮⋮  画像"), lock_corner_aspect=True)
        layout = self.layout()
        assert isinstance(layout, QVBoxLayout)
        layout.takeAt(1)
        title_row = QHBoxLayout()
        title_row.setContentsMargins(0, 0, 0, 0)
        title_row.setSpacing(2)
        layout.removeWidget(self.handle)
        title_row.addWidget(self.handle, 1)
        # No button here: PowerPoint puts nothing on the picture itself.
        # Cropping is a command -- the right-click menu, or F2 on the
        # selected picture -- and while it is on, the crop handles are
        # what says so.
        layout.addLayout(title_row)
        self.preview = CropPreview(pixmap, self)
        self.preview.setCursor(Qt.SizeAllCursor)
        layout.addWidget(self.preview, 1)
        self.preview.cropEdited.connect(self.cropEdited)
        # Its title bar, its border and a picture of two pixels: the frame
        # follows the picture however small it is, as PowerPoint's does.
        # 36 x 44 made every picture smaller than that on screen -- a small
        # one at its own size, any at a low zoom -- that much larger on the
        # page when it was moved (6.27).
        self.setMinimumSize(QSize(10, 28))

    def content_widget(self) -> QWidget | None:
        return self.preview

    def _grabs(self, point: QPointF) -> bool:
        """The edge, and -- unless it is being cropped, when the picture
        is the crop's -- the picture itself, as in PowerPoint (6.16)."""
        if not self.preview.crop_mode and QRectF(self.rect()).contains(point):
            return True
        return super()._grabs(point)

    @property
    def crop_mode(self) -> bool:
        return self.preview.crop_mode

    def _position_resize_handles(self) -> None:
        super()._position_resize_handles()
        self._show_resize_handles()

    def _show_resize_handles(self) -> None:
        """The eight handles, or none while cropping: the crop's own size
        the crop then, and PowerPoint shows one set. Round a picture 12 px
        or less across on screen, the four corners only (6.28): those in
        the middles of the sides covered the middle of the picture and
        nearly all of its title bar, so a press anywhere on it took a
        handle and sized it, and it could not be moved."""
        if getattr(self, "preview", None) is None:
            return
        left, top, right, bottom = self.content_insets((4, 22, 4, 4))
        small = min(self.width() - left - right, self.height() - top - bottom) <= 12
        for direction, handle in self.resize_handles.items():
            handle.setVisible(not self.crop_mode and not (small and len(direction) == 1))

    def set_crop_mode(self, enabled: bool) -> None:
        """PowerPoint's crop, both ways round.

        Turning it on shows the whole picture, with the part that is cropped
        away dimmed, and the frame grows to hold it -- so the part you keep
        stays exactly where it was on the page. Turning it off shrinks the
        frame back to what is kept. The picture is never rescaled: pdfNote
        used to leave the frame alone and stretch whatever was left over it,
        which made a half-width crop twice as wide.
        """
        enabled = bool(enabled)
        if enabled == self.preview.crop_mode:
            return
        crop = QRectF(self.preview.crop_rect)
        if crop.width() <= 0 or crop.height() <= 0:
            return
        layout = self.layout()
        if layout is not None:
            layout.activate()
        before = self.preview.size()
        if before.width() <= 0 or before.height() <= 0:
            self.preview.set_crop_mode(enabled)
            return
        if enabled:
            width = before.width() / crop.width()
            height = before.height() / crop.height()
        else:
            width = before.width() * crop.width()
            height = before.height() * crop.height()
        # A frame is not allowed below a floor. Growing both sides by the
        # same factor keeps the picture's shape when the floor is what
        # decides the size -- the alternative is the stretch all over again.
        lift = max(
            1.0,
            self.preview.minimumWidth() / max(1.0, width),
            self.preview.minimumHeight() / max(1.0, height),
        )
        width, height = width * lift, height * lift
        if enabled:
            shift_x, shift_y = -crop.left() * width, -crop.top() * height
        else:
            shift_x, shift_y = crop.left() * before.width(), crop.top() * before.height()
        self.preview.set_crop_mode(enabled)
        # The picture moves the box unless the crop is what it moves.
        self.preview.setCursor(Qt.ArrowCursor if enabled else Qt.SizeAllCursor)
        # In crop mode the eight handles would be sizing the whole picture
        # while the crop handles size the crop: PowerPoint shows one set.
        self._show_resize_handles()
        self.setGeometry(
            round(self.x() + shift_x),
            round(self.y() + shift_y),
            self.width() + round(width) - before.width(),
            self.height() + round(height) - before.height(),
        )
        self.geometryEdited.emit()
        self.cropModeChanged.emit(enabled)


class ClickablePageLabel(PageCanvasMixin, QLabel):
    pageActivated = Signal(int)
    editGesture = Signal(int, str, object)
    textSelectionChanged = Signal()
    caretMoved = Signal()
    # Continuous scrolling used to be the one view mode where PDF hyperlinks
    # did nothing at all and showed no hand cursor.
    linkActivated = Signal(object)

    def __init__(self, page_index: int) -> None:
        super().__init__()
        self.page_index = page_index
        self.page_pixmap = QPixmap()
        self._init_canvas_state()
        self.setAlignment(Qt.AlignCenter)
        self.setMouseTracking(True)
        self.setCursor(Qt.ArrowCursor)
        self.setFocusPolicy(Qt.ClickFocus)

    def set_page_pixmap(self, pixmap: QPixmap) -> None:
        """Show the page as drawn, or with a null pixmap the placeholder
        text the caller sets.

        Painted by paintEvent, not by QLabel.setPixmap: QLabel fits a
        pixmap into whole logical pixels, and resampled a page drawn for a
        125 % screen (793.6 logical pixels wide) until it blurred (1.0.0).
        """
        self.page_pixmap = pixmap
        if not pixmap.isNull():
            self.setText("")
        self.update()

    def _canvas_origin(self) -> QPointF:
        return QPointF(0, 0)

    def _canvas_size(self) -> QSizeF:
        return QSizeF(self.size())

    def _emit_gesture(self, mode: str, payload: object) -> None:
        self.editGesture.emit(self.page_index, mode, payload)

    def _notify_activated(self) -> None:
        self.pageActivated.emit(self.page_index)

    def paintEvent(self, event: Any) -> None:
        super().paintEvent(event)
        painter = QPainter(self)
        if not self.page_pixmap.isNull():
            # At the label's origin, where the overlays put the page, and
            # inside the frame, as QLabel drew it.
            painter.save()
            painter.setClipRect(self.contentsRect())
            painter.drawPixmap(QPointF(0, 0), self.page_pixmap)
            painter.restore()
        painter.setRenderHint(QPainter.Antialiasing, True)
        self._paint_canvas_overlays(painter)


class SaveChangesDialog(QDialog):
    """Japanese, keyboard-accessible save prompt used when closing a dirty tab."""

    CANCEL = 0
    SAVE = 1
    DISCARD = 2

    def __init__(self, parent: QWidget, document_title: str) -> None:
        super().__init__(parent)
        self.setWindowTitle(APP_NAME)
        self.setModal(True)
        self.setMinimumWidth(430)
        layout = QVBoxLayout(self)
        message = QLabel(
            tr("「{document_title}」の変更を保存しますか？").format(document_title=document_title)
        )
        message.setWordWrap(True)
        message.setStyleSheet("font-size:13px; padding:10px 6px 12px 6px;")
        layout.addWidget(message)
        buttons = QHBoxLayout()
        buttons.addStretch(1)
        self.save_button = QPushButton(tr("保存（&S）"))
        self.discard_button = QPushButton(tr("保存しない（&N）"))
        self.cancel_button = QPushButton(tr("キャンセル"))
        self.save_button.setDefault(True)
        self.save_button.clicked.connect(lambda: self.done(self.SAVE))
        self.discard_button.clicked.connect(lambda: self.done(self.DISCARD))
        self.cancel_button.clicked.connect(lambda: self.done(self.CANCEL))
        for button in (self.save_button, self.discard_button, self.cancel_button):
            buttons.addWidget(button)
        layout.addLayout(buttons)
        QWidget.setTabOrder(self.save_button, self.discard_button)
        QWidget.setTabOrder(self.discard_button, self.cancel_button)
        QWidget.setTabOrder(self.cancel_button, self.save_button)
        # Each button answers to Alt and its underlined letter, as in any
        # Windows dialog. Alt+S and Alt+N answer too where this language
        # underlines other letters (Enregistrer: Alt+E), as they did in
        # 1.0.1 -- but only there. A second shortcut for a letter a button
        # already has made Qt call the key ambiguous: Alt+S and Alt+N from
        # a keyboard only moved the focus to the button, and the prompt
        # stayed (6.32; the test had emitted the shortcut's signal itself).
        underlined = [
            QKeySequence.mnemonic(button.text())
            for button in (self.save_button, self.discard_button, self.cancel_button)
        ]
        self.save_shortcut: QShortcut | None = None
        self.discard_shortcut: QShortcut | None = None
        if QKeySequence("Alt+S") not in underlined:
            self.save_shortcut = QShortcut(QKeySequence("Alt+S"), self)
            self.save_shortcut.activated.connect(lambda: self.done(self.SAVE))
        if QKeySequence("Alt+N") not in underlined:
            self.discard_shortcut = QShortcut(QKeySequence("Alt+N"), self)
            self.discard_shortcut.activated.connect(lambda: self.done(self.DISCARD))

    def reject(self) -> None:
        self.done(self.CANCEL)


class TabDragGesture:
    """Chrome-style tab dragging, from the press to the release.

    A tab reorders inside its strip while the pointer stays with it. Pull
    it clear and it becomes a real window under the cursor, which follows
    the mouse and docks into any pdfNote tab strip it is dragged over. One
    continuous motion, with the thing being dragged always on screen.

    Before this, leaving the strip's own rectangle by a pixel abandoned the
    reorder for a QDrag: a ghost picture of the tab, nothing else moving,
    and a window only at the release.
    """

    # How far the pointer has to be pulled off the strip before the tab
    # leaves it. About a tab's height, as in Chrome -- any less and an
    # ordinary sideways drag detaches on the first wobble. Sideways does
    # not detach at all: dragging past the last tab keeps it in the strip.
    TEAR_OFF_MARGIN = 26

    def __init__(self, bar: Any, identity: int, grab_offset: QPoint) -> None:
        self.identity = identity
        self.grab_offset = grab_offset
        self.bar = bar
        self.floating: Any = None
        # Qt reorders the tab inside the strip it was pressed in; after a
        # tear-off there is no press for it to follow, so we do it.
        self.native = True
        self.home = bar.owner
        self.home_index = bar.owner._session_index_by_identity(identity)
        self.home_geometry = QRect(bar.owner.geometry())

    # -- what the strip and the window call ---------------------------
    def owns(self, widget: Any) -> bool:
        return widget is self.bar or widget is self.floating

    def update(self, global_pos: QPoint) -> None:
        if self.floating is None:
            if self._pulled_clear(global_pos):
                self._tear_off(global_pos)
            elif not self.native:
                self._reorder_within(global_pos)
            return
        strip = self._strip_at(global_pos)
        if strip is not None:
            self._dock_into(strip, global_pos)
        else:
            self._place_floating(global_pos)

    def finish(self) -> None:
        global ACTIVE_TAB_DRAG
        self._release_grabs()
        if self.bar is not None:
            self.bar._drag_session_identity = None
        if ACTIVE_TAB_DRAG is self:
            ACTIVE_TAB_DRAG = None

    def cancel(self) -> None:
        """Esc during a drag puts the tab back where it started -- in the
        window it started in, wherever it has been dropped since."""
        home = self.home
        alive = home is not None and home in OPEN_WINDOWS
        if self.floating is not None:
            floating = self.floating
            self._release_grabs()
            if floating is home:
                home.setGeometry(self.home_geometry)
            elif alive:
                self.floating = None
                home._transfer_session_from(floating, self.identity, self.home_index)
        elif self.bar is not None:
            # Qt is still sliding the tab about; take the gesture off it
            # first or it would go on until the button came up.
            if self.native:
                self.bar.end_native_drag()
            if alive and self.bar.owner is not home:
                self._release_grabs()
                home._transfer_session_from(self.bar.owner, self.identity, self.home_index)
                self.bar = home.document_tabs
            else:
                self._move_tab_to(self.home_index)
        self.finish()

    # -- the steps ----------------------------------------------------
    def _pulled_clear(self, global_pos: QPoint) -> bool:
        bar = self.bar
        if bar is None or not bar.isVisible():
            return False
        rect = QRect(bar.mapToGlobal(QPoint(0, 0)), bar.size())
        return (
            global_pos.y() < rect.top() - self.TEAR_OFF_MARGIN
            or global_pos.y() > rect.bottom() + self.TEAR_OFF_MARGIN
        )

    def _tear_off(self, global_pos: QPoint) -> None:
        bar = self.bar
        owner = bar.owner
        index = owner._session_index_by_identity(self.identity)
        if index < 0:
            return
        bar.end_native_drag()
        bar._drag_session_identity = None
        if len(owner.sessions) == 1:
            # Chrome moves the window itself when it holds the only tab.
            # Nothing is taken out, so nothing is loaded again either.
            window = owner
        else:
            window = owner._detach_tab_to_new_window(index, global_pos)
            if window is None:
                return
        self.bar = None
        self.native = False
        self.floating = window
        self._place_floating(global_pos)
        self._grab(window)

    def _place_floating(self, global_pos: QPoint) -> None:
        """Keep the grabbed tab under the cursor, where it was grabbed."""
        window = self.floating
        if window is None:
            return
        bar = window.document_tabs
        index = max(0, window._session_index_by_identity(self.identity))
        top_left = bar.mapTo(window, bar.tabRect(index).topLeft())
        # move() places the frame, while the tab's position is measured
        # inside it: without the frame's own thickness the tab drifts out
        # from under the cursor by the height of the title bar.
        frame = window.mapToGlobal(QPoint(0, 0)) - window.pos()
        window.move(global_pos - top_left - self.grab_offset - frame)

    def _strip_at(self, global_pos: QPoint) -> Any:
        """The tab strip under the cursor, if any -- never the one in the
        window being dragged, which is by definition under it. Anywhere on
        the row the tabs are in counts, as in Chrome (6.24): the tabs alone
        were the target, one tab wide in a window holding one, and a tab
        let go of beside them stayed a window of its own."""
        for window in reversed(OPEN_WINDOWS):
            if window is self.floating or not window.isVisible():
                continue
            bar = getattr(window, "document_tabs", None)
            if bar is None or not bar.isVisible():
                continue
            row = getattr(window, "document_tabs_toolbar", None)
            area = row if row is not None and row.isVisible() and row.isAncestorOf(bar) else bar
            rect = QRect(area.mapToGlobal(QPoint(0, 0)), area.size())
            reach = rect.adjusted(
                -self.TEAR_OFF_MARGIN, -self.TEAR_OFF_MARGIN,
                self.TEAR_OFF_MARGIN, self.TEAR_OFF_MARGIN,
            )
            if reach.contains(global_pos):
                return bar
        return None

    def _dock_into(self, bar: Any, global_pos: QPoint) -> None:
        floating = self.floating
        if floating is None:
            return
        target = bar.owner
        index = bar.insertion_index_at(bar.mapFromGlobal(global_pos))
        self._release_grabs()
        self.floating = None
        if not target._transfer_session_from(floating, self.identity, index):
            self.floating = floating
            self._grab(floating)
            return
        self.bar = bar
        self._grab(bar)

    def _reorder_within(self, global_pos: QPoint) -> None:
        bar = self.bar
        if bar is None:
            return
        target = bar.insertion_index_at(bar.mapFromGlobal(global_pos))
        index = bar.owner._session_index_by_identity(self.identity)
        if index < 0:
            return
        if target > index:
            target -= 1
        self._move_tab_to(target)

    def _move_tab_to(self, target: int) -> None:
        bar = self.bar
        if bar is None:
            return
        index = bar.owner._session_index_by_identity(self.identity)
        target = max(0, min(target, bar.count() - 1))
        if index >= 0 and target != index:
            bar.moveTab(index, target)

    # -- the mouse ----------------------------------------------------
    def _grab(self, widget: Any) -> None:
        # A grab keeps the gesture alive while the pointer is over another
        # window. Headless runs drive update() themselves and must not be
        # left holding one.
        owner = widget if isinstance(widget, PDFReaderWindow) else getattr(widget, "owner", None)
        if owner is not None and getattr(owner, "test_mode", False):
            return
        try:
            widget.grabMouse()
        except Exception:
            pass

    def _release_grabs(self) -> None:
        for widget in (self.floating, self.bar):
            if widget is None:
                continue
            try:
                widget.releaseMouse()
            except Exception:
                pass


ACTIVE_TAB_DRAG: TabDragGesture | None = None


class DocumentTabBar(QTabBar):
    """Movable document tabs, dragged between pdfNote windows as in Chrome."""

    MIME_META = "application/x-pdfnote-tab-meta"
    MIME_DOCUMENT = "application/x-pdfnote-document"

    def __init__(self, owner: Any, parent: QWidget | None = None) -> None:
        super().__init__(parent)
        self.owner = owner
        self._drag_start = QPoint()
        self._drag_session_identity: int | None = None
        self.setAcceptDrops(True)
        self.setContextMenuPolicy(Qt.CustomContextMenu)
        self.customContextMenuRequested.connect(self._show_tab_menu)

    def tabInserted(self, index: int) -> None:  # noqa: N802 - Qt's name
        super().tabInserted(index)
        self.refresh_close_button_tips()

    def refresh_close_button_tips(self) -> None:
        owner = self.owner
        if not hasattr(owner, "act_close"):
            return
        tip = owner._tooltip_with_keys(tr("このタブを閉じる"), owner.act_close)
        for index in range(self.count()):
            for side in (QTabBar.RightSide, QTabBar.LeftSide):
                button = self.tabButton(index, side)
                if button is not None:
                    button.setToolTip(tip)

    def _show_tab_menu(self, position: QPoint) -> None:
        if self.owner._premium_blocked(self.owner.PREMIUM_CONTEXT_MENU):
            return
        self.build_tab_menu(self.tabAt(position)).exec(self.mapToGlobal(position))

    def build_tab_menu(self, index: int) -> QMenu:
        """Chrome-style tab menu -- the tab strip had no right-click at all.

        Kept separate from showing it so it can be inspected without
        entering a modal event loop.
        """
        menu = QMenu(self)
        if index >= 0:
            for key, slot, icon, enabled in (
                ("このタブを閉じる", self.owner._close_session, "tab_close", True),
                ("他のタブを閉じる", self.owner.close_other_sessions, "tab_close_others",
                 self.count() > 1),
                ("右側のタブを閉じる", self.owner.close_sessions_to_the_right, "tab_close_right",
                 index < self.count() - 1),
                # Chrome's own entry, and the way the keyboard reaches a
                # gesture that was otherwise only a mouse one.
                ("新しいウィンドウに移動", self.owner.move_session_to_new_window, "tab_detach",
                 self.count() > 1),
            ):
                entry = menu.addAction(tr(key), lambda _checked=False, i=index, run=slot: run(i))
                entry.setIcon(menu_icon(icon))
                entry.setProperty("pdfnoteKey", key)
                entry.setEnabled(enabled)
            menu.addSeparator()
        mirror_action(menu, self.owner.act_new)
        mirror_action(menu, self.owner.act_open)
        if index >= 0:
            menu.addSeparator()
            for action in (self.owner.act_save, self.owner.act_save_copy, self.owner.act_properties):
                mirror_action(menu, action)
        return assign_access_keys(menu)

    def mousePressEvent(self, event: Any) -> None:
        if event.button() == Qt.LeftButton:
            index = self.tabAt(event.position().toPoint())
            self._drag_start = event.position().toPoint()
            self._drag_session_identity = (
                id(self.owner.sessions[index])
                if 0 <= index < len(self.owner.sessions)
                else None
            )
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: Any) -> None:
        global ACTIVE_TAB_DRAG
        gesture = ACTIVE_TAB_DRAG
        if gesture is not None and gesture.owns(self):
            gesture.update(event.globalPosition().toPoint())
            # While the tab is still in the strip it was pressed in, Qt
            # slides it along with the pointer; take that over only once
            # the gesture has had to move it itself.
            if gesture.native and gesture.bar is self:
                super().mouseMoveEvent(event)
            else:
                event.accept()
            return
        if (
            event.buttons() & Qt.LeftButton
            and self._drag_session_identity is not None
            and (event.position().toPoint() - self._drag_start).manhattanLength()
            >= QApplication.startDragDistance()
        ):
            ACTIVE_TAB_DRAG = TabDragGesture(
                self, self._drag_session_identity, self._grab_offset()
            )
            ACTIVE_TAB_DRAG.update(event.globalPosition().toPoint())
            if ACTIVE_TAB_DRAG is not None and ACTIVE_TAB_DRAG.bar is self:
                super().mouseMoveEvent(event)
            else:
                event.accept()
            return
        super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event: Any) -> None:
        gesture = ACTIVE_TAB_DRAG
        if gesture is not None and gesture.owns(self):
            gesture.finish()
        super().mouseReleaseEvent(event)

    def _grab_offset(self) -> QPoint:
        """Where inside the tab it was taken hold of, so it can stay there
        under the cursor for the whole drag."""
        index = self.owner._session_index_by_identity(self._drag_session_identity or 0)
        rect = self.tabRect(index) if index >= 0 else QRect()
        return self._drag_start - rect.topLeft() if rect.isValid() else QPoint(20, 10)

    def end_native_drag(self) -> None:
        """Let go of Qt's own in-strip drag, which otherwise waits for a
        release that now goes to the window being carried instead."""
        point = QPointF(self._drag_start)
        QTabBar.mouseReleaseEvent(
            self,
            QMouseEvent(
                QEvent.MouseButtonRelease, point, QPointF(self.mapToGlobal(self._drag_start)),
                Qt.LeftButton, Qt.NoButton, Qt.NoModifier,
            ),
        )

    def insertion_index_at(self, point: QPoint) -> int:
        """Where a tab let go of at this point belongs: before or after
        whichever tab the pointer is on, and at the near end past both."""
        index = self.tabAt(point)
        if index < 0:
            if self.count() and point.x() < self.tabRect(0).left():
                return 0
            return self.count()
        if point.x() > self.tabRect(index).center().x():
            index += 1
        return index

    def dragEnterEvent(self, event: Any) -> None:
        if event.mimeData().hasFormat(self.MIME_META):
            event.setDropAction(Qt.MoveAction)
            event.accept()
            return
        super().dragEnterEvent(event)

    def dragMoveEvent(self, event: Any) -> None:
        if event.mimeData().hasFormat(self.MIME_META):
            event.setDropAction(Qt.MoveAction)
            event.accept()
            return
        super().dragMoveEvent(event)

    def dropEvent(self, event: Any) -> None:
        mime = event.mimeData()
        if not mime.hasFormat(self.MIME_META):
            super().dropEvent(event)
            return
        try:
            metadata = json.loads(bytes(mime.data(self.MIME_META)).decode("utf-8"))
        except (TypeError, ValueError, UnicodeDecodeError):
            event.ignore()
            return
        target_index = self.insertion_index_at(event.position().toPoint())
        source = WINDOW_REGISTRY.get(str(metadata.get("source") or ""))
        identity = int(metadata.get("identity") or 0)
        if source is not None and source._session_index_by_identity(identity) >= 0:
            self.owner._transfer_session_from(source, identity, target_index)
        elif mime.hasFormat(self.MIME_DOCUMENT):
            try:
                document = fitz.open(
                    stream=bytes(mime.data(self.MIME_DOCUMENT)), filetype="pdf"
                )
                # The payload keeps its encryption and carries no password,
                # so ask, as opening the file would; it arrived locked and
                # unusable before.
                password = self.owner._unlock_document(document)
                if document.needs_pass and password is None:
                    document.close()
                    event.ignore()
                    return
                session = DocumentSession(
                    document=document,
                    # A document that arrived from another process is not
                    # bound to any path we may write to: a crafted payload
                    # could otherwise name a file that the next Ctrl+S
                    # would overwrite. It starts unsaved, and Save As asks.
                    file_path="",
                    password=password,
                    page_index=int(metadata.get("page_index") or 0),
                    zoom_mode=str(metadata.get("zoom_mode") or "fit_width"),
                    zoom_percent=int(metadata.get("zoom_percent") or 100),
                    page_layout=str(metadata.get("page_layout") or "single"),
                    continuous=bool(metadata.get("continuous")),
                    facing_cover_separate=bool(metadata.get("facing_cover_separate", True)),
                    dirty=True,
                    needs_full_rewrite=bool(metadata.get("needs_full_rewrite")),
                )
                self.owner._insert_transferred_session(session, target_index)
            except Exception:
                event.ignore()
                return
        else:
            event.ignore()
            return
        event.setDropAction(Qt.MoveAction)
        event.accept()


def is_han_or_kana(char: str) -> bool:
    """Chinese characters, kana and full-width forms: scripts written
    without spaces between words."""
    code = ord(char)
    return (
        0x3000 <= code <= 0x30FF or 0x31F0 <= code <= 0x31FF or 0x3400 <= code <= 0x4DBF
        or 0x4E00 <= code <= 0x9FFF or 0xF900 <= code <= 0xFAFF or 0xFF00 <= code <= 0xFFEF
    )


def is_hangul(char: str) -> bool:
    code = ord(char)
    return 0x1100 <= code <= 0x11FF or 0x3130 <= code <= 0x318F or 0xAC00 <= code <= 0xD7AF


def is_wide_text(text: str) -> bool:
    """Any character of a script whose characters are about as wide as
    they are tall: Chinese characters, kana, Hangul, full-width forms."""
    return any(is_han_or_kana(char) or is_hangul(char) for char in text)


