def ocr_language_name(pack: str) -> str:
    """A language's name in the list: Japanese for a Japanese user, English
    for everyone else (6.11)."""
    japanese, english = OCR_LANGUAGE_NAMES.get(pack, (pack, pack))
    return japanese if I18N.current == "ja" else english


# How the Japanese names with kanji in them read, for the gojūon order of
# the Japanese list (6.26). The other names read as they are written, with
# 語 as ゴ and 文字 as モジ.
OCR_NAME_READINGS: dict[str, str] = {
    "中英語": "チュウエイゴ",
    "数式": "スウシキ",
    "中期フランス語": "チュウキフランスゴ",
    "西フリジア語": "ニシフリジアゴ",
    "イタリア語（古い表記）": "イタリアゴフルイヒョウキ",
    "ジョージア語（古い表記）": "ジョージアゴフルイヒョウキ",
    "スペイン語（古い表記）": "スペインゴフルイヒョウキ",
    "カナダ先住民音節文字": "カナダセンジュウミンオンセツモジ",
    "漢字（簡体字）": "カンジカンタイジ",
    "漢字（繁体字）": "カンジハンタイジ",
    "日本語の文字（漢字・かな）": "ニホンゴノモジカンジカナ",
    "ラテン文字（ヨーロッパの言語など）": "ラテンモジヨーロッパノゲンゴナド",
}
# Gojūon order reads ガ as カ, ャ as ヤ, and ー as the vowel before it; the
# marks and the small kana settle only a tie, plain first (JIS X 4061).
_SMALL_KANA = str.maketrans("ァィゥェォッャュョヮヵヶ", "アイウエオツヤユヨワカケ")
_KANA_VOWELS = {
    kana: vowel
    for vowel, row in (
        ("ア", "アカサタナハマヤラワ"), ("イ", "イキシチニヒミリ"), ("ウ", "ウクスツヌフムユル"),
        ("エ", "エケセテネヘメレ"), ("オ", "オコソトノホモヨロヲ"),
    )
    for kana in row
}


def japanese_reading(name: str) -> str:
    """A Japanese name in katakana, as it reads: OCR_NAME_READINGS, or the
    name with its hiragana as katakana and 語 and 文字 read; the brackets
    and dots between its words left out."""
    reading = OCR_NAME_READINGS.get(name) or name.replace("文字", "モジ").replace("語", "ゴ")
    reading = "".join(chr(ord(char) + 0x60) if "ぁ" <= char <= "ゖ" else char for char in reading)
    return re.sub(r"[（）・\s]", "", reading)


def gojuon_key(name: str) -> tuple[str, str, str]:
    """Where a Japanese name goes in gojūon order."""
    reading = japanese_reading(name)
    plain = unicodedata.normalize("NFD", reading).replace("\u3099", "").replace("\u309a", "")
    letters: list[str] = []
    for char in plain.translate(_SMALL_KANA):
        if char == "ー" and letters:
            char = _KANA_VOWELS.get(letters[-1], char)
        letters.append(char)
    return "".join(letters), reading, name


def ocr_name_order(pack: str) -> tuple[str, str, str]:
    """Where a pack goes in the list: by name, the Japanese names by how
    they read, in gojūon order (6.26)."""
    name = ocr_language_name(pack)
    return gojuon_key(name) if I18N.current == "ja" else (name, name, name)


def ocr_listed_packs() -> list[str]:
    """The languages and scripts to choose from: the common ones, then the
    other languages and the scripts, each by name (ocr_name_order)."""
    rest = [pack for pack in OCR_LANGUAGE_NAMES if pack not in OCR_COMMON_PACKS]
    languages = sorted((pack for pack in rest if not pack.startswith("script/")), key=ocr_name_order)
    scripts = sorted((pack for pack in rest if pack.startswith("script/")), key=ocr_name_order)
    return [*OCR_COMMON_PACKS, *languages, *scripts]


def ocr_with_companions(packs: Iterable[str]) -> list[str]:
    """`packs` with the vertical-text models each loads, in order."""
    found: list[str] = []
    for pack in packs:
        found.append(pack)
        found.extend(OCR_DATA_COMPANIONS.get(pack, ()))
    return list(dict.fromkeys(found))


def ocr_installed_packs(folder: str | Path | None) -> set[str]:
    """The models in a language-data folder: "eng", and "script/Latin" for
    the scripts in its script folder."""
    if not folder:
        return set()
    try:
        root = Path(folder)
        found = {path.stem for path in root.glob("*.traineddata")}
        found |= {f"script/{path.stem}" for path in (root / "script").glob("*.traineddata")}
        return found
    except OSError:
        return set()


def ocr_pack_size(pack: str) -> int:
    """What a language takes, with the models it loads beside it."""
    return sum(OCR_DATA_FILES.get(item, (0, ""))[0] for item in ocr_with_companions([pack]))


def megabytes(value: float) -> str:
    return f"{value / 1_000_000:.0f}"


def document_window_title(title: str) -> str:
    """A window's title with a document in it: the document, a hyphen and
    pdfNote, as Windows' own apps write theirs ("Document1 - Word",
    "Untitled - Notepad"). An em dash until 6.26."""
    return f"{title} - {APP_NAME}"


def file_size_text(size: int, precise: bool = False) -> str:
    """A file's size the way Windows writes one: the number in the
    user's regional format ("1,5" in Germany), the unit in the UI
    language ("Mo" in French, "МБ" in Russian). `precise` gives two
    decimals of a megabyte and one of a kilobyte, as the properties
    dialog; otherwise whole megabytes from 10 MB and whole kilobytes
    below 1 MB, as Explorer's columns (6.25)."""
    locale = QLocale.system()
    if size >= 1048576:
        value = size / 1048576
        decimals = 2 if precise else (0 if value >= 10 else 1)
        return tr("{size} MB").format(size=locale.toString(value, "f", decimals))
    if precise:
        return tr("{size} KB").format(size=locale.toString(size / 1024, "f", 1))
    return tr("{size} KB").format(size=locale.toString(max(1, round(size / 1024))))


def set_unit_suffix(spin: QAbstractSpinBox, unit: str, width: int = 0) -> None:
    """Write a box's unit the way the UI language does -- `unit` is its
    key: " Pt." in German and " 磅" in Chinese for " pt", "100 %" in
    French -- and keep the box wide enough for it (6.25). A fixed
    `width` grows by what the unit is longer than the Japanese; with
    none, the box is as wide as its longest value with the unit, as the
    size boxes always were; -1 leaves the width to the box."""
    suffix = tr(unit) if unit in TRANSLATIONS else unit
    spin.setSuffix(suffix)
    metrics = spin.fontMetrics()
    if width > 0:
        extra = metrics.horizontalAdvance(suffix) - metrics.horizontalAdvance(source_text(unit))
        spin.setFixedWidth(width + max(0, extra))
    elif width == 0:
        longest = spin.textFromValue(spin.maximum()) + suffix
        spin.setFixedWidth(metrics.horizontalAdvance(longest) + 16)


class FontSizeSpinBox(QDoubleSpinBox):
    """The font size box: as wide as its widest value and its unit need
    beside its arrows, as the window's style draws them, in each language.
    It was a fixed 56 px, whose arrows and frame left 26 px for the
    number: "12.0 pt" lost the end of its unit in every language (from
    5.28), and the toolbar's next layout put a longer unit ("pto",
    "نقطة") back into the same 56 px (6.30). Qt's own hints leave some
    20 px more than the box needs."""

    def _fitting_width(self) -> int:
        self.ensurePolished()
        metrics = self.lineEdit().fontMetrics()
        widest = max(
            metrics.horizontalAdvance(self.textFromValue(value) + self.suffix())
            for value in (self.minimum(), self.maximum())
        )
        option = QStyleOptionSpinBox()
        option.initFrom(self)
        option.rect = QRect(0, 0, 200, max(self.height(), 20))
        option.buttonSymbols = self.buttonSymbols()
        option.frame = self.hasFrame()
        option.subControls = (
            QStyle.SC_SpinBoxFrame | QStyle.SC_SpinBoxEditField | QStyle.SC_SpinBoxUp | QStyle.SC_SpinBoxDown
        )
        field = self.style().subControlRect(QStyle.CC_SpinBox, option, QStyle.SC_SpinBoxEditField, self)
        # The line edit keeps 2 px each side of its text, and the cursor
        # takes 2 more after it.
        return widest + 6 + option.rect.width() - field.width()

    def sizeHint(self) -> QSize:  # noqa: N802 - Qt's name
        return QSize(self._fitting_width(), super().sizeHint().height())

    def minimumSizeHint(self) -> QSize:  # noqa: N802 - Qt's name
        return QSize(self._fitting_width(), super().minimumSizeHint().height())


def ocr_data_open(url: str, timeout: float = 30.0) -> Any:
    """The one connection pdfNote opens itself: the OCR language data the
    user has agreed to download (6.5). Everything else pdfNote does stays on
    the PC. The tests put their own function here."""
    import urllib.request

    request = urllib.request.Request(url, headers={"User-Agent": f"{APP_NAME}/{APP_VERSION}"})
    return urllib.request.urlopen(request, timeout=timeout)


class OcrDataDownload(QObject):
    """Fetches OCR language packs on a thread of its own and puts each in the
    folder only once its size and SHA-256 match OCR_DATA_FILES, through a
    temporary file, so a cut connection or a cancel leaves nothing half
    written behind."""

    progress = Signal(int, int)  # bytes so far, bytes in all
    failed = Signal(str)  # the reason; empty when cancelled
    succeeded = Signal()

    CORRUPT = "corrupt"

    def __init__(self, packs: Iterable[str], folder: Path, parent: QObject | None = None) -> None:
        super().__init__(parent)
        self.packs = [pack for pack in packs if pack in OCR_DATA_FILES]
        self.folder = Path(folder)
        self.total = sum(OCR_DATA_FILES[pack][0] for pack in self.packs)
        self._cancel = threading.Event()
        self._thread: threading.Thread | None = None

    def start(self) -> None:
        self._thread = threading.Thread(target=self._run, name="pdfNote OCR data", daemon=True)
        self._thread.start()

    def cancel(self) -> None:
        self._cancel.set()

    def wait(self, timeout: float | None = None) -> bool:
        if self._thread is not None:
            self._thread.join(timeout)
            return not self._thread.is_alive()
        return True

    def _run(self) -> None:
        done = 0
        try:
            self.folder.mkdir(parents=True, exist_ok=True)
            for pack in self.packs:
                size, digest = OCR_DATA_FILES[pack]
                target = self.folder / f"{pack}.traineddata"
                target.parent.mkdir(parents=True, exist_ok=True)
                partial = target.with_name(target.name + ".part")
                try:
                    hasher = hashlib.sha256()
                    received = 0
                    url = OCR_DATA_URL.format(commit=OCR_DATA_COMMIT, pack=pack)
                    with ocr_data_open(url) as response, open(partial, "wb") as stream:
                        while True:
                            if self._cancel.is_set():
                                self.failed.emit("")
                                return
                            chunk = response.read(256 * 1024)
                            if not chunk:
                                break
                            received += len(chunk)
                            if received > size:
                                raise ValueError(self.CORRUPT)
                            hasher.update(chunk)
                            stream.write(chunk)
                            self.progress.emit(done + received, self.total)
                        stream.flush()
                        os.fsync(stream.fileno())
                    if received != size or hasher.hexdigest() != digest:
                        raise ValueError(self.CORRUPT)
                    os.replace(partial, target)
                finally:
                    try:
                        partial.unlink(missing_ok=True)
                    except OSError:
                        pass
                done += size
        except Exception as exc:
            self.failed.emit(str(exc) or exc.__class__.__name__)
            return
        self.succeeded.emit()


class OptionsDialog(QDialog):
    """File > Options (6.24): the settings that stood in the File menu one
    by one -- the language, the theme, and whether a link that leaves the
    document is asked about -- in one window, as Office's Options. Put in
    place with OK; Cancel and Esc leave them as they were."""

    THEMES = (("system", "システムの設定に従う"), ("light", "ライト"), ("dark", "ダーク"))

    def __init__(self, owner: Any) -> None:
        super().__init__(owner)
        self.owner = owner
        self.setWindowTitle(tr("オプション"))
        layout = QVBoxLayout(self)
        form = QFormLayout()
        self.language_box = QComboBox()
        for code, native_name in LANGUAGES:
            self.language_box.addItem(native_name, code)
        self.language_box.setCurrentIndex(max(0, self.language_box.findData(I18N.current)))
        form.addRow(tr("言語"), self.language_box)
        self.theme_box = QComboBox()
        for name, label in self.THEMES:
            self.theme_box.addItem(tr(label), name)
        self.theme_box.setCurrentIndex(max(0, self.theme_box.findData(owner.theme_choice)))
        form.addRow(tr("表示テーマ"), self.theme_box)
        layout.addLayout(form)
        self.confirm_links_box = QCheckBox(tr("リンクを開く前に確認する"))
        self.confirm_links_box.setToolTip(tr("文書の外へのリンク（ウェブ ページやメール）を開く前に確かめる"))
        self.confirm_links_box.setChecked(owner._confirm_links())
        layout.addWidget(self.confirm_links_box)
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        layout.addWidget(buttons)
        self.buttons = buttons

    def accept(self) -> None:
        owner = self.owner
        # The links and the theme first: a new language rebuilds the labels
        # of every window, this one's owner among them.
        if self.confirm_links_box.isChecked() != owner._confirm_links():
            owner._set_confirm_links(self.confirm_links_box.isChecked())
        theme = self.theme_box.currentData()
        if theme != owner.theme_choice:
            owner.set_theme(theme)
        super().accept()
        language = self.language_box.currentData()
        if language != I18N.current:
            owner._set_language(language)


class OcrLanguageChoiceDialog(QDialog):
    """Which languages OCR reads with, this time (6.11). Tesseract reads
    only the languages it is told: ticking Japanese and English reads both
    the Japanese and the alphabet on a page. Listed are the languages whose
    data is here, and those chosen before whose data is not -- marked, and
    downloaded, with the user's leave, before OCR starts."""

    def __init__(
        self, parent: QWidget, installed: set[str], chosen: list[str],
        manage: Callable[[], set[str]],
    ) -> None:
        super().__init__(parent)
        self.setWindowTitle(tr("OCRの言語"))
        self._manage = manage
        layout = QVBoxLayout(self)
        intro = QLabel(tr(
            "読み取る言語を選んでください。複数選ぶと、そのどの言語の文字も読み取ります"
            "（例：日本語と英語を選ぶと、日本語とアルファベットの両方）。"
        ))
        intro.setWordWrap(True)
        layout.addWidget(intro)
        self.list = QListWidget()
        layout.addWidget(self.list, 1)
        self.empty = QLabel(tr("言語データがありません。［言語データの管理］からダウンロードしてください。"))
        self.empty.setWordWrap(True)
        layout.addWidget(self.empty)
        row = QHBoxLayout()
        self.manage_button = QPushButton(tr("言語データの管理..."))
        self.manage_button.clicked.connect(self._open_manager)
        row.addWidget(self.manage_button)
        row.addStretch(1)
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        self.ok_button = buttons.button(QDialogButtonBox.Ok)
        self.ok_button.setText(tr("OCRを実行"))
        buttons.button(QDialogButtonBox.Cancel).setText(tr("キャンセル"))
        buttons.accepted.connect(self.accept)
        buttons.rejected.connect(self.reject)
        row.addWidget(buttons)
        layout.addLayout(row)
        self.list.itemChanged.connect(lambda _item: self._update_ok())
        self._fill(installed, chosen)
        self.resize(440, 480)

    def _fill(self, installed: set[str], chosen: list[str]) -> None:
        self.list.blockSignals(True)
        self.list.clear()
        for pack in ocr_listed_packs():
            if pack not in installed and pack not in chosen:
                continue
            text = ocr_language_name(pack)
            if pack not in installed:
                text = tr("{name}  （ダウンロードが必要）").format(name=text)
            item = QListWidgetItem(text)
            item.setData(Qt.UserRole, pack)
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
            item.setCheckState(Qt.Checked if pack in chosen else Qt.Unchecked)
            self.list.addItem(item)
        self.list.blockSignals(False)
        self.empty.setVisible(self.list.count() == 0)
        self._update_ok()

    def _open_manager(self) -> None:
        self._fill(self._manage(), self.languages())

    def languages(self) -> list[str]:
        """The ticked languages, in the list's order."""
        return [
            self.list.item(row).data(Qt.UserRole)
            for row in range(self.list.count())
            if self.list.item(row).checkState() == Qt.Checked
        ]

    def set_checked(self, pack: str, checked: bool) -> None:
        for row in range(self.list.count()):
            item = self.list.item(row)
            if item.data(Qt.UserRole) == pack:
                item.setCheckState(Qt.Checked if checked else Qt.Unchecked)

    def _update_ok(self) -> None:
        self.ok_button.setEnabled(bool(self.languages()))


class OcrDataDialog(QDialog):
    """OCR's language data (6.11): every language and script Tesseract's
    best models read, to tick and download whatever the display language,
    and what pdfNote's folder holds, to delete what is no longer needed.
    Downloading asks first, as OCR's own download does (6.5), and names
    where the data comes from."""

    def __init__(self, window: Any) -> None:
        super().__init__(window)
        self._window = window
        self.setWindowTitle(tr("OCRの言語データ"))
        layout = QVBoxLayout(self)
        self.tabs = QTabWidget()
        layout.addWidget(self.tabs, 1)

        page = QWidget()
        column = QVBoxLayout(page)
        self.search = QLineEdit()
        self.search.setPlaceholderText(tr("言語を検索"))
        self.search.setClearButtonEnabled(True)
        self.search.textChanged.connect(self._filter)
        column.addWidget(self.search)
        self.available = QListWidget()
        self.available.itemChanged.connect(lambda _item: self._update_summaries())
        column.addWidget(self.available, 1)
        row = QHBoxLayout()
        self.download_summary = QLabel()
        row.addWidget(self.download_summary, 1)
        self.download_button = QPushButton(tr("ダウンロード"))
        self.download_button.clicked.connect(self._download)
        row.addWidget(self.download_button)
        column.addLayout(row)
        source = QLabel(tr("ダウンロード元: GitHub（Tesseract OCR プロジェクト）"))
        source.setWordWrap(True)
        column.addWidget(source)
        self.tabs.addTab(page, tr("ダウンロード"))

        page = QWidget()
        column = QVBoxLayout(page)
        self.installed_list = QListWidget()
        self.installed_list.itemChanged.connect(lambda _item: self._update_summaries())
        column.addWidget(self.installed_list, 1)
        row = QHBoxLayout()
        self.installed_summary = QLabel()
        row.addWidget(self.installed_summary, 1)
        folder_button = QPushButton(tr("フォルダーを開く"))
        folder_button.clicked.connect(window.open_ocr_data_folder)
        row.addWidget(folder_button)
        self.delete_button = QPushButton(tr("削除"))
        self.delete_button.clicked.connect(self._delete)
        row.addWidget(self.delete_button)
        column.addLayout(row)
        self.tabs.addTab(page, tr("ダウンロード済み"))

        buttons = QDialogButtonBox(QDialogButtonBox.Close)
        buttons.button(QDialogButtonBox.Close).setText(tr("閉じる"))
        buttons.rejected.connect(self.reject)
        layout.addWidget(buttons)
        self.refresh()
        self.resize(480, 560)

    def refresh(self) -> None:
        """Read the folder again and list what it holds."""
        folder = self._window.user_tessdata_dir()
        self.installed = ocr_installed_packs(folder)
        self.available.blockSignals(True)
        self.available.clear()
        for pack in ocr_listed_packs():
            item = QListWidgetItem()
            item.setData(Qt.UserRole, pack)
            size = megabytes(ocr_pack_size(pack))
            if pack in self.installed:
                item.setText(
                    tr("{name}  ({size} MB) — ダウンロード済み").format(
                        name=ocr_language_name(pack), size=size
                    )
                )
                item.setFlags(item.flags() & ~Qt.ItemIsEnabled)
            else:
                item.setText(tr("{name}  ({size} MB)").format(name=ocr_language_name(pack), size=size))
                item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
                item.setCheckState(Qt.Unchecked)
            self.available.addItem(item)
        self.available.blockSignals(False)
        self._filter(self.search.text())
        self.installed_list.blockSignals(True)
        self.installed_list.clear()
        # Every language in the folder, a file put there by hand included;
        # a vertical model goes with its language.
        listed = [pack for pack in ocr_listed_packs() if pack in self.installed]
        others = sorted(self.installed - set(listed) - OCR_COMPANION_PACKS)
        for pack in [*listed, *others]:
            on_disk = sum(
                self._file_size(folder / f"{item}.traineddata") for item in ocr_with_companions([pack])
            )
            name = ocr_language_name(pack) if pack in OCR_LANGUAGE_NAMES else pack
            item = QListWidgetItem(tr("{name}  ({size} MB)").format(name=name, size=megabytes(on_disk)))
            item.setData(Qt.UserRole, pack)
            item.setFlags(item.flags() | Qt.ItemIsUserCheckable)
            item.setCheckState(Qt.Unchecked)
            self.installed_list.addItem(item)
        self.installed_list.blockSignals(False)
        self._update_summaries()

    @staticmethod
    def _file_size(path: Path) -> int:
        try:
            return path.stat().st_size
        except OSError:
            return 0

    @staticmethod
    def _checked(listing: QListWidget) -> list[str]:
        return [
            listing.item(row).data(Qt.UserRole)
            for row in range(listing.count())
            if listing.item(row).flags() & Qt.ItemIsUserCheckable
            and listing.item(row).checkState() == Qt.Checked
        ]

    def checked_downloads(self) -> list[str]:
        return self._checked(self.available)

    def checked_installed(self) -> list[str]:
        return self._checked(self.installed_list)

    def set_checked(self, listing: QListWidget, pack: str, checked: bool) -> None:
        for row in range(listing.count()):
            item = listing.item(row)
            if item.data(Qt.UserRole) == pack and item.flags() & Qt.ItemIsUserCheckable:
                item.setCheckState(Qt.Checked if checked else Qt.Unchecked)

    def _filter(self, text: str) -> None:
        """Rows whose name -- in Japanese or in English -- or code holds the
        text."""
        wanted = text.strip().casefold()
        for row in range(self.available.count()):
            item = self.available.item(row)
            pack = item.data(Qt.UserRole)
            japanese, english = OCR_LANGUAGE_NAMES.get(pack, (pack, pack))
            haystack = " ".join((japanese, english, pack, OCR_PACK_NAMES.get(pack, ""))).casefold()
            self.available.setRowHidden(row, bool(wanted) and wanted not in haystack)

    def _update_summaries(self) -> None:
        chosen = self.checked_downloads()
        size = sum(ocr_pack_size(pack) for pack in chosen)
        self.download_summary.setText(
            tr_n("{count} 言語を選択（約 {size} MB）", len(chosen)).format(
                count=len(chosen), size=megabytes(size)
            )
        )
        self.download_button.setEnabled(bool(chosen) and self._window._ocr_download is None)
        self.installed_summary.setText(
            tr_n("{count} 言語（約 {size} MB）", self.installed_list.count()).format(
                count=self.installed_list.count(),
                size=megabytes(sum(
                    self._file_size(self._window.user_tessdata_dir() / f"{pack}.traineddata")
                    for pack in self.installed
                )),
            )
        )
        self.delete_button.setEnabled(bool(self.checked_installed()))

    def _download(self) -> None:
        packs = self.checked_downloads()
        if packs:
            self._window._download_ocr_data(packs, then=self.refresh, parent=self)
            self._update_summaries()

    def _delete(self) -> None:
        packs = self.checked_installed()
        if not packs:
            return
        answer = QMessageBox.question(
            self, tr("OCRの言語データ"),
            tr_n("選んだ {count} 言語の言語データを削除しますか？", len(packs)).format(count=len(packs))
            + "\n\n" + tr("、").join(
                ocr_language_name(pack) if pack in OCR_LANGUAGE_NAMES else pack for pack in packs
            ),
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No,
        )
        if answer == QMessageBox.Yes:
            self._window.delete_ocr_data(packs)
            self.refresh()


class OcrMixin:
    """OCR: recognition, and writing the result back as an invisible text
    layer so search, selection, copying and highlighting all work on it."""

    # Tesseract language packs for each UI language (and system language).
    OCR_LANGUAGE_PACKS: dict[str, tuple[str, ...]] = {
        "ja": ("jpn",), "zh_CN": ("chi_sim",), "ko": ("kor",), "es": ("spa",),
        "fr": ("fra",), "ru": ("rus",), "ar": ("ara",), "en": (),
        "de": ("deu",), "pt": ("por",), "pt_BR": ("por",), "pt_PT": ("por",),
        "hi": ("hin",), "bn": ("ben",), "ur": ("urd",), "la": ("lat",),
        "grc": ("grc",), "sa": ("san",), "da": ("dan",), "non": (),
    }

    @staticmethod
    def user_tessdata_dir() -> Path:
        """pdfNote's own language-data folder. Tesseract's .traineddata files
        placed here are all OCR needs -- no installer (v5.20)."""
        return app_data_dir() / "tessdata"

    @staticmethod
    def ocr_tessdata() -> str | None:
        """Tesseract's language-data folder, or None when OCR is unavailable.

        MuPDF has Tesseract built in and needs only this folder. Requiring
        tesseract.exe on PATH -- which the Windows installer does not add --
        hid OCR from most people who had installed it. Nothing is launched
        here: pymupdf.get_tessdata() runs a shell command, which flashes a
        console window from a windowed application.
        """
        candidates: list[Path] = []
        prefix = os.environ.get("TESSDATA_PREFIX")
        if prefix:
            candidates.append(Path(prefix))
        # Data put in pdfNote's own folder comes before an installed
        # Tesseract's: someone who put it there meant it to be used.
        candidates.append(OcrMixin.user_tessdata_dir())
        binary = shutil.which("tesseract")
        if binary:
            candidates.append(Path(binary).resolve().parent / "tessdata")
        for variable, subfolder in (
            ("ProgramFiles", ""), ("ProgramFiles(x86)", ""), ("LOCALAPPDATA", "Programs"),
        ):
            base = os.environ.get(variable)
            if base:
                root = Path(base) / subfolder if subfolder else Path(base)
                candidates.append(root / "Tesseract-OCR" / "tessdata")
        for candidate in candidates:
            try:
                if candidate.is_dir() and any(candidate.glob("*.traineddata")):
                    return str(candidate)
            except OSError:
                continue
        return None

    @staticmethod
    def ocr_available() -> bool:
        """Tesseract is an optional external dependency; the app has to run
        normally without it."""
        return OcrMixin.ocr_tessdata() is not None

    def _ocr_data_missing_message(self) -> str:
        return tr(
            "OCRの言語データがありません。{folder} に言語データ (.traineddata) を置くか、"
            "Tesseract OCRをインストールしてください。"
        ).format(folder=self.user_tessdata_dir())

    def open_ocr_data_folder(self) -> bool:
        """Create pdfNote's language-data folder and open it in Explorer, so
        the .traineddata files can simply be dropped in."""
        folder = self.user_tessdata_dir()
        try:
            folder.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass
        opened = folder.is_dir() and self._open_local_folder(folder)
        if not opened:
            self.status_label.setText(
                tr("フォルダーを開けませんでした: {folder}").format(folder=folder)
            )
        return opened

    @staticmethod
    def _open_local_folder(folder: Path) -> bool:
        return QDesktopServices.openUrl(QUrl.fromLocalFile(str(folder)))

    @staticmethod
    def ocr_language_codes(installed: set[str], ui_language: str, system_locale: str = "") -> str:
        """The Tesseract language string ("jpn+eng") to recognise with.

        Tesseract reads only the languages it is told to, and the default is
        English alone -- so a Japanese scan came back as noise. The UI
        language and the system language both count, because a Japanese
        Windows user may well run pdfNote in English.
        """
        system = system_locale.split("_")[0] if system_locale else ""
        wanted: list[str] = []
        for code in (ui_language, "zh_CN" if system == "zh" else system):
            wanted.extend(OcrMixin.OCR_LANGUAGE_PACKS.get(code, ()))
        wanted.append("eng")
        chosen = [pack for pack in dict.fromkeys(wanted) if pack in installed]
        if not chosen and installed:
            chosen = [sorted(installed)[0]]
        return "+".join(chosen) or "eng"

    @staticmethod
    def ocr_wanted_packs(ui_language: str, system_locale: str = "") -> list[str]:
        """The language packs OCR reads with, as ocr_language_codes picks
        them, with the vertical-text models they load beside them."""
        system = system_locale.split("_")[0] if system_locale else ""
        wanted: list[str] = []
        for code in (ui_language, "zh_CN" if system == "zh" else system):
            wanted.extend(OcrMixin.OCR_LANGUAGE_PACKS.get(code, ()))
        wanted.append("eng")
        packs: list[str] = []
        for pack in dict.fromkeys(wanted):
            packs.append(pack)
            packs.extend(OCR_DATA_COMPANIONS.get(pack, ()))
        return list(dict.fromkeys(packs))

    def _ocr_missing_packs(self, languages: list[str] | None = None) -> list[str]:
        """The packs to download before OCR reads in full: none when the
        folder in use has them all, or is one the user pointed
        TESSDATA_PREFIX at. Downloads go to pdfNote's own folder, which is
        used from then on, so what it lacks is what is missing (6.5). The
        packs are those of `languages`, chosen for the run (6.11), or the
        ones the display and Windows languages want."""
        if languages is None:
            wanted = self.ocr_wanted_packs(I18N.current, QLocale.system().name())
        else:
            wanted = ocr_with_companions(languages)

        def packs_in(folder: str | Path) -> set[str]:
            return ocr_installed_packs(folder)

        current = self.ocr_tessdata()
        own = self.user_tessdata_dir()
        if current is not None and Path(current) != own:
            if all(pack in packs_in(current) for pack in wanted):
                return []
            prefix = os.environ.get("TESSDATA_PREFIX")
            if prefix and Path(current) == Path(prefix):
                return []
        have = packs_in(own)
        return [pack for pack in wanted if pack not in have and pack in OCR_DATA_FILES]

    def _ocr_language_data_ready(self, then: Callable[[], object]) -> bool:
        """Whether OCR can start now. First the languages to read with are
        chosen (6.11). When packs they need are missing, asks to download
        them; once they are in place `then` runs again, with the same
        languages. Declined, OCR goes on with whatever data there is (6.5)."""
        if self._ocr_download is not None:
            return False
        languages = getattr(self, "_ocr_retry_languages", None)
        self._ocr_retry_languages = None
        if languages is None:
            languages = self._choose_ocr_languages()
            if languages is None:
                return False
        missing = self._ocr_missing_packs(languages)
        if missing and self._ask_ocr_download(missing):
            self._ocr_retry_languages = languages
            self._start_ocr_download(missing, then)
            return False
        if not self.ocr_available():
            self.status_label.setText(self._ocr_data_missing_message())
            return False
        self._ocr_chosen_languages = languages
        return True

    def _ocr_default_languages(self) -> list[str]:
        """The languages a run starts ticked with: the ones chosen last time,
        or those of the display language and of Windows, and English."""
        remembered = self.settings.data.get("ocr_languages")
        if isinstance(remembered, list) and remembered:
            return [str(pack) for pack in remembered]
        wanted = self.ocr_wanted_packs(I18N.current, QLocale.system().name())
        return [pack for pack in wanted if pack not in OCR_COMPANION_PACKS]

    def _choose_ocr_languages(self) -> list[str] | None:
        """Ask which languages this run reads (6.11), and remember them for
        the next. None when the user cancels."""
        default = self._ocr_default_languages()
        installed = ocr_installed_packs(self.ocr_tessdata())
        chosen = self._ask_ocr_languages(installed, default)
        if chosen is None:
            return None
        if chosen != default:
            self.settings.data["ocr_languages"] = list(chosen)
            if not self.test_mode:
                self.settings.save()
        return chosen

    def _ask_ocr_languages(self, installed: set[str], default: list[str]) -> list[str] | None:
        """The language window. The checks run without it, on `default`."""
        if self.test_mode:
            return list(default)
        dialog = OcrLanguageChoiceDialog(self, installed, default, self.manage_ocr_data)
        if dialog.exec() != QDialog.Accepted:
            return None
        return dialog.languages()

    def manage_ocr_data(self) -> set[str]:
        """The OCR language data window (6.11). Returns the languages the
        folder OCR reads from holds afterwards."""
        dialog = OcrDataDialog(self)
        self._ocr_data_dialog = dialog
        try:
            dialog.exec()
        finally:
            self._ocr_data_dialog = None
            dialog.deleteLater()
        return ocr_installed_packs(self.ocr_tessdata())

    def _download_ocr_data(
        self, languages: list[str], then: Callable[[], object], parent: QWidget | None = None
    ) -> bool:
        """Download languages chosen in the language data window, with the
        vertical models they load, once the user agrees."""
        if self._ocr_download is not None:
            return False
        have = ocr_installed_packs(self.user_tessdata_dir())
        packs = [pack for pack in ocr_with_companions(languages) if pack not in have and pack in OCR_DATA_FILES]
        if not packs or not self._ask_ocr_download(packs, parent):
            return False
        self._start_ocr_download(packs, then, parent)
        return True

    def delete_ocr_data(self, languages: list[str]) -> list[str]:
        """Delete languages from pdfNote's folder, with the vertical models
        that came with them. Not while OCR runs: it reads them."""
        if self._ocr_worker is not None:
            self.status_label.setText(tr("OCRの実行中は言語データを削除できません"))
            return []
        folder = self.user_tessdata_dir()
        removed: list[str] = []
        for pack in ocr_with_companions(languages):
            target = folder / f"{pack}.traineddata"
            try:
                target.unlink()
            except FileNotFoundError:
                continue
            except OSError:
                continue
            removed.append(pack)
        remembered = self.settings.data.get("ocr_languages")
        if isinstance(remembered, list):
            kept = [pack for pack in remembered if pack not in removed]
            if kept != remembered:
                self.settings.data["ocr_languages"] = kept
                if not self.test_mode:
                    self.settings.save()
        return removed

    def _ask_ocr_download(self, packs: list[str], parent: QWidget | None = None) -> bool:
        # Named as the list names them, where they were chosen (6.26): the
        # question gave some in their own language -- "Deutsch" for the
        # ドイツ語 ticked in a Japanese list.
        shown = [pack for pack in packs if pack not in OCR_COMPANION_PACKS]
        names = tr("、").join(ocr_language_name(pack) for pack in shown[:12])
        if len(shown) > 12:
            # The rest counted the language's way, list and all: a space put
            # it after the list in the code, "英语 另有 3 种语言" (6.25).
            names = tr_n("{languages} ほか {count} 言語", len(shown) - 12).format(
                languages=names, count=len(shown) - 12
            )
        size = sum(OCR_DATA_FILES[pack][0] for pack in packs if pack in OCR_DATA_FILES) / 1_000_000
        answer = QMessageBox.question(
            parent or self,
            tr("OCRの言語データ"),
            tr(
                "OCRには言語データが必要です。次の言語データをダウンロードしますか？\n\n"
                "{languages}（約 {size} MB）\n\n"
                "ダウンロード元: GitHub（Tesseract OCR プロジェクト）。接続するのは、このダウンロードのときだけです。"
            ).format(languages=names, size=f"{size:.0f}"),
            QMessageBox.Yes | QMessageBox.No,
            QMessageBox.Yes,
        )
        return answer == QMessageBox.Yes

    def _start_ocr_download(
        self, packs: list[str], then: Callable[[], object], parent: QWidget | None = None
    ) -> None:
        download = OcrDataDownload(packs, self.user_tessdata_dir(), parent=self)
        label = tr("OCRの言語データをダウンロードしています… ({done} / {total} MB)")
        dialog = QProgressDialog(
            label.format(done=0, total=megabytes(download.total)), tr("キャンセル"), 0, 1000,
            parent or self,
        )
        dialog.setWindowTitle(tr("OCRの言語データ"))
        dialog.setWindowModality(Qt.WindowModal)
        dialog.setMinimumDuration(0)
        dialog.setAutoClose(False)
        dialog.setAutoReset(False)
        self._ocr_download_dialog = dialog

        def progress(done: int, total: int) -> None:
            dialog.setValue(int(done * 1000 / max(total, 1)))
            dialog.setLabelText(label.format(done=megabytes(done), total=megabytes(total)))

        def finish() -> None:
            self._ocr_download = None
            self._ocr_download_dialog = None
            dialog.close()
            dialog.deleteLater()

        def failed(reason: str) -> None:
            finish()
            # The next OCR asks for its languages again.
            self._ocr_retry_languages = None
            if not reason:
                return
            if reason == OcrDataDownload.CORRUPT:
                reason = tr("ダウンロードしたデータが壊れています。もう一度お試しください。")
            QMessageBox.warning(
                parent or self, APP_NAME,
                tr("OCRの言語データをダウンロードできませんでした。\n\n{error}").format(error=reason),
            )

        def succeeded() -> None:
            finish()
            then()

        download.progress.connect(progress)
        download.failed.connect(failed)
        download.succeeded.connect(succeeded)
        dialog.canceled.connect(download.cancel)
        self._ocr_download = download
        download.start()
        dialog.show()

    @staticmethod
    def _page_object_xref(document: fitz.Document, page_index: int) -> int:
        """Which object a page index points at, to tell later whether the
        pages have moved under a running job."""
        try:
            return int(document.page_xref(page_index))
        except Exception:
            return -1

    def _ocr_pages_in_place(self, document: fitz.Document | None) -> set[int] | None:
        """The pages a running OCR job may still write to in `document`, or
        None when no job runs on it. Asked right before a save replaces the
        Document with a reopened copy of the same content."""
        if document is None or self._ocr_document is not document:
            return None
        return {
            index for index, mark in self._ocr_page_marks.items()
            if self._page_object_xref(document, index) == mark
        }

    def _document_reopened(
        self, old: fitz.Document, new: fitz.Document, ocr_pages: set[int] | None
    ) -> None:
        """A save put the same content in a new Document object. A running
        OCR job carries on with it, for the pages that had not moved."""
        if ocr_pages is None or self._ocr_document is not old:
            return
        self._ocr_document = new
        self._ocr_page_marks = {
            index: self._page_object_xref(new, index) if index in ocr_pages else -2
            for index in self._ocr_page_marks
        }

    def _ocr_settings(self) -> tuple[str | None, str]:
        """The folder and the languages ("jpn+eng") of a run: the languages
        chosen for it (6.11) that are there, or as the display and Windows
        languages want them."""
        tessdata = self.ocr_tessdata()
        installed = ocr_installed_packs(tessdata)
        chosen = [
            pack for pack in (getattr(self, "_ocr_chosen_languages", None) or [])
            if pack in installed
        ]
        self._ocr_chosen_languages = None
        if chosen:
            return tessdata, "+".join(chosen)
        return tessdata, self.ocr_language_codes(
            installed, I18N.current, QLocale.system().name()
        )

    def _page_needs_ocr(self, page: fitz.Page) -> bool:
        try:
            return len(page.get_text().strip()) < self.OCR_TEXT_THRESHOLD
        except Exception:
            return False

    @staticmethod
    def _ocr_words(
        page: fitz.Page,
        dpi: int = 300,
        language: str = "eng",
        tessdata: str | None = None,
    ) -> list[tuple[float, float, float, float, str, int]]:
        """Recognised words with their page rectangles and block numbers."""
        textpage = page.get_textpage_ocr(
            flags=0, language=language, dpi=dpi, full=True, tessdata=tessdata
        )
        words = page.get_text("words", textpage=textpage)
        result = []
        for entry in words:
            x0, y0, x1, y1, text = entry[0], entry[1], entry[2], entry[3], entry[4]
            if str(text).strip():
                result.append(
                    (float(x0), float(y0), float(x1), float(y1), str(text), int(entry[5]))
                )
        return result

    @staticmethod
    def _ocr_lines(words: list[tuple]) -> list[tuple[float, float, float, float, str]]:
        """Recognised words, joined into the lines they sit on.

        Written word by word, a Japanese line came out as a row of separate
        runs: MuPDF's OCR output puts each Japanese character on a line of
        its own, with a right edge hundreds of points out, and Tesseract
        separates the characters with spaces -- so nothing longer than one
        character could be searched for (v5.20). Words are grouped by where
        they sit instead: the same block, overlapping vertically, running
        left to right. A Chinese character or kana is taken to be about as
        wide as the line is tall, and joins its neighbours without a space.
        """
        lines: list[list[tuple[float, float, float, float, str]]] = []
        blocks: list[int] = []
        for entry in words:
            x0, y0, x1, y1 = (float(value) for value in entry[:4])
            text = str(entry[4]).strip()
            block = int(entry[5]) if len(entry) > 5 else 0
            if not text:
                continue
            if lines and blocks[-1] == block:
                line = lines[-1]
                top = min(item[1] for item in line)
                bottom = max(item[3] for item in line)
                overlap = min(bottom, y1) - max(top, y0)
                if overlap >= 0.5 * min(bottom - top, y1 - y0) and x0 >= line[-1][0] - 2.0:
                    line.append((x0, y0, x1, y1, text))
                    continue
            lines.append([(x0, y0, x1, y1, text)])
            blocks.append(block)

        def median(values: list[float]) -> float:
            ordered = sorted(values)
            middle = len(ordered) // 2
            if len(ordered) % 2:
                return ordered[middle]
            return (ordered[middle - 1] + ordered[middle]) / 2

        result = []
        for line in lines:
            height = median([item[3] - item[1] for item in line])
            text = ""
            right = line[0][0]
            for x0, _y0, x1, _y1, piece in line:
                if is_wide_text(piece):
                    x1 = min(x1, x0 + len(piece) * height * 1.1)
                right = max(right, x1)
                if text and not (is_han_or_kana(text[-1]) or is_han_or_kana(piece[0])):
                    text += " "
                text += piece
            result.append((
                line[0][0], median([item[1] for item in line]), right,
                median([item[3] for item in line]), text,
            ))
        return result

    # The built-in CJK font for each Tesseract language: each encodes its
    # own script. Chinese and Korean lines written in the Japanese font
    # lost every character that font has no code for.
    OCR_CJK_FONTS = (
        ("chi_sim", "china-s"), ("chi_tra", "china-t"), ("kor", "korea"), ("jpn", "japan"),
    )

    @staticmethod
    def _ocr_fonts(text: str, wide_font: str) -> tuple[str, ...]:
        """Built-in fonts that can hold `text`, best first.

        Base-14 Helvetica holds Latin-1 only. Anything else it writes as
        dots -- or, for CJK, not at all -- without raising, so a Japanese
        page once counted as OCR'd with an empty layer. The Japanese font
        also holds Cyrillic, Greek, "œ" and "€"; Hangul needs the Korean
        one. None of them holds Arabic.
        """
        if any(is_hangul(char) for char in text):
            return ("korea", wide_font)
        if is_wide_text(text):
            return (wide_font, "japan")
        try:
            text.encode("latin-1")
            return ("helv", "japan")
        except UnicodeEncodeError:
            return ("japan", "helv")

    @staticmethod
    def _apply_ocr_words(page: fitz.Page, words: list[tuple], language: str = "") -> int:
        """Lay the recognised text over the page as invisible text: one run
        per line, stretched to the line's width so that selecting and
        highlighting follow the characters of the scan. Returns the number
        of lines written."""
        packs = language.split("+")
        wide_font = next(
            (font for pack, font in OcrMixin.OCR_CJK_FONTS if pack in packs), "japan"
        )
        contents_before = set(page.get_contents())
        applied = 0
        for x0, y0, x1, y1, text in OcrMixin._ocr_lines(words):
            height = max(1.0, y1 - y0)
            wide = is_wide_text(text)
            # Word boxes are measured on the ink. A Latin word's runs from
            # ascender to descender; a Chinese character fills about nine
            # tenths of the em and sits just above the baseline.
            fontsize = height * (1.1 if wide else 0.85)
            point = fitz.Point(x0, y1 - height * (0.08 if wide else 0.18))
            for fontname in OcrMixin._ocr_fonts(text, wide_font):
                try:
                    natural = fitz.get_text_length(text, fontname=fontname, fontsize=fontsize)
                    scale = min(4.0, max(0.25, (x1 - x0) / natural)) if natural > 0 else 1.0
                    page.insert_text(
                        point, text, fontsize=fontsize, fontname=fontname, render_mode=3,
                        morph=(point, fitz.Matrix(scale, 1)),
                    )
                    applied += 1
                    break
                except Exception:
                    continue
        OcrMixin._join_added_streams(page, contents_before)
        return applied

    @staticmethod
    def _join_added_streams(page: fitz.Page, before: set[int]) -> None:
        """One content stream for the page's OCR text instead of one per line.

        insert_text() adds a stream for every call, each a whole q ... Q,
        so they join end to end unchanged. Fifty lines made fifty objects
        on every scanned page (6.1)."""
        from pymupdf import mupdf

        document = page.parent
        added = [xref for xref in page.get_contents() if xref not in before]
        if len(added) < 2:
            return
        try:
            joined = b"\n".join(document.xref_stream(xref) for xref in added)
            contents = mupdf.pdf_dict_get(
                mupdf.pdf_lookup_page_obj(_pdf_of(document), page.number),
                mupdf.PDF_ENUM_NAME_Contents,
            )
            contents = mupdf.pdf_resolve_indirect(contents)
            if not mupdf.pdf_is_array(contents):
                return
            document.update_stream(added[0], joined)
            for position in range(mupdf.pdf_array_len(contents) - 1, -1, -1):
                if mupdf.pdf_to_num(mupdf.pdf_array_get(contents, position)) in added[1:]:
                    mupdf.pdf_array_delete(contents, position)
        except Exception:
            return

    def ocr_current_page(self) -> bool:
        """OCR the page on screen, off the UI thread. Tesseract takes
        seconds over a page, and run here it held the window still for
        every one of them."""
        if self.document is None or self._premium_blocked("OCR"):
            return False
        if not self._ocr_language_data_ready(self.ocr_current_page):
            return False
        return self._start_ocr([self.page_index], single_page=True)

    def _finish_ocr_page(self, session: "DocumentSession", page_index: int) -> None:
        """Drop the caches built from the pre-OCR page text of `session`.

        Takes the session explicitly: a background run finishes pages long
        after the user may have moved to another tab, and only that tab's
        caches and dirty flag should move.
        """
        document = session.document
        if document is not None:
            self._page_characters_cache.pop((id(document), page_index), None)
        session.dirty = True
        session.revision += 1
        session.state_id = next(DOCUMENT_STATE_IDS)
        if session is not self._current_session():
            # Another tab is in front: update that tab's label and leave the
            # visible document's caches and render queue alone.
            if session in self.sessions:
                self.document_tabs.setTabText(self.sessions.index(session), session.title)
            return
        self._invalidate_render_cache(page_index)
        self._mark_dirty()
        if page_index == self.page_index:
            self.schedule_render(immediate=True)

    def ocr_document(self) -> bool:
        """OCR every scanned page, off the UI thread."""
        if self.document is None or self._premium_blocked("OCR"):
            return False
        if not self._ocr_language_data_ready(self.ocr_document):
            return False
        # Which pages need OCR is decided on the worker thread. Asking every
        # page for its text here froze the window for seconds on a long
        # document before anything visible happened.
        return self._start_ocr(list(range(len(self.document))), single_page=False)

    def _start_ocr(self, targets: list[int], single_page: bool) -> bool:
        """Start a background OCR run over `targets`. A single page is
        recognised whatever text it has already, as asked; a whole
        document only where a page has too little text."""
        if self._ocr_worker is not None:
            return False
        session = self._current_session()
        if session is None:
            return False
        # Pages can be deleted, inserted or undone while a run is going, so
        # remember which object each index points at now. A result that
        # comes back for a page that has moved is dropped instead of being
        # written onto whatever page took its place.
        if not self._finish_active_overlays():
            self.status_label.setText(tr("編集を確定できなかったため中止しました"))
            return False
        # And what each page draws: a page changed before its result comes
        # back -- redacted, a picture taken off -- must not get the words
        # read from the copy of how it was. Those words are invisible text:
        # a redaction would have come back as text to search and copy (6.2).
        self._ocr_page_marks = {index: self._ocr_page_mark(self.document, index) for index in targets}
        # The worker gets its own copy of the bytes: a PyMuPDF document must
        # not be touched from two threads, and the recognised words are
        # applied back here on the GUI thread.
        #
        # This must go through the one serializer. A plain tobytes() does not
        # merely hand the worker a decrypted copy: it drops the encryption
        # from *this* document too, so the next save writes an unencrypted
        # header over still-encrypted streams and the user's file becomes
        # unreadable (v5.26 defect F3-01). Taken before the undo snapshot so
        # a failure here leaves nothing behind to withdraw.
        try:
            data = serialize_document(self.document)
        except Exception as exc:
            QMessageBox.critical(
                self, APP_NAME,
                tr("OCRを実行できませんでした。\n\n{error}").format(error=exc),
            )
            return False
        # The undo step taken here is withdrawn again if nothing is applied.
        self._ocr_history = (session, len(session.undo_stack), list(session.redo_stack))
        self._snapshot_for_edit()
        # Remember which document this run belongs to. Results arrive later,
        # by which time the user may be looking at another tab.
        self._ocr_session = session
        self._ocr_document = self.document
        self._ocr_generation = session.history_generation
        tessdata, language = self._ocr_settings()
        self._ocr_language = language
        # In a process of its own: PyMuPDF must not run on two threads (6.2).
        self._ocr_worker = OcrProcess(
            data, targets, language, tessdata,
            skip_threshold=None if single_page else self.OCR_TEXT_THRESHOLD,
            password=session.password,
            parent=self,
        )
        self._ocr_worker.pageReady.connect(self._ocr_page_ready)
        self._ocr_worker.progress.connect(self._ocr_progress)
        self._ocr_worker.failed.connect(self._ocr_failed)
        self._ocr_worker.finished.connect(self._ocr_finished)
        self._ocr_applied_pages = 0
        self._ocr_error = ""
        self._ocr_single_page = single_page
        self._ocr_unwritten = False
        self._ocr_stopped_by = ""
        self._ocr_worker.start()
        self.act_ocr_page.setEnabled(False)
        self.act_ocr_document.setEnabled(False)
        self.act_ocr_cancel.setEnabled(True)
        self.status_label.setText(
            tr("OCR中… ({done}/{total})").format(done=0, total=len(targets))
        )
        return True

    def _ocr_page_ready(self, page_index: int, words: object) -> None:
        if not isinstance(words, list) or not words:
            return
        session = self._ocr_session
        # The originating tab may have been closed, or replaced by an undo
        # that swapped in a different Document. Either way the result no
        # longer belongs anywhere and writing it would corrupt whatever is
        # open now.
        if session is None or session not in self.sessions:
            return
        document = session.document
        if document is None or document.is_closed:
            return
        if (
            document is not self._ocr_document
            or session.history_generation != getattr(self, "_ocr_generation", 0)
        ):
            # An undo or redo since the run started: with snapshots it put
            # a new Document in place, with the journal it changed this one.
            # Either way the pages carry the same object numbers, so the
            # page check below let a result made from the older state
            # through.
            return
        try:
            page = document[page_index]
        except Exception:
            return
        expected = self._ocr_page_marks.get(page_index)
        if expected is None:
            # Not a page this run was started for, or no longer one it may
            # write to (see _stop_ocr_for).
            return
        if self._page_object_xref(document, page_index) != expected[0]:
            # The pages moved under the run: this result belongs to a page
            # that is no longer at this index.
            return
        if page_content_fingerprint(document, page_index) != expected[1]:
            # The page changed after the copy was taken (6.2).
            return
        # Count only pages that got text: nothing written is no page done
        # (the single-page run already checked this).
        if not self._apply_ocr_words(page, words, self._ocr_language):  # type: ignore[arg-type]
            self._ocr_unwritten = True
            return
        self._ocr_applied_pages += 1
        self._finish_ocr_page(session, page_index)

    def _ocr_progress(self, done: int, total: int) -> None:
        self.status_label.setText(tr("OCR中… ({done}/{total})").format(done=done, total=total))

    def _ocr_failed(self, message: str) -> None:
        self._ocr_error = message

    def _ocr_finished(self, cancelled: bool) -> None:
        applied = self._ocr_applied_pages
        candidates = getattr(self._ocr_worker, "candidates", None)
        error = getattr(self, "_ocr_error", "")
        stopped_by = getattr(self, "_ocr_stopped_by", "")
        self._ocr_error = ""
        self._ocr_stopped_by = ""
        self._ocr_session = None
        self._ocr_document = None
        self._stop_ocr_process()
        if not applied:
            self._withdraw_ocr_history()
        self._ocr_history = None
        self.act_ocr_page.setEnabled(self.document is not None)
        self.act_ocr_document.setEnabled(self.document is not None)
        self.act_ocr_cancel.setEnabled(False)
        single_page = getattr(self, "_ocr_single_page", False)
        if cancelled and stopped_by:
            self.status_label.setText(stopped_by)
        elif cancelled:
            self._show_document_line()
        elif single_page and not applied and not error:
            # Recognising words but writing none of them is a failure, not
            # a completed page.
            self.status_label.setText(
                tr("認識した文字をページに書き込めませんでした")
                if getattr(self, "_ocr_unwritten", False)
                else tr("認識できる文字がありませんでした")
            )
        elif not applied and not error and candidates == 0:
            self.status_label.setText(tr("OCRが必要なページはありません"))
        elif error and not applied:
            self._show_document_line()
            QMessageBox.warning(
                self, APP_NAME, tr("OCRを実行できませんでした。\n\n{error}").format(error=error)
            )
        else:
            self._show_document_line()
        self._update_controls()

    def _withdraw_ocr_history(self) -> None:
        """Take back the undo step of a run that changed nothing."""
        history = getattr(self, "_ocr_history", None)
        if history is None:
            return
        session, undo_depth, redo_stack = history
        if session in self.sessions and len(session.undo_stack) == undo_depth + 1:
            session.undo_stack.pop()
            session.redo_stack[:] = redo_stack

    def cancel_ocr(self) -> None:
        if self._ocr_worker is not None:
            self._ocr_worker.cancel()

    def _ocr_page_mark(self, document: fitz.Document, index: int) -> tuple[int | None, str]:
        """Which page object is at `index`, and what it draws."""
        return self._page_object_xref(document, index), page_content_fingerprint(document, index)

    def _stop_ocr_for(self, document: fitz.Document, reason: str) -> None:
        """Stop the OCR run of `document`, if one is going, and write none of
        its results that have not been written yet. Applying redactions
        does this first: a result read before them would put the words
        they removed back as invisible text (6.2)."""
        if self._ocr_worker is None or self._ocr_document is not document:
            return
        self._ocr_page_marks = {}
        self._ocr_stopped_by = reason
        self._ocr_worker.cancel()

    def _stop_ocr_process(self) -> None:
        worker = self._ocr_worker
        self._ocr_worker = None
        if worker is None:
            return
        if worker.running():
            worker.stop()
        worker.deleteLater()


class FormTextEditor(QPlainTextEdit):
    """The editor of a multi-line text field: Enter starts a new line, as
    the field allows, and leaving it finishes the field, as leaving a
    one-line field does. Tab still moves on rather than typing a tab."""

    editingFinished = Signal()

    def __init__(self, text: str, parent: QWidget | None = None) -> None:
        super().__init__(parent)
        self.setPlainText(text)
        self.setTabChangesFocus(True)

    def text(self) -> str:
        return self.toPlainText()

    def focusOutEvent(self, event: Any) -> None:
        super().focusOutEvent(event)
        # Its own right-click menu takes the focus too; that is not leaving.
        if event.reason() != Qt.PopupFocusReason:
            self.editingFinished.emit()


class FormFieldsMixin:
    """Interactive AcroForm fields: hit testing, editing and clearing.

    What a field says of itself is kept to (6.2): a read-only field is not
    edited, toggled or cleared; a text field keeps to its maximum length,
    hides a password as it is typed and takes several lines when it is
    multi-line; a combo box that allows its own entry takes one. A field
    was edited by its type alone, whatever it said."""

    def _page_form_fields(self, page: fitz.Page) -> list[dict[str, Any]]:
        """Form fields as plain data.

        fitz.Widget holds only a weak reference to its page, so a Widget
        that outlives the local Page variable raises "Annot is not bound to
        a page" on the next attribute access. Everything the UI needs is
        copied out here while the page is still referenced.
        """
        fields: list[dict[str, Any]] = []
        try:
            widgets = list(page.widgets())
        except Exception:
            return fields
        for widget in widgets:
            try:
                if widget.field_type not in self.EDITABLE_WIDGET_TYPES:
                    continue
                fields.append(
                    {
                        "xref": widget.xref,
                        "type": widget.field_type,
                        "rect": fitz.Rect(widget.rect),
                        "value": widget.field_value,
                        "choices": [str(v) for v in (widget.choice_values or [])],
                        "on_state": widget.on_state(),
                        "name": widget.field_name,
                        "flags": int(widget.field_flags or 0),
                        "maxlen": int(widget.text_maxlen or 0),
                    }
                )
            except Exception:
                continue
        return fields

    @staticmethod
    def _form_field_read_only(field: dict[str, Any]) -> bool:
        return bool(int(field.get("flags") or 0) & fitz.PDF_FIELD_IS_READ_ONLY)

    def _refuse_read_only_field(self, field: dict[str, Any]) -> bool:
        """True, having said so, when `field` is read-only."""
        if not self._form_field_read_only(field):
            return False
        self.status_label.setText(tr("この欄は読み取り専用です"))
        return True

    def _form_field_at_point(self, page_point: fitz.Point) -> dict[str, Any] | None:
        if self.document is None:
            return None
        page = self.document[self.page_index]
        for form_field in self._page_form_fields(page):
            if form_field["rect"].contains(page_point):
                return form_field
        return None

    def _clear_widget_value(self, xref: int) -> None:
        if self.document is None:
            return
        try:
            self.document.xref_set_key(xref, "V", "()")
        except Exception:
            pass

    def _commit_form_widget(self, xref: int, value: Any, page_index: int | None = None) -> bool:
        """Write one field value back; True when it changed the document."""
        return self._write_form_value(xref, value, page_index) == "changed"

    def _write_form_value(self, xref: int, value: Any, page_index: int | None = None) -> str:
        """Write one field value back: "changed", "unchanged" or "failed".

        Snapshotting here is what puts form edits on the same undo stack --
        and in the same recovery snapshot -- as every other edit. The field
        is looked for on `page_index`, the page its editor was opened on:
        the page on screen may be another by now. A write that fails is
        put back whole. It used to be reported as False, like a value that
        had not changed, and saving went on without it (6.2)."""
        if self.document is None:
            return "failed"
        index = self.page_index if page_index is None else page_index
        checkpoint: tuple | None = None
        try:
            page = self.document[index]
            widget = next((w for w in page.widgets() if w.xref == xref), None)
            if widget is None:
                raise LookupError(f"form field {xref} is not on page {index + 1}")
            if int(widget.field_flags or 0) & fitz.PDF_FIELD_IS_READ_ONLY:
                self.status_label.setText(tr("この欄は読み取り専用です"))
                return "unchanged"
            maximum = int(widget.text_maxlen or 0)
            if isinstance(value, str) and maximum > 0:
                value = value[:maximum]
            if widget.field_value == value:
                return "unchanged"
            checkpoint = self._begin_edit()
            widget.field_value = value
            widget.update()
            if isinstance(value, str) and not value:
                # PyMuPDF silently drops an empty value on update(), leaving
                # the old text in place, so write /V directly to clear it.
                self._clear_widget_value(widget.xref)
        except Exception as exc:
            if checkpoint is not None:
                self._rollback_edit(checkpoint)
            QMessageBox.critical(
                self, APP_NAME, tr("フォームを編集できませんでした。\n\n{error}").format(error=exc)
            )
            return "failed"
        self._mark_dirty()
        self._invalidate_render_cache(index)
        self.schedule_render(immediate=True)
        return "changed"

    def _toggle_form_check_field(self, field: dict[str, Any]) -> bool:
        currently_on = field["value"] not in (False, "Off", None, "")
        if field["type"] == fitz.PDF_WIDGET_TYPE_RADIOBUTTON and currently_on:
            # Radio groups are exclusive; clicking the selected one keeps it.
            return False
        new_value = False if currently_on else (field["on_state"] or True)
        return self._commit_form_widget(field["xref"], new_value)

    def activate_form_field(self, field: dict[str, Any]) -> bool:
        """Click behaviour for a form field: buttons toggle straight away,
        the rest get an editor placed over the field itself."""
        if self._refuse_read_only_field(field):
            return False
        if field["type"] in (
            fitz.PDF_WIDGET_TYPE_CHECKBOX,
            fitz.PDF_WIDGET_TYPE_RADIOBUTTON,
        ):
            return self._toggle_form_check_field(field)
        self._show_form_editor(field)
        return True

    def _show_form_editor(self, field: dict[str, Any]) -> None:
        if self._refuse_read_only_field(field):
            return
        self._close_form_editor()
        canvas = self._canvas_widget()
        rect = self._page_rect_to_screen(field["rect"])
        xref = field["xref"]
        flags = int(field.get("flags") or 0)
        maximum = int(field.get("maxlen") or 0)
        if field["type"] == fitz.PDF_WIDGET_TYPE_TEXT:
            text = str(field["value"] or "")
            if flags & fitz.PDF_TX_FIELD_IS_MULTILINE:
                editor: QWidget = FormTextEditor(text, canvas)
            else:
                editor = QLineEdit(text, canvas)
                if maximum > 0:
                    editor.setMaxLength(maximum)
                if flags & fitz.PDF_TX_FIELD_IS_PASSWORD:
                    editor.setEchoMode(QLineEdit.Password)
            # Enter, Tab or clicking elsewhere all finish the field. Only
            # Enter used to, so a value typed before clicking away stayed
            # uncommitted in a floating box.
            editor.editingFinished.connect(
                lambda e=editor: self._commit_form_editor()
                if e is self._active_form_editor
                else None
            )
        else:
            editor = QComboBox(canvas)
            choices = list(field["choices"])
            if not choices:
                choices = [str(field["value"] or "")]
            editor.addItems(choices)
            current = str(field["value"] or "")
            if flags & fitz.PDF_CH_FIELD_IS_EDIT:
                # The field takes an entry of its own besides its choices.
                editor.setEditable(True)
                editor.setInsertPolicy(QComboBox.NoInsert)
                editor.setCurrentText(current)
                # Enter finishes an entry of its own (activated only comes
                # for one of the choices); leaving the field finishes it as
                # any edit is finished. Not on losing the focus: opening
                # the list takes it, and would close the field.
                editor.lineEdit().returnPressed.connect(
                    lambda e=editor: self._commit_form_editor()
                    if e is self._active_form_editor
                    else None
                )
            elif current in choices:
                editor.setCurrentText(current)
            editor.activated.connect(lambda _index: self._commit_form_editor())
        editor.setGeometry(rect.toRect().adjusted(0, 0, 0, 0))
        editor.setMinimumHeight(20)
        editor.show()
        editor.setFocus()
        self._active_form_editor = editor
        self._active_form_xref = xref
        self._active_form_rect = fitz.Rect(field["rect"])
        self._active_form_page_index = self.page_index

    def _commit_form_editor(self) -> bool:
        """Write the open field editor back. False when that failed: the
        editor then stays open with what was typed, and the commit that
        asked (a save, say) stops. It used to close first and lose the
        value, and a save went on as though it had been written (6.2)."""
        editor = self._active_form_editor
        xref = self._active_form_xref
        if editor is None or xref is None or getattr(self, "_committing_form", False):
            return True
        if isinstance(editor, (QLineEdit, FormTextEditor)):
            value: Any = editor.text()
        elif isinstance(editor, QComboBox):
            value = editor.currentText()
        else:
            value = None
        if value is None:
            self._close_form_editor()
            return True
        # The error dialog takes the focus, which finishes editing and asks
        # for this commit again.
        self._committing_form = True
        try:
            result = self._write_form_value(xref, value, getattr(self, "_active_form_page_index", None))
        finally:
            self._committing_form = False
        if result == "failed":
            self._overlay_commit_failed = True
            return False
        if self._active_form_editor is editor:
            self._close_form_editor()
        return True

    def _close_form_editor(self) -> None:
        editor = getattr(self, "_active_form_editor", None)
        # Forget it first: hiding it takes the focus away, which finishes
        # editing -- and would otherwise commit it a second time.
        self._active_form_editor = None
        self._active_form_xref = None
        self._active_form_rect = None
        if editor is not None:
            try:
                editor.hide()
                editor.deleteLater()
            except RuntimeError:
                pass  # went with its page label

    def _layout_active_form_editor(self) -> None:
        """Keep an open field's editor over its field when the page is drawn
        at a new size. It stayed at the old size and position -- over the
        wrong part of the page -- after a zoom."""
        editor = getattr(self, "_active_form_editor", None)
        rect = getattr(self, "_active_form_rect", None)
        if editor is None or rect is None or self.document is None or self.continuous:
            return
        if getattr(self, "_active_form_page_index", -1) != self.page_index:
            return
        editor.setGeometry(self._page_rect_to_screen(rect).toRect())

    def _move_to_adjacent_form_field(self, step: int) -> bool:
        """Tab / Shift+Tab: finish this field and open the next one in
        reading order, the way a form is filled in anywhere else."""
        if self.document is None:
            return False
        current = self._active_form_xref
        self._commit_form_editor()
        order: list[tuple[int, dict[str, Any]]] = []
        for index in range(len(self.document)):
            fields = [
                field for field in self._page_form_fields(self.document[index])
                # Buttons toggle when activated; tabbing onto one must not.
                if field["type"] not in (
                    fitz.PDF_WIDGET_TYPE_CHECKBOX, fitz.PDF_WIDGET_TYPE_RADIOBUTTON,
                )
                and not self._form_field_read_only(field)
            ]
            fields.sort(key=lambda field: (round(field["rect"].y0, 1), field["rect"].x0))
            order.extend((index, field) for field in fields)
        if not order:
            return False
        position = next(
            (i for i, (_page, field) in enumerate(order) if field["xref"] == current), -1
        )
        target_page, target = order[(position + step) % len(order)]
        if target_page != self.page_index:
            self.go_to_page(target_page)
            if self.continuous:
                self._continuous_page_clicked(target_page)
            else:
                self.render_current_page()
        self.activate_form_field(target)
        return True

    def focus_first_form_field(self) -> bool:
        """Menu entry point: jump to the first fillable field in the file."""
        if self.document is None:
            return False
        for index in range(len(self.document)):
            page = self.document[index]
            fields = self._page_form_fields(page)
            if not fields:
                continue
            if index != self.page_index:
                self.go_to_page(index)
                # Continuous scrolling gives every page its own canvas.
                # Without this the editor is placed on the page that was in
                # front before (_move_to_adjacent_form_field does the same).
                if self.continuous:
                    self._continuous_page_clicked(index)
                else:
                    self.render_current_page()
            self.activate_form_field(fields[0])
            return True
        self.status_label.setText(tr("このPDFにはフォームがありません"))
        return False

    def clear_all_form_fields(self) -> bool:
        """Empty every fillable field in the document."""
        if self.document is None:
            return False
        targets: list[tuple[int, int]] = []
        for index in range(len(self.document)):
            page = self.document[index]
            for form_field in self._page_form_fields(page):
                # "Off" is a checkbox's *unset* state, not a value to clear.
                if form_field["value"] not in (None, "", False, "Off") and not self._form_field_read_only(form_field):
                    targets.append((index, form_field["xref"]))
        if not targets:
            return False
        self._snapshot_for_edit()
        cleared = 0
        for index, xref in targets:
            page = self.document[index]
            for widget in page.widgets():
                if widget.xref != xref:
                    continue
                try:
                    is_button = widget.field_type in (
                        fitz.PDF_WIDGET_TYPE_CHECKBOX,
                        fitz.PDF_WIDGET_TYPE_RADIOBUTTON,
                    )
                    widget.field_value = False if is_button else ""
                    widget.update()
                    if not is_button:
                        self._clear_widget_value(xref)
                    cleared += 1
                except Exception:
                    pass
                break
        if not cleared:
            return False
        self._mark_dirty()
        self._invalidate_render_cache()
        self.schedule_render(immediate=True)
        return True

    def _form_field_context_menu(self, field: dict[str, Any]) -> QMenu:
        """Right-clicking a form field. It had no menu at all."""
        menu = QMenu(self)
        writable = not self._form_field_read_only(field)
        if field["type"] in (
            fitz.PDF_WIDGET_TYPE_CHECKBOX,
            fitz.PDF_WIDGET_TYPE_RADIOBUTTON,
        ):
            toggle = menu.addAction(
                tr("切り替え"), lambda _checked=False, f=field: self._toggle_form_check_field(f)
            )
            toggle.setEnabled(writable)
            menu.setDefaultAction(toggle)
        else:
            edit = menu.addAction(
                tr("入力"), lambda _checked=False, f=field: self._show_form_editor(f)
            )
            edit.setEnabled(writable)
            menu.setDefaultAction(edit)
        menu.addSeparator()
        clear = menu.addAction(
            tr("この欄を消去"),
            lambda _checked=False, f=field: self._commit_form_widget(f["xref"], ""),
        )
        clear.setEnabled(writable)
        menu.addAction(tr("すべての欄を消去"), self.clear_all_form_fields)
        menu.addSeparator()
        menu.addAction(self.act_fill_form)
        return menu


class RedactionMixin:
    """Redaction and sanitising -- the two operations that remove content
    rather than annotate it."""

    def _pending_redaction_count(self) -> int:
        if self.document is None:
            return 0
        total = 0
        for page in self.document:
            total += sum(
                1 for _xref, kind, _name in page.annot_xrefs()
                if kind == fitz.PDF_ANNOT_REDACT
            )
        return total

    def _pending_redaction_count_for_notice(self) -> int:
        """The count the notice bar shows, counted once per document state.

        _update_controls asks on every selection and page change, and the
        count walks every page: 0.03 s a time on 2,000 pages. Every change
        to the marks goes through _mark_dirty, which drops the kept count;
        an undo or redo, another tab or a save that replaced the document is
        another (document, state) and is counted again. Applying and
        clearing the marks still count afresh."""
        if self.document is None:
            return 0
        session = self._current_session()
        state = session.state_id if session is not None else None
        kept = self._redaction_count_kept
        if kept is not None and kept[0] is self.document and kept[1] == state:
            return kept[2]
        count = self._pending_redaction_count()
        self._redaction_count_kept = (self.document, state, count)
        return count

    @staticmethod
    def _redaction_marks(page: fitz.Page) -> list[fitz.Rect]:
        marks: list[fitz.Rect] = []
        for xref, kind, _name in page.annot_xrefs():
            if kind != fitz.PDF_ANNOT_REDACT:
                continue
            try:
                marks.append(fitz.Rect(page.load_annot(xref).rect))
            except Exception:
                continue
        return marks

    def _image_stamps_into_content(self, page: fitz.Page, marks: list[fitz.Rect]) -> int:
        """A picture under a redaction mark goes back into the page's
        content first, so the redaction blanks the part of it under the
        mark, as when every picture was page content -- the annotations
        over a mark are taken away whole, and a picture with them (6.19)."""
        moved = 0
        for xref, kind, _name in list(page.annot_xrefs()):
            if kind != fitz.PDF_ANNOT_STAMP:
                continue
            try:
                stamp = page.load_annot(xref)
                if not self._is_image_stamp(stamp):
                    continue
                rect = fitz.Rect(stamp.rect)
                if not any(rect.intersects(mark) for mark in marks):
                    continue
                image_xref = self._stamp_image_xref(stamp)
                if image_xref <= 0:
                    continue
                page.delete_annot(stamp)
                page.insert_image(rect, xref=image_xref, keep_proportion=False, overlay=True)
                moved += 1
            except Exception:
                continue
        return moved

    @staticmethod
    def _remove_content_over_marks(page: fitz.Page, marks: list[fitz.Rect]) -> tuple[int, int]:
        """Delete what overlaps a redaction mark that apply_redactions()
        leaves in place.

        MuPDF removes the text, images and drawings under the marks, and a
        free-text box or link over them -- but a sticky note, a highlight's
        comment or a form field lying across the area kept its text, and the
        "redacted" words could still be read out of the saved file. Acrobat
        deletes those as well.

        Returns how many were removed and how many could not be. The caller
        warns about the second number: skipping them silently would leave
        text under a redaction with nothing said.
        """
        def overlaps(rect: fitz.Rect) -> bool:
            return any(rect.intersects(mark) for mark in marks)

        removed = 0
        failed = 0
        skipped_kinds = (
            fitz.PDF_ANNOT_REDACT, fitz.PDF_ANNOT_POPUP,
            fitz.PDF_ANNOT_WIDGET, fitz.PDF_ANNOT_LINK,
        )
        for xref, kind, _name in list(page.annot_xrefs()):
            if kind in skipped_kinds:
                continue
            try:
                annot = page.load_annot(xref)
                if overlaps(fitz.Rect(annot.rect)):
                    # Takes the note's popup with it.
                    page.delete_annot(annot)
                    removed += 1
            except Exception:
                failed += 1
        for widget in list(page.widgets()):
            try:
                if overlaps(fitz.Rect(widget.rect)):
                    page.delete_widget(widget)
                    removed += 1
            except Exception:
                failed += 1
        for link in page.get_links():
            try:
                if overlaps(fitz.Rect(link["from"])):
                    page.delete_link(link)
            except Exception:
                failed += 1
        return removed, failed

    def redact_selection(self) -> bool:
        """Mark the current text selection for redaction. Premium; applying
        or clearing marks already made is not, so nothing marked is left
        unapplied for want of a purchase."""
        if self.document is None or self._premium_blocked("墨消し〔名詞〕"):
            return False
        target = self._current_markup_target()
        if target is None:
            self.status_label.setText(tr("文字列を選択してください"))
            return False
        page, line_rects, _count = target
        self._snapshot_for_edit()
        for rect in line_rects:
            annot = page.add_redact_annot(fitz.Rect(rect))
            annot.set_info(subject=self.REDACTION_SUBJECT)
            annot.update()
        self._mark_dirty()
        self.schedule_render(immediate=True)
        self._update_controls()
        return True

    def redact_page_region(self, page_rect: fitz.Rect) -> bool:
        """Mark an arbitrary rectangle (images included) for redaction."""
        if self.document is None or self._premium_blocked("墨消し〔名詞〕"):
            return False
        page = self.document[self.page_index]
        self._snapshot_for_edit()
        annot = page.add_redact_annot(fitz.Rect(page_rect))
        annot.set_info(subject=self.REDACTION_SUBJECT)
        annot.update()
        self._mark_dirty()
        self.schedule_render(immediate=True)
        self._update_controls()
        return True

    def apply_pending_redactions(self, confirm: bool = True) -> bool:
        """Burn the marked areas out of the document. Irreversible in the
        saved file, so it always asks first."""
        if self.document is None:
            return False
        pending = self._pending_redaction_count()
        if not pending:
            self.status_label.setText(tr("適用する墨消しがありません"))
            return False
        if confirm:
            answer = QMessageBox.question(
                self,
                APP_NAME,
                # What it does, truthfully: gone from the saved file, but a
                # step in the edit history like any other. It said it could
                # not be undone, and Undo took it back (6.2).
                tr_n(
                    "{count}件の墨消しを適用します。範囲内の文字や画像と、範囲にかかる文字装飾・オブジェクト・フォーム欄が"
                    "削除されます。保存したPDFには残らず、そこから取り戻すことはできません。"
                    "編集履歴に残っている間は［元に戻す］で取り消せます。\n\n実行しますか？",
                    pending,
                ).format(count=pending),
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if answer != QMessageBox.Yes:
                return False
        if not self._finish_active_overlays():
            self.status_label.setText(tr("編集を確定できなかったため中止しました"))
            return False
        self._stop_ocr_for(self.document, tr("墨消しを適用したため、OCRを中止しました"))
        checkpoint = self._begin_edit()
        failed = 0
        try:
            for page in self.document:
                marks = self._redaction_marks(page)
                if marks:
                    self._image_stamps_into_content(page, marks)
                    failed += self._remove_content_over_marks(page, marks)[1]
                    page.apply_redactions()
        except Exception as exc:
            # The pages before the failing one were already redacted, while
            # the document still counted as unchanged. Put it back whole.
            if not self._rollback_edit(checkpoint):
                session = self._current_session()
                if session is not None:
                    # Could not go back: a later save must at least rebuild.
                    session.needs_full_rewrite = True
            QMessageBox.critical(
                self, APP_NAME, tr("墨消しを適用できませんでした。\n\n{error}").format(error=exc)
            )
            return False
        session = self._current_session()
        if session is not None:
            session.needs_full_rewrite = True
        self._invalidate_render_cache()
        self._mark_dirty()
        self._refresh_after_document_change(rebuild_navigation=False)
        if session is not None:
            # The crash-recovery copy on disk still holds what was just
            # removed. It is replaced now rather than at the next two-minute
            # tick (6.2).
            self._write_recovery_snapshot(session)
        if failed:
            QMessageBox.warning(
                self,
                APP_NAME,
                tr_n(
                    "{count}個の項目またはフォーム欄を削除できませんでした。"
                    "墨消しした範囲に内容が残っている可能性があります。保存する前に確認してください。",
                    failed,
                ).format(count=failed),
            )
        self._update_controls()
        return True

    def clear_pending_redactions(self) -> bool:
        """Drop redaction marks that have not been applied."""
        if self.document is None:
            return False
        if not self._pending_redaction_count():
            # Nothing to drop: taking a snapshot anyway left an undo step
            # that did nothing.
            return False
        removed = 0
        failed = 0
        self._snapshot_for_edit()
        for page in self.document:
            for xref, kind, _name in list(page.annot_xrefs()):
                if kind != fitz.PDF_ANNOT_REDACT:
                    continue
                try:
                    page.delete_annot(page.load_annot(xref))
                    removed += 1
                except Exception:
                    failed += 1
        if not removed:
            if failed:
                self.status_label.setText(tr("墨消しのマークを削除できませんでした"))
            return False
        self._mark_dirty()
        self.schedule_render(immediate=True)
        self._update_controls()
        return True

    def _has_invisible_text(self) -> bool:
        """Text drawn invisibly (render mode 3): what OCR adds, and what
        sanitising removes as hidden text."""
        if self.document is None:
            return False
        for page in self.document:
            try:
                if any(span.get("type") == 3 for span in page.get_texttrace()):
                    return True
            except Exception:
                continue
        return False

    def sanitize_document_copy(
        self, target_path: str | None = None, remove_hidden_text: bool | None = None
    ) -> str | None:
        """Write a scrubbed copy: metadata, JavaScript, embedded files and
        other hidden data removed. The open document is left untouched.

        Removing hidden text also removes the invisible text layer that OCR
        adds, which leaves the copy unsearchable. Run from the menu, pdfNote
        asks first when the document has such text; a caller that names the
        target decides with `remove_hidden_text` (default: remove).
        """
        if self.document is None:
            return None
        if remove_hidden_text is None:
            remove_hidden_text = True
            if target_path is None and self._has_invisible_text():
                answer = QMessageBox.question(
                    self,
                    APP_NAME,
                    tr(
                        "この文書には見えない文字（OCRで付けた文字など）があります。"
                        "削除すると、サニタイズしたPDFでは検索やコピーができなくなります。\n\n"
                        "見えない文字も削除しますか？"
                    ),
                    QMessageBox.Yes | QMessageBox.No | QMessageBox.Cancel,
                    QMessageBox.Yes,
                )
                if answer == QMessageBox.Cancel:
                    return None
                remove_hidden_text = answer == QMessageBox.Yes
        if target_path is None:
            base = Path(self.file_path) if self.file_path else Path.home() / tr("無題.pdf")
            suggestion = str(base.with_name(tr("{name} (サニタイズ済み)").format(name=base.stem) + ".pdf"))
            selected, _filter = QFileDialog.getSaveFileName(
                self, tr("サニタイズしたPDFを保存"), suggestion, tr("PDFファイル (*.pdf)")
            )
            if not selected:
                return None
            if not selected.lower().endswith(".pdf"):
                selected += ".pdf"
            target_path = selected
        session = self._current_session()
        if session is None:
            return None
        try:
            # scrub() mutates in place, so it runs on a throwaway copy of
            # the bytes rather than on the document the user has open. The
            # copy keeps the document's encryption: sanitising removes hidden
            # data, and quietly dropping a password is not part of that.
            copy = fitz.open(stream=serialize_session(session), filetype="pdf")
            if copy.needs_pass and self.password:
                copy.authenticate(self.password)
        except Exception as exc:
            QMessageBox.critical(
                self, APP_NAME, tr("サニタイズできませんでした。\n\n{error}").format(error=exc)
            )
            return None
        temp_path: Path | None = None
        try:
            copy.scrub(
                metadata=True,
                javascript=True,
                attached_files=True,
                embedded_files=True,
                hidden_text=remove_hidden_text,
                remove_links=False,
                reset_fields=False,
                reset_responses=True,
                thumbnails=True,
                xml_metadata=True,
            )
            # Through the one serializer, so the copy is fully rebuilt (what
            # scrub() unlinked is really dropped) and keeps its encryption;
            # then swapped in atomically, as every save is.
            data = serialize_document(copy, full_rewrite=True)
            target = Path(target_path)
            file_descriptor, temp_name = tempfile.mkstemp(
                prefix=f".{target.stem}-", suffix=".sumi.tmp", dir=str(target.parent)
            )
            temp_path = Path(temp_name)
            with os.fdopen(file_descriptor, "wb") as stream:
                stream.write(data)
            os.replace(temp_path, target)
            temp_path = None
        except Exception as exc:
            QMessageBox.critical(
                self, APP_NAME, tr("サニタイズできませんでした。\n\n{error}").format(error=exc)
            )
            return None
        finally:
            if temp_path is not None:
                try:
                    temp_path.unlink(missing_ok=True)
                except OSError:
                    pass
            try:
                copy.close()
            except Exception:
                pass
        return target_path


TEXT_MARKUP_ANNOT_TYPES = (
    fitz.PDF_ANNOT_HIGHLIGHT, fitz.PDF_ANNOT_UNDERLINE,
    fitz.PDF_ANNOT_STRIKE_OUT, fitz.PDF_ANNOT_SQUIGGLY,
)


def annotation_hit_rect(annot: fitz.Annot) -> fitz.Rect:
    """Where an annotation takes a click. Text markup is measured by its
    quads: MuPDF pads a highlight's rectangle by almost 4 pt at each end,
    enough to cover the character beside it, so clicking that character
    picked the highlight instead of the text."""
    if annot.type[0] in TEXT_MARKUP_ANNOT_TYPES:
        points = annot.vertices or []
        if points:
            xs = [point[0] for point in points]
            ys = [point[1] for point in points]
            return fitz.Rect(min(xs), min(ys), max(xs), max(ys))
    return fitz.Rect(annot.rect)


def lines_overlap(a: fitz.Rect, b: fitz.Rect) -> bool:
    """Do two text-line boxes share a line? Neighbouring lines' boxes meet
    in a thin seam, which is not the same line."""
    shared = fitz.Rect(a) & b
    return not shared.is_empty and shared.height >= 0.5 * min(a.height, b.height)


# The drawing tools. Each picture is drawn in that tool's own colour.
SHAPE_TOOL_KINDS = ("ink", "rectangle", "arrow", "line")
# The tools that carry a colour of their own, the sticky note included.
TOOL_COLOR_KINDS = ("note",) + SHAPE_TOOL_KINDS
# The basic colours (6.10). Every palette -- the highlight's, the sticky
# note's, the underline's and the strikethrough's, the drawing tools', the
# font colour's -- offers the same colours, by the same names, in the same
# order: each palette had colours of its own, so a "red" underline and a
# "red" note were different reds, and nothing could tell which colour a
# mark was. Now it is one of these, and the 文字装飾 and オブジェクト tabs
# filter by them (6.10, 6.14).
#
# Each colour has a shade for each use: a light one for what lies under
# the text or is a sheet of its own (highlight, sticky note); a strong one
# for lines -- 3:1 or more on white paper; the highlight's yellow as a thin
# line all but vanished (v5.20) -- and a dark one for type, 4.5:1 or more.
# A black highlight would hide the text, so black has no light shade.
#
# (name, light, line, type)
BASIC_COLORS = (
    ("黄", "#FFD633", "#B38600", "#8A6500"),
    ("オレンジ", "#FFAA45", "#E26D00", "#B45309"),
    ("赤", "#F05252", "#E02424", "#C81E1E"),
    ("ピンク", "#FF77A8", "#DB2777", "#BE185D"),
    ("紫", "#A879FF", "#7E22CE", "#7E22CE"),
    ("青", "#57A0FF", "#1D4ED8", "#1D4ED8"),
    ("緑", "#6DDC78", "#22A55A", "#15803D"),
    ("黒", None, "#151515", "#151515"),
)
# Highlight and sticky note.
MARKUP_COLORS = tuple((name, light) for name, light, _line, _type in BASIC_COLORS if light)
# Underline and strikethrough.
LINE_MARKUP_COLORS = tuple((name, line) for name, _light, line, _type in BASIC_COLORS)
# Shapes and ink.
DRAWING_COLORS = LINE_MARKUP_COLORS
# The Font Color button's colours, also offered for a placed text box;
# white for type on a dark picture.
TEXT_COLORS = tuple((name, kind) for name, _light, _line, kind in BASIC_COLORS) + (
    ("白", "#FFFFFF"),
)
# Each markup keeps its own colour, as in Acrobat: highlight yellow,
# underline green, strikethrough red.
MARKUP_DEFAULT_COLORS = {"highlight": "#FFD633", "underline": "#22A55A", "strikeout": "#E02424"}
# What each tool starts as. The note keeps the yellow it always had; the
# shapes and the ink the basic red.
TOOL_DEFAULT_COLORS = {
    "note": "#FFD633",
    "ink": "#E02424",
    "rectangle": "#E02424",
    "arrow": "#E02424",
    "line": "#E02424",
}


# Where each basic colour lies on the colour wheel (degrees), to tell which
# one a colour is. Placed by eye, not averaged from the shades: the dark
# yellow the type uses would have pulled yellow down into orange's half.
BASIC_COLOR_HUES = {
    "黄": 52.0, "オレンジ": 30.0, "赤": 0.0, "ピンク": 335.0,
    "紫": 270.0, "青": 220.0, "緑": 135.0,
}


def basic_color_name(colour: Any) -> str | None:
    """Which basic colour a colour is (6.10): the one nearest in hue, black
    for the dark and the grey, None for white and the palest greys -- and
    for no colour at all. A mark made before 6.10, or by another program,
    counts as the basic colour it looks like."""
    if colour is None:
        return None
    if isinstance(colour, (tuple, list)):
        if len(colour) != 3:
            return None
        colour = QColor.fromRgbF(*(min(1.0, max(0.0, float(value))) for value in colour))
    colour = QColor(colour)
    if not colour.isValid():
        return None
    saturation, value = colour.hsvSaturationF(), colour.valueF()
    if value < 0.3 or (saturation < 0.2 and value < 0.7):
        return "黒"
    if saturation < 0.2:
        return None
    hue = colour.hsvHueF() * 360

    def distance(name: str) -> float:
        gap = abs(hue - BASIC_COLOR_HUES[name]) % 360
        return min(gap, 360 - gap)

    return min(BASIC_COLOR_HUES, key=distance)

# Access keys -- the underlined letter -- for right-click menu entries, so
# Shift+F10 and one key run a command, as in Windows and Office. Common
# commands take Windows' and Office's letters; every other entry gets the
# first free letter. Japanese, Chinese and Korean show it in brackets after
# the label, taken from the English name, as Office does: 切り取り(T).
ACCESS_KEYS = {
    "元に戻す": "U", "やり直す": "R", "切り取り": "T", "コピー": "C", "貼り付け": "P",
    "削除": "D", "すべて選択": "A", "テキストの編集": "X", "画像として保存...": "S",
    "最前面へ移動": "R", "最背面へ移動": "K", "前面へ移動": "F", "背面へ移動": "B",
    "付箋を追加": "M", "フォント": "F", "印刷...": "P", "プロパティ": "R",
    "その他の色...": "M",
}
BRACKETED_ACCESS_KEYS = frozenset({"ja", "zh_CN", "ko", "hi", "bn", "ur", "grc", "sa", "non"})


def _access_key_candidates(text: str) -> list[str]:
    """Letters worth underlining, best first: word initials, then the rest."""
    words = re.findall(r"\w+", text)
    initials = [word[0] for word in words]
    others = [char for word in words for char in word[1:]]
    return [char for char in initials + others if char.isalnum()]


def assign_access_keys(menu: QMenu) -> QMenu:
    """Give each entry of a right-click menu, and of its submenus, an access
    key of its own. Only entries that know their source string (property
    "pdfnoteKey") take part: the font and size lists are names and numbers,
    and Office's lists of them have none either."""
    bracketed = I18N.current in BRACKETED_ACCESS_KEYS
    entries: list[tuple[QAction, str, str, str]] = []
    for action in menu.actions():
        if action.isSeparator() or not action.text():
            continue
        source = action.property("pdfnoteKey")
        label, tab, hint = action.text().partition("\t")
        if not source or "&" in label.replace("&&", ""):
            continue
        entries.append((action, str(source), label, tab + hint))
    used: set[str] = set()
    picks: dict[int, str] = {}
    # Windows' and Office's letters first, so no automatic pick takes them.
    for index, (_action, source, label, _rest) in enumerate(entries):
        preferred = ACCESS_KEYS.get(source)
        if (
            preferred
            and (bracketed or preferred.casefold() in label.casefold())
            and preferred.casefold() not in used
        ):
            picks[index] = preferred
            used.add(preferred.casefold())
    # Then the rest, the entries with the fewest letters to choose from
    # first, so a short word is not left with none ("Imprimir..." lost all
    # four of its letters to Insertar, Mover, Pegar and Propiedades).
    options: dict[int, list[str]] = {}
    for index, (_action, source, label, _rest) in enumerate(entries):
        if index not in picks:
            name = TRANSLATIONS.get(source, {}).get("en", source) if bracketed else label
            options[index] = [
                char for char in _access_key_candidates(name) if char.isascii() or not bracketed
            ]
    in_brackets: set[int] = set()
    for index in sorted(options, key=lambda i: len({char.casefold() for char in options[i]})):
        for char in options[index]:
            if char.casefold() not in used:
                picks[index] = char.upper() if bracketed else char
                used.add(char.casefold())
                break
        else:
            # No letter of its own left: a free one in brackets, the way
            # East Asian labels carry theirs, rather than no key at all.
            free = next(
                (char for char in "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
                 if char.casefold() not in used),
                None,
            )
            if free is not None:
                picks[index] = free
                used.add(free.casefold())
                in_brackets.add(index)
    for index, (action, _source, label, rest) in enumerate(entries):
        pick = picks.get(index)
        if pick is None:
            continue
        escaped = label.replace("&", "&&")
        if bracketed or index in in_brackets:
            dots = next((end for end in ("...", "…") if escaped.endswith(end)), "")
            stem = escaped[: len(escaped) - len(dots)]
            marked = f"{stem}(&{pick}){dots}"
        else:
            position = escaped.casefold().find(pick.casefold())
            marked = escaped[:position] + "&" + escaped[position:]
        action.setText(marked + rest)
    for action in menu.actions():
        if action.menu() is not None:
            assign_access_keys(action.menu())
    return menu


def mirror_action(menu: QMenu, action: QAction) -> QAction:
    """A right-click menu entry for a window action: its label, picture and
    first key, running the action itself. The entry is the menu's own, so
    the access key it gets here never renames the action in the File menu,
    and its key is written like every other entry's."""
    shortcut = PDFReaderWindow._action_shortcut(action)
    if shortcut is None:
        # A key the window's key filter handles for it (Ctrl+Z, Ctrl+Y ...).
        shown = getattr(action.parent(), "_display_keys", {}).get(action)
        shortcut = shown[0] if shown else None
    label = re.sub(r"&(?!&)", "", action.text())
    entry = menu.addAction(action.icon(), label + (f"\t{key_text(shortcut)}" if shortcut else ""))
    entry.setProperty("pdfnoteKey", action.property("pdfnoteKey"))
    entry.setEnabled(action.isEnabled())
    if action.isCheckable():
        entry.setCheckable(True)
        entry.setChecked(action.isChecked())
    entry.triggered.connect(lambda _checked=False, source=action: source.trigger())
    return entry


# Icons that point back or forward: flipped when the UI reads right to left.
DIRECTIONAL_ICON_KINDS = frozenset({
    "page_prev", "page_next", "page_first", "page_last", "undo", "redo", "tab_prev", "tab_next",
})


def menu_icon(kind: str, color: QColor | None = None) -> QIcon:
    """A context-menu entry's icon: the ribbon's picture for the same
    command, as Office's menus reuse its ribbon's, mirrored like the
    ribbon's where it points back or forward."""
    icon = render_ribbon_icon(kind, color)
    if QApplication.isRightToLeft() and kind in DIRECTIONAL_ICON_KINDS:
        return mirrored_icon(icon)
    return icon


def mirrored_icon(icon: QIcon) -> QIcon:
    """`icon` flipped left to right."""
    flipped = QIcon()
    for size in icon.availableSizes() or [QSize(16, 16), QSize(18, 18), QSize(32, 32), QSize(36, 36)]:
        pixmap = icon.pixmap(size)
        if not pixmap.isNull():
            flipped.addPixmap(pixmap.transformed(QTransform().scale(-1, 1)))
    return flipped


class StatusLabel(QLabel):
    """The status bar's text, readable in a right-to-left UI.

    QLabel takes a paragraph's direction from its first strong character,
    so an Arabic status line that starts with a Latin file name was laid
    out left to right and read backwards ("105 • الصفحة 1/2%"). A leading
    right-to-left mark fixes the direction; text() hands back the text as
    it was given.
    """

    RLM = "‏"

    def setText(self, text: str) -> None:
        if text and QApplication.isRightToLeft() and not text.startswith(self.RLM):
            text = self.RLM + text
        super().setText(text)

    def text(self) -> str:
        return super().text().lstrip(self.RLM)


class ChromeMixin:
    """Actions, menus, the toolbar rows and the language switch."""

    def _action(
        self,
        text: str,
        slot: Any,
        shortcut: str | tuple[str, ...] | None = None,
        tip: str | None = None,
        keys: tuple[str, ...] = (),
    ) -> QAction:
        """A window action. `shortcut` is one key or several, in Qt's
        portable names; `keys` are keys eventFilter handles for it (Ctrl+C,
        Ctrl+Z ...): shown in its tooltip, not bound to it."""
        action = QAction(tr(text), self)
        action.triggered.connect(slot)
        # The source string, for the access key a context menu gives it.
        action.setProperty("pdfnoteKey", text)
        sequences = [shortcut] if isinstance(shortcut, str) else list(shortcut or ())
        if sequences:
            action.setShortcuts([key_sequence(value) for value in sequences])
            # Per window. As application-wide shortcuts, every open pdfNote
            # window registered the same keys, Qt found each one twice and
            # ran neither: with a second window open (a tab dragged out),
            # Ctrl+W, Ctrl+S, F3 ... did nothing in either. Actions not on
            # a toolbar or menu are reached through eventFilter instead.
            action.setShortcutContext(Qt.WindowShortcut)
        if keys:
            self._display_keys[action] = list(keys)
        self._apply_action_i18n(action, text, tip)
        self._i18n_refresh_callbacks.append(
            lambda a=action, t=text, p=tip: self._apply_action_i18n(a, t, p)
        )
        return action

    def _apply_action_i18n(self, action: QAction, text: str, tip: str | None) -> None:
        action.setText(tr(text))
        description = tr(tip) if tip else tr(text).replace("&", "")
        if description:
            # Kept, because the tooltip cannot be read back as its own
            # description: the key is on the same line as the words.
            action.setProperty("pdfnoteTipText", description)
            action.setToolTip(self._action_tooltip(action, description))
            action.setStatusTip(description)

    # What these say about themselves, rather than the bare noun: what
    # they do is done to the text that is selected.
    SELECTION_DESCRIPTIONS = {
        "act_unified_underline": "選択中の文字列に下線を引く",
        "act_unified_strikeout": "選択中の文字列に取り消し線を引く",
        "act_unified_highlight": "選択中の文字列をハイライト",
    }

    def _short_tip_description(self, action: QAction) -> str | None:
        """A better description than the bare name, where there is one.

        The markup buttons say what they do to the selected text; a
        tool says what it inserts. None for everything else, whose own
        name is already the description.
        """
        for name, key in self.SELECTION_DESCRIPTIONS.items():
            if action is getattr(self, name, None):
                return tr(key)
        for mode, tool in getattr(self, "edit_actions", {}).items():
            # The text box reads the same way, though its colour is the
            # font's and lives with the other font controls.
            if action is tool and (mode in TOOL_COLOR_KINDS or mode == "text"):
                return tr(action.property("pdfnoteKey") or action.text()).replace("&", "")
        return None

    def _action_tooltip(self, action: QAction, description: str) -> str:
        """An action's tooltip: what it does and its keys, the colour key
        of a markup split button, and the premium mark where it applies."""
        short = self._short_tip_description(action)
        text = self._tooltip_with_keys(short if short is not None else description, action)
        for mode, tool in getattr(self, "edit_actions", {}).items():
            if action is tool and mode in TOOL_COLOR_KINDS:
                keys = self._marked_shortcuts(action)
                letter = keys.split(" / ")[0].replace("Alt+", "") if keys else ""
                if letter:
                    text += "\n" + tr("{description}：{shortcut}").format(
                        description=tr("色の変更"),
                        shortcut=tr("{first}、{then}").format(
                            first=keys.split(" / ")[0], then=key_text(self.TOOL_COLOUR_KEY)
                        ),
                    )
                # What Shift does while drawing (6.12), written where the
                # tool is taken (6.24): it was nowhere on screen.
                shifted = {
                    "rectangle": "正方形に描く",
                    "arrow": "45度ずつ描く",
                    "line": "45度ずつ描く",
                }.get(mode)
                if shifted is not None:
                    text += "\n" + tr("{description}：{shortcut}").format(
                        description=tr(shifted), shortcut=key_text("Shift+ドラッグ"),
                    )
                break
        colour_action = {
            getattr(self, "act_unified_highlight", None): getattr(self, "act_markup_color_menu", None),
            getattr(self, "act_unified_underline", None): getattr(self, "act_underline_color_menu", None),
            getattr(self, "act_unified_strikeout", None): getattr(self, "act_strikeout_color_menu", None),
        }.get(action)
        if colour_action is not None:
            keys = self._marked_shortcuts(colour_action)
            if keys:
                colour = (
                    colour_action.property("pdfnoteTipText")
                    or colour_action.statusTip()
                    or colour_action.text()
                ).replace("&", "")
                text += "\n" + tr("{description}：{shortcut}").format(
                    description=colour, shortcut=keys
                )
        if action in self._premium_feature_actions() and self._premium_marks_visible():
            text += "\n" + tr("{badge} — プレミアム機能").format(badge=PREMIUM_BADGE_TEXT)
        return text

    def _shortcut_texts(self, action: QAction) -> list[str]:
        """An action's keys as the UI language writes them: its shortcuts,
        then any key eventFilter handles for it. Two bindings that read the
        same (Alt+Enter on either Enter key) are listed once."""
        portable = [
            sequence.toString(QKeySequence.PortableText) for sequence in action.shortcuts()
        ]
        portable += self._display_keys.get(action, [])
        texts: list[str] = []
        for value in portable:
            text = key_text(value) if value else ""
            if text and text not in texts:
                texts.append(text)
        return texts

    def _tooltip_with_keys(self, description: str, action: QAction) -> str:
        """One line: what it does, then its key.

        It used to be two, with "Shortcut:" heading the second. A key
        reads as a key without being announced, and the announcement
        was on every button in the window (5.36).
        """
        shown = self._marked_shortcuts(action)
        if not shown:
            return description
        return tr("{description}：{shortcut}").format(
            description=description, shortcut=shown
        )

    # The one-line form is the only form now; the other name is kept
    # for the places that ask for it.
    _short_tooltip = _tooltip_with_keys

    def _marked_shortcuts(self, action: QAction) -> str:
        """The action's keys as a tooltip writes them, each Alt key with the
        premium mark until a purchase."""
        portable = [
            sequence.toString(QKeySequence.PortableText) for sequence in action.shortcuts()
        ]
        portable += self._display_keys.get(action, [])
        marks = self._premium_marks_visible()
        shown: list[str] = []
        seen: set[str] = set()
        for value in portable:
            text = key_text(value) if value else ""
            if not text or text in seen:
                continue
            seen.add(text)
            if marks and self._is_premium_key(value):
                text = f"{text} [{PREMIUM_BADGE_COMPACT_TEXT}]"
            shown.append(text)
        return " / ".join(shown)

    def _create_actions(self) -> None:
        self.act_new = self._action("新規PDF", self.new_blank_document, "Ctrl+N", "新しい空白PDFを作成")
        self.act_open = self._action("開く...", self.choose_file, "Ctrl+O", "PDFファイルを開く")
        self.act_save = self._action("上書き保存", self.save_document, "Ctrl+S", "編集内容を保存")
        # Ctrl+Shift+S is PowerPoint's Save As, F12 Word's and Excel's.
        self.act_save_copy = self._action(
            "名前を付けて保存...", self.save_as, ("Ctrl+Shift+S", "F12")
        )
        # File > Export (6.7), one entry a format.
        self.export_actions: dict[str, QAction] = {
            "docx": self._action("Word 文書...", lambda: self.export_document("docx")),
            "pptx": self._action(
                "PowerPoint プレゼンテーション...", lambda: self.export_document("pptx")
            ),
            "xlsx": self._action("Excel ブック...", lambda: self.export_document("xlsx")),
        }
        self.act_print = self._action("印刷...", self.print_document, "Ctrl+P")
        # Alt+Enter, as everywhere in Windows. To Qt the main Enter key is
        # "Return" and only the keypad one "Enter", so bind both.
        self.act_properties = self._action(
            "プロパティ", self.show_properties, ("Alt+Return", "Alt+Enter")
        )
        # Ctrl+F4 is Word's other key for closing the document.
        self.act_close = self._action(
            "文書を閉じる", self.close_document, ("Ctrl+W", "Ctrl+F4")
        )
        self.act_exit = self._action("終了", self.close)
        self.act_file_menu = self._action(
            "ファイル", lambda: self.file_button.showMenu(), "Alt+F",
            tip="ファイル メニューを開く",
        )
        self.act_shortcuts = self._action("キーボード ショートカット", self.show_shortcuts, "F1")
        self.act_license = self._action("ライセンス情報...", self.show_license_info)
        self.act_about = self._action(
            "{app} について".format(app=APP_NAME), self.show_about
        )
        # act_about's label embeds APP_NAME (a brand name, never itself
        # translated) via a template; _action()'s own retranslation would try
        # to look up the already-formatted string as a key, so re-apply the
        # template explicitly on every language switch instead.
        def _retranslate_about(action: QAction = self.act_about) -> None:
            label = tr("{app} について").format(app=APP_NAME)
            action.setText(label)
            # _action() derives the tooltip from the text it was given, which
            # here is the already-formatted string, so set it here too.
            action.setToolTip(label)
            action.setStatusTip(label)

        _retranslate_about()
        self._i18n_refresh_callbacks.append(_retranslate_about)
        # Ctrl+C / X / Z / Y are handled in eventFilter (they mean one thing
        # in a text box and another on the page); listed for the tooltip.
        self.act_copy = self._action(
            "コピー", self.copy_selection, keys=("Ctrl+C",)
        )
        self.act_cut = self._action(
            "切り取り", self.cut_selection, keys=("Ctrl+X",)
        )
        self.act_find = self._action("検索", self.focus_search, "Ctrl+F")
        self.act_undo = self._action("元に戻す", self.undo, keys=("Ctrl+Z",))
        self.act_redo = self._action("やり直す", self.redo, keys=("Ctrl+Y",))
        # Ctrl+Page Down / Page Up: Word's next and previous page.
        self.act_prev = self._action(
            "前のページ", self.previous_page, ("Shift+Up", "Ctrl+PgUp")
        )
        self.act_next = self._action(
            "次のページ", self.next_page, ("Shift+Down", "Ctrl+PgDown")
        )
        self.act_zoom_in = self._action(
            "拡大", lambda: self.change_zoom(10), ("Ctrl++", "Ctrl+Up"), "拡大"
        )
        self.act_zoom_out = self._action(
            "縮小", lambda: self.change_zoom(-10), ("Ctrl+-", "Ctrl+Down"), "縮小"
        )
        self.act_actual = self._action("100%", lambda: self.set_zoom(100), "Ctrl+0")
        # Ctrl+Alt+O is PowerPoint's Zoom to Fit; the key tip adds Alt+E.
        self.act_fit_page = self._action("ページに合わせる", self.fit_page, "Ctrl+Alt+O")
        self.act_fit_width = self._action("幅に合わせる", self.fit_width, "Alt+W")
        self.act_sidebar = self._action("サイド バーを表示/非表示", self.toggle_sidebar, "Alt+B")
        self.act_refresh = self._action("更新", self.refresh_view, "F5")
        self.act_first_page = self._action("最初のページ", lambda: self.go_to_page(0), "Ctrl+Home")
        self.act_last_page = self._action("最後のページ", self.go_to_last_page, "Ctrl+End")
        self.act_next_match = self._action("次の検索結果", self.next_match, "F3")
        self.act_prev_match = self._action("前の検索結果", self.previous_match, "Shift+F3")
        # Ctrl+F6 / Ctrl+Shift+F6: Word's next and previous document window.
        self.act_next_tab = self._action("次のタブ", self.next_tab, ("Ctrl+Tab", "Ctrl+F6"))
        self.act_prev_tab = self._action(
            "前のタブ", self.previous_tab, ("Ctrl+Shift+Tab", "Ctrl+Shift+F6")
        )
        # Ctrl+G is Word's Go To (Japanese "ジャンプ"); the key tip adds
        # Alt+J for it. It was Alt+P until v5.26, which the Codex desktop app
        # takes system-wide on this PC (its "Show pet" shortcut is meant to be
        # Win+Alt+P, but its runtime drops the Windows key when registering).
        self.act_focus_page = self._action("ページ番号へ移動", self.focus_page_entry, "Ctrl+G")
        # The zoom box had no key of its own, only zoom in and zoom out.
        self.act_focus_zoom = self._action("ズーム率を入力", self.focus_zoom_entry, "Alt+Z")
        self.act_focus_text_size = self._action(
            "フォント サイズを選択", self._focus_text_size, "Alt+S"
        )
        self.act_text_color_menu = self._action(
            "フォントの色を選択", self._open_text_color_menu, "Alt+C"
        )
        self.act_text_bold = self._action("太字", self._toggle_active_text_bold, "Ctrl+B")
        # One control per operation, shared between editing a text box's own
        # text and marking up already-placed PDF text -- which target it
        # actually hits depends on what's active when it's triggered (see
        # _toggle_unified_highlight/_underline/_strikeout). Bold has no PDF
        # markup-annotation equivalent (PDF has no "make existing text bold"
        # annotation type), so it stays text-box-only.
        # Ctrl+H and Ctrl+K are Replace and Insert Hyperlink in Office;
        # pdfNote has neither, so they stay on the two markups (v5.17 review).
        self.act_unified_highlight = self._action(
            "ハイライト", self._toggle_unified_highlight, "Ctrl+H"
        )
        self.act_unified_underline = self._action(
            "下線", self._toggle_unified_underline, "Ctrl+U"
        )
        self.act_unified_strikeout = self._action(
            "取り消し線", self._toggle_unified_strikeout, "Ctrl+K"
        )
        # Office shows the state of the current selection on these buttons;
        # here that state is also the clearest signal of which target the
        # button is pointed at right now (a text box being edited, or the
        # page text under the cursor).
        for action in (
            self.act_unified_highlight,
            self.act_unified_underline,
            self.act_unified_strikeout,
            self.act_text_bold,
        ):
            action.setCheckable(True)
        # No key of its own since v5.17: Ctrl+Shift+F is the font in Word
        # and PowerPoint. Reached from the File menu (Alt+F) and the page's
        # context menu (Shift+F10, Tools).
        self.act_fill_form = self._action("フォーム入力", self.focus_first_form_field)
        self.act_ocr_page = self._action("このページをOCR", self.ocr_current_page)
        self.act_ocr_document = self._action("文書全体をOCR", self.ocr_document)
        self.act_ocr_cancel = self._action("OCRを中止", self.cancel_ocr)
        self.act_ocr_cancel.setEnabled(False)
        self.act_ocr_data_folder = self._action(
            "言語データのフォルダーを開く", self.open_ocr_data_folder
        )
        # Every language's data, to download and delete (6.11).
        # File > Options (6.24): the language, the theme and whether links
        # are confirmed (6.18), which stood in the File menu one by one.
        self.act_options = self._action("オプション...", lambda _checked=False: self.show_options())
        self.act_ocr_data = self._action(
            "OCRの言語データ...", lambda _checked=False: self.manage_ocr_data()
        )
        self.act_redact_selection = self._action("墨消し", self.redact_selection, "Ctrl+Shift+R")
        self.act_apply_redactions = self._action(
            "墨消しを適用", lambda: self.apply_pending_redactions()
        )
        self.act_sanitize = self._action(
            "サニタイズしたコピーを保存", lambda: self.sanitize_document_copy()
        )
        # One colour per markup (v5.20), each with its own menu and key.
        # The colour keys match the keys that apply the markup: Alt+H, Alt+U
        # and Alt+K beside Ctrl+H, Ctrl+U and Ctrl+K. The highlight colour
        # sat on Alt+G from v4.1 -- a free letter rather than a matching one,
        # picked when Alt+H still applied the highlight itself (v5.23).
        self.act_markup_color_menu = self._action(
            "ハイライトの色を選択", lambda: self._open_markup_color_menu("highlight"), "Alt+H"
        )
        self.act_underline_color_menu = self._action(
            "下線の色を選択", lambda: self._open_markup_color_menu("underline"), "Alt+U"
        )
        self.act_strikeout_color_menu = self._action(
            "取り消し線の色を選択", lambda: self._open_markup_color_menu("strikeout"), "Alt+K"
        )
        self.act_drawing_color_menu = self._action(
            "図形・手書きの色を選択", self._open_drawing_color_menu, "Alt+X"
        )
        # Keyboard-first additions (v5.15). Ctrl+Alt+M and Ctrl+] / Ctrl+[
        # are Word's keys for a new comment and for font size.
        self.act_add_note_here = self._action(
            "付箋を追加", self.add_note_at_caret, "Ctrl+Alt+M"
        )
        # Ctrl+Shift+> / < are Word's and PowerPoint's font-size keys too.
        self.act_font_grow = self._action(
            "フォント サイズの拡大", lambda: self._step_font_size(1), ("Ctrl+Shift+>", "Ctrl+]")
        )
        self.act_font_shrink = self._action(
            "フォント サイズの縮小", lambda: self._step_font_size(-1), ("Ctrl+Shift+<", "Ctrl+[")
        )
        self.act_text_cursor = self._action(
            "カーソルを表示/非表示", self.toggle_text_cursor, "F7"
        )
        # Office's keys (v5.17), checked against Microsoft's Word and
        # PowerPoint shortcut pages: Ctrl+D duplicates, Ctrl+Shift+] / [
        # move one layer, Ctrl+L / E / R align, Ctrl+Shift+F goes to the font.
        self.act_duplicate = self._action("複製", self.duplicate_selection, "Ctrl+D")
        self.act_bring_forward = self._action(
            "前面へ移動", lambda: self._arrange_selected_annotations("forward"), "Ctrl+Shift+]"
        )
        self.act_send_backward = self._action(
            "背面へ移動", lambda: self._arrange_selected_annotations("backward"), "Ctrl+Shift+["
        )
        self.act_bring_to_front = self._action(
            "最前面へ移動", lambda: self._arrange_selected_annotations("front")
        )
        self.act_send_to_back = self._action(
            "最背面へ移動", lambda: self._arrange_selected_annotations("back")
        )
        # For the toolbar's arrange group (6.24). Delete itself is taken in
        # eventFilter (it means another thing in a text box); listed for
        # the tooltip.
        self.act_delete_selection = self._action(
            "削除", self.delete_selected_annotations, keys=("Del",)
        )
        # A real keyboard sends Ctrl+Shift+] as Ctrl+Shift+}. Only Qt's own
        # shortcut map also tries the unshifted key, and it only looks at
        # actions that belong to a widget -- so these two belong to the window.
        self.addAction(self.act_bring_forward)
        self.addAction(self.act_send_backward)
        self.act_align_left = self._action(
            "左揃え", lambda: self._align_active_text_box(Qt.AlignLeft), "Ctrl+L"
        )
        self.act_align_center = self._action(
            "中央揃え", lambda: self._align_active_text_box(Qt.AlignHCenter), "Ctrl+E"
        )
        self.act_align_right = self._action(
            "右揃え", lambda: self._align_active_text_box(Qt.AlignRight), "Ctrl+R"
        )
        self.act_focus_font = self._action(
            "フォントを選択", self._focus_text_font, "Ctrl+Shift+F"
        )

        self.edit_action_group = QActionGroup(self)
        self.edit_action_group.setExclusive(True)
        self.edit_actions: dict[str, QAction] = {}
        # Source keys, not tr() results: _action() translates them and
        # registers the retranslation callback with what it is given, so a
        # pre-translated label can never change language again.
        # A tool is a command: "Insert Line", not "Line". The plain nouns
        # stay where they read as nouns -- the Insert submenu, and the list
        # of annotations on the page.
        mode_specs = [
            ("select", "選択", "Esc"),
            ("note", "付箋の挿入", "Alt+N"),
            ("text", "テキスト ボックスの挿入", "Alt+T"),
            ("ink", "手書きの挿入", "Alt+D"),
            ("rectangle", "四角形の挿入", "Alt+R"),
            ("arrow", "矢印の挿入", "Alt+A"),
            ("line", "直線の挿入", "Alt+L"),
        ]
        for mode, label, shortcut in mode_specs:
            action = self._action(label, lambda _checked=False, m=mode: self._toggle_edit_mode(m), shortcut)
            action.setCheckable(True)
            action.setData(mode)
            self.edit_action_group.addAction(action)
            self.edit_actions[mode] = action
        self.edit_actions["select"].setChecked(True)
        self.act_insert_image = self._action("画像を追加...", self.insert_image, "Alt+I")
        self.act_paste_image = self._action(
            "クリップボードの画像を貼り付け", self.paste_clipboard_image,
            tip="貼り付け", keys=("Ctrl+V",),
        )
        # Ctrl+M and Ctrl+Shift+D are PowerPoint's New Slide and copy of the
        # selected slide; the Alt keys are pdfNote's own, kept.
        self.act_insert_blank = self._action(
            "空白ページを挿入", self.insert_blank_page, ("Ctrl+M", "Alt+Q")
        )
        self.act_insert_pdf = self._action("別のPDFからページを追加...", self.insert_pdf_pages, "Alt+M")
        self.act_delete_page = self._action("現在のページを削除", self.delete_current_page, "Ctrl+Shift+Del")
        self.act_duplicate_page = self._action(
            "現在のページを複製", self.duplicate_current_page, ("Ctrl+Shift+D", "Alt+Y")
        )
        self.act_rotate_pdf_page = self._action("ページを90度回転", self.rotate_pdf_page, "Alt+O")
        self.act_extract_page = self._action("現在のページを書き出し...", self.extract_current_page)
        # Over the 文字装飾 and オブジェクト tabs: each shows its filter
        # (6.10, 6.14).
        self.act_mark_filter = self._action(
            "絞り込み",
            lambda _checked=False: self.marks_pane.filter_panel.setVisible(
                self.act_mark_filter.isChecked()
            ),
            tip="種類と色で絞り込む",
        )
        self.act_mark_filter.setCheckable(True)
        self.act_object_filter = self._action(
            "絞り込み",
            lambda _checked=False: self.objects_pane.filter_panel.setVisible(
                self.act_object_filter.isChecked()
            ),
            tip="種類と色で絞り込む",
        )
        self.act_object_filter.setCheckable(True)
        # ＋ under the 目次 tab (6.9).
        self.act_outline_add = self._action(
            "このページを目次に追加",
            # Not the action's checked state for a page.
            lambda _checked=False: self.add_outline_entry(),
            tip="表示しているページを目次に追加",
        )
        self.act_merge_pdfs = self._action(
            "PDFを結合...", self.merge_pdfs, tip="複数のPDFファイルを1つに結合"
        )
        self.act_split_pdf = self._action(
            "PDFを分割...", self.split_pdf, tip="現在のPDFをページ単位またはページ範囲で分割"
        )

        self.layout_action_group = QActionGroup(self)
        self.layout_action_group.setExclusive(True)
        self.act_single_page = self._action("単ページ表示", lambda: self.set_page_layout("single"), "Alt+1")
        self.act_single_page.setCheckable(True)
        self.act_single_page.setChecked(True)
        self.act_facing_pages = self._action("見開き表示", lambda: self.set_page_layout("facing"), "Alt+2")
        self.act_facing_pages.setCheckable(True)
        self.layout_action_group.addAction(self.act_single_page)
        self.layout_action_group.addAction(self.act_facing_pages)
        # Continuous scrolling is the default (v5.25); this freezes the view
        # on one page (or one spread) at a time.
        self.act_fix_page = self._action(
            "ページを固定",
            lambda checked=False: self.toggle_continuous_view(not checked),
            # Alt+3 follows Alt+1 (single page) and Alt+2 (facing pages).
            "Alt+3",
        )
        self.act_fix_page.setCheckable(True)
        self.act_fix_page.setChecked(not self.continuous)

    def _build_document_tabs_toolbar(self) -> None:
        toolbar = QToolBar(tr("文書タブ"), self)
        self._i18n_refresh_callbacks.append(
            lambda w=toolbar: w.setWindowTitle(tr("文書タブ"))
        )
        toolbar.setObjectName("documentTabToolbar")
        toolbar.setMovable(False)
        toolbar.setFloatable(False)
        toolbar.setContentsMargins(0, 0, 0, 0)
        self.document_tabs = DocumentTabBar(self, toolbar)
        self.document_tabs.setObjectName("documentTabs")
        self.document_tabs.setDocumentMode(True)
        self.document_tabs.setTabsClosable(True)
        self.document_tabs.setMovable(True)
        self.document_tabs.setExpanding(False)
        self.document_tabs.setElideMode(Qt.ElideMiddle)
        self.document_tabs.setUsesScrollButtons(True)
        # Chrome-style: size to the tabs' own content width so the "+"
        # button added right after sits immediately next to the last tab,
        # not stretched to the far right edge of the window (Expanding would
        # push it there, with a big blank gap in between).
        self.document_tabs.setSizePolicy(QSizePolicy.Maximum, QSizePolicy.Fixed)
        self.document_tabs.currentChanged.connect(self._tab_changed)
        self.document_tabs.tabCloseRequested.connect(self._tab_close_requested)
        self.document_tabs.tabMoved.connect(self._tab_moved)
        toolbar.addWidget(self.document_tabs)
        self.new_tab_button = QToolButton()
        self.new_tab_button.setText("+")
        self.new_tab_button.setToolTip(self._tooltip_with_keys(tr("新しいタブでPDFを開く"), self.act_open))
        self.new_tab_button.setFixedSize(26, 26)
        self.new_tab_button.setStyleSheet(
            "QToolButton { font-size: 16px; font-weight: 600; }"
        )
        self.new_tab_button.clicked.connect(self.act_open.trigger)
        self._i18n_refresh_callbacks.append(
            lambda w=self.new_tab_button: w.setToolTip(self._tooltip_with_keys(tr("新しいタブでPDFを開く"), self.act_open))
        )
        toolbar.addWidget(self.new_tab_button)
        self.addToolBar(Qt.TopToolBarArea, toolbar)
        self.addToolBarBreak(Qt.TopToolBarArea)
        self.document_tabs_toolbar = toolbar
        toolbar.hide()

    def _build_file_menu(self) -> QToolButton:
        self.file_button = QToolButton()
        self.file_button.setToolButtonStyle(Qt.ToolButtonTextOnly)
        self.file_button.setText(tr("ファイル"))
        self.file_button.setToolTip(self._tooltip_with_keys(tr("ファイル メニューを開く"), self.act_file_menu))
        self.file_button.setPopupMode(QToolButton.InstantPopup)
        self.file_button.setStyleSheet("QToolButton { font-weight: 600; padding: 2px 8px; }")
        self._i18n_refresh_callbacks.append(
            lambda w=self.file_button: (
                w.setText(tr("ファイル")),
                w.setToolTip(self._tooltip_with_keys(tr("ファイル メニューを開く"), self.act_file_menu)),
            )
        )
        menu = QMenu(self.file_button)
        menu.addAction(self.act_new)
        menu.addAction(self.act_open)
        self.recent_menu = menu.addMenu(tr("最近使ったファイル"))
        self._i18n_refresh_callbacks.append(
            lambda m=self.recent_menu: m.setTitle(tr("最近使ったファイル"))
        )
        menu.aboutToShow.connect(self._refresh_recent_menu)
        menu.addSeparator()
        menu.addAction(self.act_save)
        menu.addAction(self.act_save_copy)
        export_menu = menu.addMenu(tr("エクスポート"))
        self._i18n_refresh_callbacks.append(
            lambda m=export_menu: m.setTitle(tr("エクスポート"))
        )
        for action in self.export_actions.values():
            export_menu.addAction(action)
        self.export_menu = export_menu
        menu.addSeparator()
        menu.addAction(self.act_extract_page)
        menu.addAction(self.act_merge_pdfs)
        menu.addAction(self.act_split_pdf)
        menu.addSeparator()
        menu.addAction(self.act_fill_form)
        ocr_menu = menu.addMenu(tr("OCR"))
        self._i18n_refresh_callbacks.append(lambda m=ocr_menu: m.setTitle(tr("OCR")))
        ocr_menu.addAction(self.act_ocr_page)
        ocr_menu.addAction(self.act_ocr_document)
        ocr_menu.addSeparator()
        ocr_menu.addAction(self.act_ocr_cancel)
        ocr_menu.addSeparator()
        ocr_menu.addAction(self.act_ocr_data)
        ocr_menu.addAction(self.act_ocr_data_folder)
        menu.addSeparator()
        protect_menu = menu.addMenu(tr("保護"))
        self._i18n_refresh_callbacks.append(
            lambda m=protect_menu: m.setTitle(tr("保護"))
        )
        protect_menu.addAction(self.act_redact_selection)
        protect_menu.addAction(self.act_apply_redactions)
        protect_menu.addSeparator()
        protect_menu.addAction(self.act_sanitize)
        menu.addSeparator()
        menu.addAction(self.act_print)
        menu.addAction(self.act_properties)
        menu.addSeparator()
        menu.addAction(self.act_close)
        menu.addAction(self.act_exit)
        menu.addSeparator()
        menu.addAction(self.act_options)
        menu.addSeparator()
        menu.addAction(self.act_shortcuts)
        menu.addAction(self.act_license)
        menu.addAction(self.act_about)
        self.file_button.setMenu(menu)
        return self.file_button

    def _refresh_recent_menu(self) -> None:
        self.recent_menu.clear()
        recent = self.settings.existing()
        if not recent:
            action = self.recent_menu.addAction(tr("最近使ったファイルはありません"))
            action.setEnabled(False)
            return
        for path in recent:
            action = self.recent_menu.addAction(Path(path).name)
            action.setToolTip(path)
            action.triggered.connect(lambda _checked=False, p=path: self.open_document(p))

    def _build_language_button(self) -> QToolButton:
        self.language_button = QToolButton()
        self.language_button.setIcon(self._ribbon_icon("language"))
        self.language_button.setIconSize(QSize(16, 16))
        self.language_button.setToolButtonStyle(Qt.ToolButtonTextBesideIcon)
        self.language_button.setAutoRaise(True)
        self.language_button.setText(dict(LANGUAGES)[I18N.current])
        self._themed(
            self.language_button,
            lambda: f"QToolButton {{ color: {COLORS['chrome_button_text']};"
                    f" padding: 1px 4px; }}",
        )
        self.language_button.setToolTip(tr("言語"))
        self.language_button.setPopupMode(QToolButton.InstantPopup)
        self._i18n_refresh_callbacks.append(
            lambda w=self.language_button: (
                w.setToolTip(tr("言語")),
                w.setText(dict(LANGUAGES)[I18N.current]),
            )
        )
        menu = QMenu(self.language_button)
        group = QActionGroup(self)
        group.setExclusive(True)
        self._language_actions: dict[str, QAction] = {}
        for code, native_name in LANGUAGES:
            action = menu.addAction(native_name)
            action.setCheckable(True)
            action.setChecked(code == I18N.current)
            action.setData(code)
            action.triggered.connect(lambda _checked=False, c=code: self._set_language(c))
            group.addAction(action)
            self._language_actions[code] = action
        self.language_button.setMenu(menu)
        return self.language_button

    def _system_theme_changed(self, _scheme: object = None) -> None:
        """Windows changed its light/dark setting. Only windows set to
        follow it move."""
        if self.theme_choice != "system":
            return
        if resolve_theme("system") == self._resolved_theme():
            return
        self.set_theme("system", persist=False)

    def _resolved_theme(self) -> str:
        """Which of the two palettes is on screen right now."""
        return "light" if COLORS["chrome"] == LIGHT_COLORS["chrome"] else "dark"

    def set_theme(self, choice: str, *, persist: bool = True) -> None:
        """Dark, light, or whatever Windows is set to. Every open window
        changes together: one application, one look."""
        if choice not in THEME_NAMES:
            return
        # The choice too, not only the look: another window still holding
        # "follow the system" moved every window back to the system's
        # colours when Windows changed them, and its menu showed the old
        # choice (6.2).
        for window in {*OPEN_WINDOWS, self}:
            window.theme_choice = choice
        if persist:
            self.settings.data["theme"] = choice
            self.settings.save()
        apply_theme(choice)
        for window in list(OPEN_WINDOWS):
            window._apply_theme_to_window()

    def _themed(self, widget: QWidget, factory: Callable[[], str]) -> QWidget:
        """Set a palette-dependent stylesheet and remember how to set it
        again. A stylesheet written once at build time keeps its colours for
        ever, which is how the page-count label stayed dark grey on the
        light toolbar (v5.29)."""
        self._themed_styles.append((weakref.ref(widget), factory))
        widget.setStyleSheet(factory())
        return widget

    def _restyle_themed_widgets(self) -> None:
        living: list[tuple[Any, Callable[[], str]]] = []
        for reference, factory in self._themed_styles:
            widget = reference()
            if widget is None:
                continue
            living.append((reference, factory))
            try:
                widget.setStyleSheet(factory())
            except RuntimeError:
                # The C++ side is gone; the weak reference has not caught up.
                continue
        self._themed_styles = living

    def _apply_theme_to_window(self) -> None:
        """Re-dress this window after the palette changed: the stylesheet,
        the icons (which are painted, not loaded, so they carry the old
        colours until redrawn) and the page, whose margin is a palette
        colour too."""
        self.setStyleSheet(self._stylesheet())
        if hasattr(self, "act_new"):
            self._install_home_icons()
            self._refresh_directional_icons()
            self._update_text_color_button()
            self._update_drawing_color_button()
            self._update_markup_color_button()
            self._sync_format_action_states()
        self._apply_premium_icons()
        self._restyle_themed_widgets()
        self._update_pane_indicator()
        # The wordmark is a picture, not a stylesheet: the dark theme has
        # its own copy, and nothing else would swap it.
        self._refresh_welcome_logo()
        self._rebuild_welcome()
        self._update_license_status()
        self.update_document_notices()
        self._invalidate_render_cache()
        if self.document is not None:
            self.schedule_render(immediate=True)
            # The 文字装飾 and オブジェクト tabs' rows carry pictures painted
            # in the palette too (6.10): the lists are made again.
            self._invalidate_notes()
        self.update()

    def _set_language(self, code: str, *, persist: bool = True) -> None:
        if code == I18N.current or code not in dict(LANGUAGES):
            return
        I18N.current = code
        install_qt_translations(code)
        font_changed = apply_ui_font(code)
        # Arabic reads right to left: Qt mirrors layouts, menus and scroll
        # bars once told. The pages themselves are never mirrored.
        QApplication.setLayoutDirection(
            Qt.RightToLeft if code in RIGHT_TO_LEFT_LANGUAGES else Qt.LeftToRight
        )
        if persist:
            self.settings.data["language"] = code
            self.settings.save()
        # Every window: the language belongs to the application, and the
        # others kept their labels in the old one while what they said next
        # came in the new one (6.2).
        for window in [self, *(w for w in OPEN_WINDOWS if w is not self)]:
            if font_changed:
                window._dress_in_ui_font()
            window._retranslate_ui()

    def _dress_in_ui_font(self) -> None:
        """Every control in the application's font again, after it changed
        with the language. Qt gives a new application font only to controls
        no style sheet has dressed; these kept the font they were dressed in
        (175 of the window's 274 controls, 6.32). Dressed afresh, they take
        the new one, and the style sheet's own sizes stay."""
        sheet = self.styleSheet()
        self.setStyleSheet("")
        self.setStyleSheet(sheet)

    def _retranslate_ui(self) -> None:
        for callback in self._i18n_refresh_callbacks:
            callback()
        if hasattr(self, "act_new"):
            self._refresh_directional_icons()
            self._refresh_lettered_icons()
        self._setup_keytips()
        if getattr(self, "_toolbar_rows", None):
            self._relayout_toolbar_rows()
        for code, action in getattr(self, "_language_actions", {}).items():
            action.setChecked(code == I18N.current)
        self._rebuild_welcome()
        for index, session in enumerate(self.sessions):
            self.document_tabs.setTabText(index, session.title)
        self.document_tabs.refresh_close_button_tips()
        if self.document is None:
            self.status_label.setText(tr("PDFファイルを開いてください"))
        else:
            session = self.sessions[self.current_session_index]
            self.setWindowTitle(document_window_title(session.title))
            # The line under the page stayed in the language switched from
            # until the next page turn or view change (6.4).
            self._page_line = ""
            self.status_label.setText(self._document_summary())
            # So did the notice over the page and its buttons, the rows of
            # the 文字装飾 and オブジェクト tabs, and the search results'
            # rows ("стр. 3" after a switch to English) and count, until the
            # document next changed (6.25).
            self.update_document_notices()
            self._invalidate_notes()
            self._retranslate_search_results()

    def _show_document_line(self) -> None:
        """The status bar's own line again, where a line about work under
        way (OCR, printing) stood until it ended. What was done is not
        said there (6.24)."""
        if self.document is None:
            self.status_label.setText(tr("PDFファイルを開いてください"))
        elif not getattr(self, "continuous", False) and getattr(self, "_page_line", ""):
            self.status_label.setText(self._page_line)
        else:
            self.status_label.setText(self._document_summary())

    def _document_summary(self) -> str:
        """The status bar's line about the open document: its name, the
        continuous view when it is on, and how many pages it has."""
        count = len(self.document) if self.document is not None else 0
        name = Path(self.file_path).name if self.file_path else tr("無題.pdf")
        key = (
            "{name}  •  連続スクロール  •  {count}ページ"
            if getattr(self, "continuous", False)
            else "{name}  •  {count}ページ"
        )
        return tr_n(key, count).format(name=name, count=count)

    def _build_toolbar(self) -> None:
        self.page_edit = QLineEdit("-")
        self.page_edit.setAlignment(Qt.AlignCenter)
        self.page_edit.setFixedWidth(42)
        self.page_edit.setToolTip(tr("ページ番号へ移動"))  # keys added by _setup_keytips
        self.page_edit.setValidator(QIntValidator(1, 999999, self))
        self.page_edit.returnPressed.connect(self._page_entry_submitted)
        select_all_on_first_click(self.page_edit)
        self.page_count_label = QLabel(" / 0")
        # A minimum, not a fixed width, so a six-digit page count still fits.
        self.page_count_label.setMinimumWidth(48)
        self._themed(
            self.page_count_label,
            lambda: f"color: {COLORS['muted']}; padding-left: 3px;",
        )

        self.zoom_percent_spin = QSpinBox()
        self.zoom_percent_spin.setRange(10, 600)
        self.zoom_percent_spin.setValue(100)
        self.zoom_percent_spin.setAlignment(Qt.AlignCenter)
        set_unit_suffix(self.zoom_percent_spin, "%", 66)
        self._i18n_refresh_callbacks.append(
            lambda w=self.zoom_percent_spin: set_unit_suffix(w, "%", 66)
        )
        self.zoom_percent_spin.setKeyboardTracking(False)
        select_all_on_first_click(self.zoom_percent_spin.lineEdit())
        self.zoom_percent_spin.setToolTip(tr("ズーム率を数値で入力"))
        # Their tooltips followed no language switch: English in every
        # language, as they were built before the saved language applied.
        self._i18n_refresh_callbacks.append(
            # Rebuilt by _refresh_zoom_box_tooltip, which keeps the keys.
            lambda: None
        )
        self.zoom_percent_spin.editingFinished.connect(self._zoom_entry_submitted)
        self.zoom_slider = QSlider(Qt.Horizontal)
        self.zoom_slider.setRange(10, 300)
        self.zoom_slider.setValue(100)
        self.zoom_slider.setFixedWidth(70)
        self.zoom_slider.setToolTip(tr("ズーム"))
        self._i18n_refresh_callbacks.append(lambda w=self.zoom_slider: w.setToolTip(tr("ズーム")))
        self.zoom_slider.valueChanged.connect(self._zoom_slider_changed)

    def _add_toolbar_widget(self, toolbar: QToolBar, widget: QWidget) -> QAction:
        """Like QToolBar.addWidget, but the QWidgetAction is owned by the main
        window instead of the toolbar, so QToolBar.clear() (used when
        redistributing actions across responsive toolbar rows) never deletes
        it out from under us."""
        action = QWidgetAction(self)
        action.setDefaultWidget(widget)
        toolbar.addAction(action)
        return action

    def _toolbar_separator_widget(self) -> QFrame:
        """A separator drawn as a plain widget rather than via
        QToolBar.addSeparator(), since QToolBar.clear() (used when
        redistributing actions across responsive toolbar rows) deletes
        separator QActions it created itself."""
        frame = QFrame()
        frame.setFrameShape(QFrame.VLine)
        frame.setFixedWidth(9)
        self._themed(frame, lambda: f"QFrame {{ color: {COLORS['toolbar_separator']}; }}")
        return frame

    def _new_ribbon_toolbar(self, title: str) -> QToolBar:
        toolbar = QToolBar(title, self)
        toolbar.setMovable(False)
        toolbar.setFloatable(False)
        toolbar.setToolButtonStyle(Qt.ToolButtonIconOnly)
        toolbar.setIconSize(QSize(18, 18))
        toolbar.setMinimumHeight(42)
        self.addToolBar(Qt.TopToolBarArea, toolbar)
        return toolbar

    @staticmethod
    def _ribbon_icon(kind: str, color: QColor | None = None) -> QIcon:
        return render_ribbon_icon(kind, color)


