        self._active_text_original: tuple[str, float, tuple[float, float, float], fitz.Rect] | None = None
        self._positioning_text_box = False
        self._text_color = QColor("#151515")
        self._text_font_family = DEFAULT_TEXT_BOX_FONT
        # Set while the size box is made to show the text at the caret, so
        # that showing a size does not apply it.
        self._syncing_text_controls = False
        self._markup_colors = {
            kind: QColor(value) for kind, value in MARKUP_DEFAULT_COLORS.items()
        }
        self._tool_colors = {
            kind: QColor(value) for kind, value in TOOL_DEFAULT_COLORS.items()
        }
        # Which tool Alt+X and the shape menus mean when none is in hand.
