        self._moving_note_xref: int | None = None
        self._active_object_box: CanvasObjectBox | None = None
        self._active_object_xref: int | None = None
        self._active_object_page_index = -1
        self._active_object_rect: fitz.Rect | None = None
        self._active_object_original_rect: fitz.Rect | None = None
        self._active_object_kind = ""
        self._active_object_width: float | None = None
        self._active_object_color: tuple[float, float, float] | None = None
        self._active_object_original_color: tuple[float, float, float] | None = None
        self._active_object_original_opacity: float | None = None
        self._active_object_preview_hidden = False
        self._active_line_points: tuple[fitz.Point, fitz.Point] | None = None
        self._active_line_original_points: tuple[fitz.Point, fitz.Point] | None = None
        self._active_line_handles: list[LineEndpointHandle] = []
        self._active_shape_points: list[fitz.Point] | None = None
        self._active_ink_strokes: list[list[fitz.Point]] | None = None
        self._active_ink_original_strokes: list[list[fitz.Point]] | None = None
        # How far a drawing in ink has been turned since it was taken hold
        # of: it has no angle of its own (6.21).
        self._active_ink_angle = 0.0
        self._active_shape_original_points: list[fitz.Point] | None = None
        self._active_rotation_handle: ShapeRotationHandle | None = None
        self._active_object_box_geometry: QRect | None = None
        # Geometry each box was last given by its own layout pass, so a
        # resync can tell "the user moved it" from "nothing happened".
        self._active_text_box_geometry: QRect | None = None
        self._active_image_box_geometry: QRect | None = None
        self._positioning_object_box = False
        self._active_image_box: CanvasImageBox | None = None
        self._active_image_marker_xref: int | None = None
        self._active_image_xref: int | None = None
        self._active_image_source_xref: int | None = None
        self._active_image_page_index = -1
        self._active_image_rect: fitz.Rect | None = None
        self._active_image_original_rect: fitz.Rect | None = None
        self._active_image_crop = QRectF(0.0, 0.0, 1.0, 1.0)
        self._active_image_original_crop = QRectF(0.0, 0.0, 1.0, 1.0)
        self._positioning_image_box = False
        # (picture xref, content stream xref) of an open picture not yet
        # lifted off the page -- see _take_up_active_image.
        self._active_image_pending: tuple[int, int | None] | None = None
        self._active_image_content_xref: int | None = None
        # (session, marker xref, page, state before) for a picture that was
        # selected but not yet changed -- see _withdraw_provisional_image_marker.
        self._provisional_image_marker: tuple[Any, int, int, tuple] | None = None
        # (document, state id, count) -- see _pending_redaction_count_for_notice.
        self._redaction_count_kept: tuple[Any, Any, int] | None = None
        # {(document id, page): {annotation xref: white cover rect or None}}
        # hidden on screen only while a box is open -- see _hide_on_screen.
        self._screen_hidden: dict[tuple[int, int], dict[int, fitz.Rect | None]] = {}
        self._reveal_match_after_render = False
        self._render_cache: OrderedDict[tuple[int, int, int, int], QImage] = OrderedDict()
        self._page_characters_cache: OrderedDict[
            tuple[int, int], list[tuple[fitz.Rect, str, tuple[int, int]]]
        ] = OrderedDict()
        self._text_selection_boxes_cache: OrderedDict[
            tuple[int, int, int, int], list[QRectF]
        ] = OrderedDict()
        self._render_cache_bytes = 0
        self._render_was_limited = False
        self._page_clipboard: bytes | None = None
        # The session a copied page came from, and whether that PDF was
        # protected (see _paste_page_from_clipboard).
        self._page_clipboard_origin: tuple[Any, bool] | None = None
        self._suspend_thumbnail_reorder = False
        # Caret hand-offs: to the widget of the other view mode, and to the
        # page the arrow keys ran on to (see _place_pending_caret).
        self._carried_caret: tuple[int, int, int, bool] | None = None
        self._pending_caret_placement: tuple[int, int] | None = None
